    "q.l3#3.o2" to "Он должен быть однослойным",
    "q.l3#3.o3" to "Чем мягче подошва, тем удобнее",
    "q.l3#3.e" to "Съёмный вкладыш можно вынуть на ночь, чтобы высушить или держать в тепле на теле, поэтому он никогда не замерзает — это и есть ключ к рабочим ногам на многодневных высотных маршрутах. Верх обычно делают трёхслойным ламинатом: водонепроницаемость, ветрозащита и долговечность.",
    "q.l3#4.p" to "Почему нижний слой никогда не должен быть хлопковым?",
    "q.l3#4.o0" to "Хлопок слишком дорог",
    "q.l3#4.o1" to "Хлопок удерживает пот и медленно сохнет, поэтому влажная ткань на коже ускоряет потерю тепла",
    "q.l3#4.o2" to "Хлопок вызывает аллергию",
    "q.l3#4.o3" to "Хлопок не дышит, поэтому кажется холоднее",
    "q.l3#4.e" to "Задача нижнего слоя — отводить пот от кожи. Хлопок впитывает воду и почти не отдаёт её, поэтому влажная холодная ткань продолжает забирать тепло. Выбирайте полиэстер или шерсть мериноса: они быстро переносят влагу.",
    "q.l3#5.p" to "Какой материал рекомендуется для ботинка на 6 000 м?",
    "q.l3#5.o0" to "Обычная кожа",
    "q.l3#5.o1" to "Водонепроницаемый дышащий материал, например GORE-TEX",
    "q.l3#5.o2" to "Ткань из чистого хлопка",
    "q.l3#5.o3" to "Жёсткий пластиковый корпус",
    "q.l3#5.e" to "Ботинок на 6 000 м ценится за лёгкость, комфорт и сцепление, и при этом в нём нужно много часов нормально идти. Водонепроницаемая дышащая мембрана вроде GORE-TEX не пускает воду внутрь и выпускает пар: водонепроницаемость без дышимости просто запирает пот, и вы всё равно оказываетесь мокрым и холодным.",
    "q.l3#6.p" to "Какого материала следует избегать в альпинистских носках?",
    "q.l3#6.o0" to "Шерсти мериноса",
    "q.l3#6.o1" to "Синтетических волокон, например полиэстера",
    "q.l3#6.o2" to "Хлопка",
    "q.l3#6.o3" to "Нейлона",
    "q.l3#6.e" to "Логика та же, что с нижним слоем: хлопок впитывает пот и почти не отдаёт его, поэтому влажная холодная ткань продолжает отнимать тепло и резко повышает риск мозолей. Выбирайте синтетику (без хлопка) или меринос, с высоким голенищем, которое балансирует тепло и кровообращение.",
    "q.l3#7.p" to "Как правильно подходить к выбору бахил?",
    "q.l3#7.o0" to "Использовать одни и те же короткие бахилы в любом выходе",
    "q.l3#7.o1" to "Для высоких вершин предпочитать длинные бахилы, не пускающие снег в ботинок",
    "q.l3#7.o2" to "Бахилы нужны только от дождя",
    "q.l3#7.o3" to "Чем короче и легче, тем всегда лучше",
    "q.l3#7.e" to "Бахилы — это тканевый чехол поверх ботинка, который не пускает снег и мусор. На глубоком высотном снегу короткая пара быстро уходит под снег и становится бесполезной, поэтому рекомендуются длинные; короткие подходят для известных треккинговых маршрутов и неглубокого снега в альпийском стиле.",
    "q.l3#8.p" to "Для чего нужны лагерная обувь и тапочки и какими они должны быть?",
    "q.l3#8.o0" to "Для вершины; они должны быть очень жёсткими",
    "q.l3#8.o1" to "Для перемещения по лагерю; они должны быть тёплыми, водонепроницаемыми и нескользящими",
    "q.l3#8.o2" to "Для технического лазания; нужны передние зубья",
    "q.l3#8.o3" to "Только для красоты; необязательны",
    "q.l3#8.e" to "Они дают отдых основным ботинкам: в палатке переобуваешься в лагерную обувь или тапочки, вкладыши могут просохнуть, а стопы не сдавлены целый день. Технической функции у них нет, но на состояние ног на следующее утро они влияют напрямую.",
    "q.l3#9.p" to "Что даёт высокое голенище носка в длительной экспедиции?",
    "q.l3#9.o0" to "Выглядит профессиональнее",
    "q.l3#9.o1" to "Сохраняет тепло стопы и поддерживает кровообращение",
    "q.l3#9.o2" to "Носок легче надеть",
    "q.l3#9.o3" to "Добавляет амортизирующую толщину",
    "q.l3#9.e" to "В долгие дни стопы отекают, кровообращение ухудшается. Высокий носок закрывает голень, согревает её и за счёт равномерного давления помогает венозному возврату — а на многодневном выходе это решает, работают ли ноги ещё на третий день.",
    // ---------- l4 Техника передвижения по снегу ----------
    "q.l4#0.p" to "Как правильно выбивать ступени?",
    "q.l4#0.o0" to "Делать длинные шаги, чтобы ступеней было меньше",
    "q.l4#0.o1" to "Выбивать небольшие ступени в ровном ритме и держать центр масс устойчиво",
    "q.l4#0.o2" to "Идти только на носках",
    "q.l4#0.o3" to "Вбивать пятку в снег всю дорогу",
    "q.l4#0.e" to "Мелкие ступени в ровном ритме держат центр масс устойчиво и тратят меньше энергии. Длинные шаги раскачивают корпус из стороны в сторону — самый простой способ потерять равновесие на снежном склоне.",
    "q.l4#1.p" to "В какой руке нести ледоруб при движении?",
    "q.l4#1.o0" to "В руке со стороны склона (нижней)",
    "q.l4#1.o1" to "В руке со стороны горы (верхней), готовым сразу перейти к самозадержанию",
    "q.l4#1.o2" to "Ни в какой",
    "q.l4#1.o3" to "Снаружи на рюкзаке",
    "q.l4#1.e" to "Несут в верхней руке в положении «пиоле канн»: клюв назад, головка вперёд. При срыве вы можете надавить и войти в самозадержание, не меняя руку, — а эти несколько секунд на перехват часто и есть всё окно аварии.",
    "q.l4#2.p" to "Какая техника облегчает нехватку дыхания на высоте при подъёме?",
    "q.l4#2.o0" to "Задерживать дыхание на ходу",
    "q.l4#2.o1" to "Дыхание под давлением: глубокий вдох и энергичный выдох в ритме шагов",
    "q.l4#2.o2" to "Частое поверхностное дыхание",
    "q.l4#2.o3" to "Дышать через рукавицу",
    "q.l4#2.e" to "Дыхание под давлением повышает положительное давление в лёгких за счёт активного выдоха и улучшает газообмен. В связке с ритмом шагов — например, один вдох на два-три шага — оно заметно снижает ощущение удушья на высоте.",
    "q.l4#3.p" to "Когда связка идёт вверх по снежному склону, как правильно выбивать ступени?",
    "q.l4#3.o0" to "Каждый выбивает свою отдельную линию",
    "q.l4#3.o1" to "Первый выбивает ровную лестницу, остальные идут по тем же ступеням",
    "q.l4#3.o2" to "Каждый выбивает как хочет",
    "q.l4#3.o3" to "Выбивать как можно глубже и шире",
    "q.l4#3.e" to "Одна лестница сильно снижает затраты всех, кто идёт сзади, и держит связку на одной линии и в одном ритме. Ровная лестница с одинаковым шагом сама по себе признак эффективности и безопасности группы.",
    "q.l4#4.p" to "Каков главный принцип темпа на высоте?",
    "q.l4#4.o0" to "Идти как можно быстрее и раньше отдыхать",
    "q.l4#4.o1" to "Держать ровный посильный темп и избегать повторных взрывных усилий",
    "q.l4#4.o2" to "Чередовать быстро и медленно, чтобы экономить силы",
    "q.l4#4.o3" to "Идти за напарником и не следить за своим состоянием",
    "q.l4#4.e" to "На высоте потребление кислорода ограничено, поэтому повторные взрывные усилия быстро накапливают лактат и углубляют гипоксию. Ровный темп с дыханием под давлением уводит дальше и не даёт одному бегуну разваливать всю связку.",
    "q.l4#5.p" to "Кто должен задавать темп связки на снежном склоне?",
    "q.l4#5.o0" to "Самый сильный в группе",
    "q.l4#5.o1" to "Нужно идти в темпе самого слабого, чтобы связка не разрывалась",
    "q.l4#5.o2" to "Ведущий, жёстко по графику",
    "q.l4#5.o3" to "Каждый в своём темпе",
    "q.l4#5.e" to "Как только на снежном склоне появляются разрывы, идущие сзади теряют и страховку, и поддержку; а слишком быстрый темп выматывает слабых ещё до того, как они дойдут до опасного места. Движение в темпе самого медленного сохраняет запас безопасности всей группы.",
    "q.l4#6.p" to "При пересечении ледового склона с заметным уклоном что рекомендует руководство?",
    "q.l4#6.o0" to "Идти как обычная связка",
    "q.l4#6.o1" to "Навесить перила или использовать попеременную страховку; обычно не идти одновременно",
    "q.l4#6.o2" to "Пробежать как можно быстрее",
    "q.l4#6.o3" to "Снять кошки, чтобы трения было больше",
    "q.l4#6.e" to "Самозадержание на льду гораздо менее надёжно, чем на снегу, а связка на льду может утащить вниз всю группу. Правильный подход на наклонном льду — перила или попеременная страховка: защита от системы, а не от умения отдельного человека тормозить.",
    "q.l4#7.p" to "В чём главное преимущество подъёма по снежному склону зигзагом, а не напрямую?",
    "q.l4#7.o0" to "Короче расстояние",
    "q.l4#7.o1" to "Снижается эффективный угол каждого участка и экономит силы",
    "q.l4#7.o2" to "Лучше видно панораму",
    "q.l4#7.o3" to "Не нужен ледоруб",
    "q.l4#7.e" to "Зигзаг разбивает крутой склон на несколько более пологих участков, сильно снижая нагрузку на икры и голеностопы, и хорошо сочетается с французской техникой (на плоско поставленной кошке). Плата — длина пути, поэтому поправьте бюджет времени: ещё один повод держать запас в контрольном времени возвращения.",
    // ---------- l5 Техника передвижения в кошках ----------
    "q.l5#0.p" to "В чём суть французской техники (на плоско поставленной кошке)?",
    "q.l5#0.o0" to "Бить в лёд только передними зубьями",
    "q.l5#0.o1" to "Ставить все нижние зубья кошки плоско на склон, ступня тоже плоско",
    "q.l5#0.o2" to "Прыгать на одной ноге",
    "q.l5#0.o3" to "Врезаться в лёд ребром ботинка",
    "q.l5#0.e" to "Французская техника — это про плоско: работают все двенадцать нижних зубьев, нагрузка распределяется через бедро и всё тело, поэтому она самая экономная. Именно поэтому она подходит для длинных участков пологого снега.",
    "q.l5#1.p" to "Почему лазание на передних зубьях (немецкая техника) самое утомительное?",
    "q.l5#1.o0" to "Потому что работают руки",
    "q.l5#1.o1" to "Потому что нагрузка стоит на передних зубьях, и икра работает непрерывно",
    "q.l5#1.o2" to "Потому что приходится задерживать дыхание",
    "q.l5#1.o3" to "Потому что трение больше",
    "q.l5#1.e" to "На передних зубьях вес приходится на две-три точки, поэтому икра держит постоянное сокращение, чтобы сохранить положение. Это крайне утомительно и долго не выдерживается — потому технику и оставляют для крутого рельефа.",
    "q.l5#2.p" to "Какую работу ног использовать при траверсе снежного склона?",
    "q.l5#2.o0" to "Передние зубья, вбивая их прямо",
    "q.l5#2.o1" to "Утиный шаг: пятки вместе, носки разведены, чтобы кошка лежала на склоне целиком",
    "q.l5#2.o2" to "Прыжки вбок",
    "q.l5#2.o3" to "Ползти на коленях",
    "q.l5#2.e" to "Утиный шаг даёт боковым и нижним зубьям цеплять одновременно, поэтому вес не сосредоточен на внутренних зубьях, где он может соскользнуть. При траверсе слегка наклоняйтесь в сторону склона.",
    "q.l5#3.p" to "Какой рельеф лучше всего подходит для французской техники (плоская кошка)?",
    "q.l5#3.o0" to "Вертикальный лёд",
    "q.l5#3.o1" to "Твёрдый снег малого и среднего угла, по которому идёшь часами",
    "q.l5#3.o2" to "Нависания",
    "q.l5#3.o3" to "Только ровная площадка",
    "q.l5#3.e" to "Французская техника распределяет нагрузку через всё тело и бедро, поэтому она самая экономная и основная рабочая для малых и средних углов и длинных снежных склонов. Крутой рельеф требует передних зубьев, но на передних зубьях долго не продержаться.",
    "q.l5#4.p" to "Что будет, если долго идти на передних зубьях по крутому склону?",
    "q.l5#4.o0" to "Дальше будет легче",
    "q.l5#4.o1" to "Икра быстро устанет, пока вы не сможете удерживать положение",
    "q.l5#4.o2" to "Кошки сами слетят",
    "q.l5#4.o3" to "Ничего особенного",
    "q.l5#4.e" to "Передние зубья сосредотачивают вес на двух-трёх точках и держат икру в постоянном сокращении, поэтому усталость приходит быстро. Поэтому техника годится только для коротких крутых участков — и поэтому бюджет сил должен её учитывать при планировании маршрута.",
    "q.l5#5.p" to "В смешанной (американской) технике как две ноги делят работу?",
    "q.l5#5.o0" to "Обе ноги стоят плоско на склоне",
    "q.l5#5.o1" to "Обе ноги работают на передних зубьях",
    "q.l5#5.o2" to "Одна нога плоско для опоры, другая толкается на передних зубьях, попеременно",
    "q.l5#5.o3" to "Одна нога делает всю работу, другая отдыхает",
    "q.l5#5.e" to "Смешанная техника — мост между французской и немецкой: плоская нога даёт устойчивость и момент отдыха, нога на передних зубьях даёт тягу. На средних и крутых склонах она держит эффективность, не выматывая икры так, как чистое лазание на передних зубьях.",
    "q.l5#6.p" to "[Соответствие] Соотнесите класс кошек и подходящий ботинок.",
    "q.l5#6.l0" to "C1, полностью на ремнях",
    "q.l5#6.r0" to "Мягкий ботинок B1",
    "q.l5#6.l1" to "C2, ремень спереди и защёлка сзади",
    "q.l5#6.r1" to "Полужёсткий ботинок B2",
    "q.l5#6.l2" to "C3, полностью на защёлках",
    "q.l5#6.r2" to "Полностью жёсткий ботинок B3",
    "q.l5#6.e" to "Ботинок и кошки должны соответствовать друг другу: мягкий с C1, полужёсткий с C2, жёсткий с C3. Кошки на защёлках на мягком ботинке дают ему прогибаться, защёлки теряют зацеп, и на крутом склоне кошка может сойти — заведомо опасное сочетание.",
    "q.l5#7.p" to "Какие две базовые техники передвижения по льду существуют?",
    "q.l5#7.o0" to "Плоская постановка и приставной шаг",
    "q.l5#7.o1" to "Техника на плоско поставленной кошке (французская) и на передних зубьях (немецкая)",
    "q.l5#7.o2" to "Прыжки и скольжение",
    "q.l5#7.o3" to "Техника подъёма и техника спуска",
    "q.l5#7.e" to "Техника на плоско поставленной кошке включает все вертикальные зубья, кроме передних; техника на передних зубьях вбивает передние зубья прямо в лёд. Сложный рельеф обычно смешивает обе — поэтому сначала осваивают обе, а потом берутся за смешанную.",
    "q.l5#8.p" to "При технике на плоско поставленной кошке (французской) какие мышцы несут нагрузку?",
    "q.l5#8.o0" to "Икры",
    "q.l5#8.o1" to "Бёдра",
    "q.l5#8.o2" to "Предплечья",
    "q.l5#8.o3" to "Поясница",
    "q.l5#8.e" to "Поскольку ступня остаётся плоской, нагрузку несут бёдра и всё тело, поэтому техника экономична и выдерживается часами. На передних зубьях всё наоборот: нагрузка на двух-трёх точках, и всю работу делает икра — два совершенно разных энергетических счёта.",
    "q.l5#9.p" to "Техника на плоско поставленной кошке (французская) особенно подходит для какого угла склона?",
    "q.l5#9.o0" to "0°–30°",
    "q.l5#9.o1" to "30°–50°",
    "q.l5#9.o2" to "50°–70°",
    "q.l5#9.o3" to "Выше 70°",
    "q.l5#9.e" to "Руководства прямо называют 0°–30°. Круче ступня уже не может оставаться плоской, поэтому нужно переходить на передние зубья. Знать диапазон углов для каждой техники — значит знать, когда её менять.",
    // ---------- l6 Самозадержание ледорубом ----------
    "q.l6#0.p" to "Где должны быть ноги при самозадержании?",
    "q.l6#0.o0" to "Упираться в снег, чтобы тормозить",
    "q.l6#0.o1" to "Подняты над снегом, носки вверх, чтобы весь вес шёл через ледоруб",
    "q.l6#0.o2" to "Носки воткнуты в снег для якоря",
    "q.l6#0.o3" to "Вместе и плоско на снегу",
    "q.l6#0.e" to "В момент, когда нога касается снега, она снимает вес с ледоруба, эффективность торможения падает и появляется риск травмы голеностопа и колена. Поднимите обе ноги, чтобы весь вес тела шёл через клюв в снег.",
    "q.l6#1.p" to "Вы скользите головой вниз, ноги выше. Что делать в первую очередь?",
    "q.l6#1.o0" to "Попытаться схватить верёвку",
    "q.l6#1.o1" to "Сразу перевернуться в положение лицом вниз, ногами вниз, и затем выполнить самозадержание",
    "q.l6#1.o2" to "Продолжать скользить и ждать, пока скорость упадёт",
    "q.l6#1.o3" to "Сначала выбросить рюкзак",
    "q.l6#1.e" to "Головой вниз клюв невозможно эффективно прижать к снегу, а удар головой крайне опасен. Сначала корпусом и мышцами живота перевернитесь в положение для самозадержания лицом вниз, и только потом вдавливайте клюв.",
    "q.l6#2.p" to "Как правильно учиться самозадержанию?",
    "q.l6#2.o0" to "Достаточно посмотреть видео",
    "q.l6#2.o1" to "Прочитать руководство и запомнить ключевые пункты",
    "q.l6#2.o2" to "Многократно отрабатывать на безопасном склоне с мягким снегом и инструктором на страховке, пока движение не станет инстинктом",
    "q.l6#2.o3" to "Выучить, один раз упав на настоящем крутом склоне",
    "q.l6#2.e" to "Самозадержание — навык рефлекторного уровня: чтобы он стал надёжным, нужны сотни повторений в контролируемых условиях. Отрабатывайте на пологом склоне с чистым выкатом, мягким снегом и инструктором на страховке.",
    "q.l6#3.p" to "Как эффективнее всего приложить силу при самозадержании?",
    "q.l6#3.o0" to "Сильно давить руками",
    "q.l6#3.o1" to "Вдавливать клюв вниз весом тела, по вертикали",
    "q.l6#3.o2" to "Тащить древко боком по снегу",
    "q.l6#3.o3" to "Быстро проводить клювом по поверхности",
    "q.l6#3.e" to "Сила рук отказывает при усталости и панике; только вес тела вгоняет клюв глубже. Поэтому положение — лицом вниз, ноги подняты — важнее грубой силы.",
    "q.l6#4.p" to "На твёрдом снегу или льду насколько работает самозадержание?",
    "q.l6#4.o0" to "Лучше — останавливает сразу",
    "q.l6#4.o1" to "Тормозной путь сильно растёт и может не сработать вообще",
    "q.l6#4.o2" to "Так же, как на мягком снегу",
    "q.l6#4.o3" to "Автоматически превращается в скольжение",
    "q.l6#4.e" to "На твёрдом снегу и льду клюв с трудом цепляет. Поэтому нельзя выходить на крутой твёрдый снежный склон без страховки: техника не заменяет уклонения, и знать пределы техники так же важно, как саму технику.",
    "q.l6#5.p" to "При самозадержании как две руки делят работу?",
    "q.l6#5.o0" to "Обе руки на древке",
    "q.l6#5.o1" to "Обе руки давят на головку",
    "q.l6#5.o2" to "Одна рука давит на головку у клюва, создавая усилие вниз, другая держит древко для направления и устойчивости",
    "q.l6#5.o3" to "Хватит одной руки; вторая остаётся свободной",
    "q.l6#5.e" to "Рука на головке передаёт вес тела на клюв; рука на древке стабилизирует и корректирует направление. Когда роли ясны, задержание получается и сильным, и прямым.",
    "q.l6#6.p" to "[Порядок] Расставьте шаги задержания при срыве в правильном порядке.",
    "q.l6#6.o0" to "Крепко взяться за ледоруб и прижать головку под себя в хвате для самозадержания",
    "q.l6#6.o1" to "Перевернуться в положение лицом вниз, головой вверх, лицом к снегу",
    "q.l6#6.o2" to "Вдавить клюв в снег и лёд весом тела, ноги разведены, колени прижаты к поверхности",
    "q.l6#6.o3" to "Поднять обе ноги, чтобы кошки не зацепились и не перевернули вас",
    "q.l6#6.e" to "Чаще всего забывают последний шаг — поднять ноги. В момент, когда нога касается снега, она отнимает вес у ледоруба, кошки могут резко зацепиться и перевернуть вас, прервав само задержание.",
    "q.l6#7.p" to "Где должна находиться лопатка (плоская сторона головки) при самозадержании?",
    "q.l6#7.o0" to "Снаружи от колена",
    "q.l6#7.o1" to "В ямке плеча",
    "q.l6#7.o2" to "На уровне бедра",
    "q.l6#7.o3" to "Далеко в стороне от головы",
    "q.l6#7.e" to "Когда лопатка в ямке плеча, древко идёт близко к средней линии тела, а нагрузка сосредоточена под корпусом — именно там усилие вниз работает лучше всего. Дальше в сторону нагрузка рассеивается, клюв гуляет, и тормозной путь заметно растёт.",
    "q.l6#8.p" to "[Несколько ответов] Что в основном определяет успех задержания?",
    "q.l6#8.o0" to "Угол снега или льда",
    "q.l6#8.o1" to "Твёрдость снега или льда",
    "q.l6#8.o2" to "Положение падающего",
    "q.l6#8.o3" to "Скорость реакции",
    "q.l6#8.o4" to "Бренд и цена снаряжения",
    "q.l6#8.e" to "Руководства честны: помимо скорости реакции успех зависит от угла, твёрдости и положения, и «иногда даже самое отработанное движение не может остановить падение». Признать этот предел — значит понять, почему не падать важнее, чем задерживаться.",
    "q.l6#9.p" to "Каково правильное положение ног и коленей при задержании?",
    "q.l6#9.o0" to "Ноги вместе, колени над землёй",
    "q.l6#9.o1" to "Ноги разведены, колени прижаты к снегу и льду",
    "q.l6#9.o2" to "Одна нога прямая, другая согнута",
    "q.l6#9.o3" to "Обе ноги подняты над снегом",
    "q.l6#9.e" to "Разведённые ноги дают боковую устойчивость и не дают перевернуться; колени, прижатые к поверхности, добавляют точку опоры и помогают держать вес на ледорубе. Обратите внимание на разницу: колени могут слегка касаться, а стопы — и кошки — должны быть подняты.",
    // ---------- l7 Профилактика срыва и задержание ----------
    "q.l7#0.p" to "Как эффективнее всего не допустить срыва при движении?",
    "q.l7#0.o0" to "Идти быстрее",
    "q.l7#0.o1" to "Самостраховаться ледорубом, создавая себе временную точку опоры на каждом шаге",
    "q.l7#0.o2" to "Убрать ледоруб в рюкзак",
    "q.l7#0.o3" to "Полагаться только на верёвку",
    "q.l7#0.e" to "Самостраховка — самая прямая линия обороны в движении: рука с ледорубом втыкает древко в снег на каждом шаге, создавая третью точку опоры. Подавляющее большинство срывов происходит именно в тот момент, когда этой опоры нет.",
    "q.l7#1.p" to "Напарник внезапно сорвался, вы идёте в связке. Что делать в первую очередь?",
    "q.l7#1.o0" to "Бежать вниз и ловить его",
    "q.l7#1.o1" to "Сразу встать в положение для самозадержания и выбирать верёвку, чтобы его удержать",
    "q.l7#1.o2" to "Развязаться, чтобы вас не утащило",
    "q.l7#1.o3" to "Кричать о помощи и ждать",
    "q.l7#1.e" to "Связка работает потому, что сначала вы держите себя, и уже потом верёвка передаёт задержание. Бежать вниз или развязываться — значит пустить в скольжение всю связку: классический цепной отказ в авариях на леднике.",
    "q.l7#2.p" to "В момент потери опоры какое действие первое?",
    "q.l7#2.o0" to "Поправить снаряжение",
    "q.l7#2.o1" to "Крикнуть предупреждение и сразу перевернуться лицом вниз для задержания",
    "q.l7#2.o2" to "Оценить крутизну склона",
    "q.l7#2.o3" to "Посмотреть, что внизу",
    "q.l7#2.e" to "Первые две секунды решают исход. Крик приводит напарников в защитное положение одновременно с тем, как вы переворачиваетесь лицом вниз: этот переворот и есть главное действие, ограничивающее ущерб.",
    "q.l7#3.p" to "В каком состоянии должна быть верёвка при движении в связке?",
    "q.l7#3.o0" to "Как можно более провисшая, для свободы движения",
    "q.l7#3.o1" to "Умеренно натянутая, без больших провисающих петель",
    "q.l7#3.o2" to "Полностью натянутая",
    "q.l7#3.o3" to "Как удобнее",
    "q.l7#3.e" to "Большие петли означают, что падающий сначала свободно летит, прежде чем верёвка нагрузится: удар умножается, а верёвка успевает пропилить снег. Умеренное натяжение включает задержание раньше.",
    "q.l7#4.p" to "Почему «не сорваться» важнее, чем «научиться задерживаться»?",
    "q.l7#4.o0" to "Потому что техника задержания бесполезна",
    "q.l7#4.o1" to "Потому что на твёрдом снегу и крутых склонах задержание может не сработать — надёжная защита это не потерять опору",
    "q.l7#4.o2" to "Потому что задерживаться слишком тяжело",
    "q.l7#4.o3" to "Потому что инструкторы запрещают тренировать это",
    "q.l7#4.e" to "Самозадержание необходимо, но у него есть ясные пределы. Надёжная стратегия — не входить на рельеф, где можно поскользнуться, не имея страховки. Техника — последняя линия обороны, а не первая.",
    "q.l7#5.p" to "При задержании клюв отскакивает от твёрдого снега и не цепляет. Что делать?",
    "q.l7#5.o0" to "Поднять его и ударить снова",
    "q.l7#5.o1" to "Оставаться лицом вниз и продолжать давить весом тела, чтобы клюв постепенно вошёл",
    "q.l7#5.o2" to "Тащить древко боком по снегу",
    "q.l7#5.o3" to "Отказаться от задержания и защищать голову",
    "q.l7#5.e" to "Поднять ледоруб — значит полностью отменить задержание и потерять то положение давления, которое вы уже построили. Оставайтесь лицом вниз и продолжайте давить: по мере скольжения клюв входит глубже. Задержание — процесс, а не одно движение.",
    "q.l7#6.p" to "Почему говорят, что задерживаться на льду очень трудно?",
    "q.l7#6.o0" to "Потому что лёд слишком холодный",
    "q.l7#6.o1" to "Потому что клюв с трудом цепляет лёд, поэтому на ледовых склонах навешивают перила, а не рассчитывают на задержание",
    "q.l7#6.o2" to "Потому что трение по льду слишком велико",
    "q.l7#6.o3" to "Потому что лёд легко ломается",
    "q.l7#6.e" to "Задержание держится на зацепе клюва, а лёд — самая трудная для зацепа поверхность. Руководства отвечают системно: на наклонном льду навешивают перила или используют попеременную страховку и обычно не идут одновременно — вопрос решается системой, а не надеждой на личную технику.",
    "q.l7#7.p" to "[Порядок] Напарник сорвался, вы идёте в связке. Какая последовательность верна?",
    "q.l7#7.o0" to "Сразу встать в положение для самозадержания и удержать себя",
    "q.l7#7.o1" to "Выбрать верёвку, чтобы остановить падение",
    "q.l7#7.o2" to "Построить независимую точку страховки (снежный крюк, закопанный ледоруб и так далее)",
    "q.l7#7.o3" to "Перенести нагрузку на точку страховки и затем начать спасение",
    "q.l7#7.e" to "Эти четыре шага нельзя переставить: сначала вы держите себя, иначе не сделать ничего остального, а спасение без точки страховки взваливает на вас вес двоих. В реальности шаги занимают минуты, поэтому их нужно отрабатывать заранее.",
    "q.l7#8.p" to "Задержание сработало, скольжение остановилось. Что дальше?",
    "q.l7#8.o0" to "Встать и идти дальше",
    "q.l7#8.o1" to "Держать задержание, пошагово построить страховку и перенести вес на точку страховки",
    "q.l7#8.o2" to "Развязать верёвку",
    "q.l7#8.o3" to "Проверить, не повреждено ли снаряжение",
    "q.l7#8.e" to "Остановленное скольжение — ещё не безопасность: вы всё ещё в незащищённом положении, и повторно задержаться будет трудно. Держите задержание, пока строите надёжную страховку, освободитесь, и только потом занимайтесь травмами и маршрутом.",
    "q.l7#9.p" to "[Несколько ответов] Что действительно предотвращает срывы?",
    "q.l7#9.o0" to "Непрерывная самостраховка ледорубом в движении",
    "q.l7#9.o1" to "Навешивание перил на твёрдом снегу и льду",
    "q.l7#9.o2" to "Ровный посильный темп без резких усилий, ломающих равновесие",
    "q.l7#9.o3" to "Движение в темпе самого медленного, чтобы связка не растягивалась",
    "q.l7#9.o4" to "Движение быстрее, чтобы сократить время под опасностью",
    "q.l7#9.e" to "Первые четыре работают на разных уровнях: личная техника, системная защита, управление темпом и целостность связки. Профилактика срывов никогда не бывает одним действием — это все слои сразу.",
    // ---------- l8 Спуск и дюльфер ----------
    "q.l8#0.p" to "Почему аварии чаще происходят на спуске?",
    "q.l8#0.o0" to "Потому что рельеф вниз сложнее",
    "q.l8#0.o1" to "Потому что усталость ухудшает внимание и качество движения",
    "q.l8#0.o2" to "Потому что на спуске погода всегда хуже",
    "q.l8#0.o3" to "Потому что отказывает снаряжение",
    "q.l8#0.e" to "Когда вершина взята, внимание падает, а тело уже почти пустое. Значительная часть альпинистских аварий происходит на спуске — отсюда и поговорка, что вершина это только половина пути.",
    "q.l8#1.p" to "При каких условиях можно скользить по склону (глиссада)?",
    "q.l8#1.o0" to "Всякий раз, когда склон достаточно крутой",
    "q.l8#1.o1" to "Нет трещин, нет риска камнепада, внизу чистый выкат и есть возможность задержаться в любой момент",
    "q.l8#1.o2" to "На любом снежном склоне",
    "q.l8#1.o3" to "Когда напарники согласны",
    "q.l8#1.e" to "Скольжение — необратимое ускорение: начав, трудно остановиться. Нужно исключить трещины, камнепад и людей внизу и быть уверенным, что сможете перевернуться в задержание в любой точке. Иначе спускайтесь нормально.",
    "q.l8#2.p" to "Как предпочтительно спускаться по техническому рельефу?",
    "q.l8#2.o0" to "Спускаться лицом к склону, сохраняя три точки опоры",
    "q.l8#2.o1" to "Бежать вниз лицом наружу",
    "q.l8#2.o2" to "Скользить (глиссада)",
    "q.l8#2.o3" to "Сидеть и сползать",
    "q.l8#2.e" to "Лицом к склону вы видите точки опоры, держите центр масс близко к поверхности и обе руки свободны для опоры. Лицом наружу точки опоры не видны — очень частая ошибка.",
    "q.l8#3.p" to "Какая ошибка на спуске самая опасная и самая частая?",
    "q.l8#3.o0" to "Спуск лицом к склону на трёх точках",
    "q.l8#3.o1" to "Наклон вперёд и спуск лицом наружу",
    "q.l8#3.o2" to "Ровный ритм",
    "q.l8#3.o3" to "Самостраховка ледорубом",
    "q.l8#3.e" to "Лицом наружу вы не видите точек опоры, а наклон вперёд делает вас ещё менее устойчивым. Добавьте усталость, снижающую контроль ног, — и вы получите настоящую причину, почему спуски так подвержены авариям.",
    "q.l8#4.p" to "Что нужно сделать до начала скольжения?",
    "q.l8#4.o0" to "Убрать ледоруб в рюкзак",
    "q.l8#4.o1" to "Убедиться, что внизу никого нет, на линии нет трещин и камнепада, и держать ледоруб готовым к задержанию",
    "q.l8#4.o2" to "Затянуть ремни рюкзака",
    "q.l8#4.o3" to "Сообщить близким маршрут",
    "q.l8#4.e" to "Скольжение — необратимое ускорение. До начала нужно исключить людей внизу, трещины и камнепад и держать ледоруб в руке: иначе при любой ошибке вам нечем замедлиться.",
    "q.l8#5.p" to "Как управлять усталостью связки на долгом спуске?",
    "q.l8#5.o0" to "Идти без остановок, сводя привалы к минимуму",
    "q.l8#5.o1" to "Делать короткие запланированные привалы, пить и есть, переоценивать состояние связки",
    "q.l8#5.o2" to "Ускориться, чтобы сократить время под опасностью",
    "q.l8#5.o3" to "Останавливаться только если кто-то травмирован",
    "q.l8#5.e" to "Спуск — это рискованная половина, и усталость её главный двигатель. Регулярные короткие привалы возвращают силы и позволяют заново прочитать погоду, маршрут и напарников — те оценки, которые на долгом выходе исчезают первыми.",
    "q.l8#6.p" to "[Порядок] Расставьте шаги подготовки спуска в разумном порядке.",
    "q.l8#6.o0" to "Определить линию спуска и точку приземления, убрать людей снизу",
    "q.l8#6.o1" to "Проверить, что верёвка, спусковое устройство, карабины и петли на месте",
    "q.l8#6.o2" to "Построить надёжную точку страховки или проверить существующую станцию",
    "q.l8#6.o3" to "Разобрать верёвку, чтобы не было узлов и перехлёстов, и начать спуск",
    "q.l8#6.e" to "Спуск отдаёт жизнь одной точке, поэтому порядок такой: решить, куда идём, проверить снаряжение, затем вложиться. Разбор верёвки так же важен: узел или перехлёст оставляет вас висеть на верёвке надолго.",
    "q.l8#7.p" to "Что в основном определяет выбор между дюльфером и спуском лазанием?",
    "q.l8#7.o0" to "Чем короче спуск, тем больше нужен дюльфер",
    "q.l8#7.o1" to "Сложность рельефа, доступные точки страховки и подготовка связки",
    "q.l8#7.o2" to "Погода",
    "q.l8#7.o3" to "Насколько новое снаряжение",
    "q.l8#7.e" to "Дюльфер быстр, но зависит от точек страховки и от исполнения; спуск лазанием медленнее, но автономен. Рельеф, надёжность точек и навык связки решают вместе. Помните, что у дюльфера высокая аварийность: запас на ошибку оператора очень мал.",
    "q.l8#8.p" to "Какое техническое снаряжение обычно нужно для дюльфера?",
    "q.l8#8.o0" to "Один карабин и одна петля",
    "q.l8#8.o1" to "Несколько карабинов, длинная петля или самостраховка, шнур прусика и так далее",
    "q.l8#8.o2" to "Только верёвка",
    "q.l8#8.o3" to "Только спусковое устройство",
    "q.l8#8.e" to "Руководства перечисляют несколько карабинов, длинную петлю или дайзи-чейн и шнур прусика. Спуск часто означает снятие точек страховки по ходу и всё равно требует дублирования: слишком мало снаряжения заставляет импровизировать высоко над землёй — именно там и рождаются аварии.",
    "q.l8#9.p" to "[Несколько ответов] Каковы главные риски на спуске?",
    "q.l8#9.o0" to "Отказ точки страховки",
    "q.l8#9.o1" to "Срыв с конца верёвки, потому что концы не были связаны",
    "q.l8#9.o2" to "Верёвка застревает или перехлёстывается",
    "q.l8#9.o3" to "Камнепад и люди внизу",
    "q.l8#9.o4" to "Спуск менее рискован, чем подъём, потому что помогает гравитация",
    "q.l8#9.e" to "Первые четыре — обычные причины аварий на дюльфере. Самая недооценённая — несвязанные концы: если верёвка коротка, а концы свободны, вы соскальзываете с неё незаметно и падаете. На усталом спуске эта ошибка особенно часта.",
    "q.l9#0.p" to "Какой узел привязывает верёвку к обвязке и обычно применяется на ледниковых маршрутах?",
    "q.l9#0.o0" to "Восьмёрка с повторным проходом",
    "q.l9#0.o1" to "Прямой узел",
    "q.l9#0.o2" to "Простой узел",
    "q.l9#0.o3" to "Булинь",
    "q.l9#0.e" to "Восьмёрка с повторным проходом прочна, хорошо читается и легко проверяется со стороны, а после нагрузки всё же развязывается. Прямой узел может ползти или затянуться под нагрузкой и никогда не должен нести жизнь.",
    "q.l9#1.p" to "Какой узел позволяет одной рукой регулировать длину при креплении верёвки к карабину?",
    "q.l9#1.o0" to "Двойной рыбацкий узел",
    "q.l9#1.o1" to "Узел «удавка»",
    "q.l9#1.o2" to "Узел «бабочка»",
    "q.l9#1.o3" to "Встречный узел",
    "q.l9#1.e" to "Удавку можно одной рукой подтягивать и отпускать на карабине до нужной длины — это стандартный способ самостраховки на станции. Двойной рыбацкий соединяет две верёвки, «бабочка» создаёт точку крепления в середине верёвки.",
    "q.l9#2.p" to "Какое главное свойство схватывающего узла, например прусика?",
    "q.l9#2.o0" to "Держит верёвку под нагрузкой и скользит по ней без нагрузки",
    "q.l9#2.o1" to "Может навсегда заменить основную верёвку",
    "q.l9#2.o2" to "Нужен только для украшения",
    "q.l9#2.o3" to "Сам развязывается под нагрузкой",
    "q.l9#2.e" to "Односторонний захват и делает схватывающие узлы пригодными для подъёма, для дублирования и для систем с выигрышем в силе. А поскольку надёжность зависит от диаметра шнура относительно верёвки и числа витков, проверяйте узел на месте, прежде чем на него полагаться.",
    "q.l9#3.p" to "Какой длины должен оставаться хвост после завязывания узла?",
    "q.l9#3.o0" to "Достаточно около 1 см",
    "q.l9#3.o1" to "Не меньше десяти диаметров верёвки",
    "q.l9#3.o2" to "Хвост не нужен",
    "q.l9#3.o3" to "Как можно длиннее — не меньше 1 м",
    "q.l9#3.e" to "Достаточный хвост — базовая защита от того, что узел поползёт под нагрузкой или распустится от тряски. Привыкайте и к взаимной проверке: узлы — единственная часть системы страховки, сделанная целиком руками, без заводского контроля.",
    "q.l9#4.p" to "Какой узел соединяет две верёвки или замыкает петлю прусика?",
    "q.l9#4.o0" to "Прямой узел",
    "q.l9#4.o1" to "Двойной рыбацкий узел",
    "q.l9#4.o2" to "Простой узел",
    "q.l9#4.o3" to "Булинь",
    "q.l9#4.e" to "Двойной рыбацкий очень стабилен и почти не распускается, но после нагрузки развязывается тяжело — поэтому он подходит для соединения верёвок и замыкания шнура в петлю. Прямой узел может ползти под нагрузкой, и нагружать его нельзя.",
    "q.l9#5.p" to "Почему надёжность схватывающего узла зависит от диаметра шнура?",
    "q.l9#5.o0" to "Диаметр не имеет значения",
    "q.l9#5.o1" to "Если шнур намного тоньше верёвки, площади контакта и силы прижима не хватает для захвата",
    "q.l9#5.o2" to "Чем тоньше шнур, тем лучше он держит",
    "q.l9#5.o3" to "Чем толще шнур, тем лучше он держит",
    "q.l9#5.e" to "Схватывающий узел держит за счёт обжатия основной верёвки. Слишком тонкий шнур — не хватает ни площади контакта, ни силы прижима; слишком толстый — не обхватывает плотно. Поэтому проверяйте сочетание каждый раз и тестируйте в безопасном месте, прежде чем на него рассчитывать.",
    "q.l9#6.p" to "Для чего в основном служит узел «бабочка»?",
    "q.l9#6.o0" to "Для соединения двух верёвок",
    "q.l9#6.o1" to "Для создания фиксированной петли в середине верёвки, воспринимающей нагрузку в нескольких направлениях",
    "q.l9#6.o2" to "Чтобы заменить восьмёрку при привязывании к обвязке",
    "q.l9#6.o3" to "Для замыкания петли прусика",
    "q.l9#6.e" to "«Бабочка» образует петлю в середине верёвки, которая держит нагрузку с любой стороны, — поэтому она нужна в связках, на леднике и в спасательных системах. Её также вяжут между участниками, чтобы добавить трение там, где верёвка лежит на снегу.",
    "q.l9#7.p" to "[Сопоставление] Соотнесите каждый узел с его основным назначением.",
    "q.l9#7.l0" to "Восьмёрка",
    "q.l9#7.r0" to "Обычное привязывание к точке страховки или обвязке",
    "q.l9#7.l1" to "Двойной рыбацкий узел",
    "q.l9#7.r1" to "Соединение двух верёвок или замыкание петли из шнура",
    "q.l9#7.l2" to "Схватывающий узел (прусик)",
    "q.l9#7.r2" to "Схватывающий узел: держит под нагрузкой, скользит без неё",
    "q.l9#7.l3" to "Булинь",
    "q.l9#7.r3" to "Крепление к точке страховки; также часто при швартовке лодки",
    "q.l9#7.e" to "Этих четырёх хватает почти для всего ледникового передвижения и базовой страховки. В руководствах их группируют по функции — привязаться к точке, соединить верёвки, схватывающий узел. Запоминать по функции получается гораздо прочнее, чем по форме.",
    "q.l9#8.p" to "Какое утверждение об узлах и прочности верёвки верно?",
    "q.l9#8.o0" to "Узлы не влияют на прочность верёвки",
    "q.l9#8.o1" to "Любой узел снижает прочность верёвки в этом месте, но в разной степени",
    "q.l9#8.o2" to "Узлы делают верёвку прочнее",
    "q.l9#8.o3" to "Правильно завязанный узел не влияет на прочность",
    "q.l9#8.e" to "В узле верёвка изгибается, и под нагрузкой волокна нагружаются неравномерно, поэтому прочность всегда падает — различается только величина. Именно поэтому в руководствах есть таблица потерь прочности по узлам: узел выбирают и по тому, как он работает, и по тому, сколько прочности он стоит.",
    "q.l9#9.p" to "В руководстве суть узлов сформулирована одной фразой: «Узел даёт верёвке ( ).»",
    "q.l9#9.a0" to "жизнь",
    "q.l9#9.a1" to "свою жизнь",
    "q.l9#9.e" to "В оригинале: «узел даёт верёвке жизнь». Это точно передаёт суть: сама по себе верёвка — просто линия, и только через узлы — соединение с точками страховки, станциями и другими верёвками — она становится системой, способной нести жизнь.",
    "q.l10#0.p" to "Каков оптимальный размер группы на леднике при движении в связке?",
    "q.l10#0.o0" to "2",
    "q.l10#0.o1" to "3",
    "q.l10#0.o2" to "6 и больше",
    "q.l10#0.o3" to "Один человек",
    "q.l10#0.e" to "Связка из трёх человек располагает людьми, чтобы построить станцию и организовать спасение, если один провалится в трещину. В двойке, если один провалился, второй должен одновременно задержать падение, построить станцию и вытаскивать — запаса почти нет.",
    "q.l10#1.p" to "Какое расстояние между участниками обычно на леднике?",
    "q.l10#1.o0" to "2–3 м",
    "q.l10#1.o1" to "8–12 м",
    "q.l10#1.o2" to "Больше 30 м",
    "q.l10#1.o3" to "Как можно короче",
    "q.l10#1.e" to "8–12 м дают партнёрам время и дистанцию, чтобы среагировать и задержать падение, и при этом позволяют переговариваться и действовать вместе. Слишком коротко — верёвки почти не остаётся на амортизацию рывка.",
    "q.l10#2.p" to "Что нужно связке, чтобы она действительно давала защиту?",
    "q.l10#2.o0" to "Достаточно привязаться — и ты в безопасности",
    "q.l10#2.o1" to "Партнёры, умеющие задерживать падение и строить страховку",
    "q.l10#2.o2" to "Достаточно длинная верёвка",
    "q.l10#2.o3" to "Достаточно большая группа",
    "q.l10#2.e" to "Безопасность в связке держится на двух действиях, выполняемых надёжно: задержать падение и закрепиться. Связка без навыка задержания и без техники станции — это просто несколько человек, связанных вместе и падающих в одну трещину.",
    "q.l10#3.p" to "Зачем вязать узлы (например, «бабочку») между участниками на леднике?",
    "q.l10#3.o0" to "Исключительно для красоты",
    "q.l10#3.o1" to "Чтобы добавить трение там, где верёвка идёт по снегу, и ограничить глубину падения",
    "q.l10#3.o2" to "Чтобы узнавать своих партнёров",
    "q.l10#3.o3" to "Чтобы верёвка была легче",
    "q.l10#3.e" to "Каждый узел создаёт дополнительную точку трения на снегу, заметно сокращает падение и даёт верхним партнёрам время построить страховку. Это очень дешёвый и очень эффективный тормоз.",
    "q.l10#4.p" to "Где должно находиться спасательное снаряжение при движении по леднику?",
    "q.l10#4.o0" to "На дне рюкзака",
    "q.l10#4.o1" to "Под рукой, готовое к применению в любой момент",
    "q.l10#4.o2" to "Оставлено в палатке в лагере",
    "q.l10#4.o3" to "Отдано партнёру",
    "q.l10#4.e" to "Золотое время при спасении из трещины — несколько минут. Если шнуры для прусика, карабины и ледобуры лежат на дне рюкзака, пока вы их достанете, партнёр может получить переохлаждение, а верёвка — перепилить край трещины.",
    "q.l10#5.p" to "В чём главный риск связки из двух человек по сравнению с тремя?",
    "q.l10#5.o0" to "Она движется медленнее",
    "q.l10#5.o1" to "Если один падает, оставшийся не может одновременно держать рывок и организовывать спасение",
    "q.l10#5.o2" to "Верёвки не хватает по длине",
    "q.l10#5.o3" to "Нужно нести больше снаряжения",
    "q.l10#5.e" to "В двойке, если один провалился в трещину, второй должен одновременно удерживать его, строить станцию и работать с системой вытаскивания — запаса почти нет. Если идти вдвоём, выбирайте более консервативный маршрут и планируйте дальше вперёд.",
    "q.l10#6.p" to "Почему нельзя по желанию отвязываться при движении по леднику?",
    "q.l10#6.o0" to "Потому что отвязываться и привязываться заново — хлопотно",
    "q.l10#6.o1" to "Потому что риск в трещинном рельефе постоянен: в момент, когда вы отвязались, защиты нет",
    "q.l10#6.o2" to "Потому что верёвка может потеряться",
    "q.l10#6.o3" to "Потому что партнёры будут ворчать",
    "q.l10#6.e" to "Риск на леднике распределён неравномерно и плохо предсказуем, а отвязываются обычно из ошибочного чувства, что «этот участок нормальный». Если отвязаться действительно нужно, сначала остановитесь, оцените рельеф и снег и действуйте всей группой.",
    "q.l10#7.p" to "[Сопоставление] Соотнесите международные команды в связке с их значением.",
    "q.l10#7.l0" to "On belay",
    "q.l10#7.r0" to "Страховка готова, можно начинать",
    "q.l10#7.l1" to "Climbing",
    "q.l10#7.r1" to "Я начинаю подъём",
    "q.l10#7.l2" to "Falling",
    "q.l10#7.r2" to "Я падаю (предупреждение)",
    "q.l10#7.l3" to "Off belay",
    "q.l10#7.r3" to "Страховка снята, страховка окончена",
    "q.l10#7.e" to "Система команд работает потому, что не требует объяснений. На высоте ветер громкий, а расстояния большие, поэтому короткие слова с одинаковым смыслом для обеих сторон убирают двусмысленность. Самый опасный момент в страховке — когда каждый считает, что другой знает. В руководствах перечислены международные команды, потому что это минимальное соглашение между группами и языками.",
    "q.l10#8.p" to "Какое базовое техническое снаряжение нужно страхующему?",
    "q.l10#8.o0" to "Обвязка, карабин, спусковое устройство, перчатки, каска",
    "q.l10#8.o1" to "Только спусковое устройство и карабин",
    "q.l10#8.o2" to "Каска и солнцезащитные очки",
    "q.l10#8.o3" to "Обвязка и верёвка",
    "q.l10#8.e" to "Список выглядит простым, но у каждого отсутствующего предмета есть конкретное последствие: без перчаток обожжёте руки и потеряете контроль над верёвкой; без каски нечем ответить на камнепад. Страхующий — тот, кто ловит других, поэтому своё снаряжение должно быть собрано первым.",
    "q.l10#9.p" to "Зачем делать взаимную проверку перед началом подъёма?",
    "q.l10#9.o0" to "Потому что этого требует дисциплина в группе",
    "q.l10#9.o1" to "Потому что ошибки в обвязке, узле и спусковом устройстве часто не видны тому, кто их надел",
    "q.l10#9.o2" to "Чтобы отметить прогресс",
    "q.l10#9.o3" to "Чтобы размяться",
    "q.l10#9.e" to "Проверяя себя, вы видите то, что, как вам кажется, вы завязали. Партнёр смотрит сзади и сбоку — туда, куда вы не видите. В руководствах взаимная проверка стоит первой в теме общения на страховке: она использует чужие глаза, чтобы закрыть вашу слепую зону.",
    "q.l11#0.p" to "В принципах SRENE что означает буква R?",
    "q.l11#0.o0" to "Rapid",
    "q.l11#0.o1" to "Redundant",
    "q.l11#0.o2" to "Rope",
    "q.l11#0.o3" to "Rigid",
    "q.l11#0.e" to "Redundant означает, что в системе несколько независимых точек страховки, поэтому при отказе любой из них остальные принимают нагрузку. Это важнейший элемент надёжности станции.",
    "q.l11#1.p" to "Что означает принцип No Extension (без удлинения)?",
    "q.l11#1.o0" to "Чем длиннее верёвка, тем лучше",
    "q.l11#1.o1" to "При отказе одной точки система не должна удлиняться и давать рывок на остальные",
    "q.l11#1.o2" to "Станцию не следует строить низко",
    "q.l11#1.o3" to "Запасное снаряжение не нужно",
    "q.l11#1.e" to "Если между точками есть слабина, при отказе нагрузка падает на оставшиеся точки как внезапный рывок, гораздо больший статической нагрузки. No Extension означает выравнивание и предварительное натяжение, чтобы рывок вообще не возникал в системе.",
    "q.l11#2.p" to "В чём основная идея построения станции?",
    "q.l11#2.o0" to "Использовать как можно меньше снаряжения",
    "q.l11#2.o1" to "Отказ одной точки не должен разрушать всю систему",
    "q.l11#2.o2" to "Строить как можно выше",
    "q.l11#2.o3" to "Использовать только самую толстую верёвку",
    "q.l11#2.e" to "Скальные и снежные точки никогда не бывают абсолютно надёжными, поэтому систему строят с допуском на ошибку: ни один единичный отказ не должен быть смертельным — это даёт время на реакцию и запасной вариант.",
    "q.l11#3.p" to "Какие два измерения EARNEST добавляет к SRENE?",
    "q.l11#3.o0" to "Efficient и Timely",
    "q.l11#3.o1" to "Easy и Tight",
    "q.l11#3.o2" to "Equal и Nice",
    "q.l11#3.o3" to "Empty и True",
    "q.l11#3.e" to "Станция должна быть не только надёжной, но и собираться быстро и просто в обращении — потому что время на её сборку и есть время под риском. Именно здесь EARNEST ближе к реальному рельефу, чем SRENE.",
    "q.l11#4.p" to "От чего в основном зависит надёжность снежной точки страховки?",
    "q.l11#4.o0" to "От марки снаряжения",
    "q.l11#4.o1" to "От качества снега и от того, насколько хорошо она закопана",
    "q.l11#4.o2" to "От цвета верёвки",
    "q.l11#4.o3" to "От высоты",
    "q.l11#4.e" to "Один и тот же ледоруб или снежный анкер держит совершенно разные нагрузки в глубоком снегу, в мокром снегу и на краю снежного моста. Снежные точки требуют оценки снежного покрова на месте — фиксированный алгоритм здесь не работает.",
    "q.l11#5.p" to "Зачем нужно выравнивание нагрузки на станции?",
    "q.l11#5.o0" to "Чтобы станция выглядела аккуратно",
    "q.l11#5.o1" to "Чтобы нагрузка распределялась между точками по расчёту и ни одна не была перегружена",
    "q.l11#5.o2" to "Чтобы сэкономить снаряжение",
    "q.l11#5.o3" to "Чтобы её было легче разобрать",
    "q.l11#5.e" to "Выравнивание означает, что каждая точка несёт близкую к расчётной нагрузку, а не одна берёт всё. Если точка доходит до предела и отказывает, нагрузка мгновенно переходит на остальные и может запустить цепной отказ.",
    "q.l11#6.p" to "Что из этого нарушает принцип резервирования?",
    "q.l11#6.o0" to "Использование элементов разной прочности",
    "q.l11#6.o1" to "Две точки страховки, которые фактически зависят от одной трещины или одного блока",
    "q.l11#6.o2" to "Соединение точек стропами",
    "q.l11#6.o3" to "Установка трёх точек страховки",
    "q.l11#6.e" to "Резервирование требует, чтобы каждая точка отказывала независимо. Если две точки делят одну трещину, раскрытие трещины выводит обе сразу — выглядит как две, работает как одна. Такое ложное резервирование встречается часто и убивает.",
    "q.l11#7.p" to "[Сопоставление] Соотнесите каждый критерий оценки станции с его смыслом.",
    "q.l11#7.l0" to "S (Solid)",
    "q.l11#7.r0" to "Прочно: каждая точка выдерживает ожидаемую нагрузку",
    "q.l11#7.l1" to "R (Redundant)",
    "q.l11#7.r1" to "Резервирование: несколько независимых точек страховки",
    "q.l11#7.l2" to "E (Equalized)",
    "q.l11#7.r2" to "Выравнивание: нагрузка разумно распределена между точками",
    "q.l11#7.l3" to "No Extension",
    "q.l11#7.r3" to "Без удлинения: отказ не создаёт удлинения с рывком",
    "q.l11#7.e" to "Эти четыре образуют базовую схему, сокращённо SRENE. Порядок стоит запомнить: сначала спросите, прочна ли каждая точка, затем — резервирована ли система; если отдельная точка ненадёжна, обсуждать резервирование бессмысленно.",
    "q.l11#8.p" to "Судя по цифрам нагрузки, к какому углу между ветвями стропы нужно стремиться?",
    "q.l11#8.o0" to "В пределах 60°",
    "q.l11#8.o1" to "В пределах 90°",
    "q.l11#8.o2" to "В пределах 120°",
    "q.l11#8.o3" to "Угол не влияет на нагрузку",
    "q.l11#8.e" to "При 0° каждая точка несёт около 50%, при 60° — около 58%, при 90° — около 71%: чем шире угол, тем большую нагрузку от веса одного человека получает каждая точка. Правило «держать в пределах 60°» прямо следует из этих цифр.",
    "q.l11#9.p" to "Почему эффективность и своевременность входят в оценку станции?",
    "q.l11#9.o0" to "Чтобы работа выглядела лучше",
    "q.l11#9.o1" to "Потому что сборка станции сама по себе — время под риском",
    "q.l11#9.o2" to "Чтобы сэкономить снаряжение",
    "q.l11#9.o3" to "Чтобы было легче учить",
    "q.l11#9.e" to "Пока вы строите станцию, вы часто без страховки или со слабой страховкой. Чем короче это время, тем ниже риск, — поэтому «быстро собирается, просто в обращении» не лень, а часть критерия безопасности.",
    "q.l11#10.p" to "[Множественный выбор] Как выглядит достаточная станция?",
    "q.l11#10.o0" to "Каждая точка страховки прочна сама по себе",
    "q.l11#10.o1" to "Точки отказывают независимо друг от друга",
    "q.l11#10.o2" to "Нагрузка разумно распределена между точками",
    "q.l11#10.o3" to "В системе оставлена слабина для амортизации рывка",
    "q.l11#10.e" to "Первые три — требования, последнее — наоборот. У станции не должно быть удлинения, а не запаса слабины: слабина позволяет отказу одной точки дать рывок на остальные, а рывковые нагрузки гораздо больше статических.",
    "q.l11#11.p" to "Если условия позволяют только одну точку страховки, как поступить правильно?",
    "q.l11#11.o0" to "Отказаться от подъёма и вернуться тем же путём",
    "q.l11#11.o1" to "Сделать её как можно надёжнее и свести к минимуму время, которое система на ней висит",
    "q.l11#11.o2" to "Добавить хоть какую-то вторую точку, чтобы их стало две",
    "q.l11#11.o3" to "Привязать верёвку прямо к обвязке",
    "q.l11#11.e" to "Ситуации с одной точкой действительно бывают — например, один хороший ледобур. Честный подход — признать, что запаса нет: сделать эту точку максимально хорошей и быстро провести людей мимо, а не добавлять бесполезную вторую точку, создающую ложную уверенность.",
    "q.l12#0.p" to "Ваш партнёр провалился в трещину. Каков первый шаг?",
    "q.l12#0.o0" to "Прыгнуть за ним",
    "q.l12#0.o1" to "Занять положение задержания, построить станцию и перенести на неё нагрузку",
    "q.l12#0.o2" to "Сначала позвать помощь",
    "q.l12#0.o3" to "Перерезать верёвку",
    "q.l12#0.e" to "Сейчас на вас весь вес упавшего. Сначала задержите его, чтобы удержаться самому, затем постройте независимую станцию и перенесите нагрузку — только тогда руки свободны для спасательной системы. Прыжок вниз или перерезанная верёвка мгновенно ухудшают всё.",
    "q.l12#1.p" to "Какая система выигрыша в силе чаще всего применяется для вытаскивания?",
    "q.l12#1.o0" to "Прямое вытягивание 1:1",
    "q.l12#1.o1" to "Система Z 3:1 (Z-drag)",
    "q.l12#1.o2" to "Система 10:1",
    "q.l12#1.o3" to "Выигрыш не нужен",
    "q.l12#1.e" to "Система Z 3:1 использует прусик и один блок, давая тройной выигрыш в силе. Она проста, быстро собирается и требует мало снаряжения — поэтому является стандартом спасения из трещины.",
    "q.l12#2.p" to "Почему снежные мосты особенно опасны?",
    "q.l12#2.o0" to "Потому что они всегда шумят",
    "q.l12#2.o1" to "Потому что под свежим снегом они выглядят как обычный грунт и их трудно распознать",
    "q.l12#2.o2" to "Потому что они появляются только ночью",
    "q.l12#2.o3" to "Потому что они всегда тонкие",
    "q.l12#2.e" to "Снежный мост — самая скрытая опасность ледника: поверхность выглядит ровной и толстой, а под ней пустота. Оценить его значит читать линии трещин, структуру снежного покрова и сезон — именно поэтому по такому рельефу идут в связке.",
    "q.l12#3.p" to "В каком состоянии должна быть верёвка при переходе через трещинный рельеф?",
    "q.l12#3.o0" to "Полностью ослаблена для свободы движения",
    "q.l12#3.o1" to "Умеренно натянута, без больших провисающих петель",
    "q.l12#3.o2" to "Как можно туже",
    "q.l12#3.o3" to "Связка не нужна",
    "q.l12#3.e" to "Слабина позволяет упавшему свободно пролететь до нагружения верёвки, умножая удар и повышая шанс, что верёвка перепилит край. Умеренное натяжение включает задержание раньше и снижает этот риск.",
    "q.l12#4.p" to "Как безопаснее всего переходить снежный мост?",
    "q.l12#4.o0" to "Пробежать одному и быстро",
    "q.l12#4.o1" to "Идти в связке с натянутой верёвкой: один переходит, остальные готовы задержать",
    "q.l12#4.o2" to "Избегать любого снежного моста",
    "q.l12#4.o3" to "Сильно потоптаться для проверки, потом перейти",
    "q.l12#4.e" to "Снежный мост нельзя оценить на глаз. Связка и готовность задержать превращают неопределённость в управляемый риск. Проверка топтанием может просто обрушить мост под вами.",
    "q.l12#5.p" to "Пока партнёр висит на верёвке в трещине, в чём главная опасность?",
    "q.l12#5.o0" to "Что партнёр уснёт внизу",
    "q.l12#5.o1" to "Что нагруженная верёвка перепилит снежный край и внезапно лопнет",
    "q.l12#5.o2" to "Что выпадет снаряжение",
    "q.l12#5.o3" to "Что резко изменится погода",
    "q.l12#5.e" to "Нагруженная верёвка ходит туда-сюда по краю, прорезая всё более глубокую борозду. Это главный источник цейтнота при спасении: нужно вытащить или перенести нагрузку на надёжную станцию раньше, чем край будет перепилен.",
    "q.l12#6.p" to "Зачем при сборке Z-системы на прусиках нужен дублирующий узел?",
    "q.l12#6.o0" to "Чтобы система выглядела полной",
    "q.l12#6.o1" to "Если основной прусик откажет, вы мгновенно теряете выигрыш и человек снова падает",
    "q.l12#6.o2" to "Чтобы добавить трение",
    "q.l12#6.o3" to "Чтобы сэкономить верёвку",
    "q.l12#6.e" to "Прусик держит за счёт трения, а лёд, грязь или износ верёвки могут его подвести. Дублирующий прусик примет нагрузку при отказе основного и предотвратит второе падение с новыми травмами и задержкой.",
    "q.l12#7.p" to "[Порядок] Расставьте стандартную последовательность спасения из трещины по порядку.",
    "q.l12#7.o0" to "Сразу занять задержание и удержаться",
    "q.l12#7.o1" to "Построить независимую станцию",
    "q.l12#7.o2" to "Перенести вес с тела на станцию",
    "q.l12#7.o3" to "Вытаскивать системой 3:1",
    "q.l12#7.e" to "Эти четыре шага нельзя менять местами. Третий чаще всего пропускают: без переноса нагрузки вы продолжаете держать партнёра телом и не имеете свободных рук для системы — самая частая причина неудачи спасения.",
    "q.l12#8.p" to "Что должен делать человек в трещине?",
    "q.l12#8.o0" to "Сильно трясти верёвку, чтобы привлечь внимание",
    "q.l12#8.o1" to "Сохранять спокойствие, пытаться подняться прусиком и не давать верёвке дальше пилить край",
    "q.l12#8.o2" to "Сразу отвязаться",
    "q.l12#8.o3" to "Спускаться вниз в поисках выхода",
    "q.l12#8.e" to "Помощь упавшего сильно облегчает спасение. Тряска верёвки усиливает перепиливание, а отвязывание обрывает единственную связь. Стойте спокойно, уменьшайте перепиливание и, если возможно, примите часть веса на прусик.",
    "q.l12#9.p" to "[Множественный выбор] Что из спасательного снаряжения должно быть на себе и под рукой на леднике?",
    "q.l12#9.o0" to "Шнур для прусика",
    "q.l12#9.o1" to "Карабины и блок",
    "q.l12#9.o2" to "Снежный анкер или ледобур",
    "q.l12#9.o3" to "Стропы",
    "q.l12#9.o4" to "Треккинговые палки",
    "q.l12#9.e" to "Вместе эти четыре дают импровизированную систему: шнур для прусика — односторонний захват, карабины и блок — выигрыш в силе, анкер или ледобур — станция, стропы — соединение и удлинение. Ключевое слово — под рукой: снаряжение на дне рюкзака можно считать отсутствующим.",
    "q.l12#10.p" to "Почему перед вытаскиванием нужно перенести нагрузку на станцию?",
    "q.l12#10.o0" to "Чтобы распределить нагрузку по верёвке равномернее",
    "q.l12#10.o1" to "Потому что иначе руки заняты удержанием и не могут работать с системой",
    "q.l12#10.o2" to "Чтобы сэкономить силы",
    "q.l12#10.o3" to "Чтобы защитить верёвку",
    "q.l12#10.e" to "Когда на вас весь вес упавшего, вы вынуждены держать задержание и не можете ни освободить руки, ни работать ровно. Передать нагрузку станции — единственный способ перестать быть живой станцией и стать оператором.",
    "q.l12#11.p" to "Какую роль играет прусик в спасательной системе?",
    "q.l12#11.o0" to "Декоративную",
    "q.l12#11.o1" to "Односторонний захват — держит под нагрузкой и скользит по свободной верёвке",
    "q.l12#11.o2" to "Повышает прочность верёвки",
    "q.l12#11.o3" to "Защищает от воды",
    "q.l12#11.e" to "Односторонний захват и делает возможной систему выигрыша в силе: прусик продвигается по верёвке, но не идёт назад под нагрузкой. Его надёжность зависит от диаметра шнура и числа витков, поэтому проверяйте его до того, как на него положитесь.",
    "q.l13#0.p" to "По критериям Лейк-Луизы, какой симптом обязателен для диагноза AMS?",
    "q.l13#0.o0" to "Головная боль плюс хотя бы один из: тошнота, головокружение, усталость или бессонница",
    "q.l13#0.o1" to "Только кашель",
    "q.l13#0.o2" to "Только боль в ногах",
    "q.l13#0.o3" to "Только улучшившийся аппетит",
    "q.l13#0.e" to "Головная боль — ключевой симптом AMS. Усталость или бессонница сами по себе недостаточны: они должны идти вместе с головной болью. Практическая ценность критериев в том, что вы можете оценить себя в лагере и действовать по результату.",
    "q.l13#1.p" to "Как правильно действовать при появлении симптомов AMS?",
    "q.l13#1.o0" to "Принять обезболивающее и продолжить подъём по плану",
    "q.l13#1.o1" to "Прекратить подъём; при ухудшении немедленно спускаться",
    "q.l13#1.o2" to "Выпить больше кофе для бодрости и идти дальше",
    "q.l13#1.o3" to "Игнорировать и терпеть",
    "q.l13#1.e" to "AMS может перейти в смертельные HACE или HAPE. Остановка подъёма даёт телу время адаптироваться; как только симптомы усиливаются, спуск — единственное надёжное лечение. Любой план «дотерпеть» — ставка на собственную жизнь.",
    "q.l13#2.p" to "После обезболивающего головная боль прошла. Можно продолжать подъём?",
    "q.l13#2.o0" to "Да, симптом ушёл",
    "q.l13#2.o1" to "Нет — маскировка симптома не значит, что организм акклиматизировался",
    "q.l13#2.o2" to "Да, но идти медленнее",
    "q.l13#2.o3" to "Да, если пить больше воды",
    "q.l13#2.e" to "Обезболивающее подавляет сигнал, а физиологический стресс высоты продолжается. Подъём под этим прикрытием позволяет AMS перейти в HACE или HAPE без предупреждения.",
    "q.l13#3.p" to "Через сколько после прибытия на высоту обычно появляются симптомы AMS?",
    "q.l13#3.o0" to "Сразу",
    "q.l13#3.o1" to "6–12 часов",
    "q.l13#3.o2" to "Через три дня",
    "q.l13#3.o3" to "Через неделю",
    "q.l13#3.e" to "Время имеет значение: симптомы часто начинаются после того, как вы дошли до лагеря, поужинали и готовитесь ко сну, — а ночью их легче всего не заметить и именно ночью они чаще усиливаются.",
    "q.l13#4.p" to "Как правильно вести лёгкую AMS в полевых условиях?",
    "q.l13#4.o0" to "Продолжать подъём по плану",
    "q.l13#4.o1" to "Прекратить набор высоты, отдыхать на текущей высоте и спускаться, если симптомы сохраняются или усиливаются",
    "q.l13#4.o2" to "Принять обезболивающее и продолжать подъём",
    "q.l13#4.o3" to "Немедленно спуститься на 2 000 м",
    "q.l13#4.e" to "При лёгкой AMS первое — прекратить подъём и дать телу время. Обезболивающее облегчает головную боль, но не влияет на акклиматизацию. Если после отдыха симптомы сохраняются или усиливаются, спуск — единственное надёжное лечение.",
    "q.l13#5.p" to "Почему принцип «высоко подняться, низко спать» улучшает акклиматизацию?",
    "q.l13#5.o0" to "Потому что днём теплее",
    "q.l13#5.o1" to "Дневная гипоксия даёт стимул, а возвращение ниже на ночёвку сохраняет качество сна",
    "q.l13#5.o2" to "Потому что несёшь меньше снаряжения",
    "q.l13#5.o3" to "Потому что ночью идти безопаснее",
    "q.l13#5.e" to "Акклиматизации нужен гипоксический стресс, но качество сна тоже необходимо: сильная ночная гипоксия усиливает периодическое дыхание и симптомы. «Высоко подняться, низко спать» примиряет эти две вещи — поэтому работает лучше, чем постоянное пребывание на высоте.",
    "q.l13#6.p" to "Каково худшее последствие продолжения подъёма при AMS?",
    "q.l13#6.o0" to "Вы почувствуете чуть большую усталость",
    "q.l13#6.o1" to "Переход в HACE или HAPE, которые могут стать смертельными в течение часов",
    "q.l13#6.o2" to "Ухудшение аппетита",
    "q.l13#6.o3" to "Плохой сон",
    "q.l13#6.e" to "AMS обычно проходит при отдыхе или спуске, но может быть предвестником критического состояния. Именно поэтому «не поднимайся с симптомами» повторяют так часто: это блокирует первое звено всей цепи ухудшения.",
    "q.l13#7.p" to "Оценивая, усиливается ли AMS, за чем нужно следить в первую очередь?",
    "q.l13#7.o0" to "Прошла ли головная боль",
    "q.l13#7.o1" to "Прогрессивно ли усиливаются симптомы, особенно сознание, походка и дыхание",
    "q.l13#7.o2" to "Нормальна ли температура тела",
    "q.l13#7.o3" to "Вырос ли показатель кислорода",
    "q.l13#7.e" to "Переход от AMS к HACE/HAPE виден по трём измерениям: сознание, походка и дыхание. Следить за этими тремя надёжнее, чем за отдельным симптомом или одной цифрой пульсоксиметра.",
    "q.l13#8.p" to "Что типично для головной боли при AMS?",
    "q.l13#8.o0" to "Обычно это первый симптом",
    "q.l13#8.o1" to "Она появляется только ночью",
    "q.l13#8.o2" to "Она появляется только при нагрузке",
    "q.l13#8.o3" to "Обычно это последний появляющийся симптом",
    "q.l13#8.e" to "Головная боль часто бывает самым ранним сигналом и входит в критерии Лейк-Луизы как обязательный элемент. Поскольку она очень распространена, её легко списать на обычную усталость, — поэтому важен контекст: она появилась после набора высоты.",
    "q.l13#9.p" to "Когда ацетазоламид используют для профилактики высотной болезни, какую схему рекомендует руководство?",
    "q.l13#9.o0" to "250 мг три раза в день",
    "q.l13#9.o1" to "125 мг два раза в день, начиная примерно за день до подъёма и заканчивая примерно через два дня после",
    "q.l13#9.o2" to "500 мг один раз в день",
    "q.l13#9.o3" to "Только после появления симптомов",
    "q.l13#9.e" to "Следуя новым медицинским рекомендациям, доза — 125 мг два раза в день, ниже прежних 250 мг три раза в день. Меньшая доза работает, но реже даёт тяжёлые побочные эффекты. Препарат рецептурный, и принимать его нужно по назначению врача.",
    "q.l13#10.p" to "Почему облегчение симптомов после лекарства не повод продолжать подъём?",
    "q.l13#10.o0" to "Потому что препарат создаёт иллюзию",
    "q.l13#10.o1" to "Потому что препарат снимает симптомы, но не улучшает акклиматизацию к гипоксии",
    "q.l13#10.o2" to "Потому что препарат перестаёт действовать",
    "q.l13#10.o3" to "Потому что дозу приходится постоянно увеличивать",
    "q.l13#10.e" to "Это главная мысль в тактике высотной болезни: симптом — это сигнализация, а не сама болезнь. Лекарство выключает сигнализацию, а физиологический стресс гипоксии продолжает накапливаться — подъём под этим прикрытием позволяет болезни развиваться незаметно.",
    "q.l13#11.p" to "[Множественный выбор] Какие состояния легко спутать с AMS и нужно тщательно различать?",
    "q.l13#11.o0" to "Обезвоживание",
    "q.l13#11.o1" to "Инфекции верхних дыхательных путей, например простуда",
    "q.l13#11.o2" to "Переутомление",
    "q.l13#11.o3" to "Недостаток сна",
    "q.l13#11.o4" to "Снежная слепота (ультрафиолетовый кератит)",
    "q.l13#11.e" to "Все четыре дают головную боль, усталость, тошноту или плохой сон — сильное пересечение с AMS. Полезные различия: появились ли симптомы вместе с набором высоты, проходят ли они при отдыхе и изменились ли походка или сознание.",
    "q.l13#12.p" to "По клиническим данным и источникам для гидов, примерно какая доля людей выше 4 000 м заболевает острой горной болезнью?",
    "q.l13#12.o0" to "5–10 %",
    "q.l13#12.o1" to "20–30 %",
    "q.l13#12.o2" to "50–65 %",
    "q.l13#12.o3" to "Почти 100 %",
    "q.l13#12.e" to "Чем выше и быстрее подъём, тем чаще: около 50–65 % людей выше 4 000 м заболевают острой горной болезнью, а исследования на 2 500–4 300 м дают примерно 25–43 %. То есть высотная болезнь — норма, а не исключение, и поэтому запланированная акклиматизация — необходимость, а не перестраховка.",
    "q.l13#13.p" to "Какое утверждение о возрасте и риске высотной болезни верно?",
    "q.l13#13.o0" to "Молодые не болеют высотной болезнью",
    "q.l13#13.o1" to "Чем старше, тем выше должен быть риск",
    "q.l13#13.o2" to "Возраст существенно не повышает риск; важны скорость подъёма и высота ночёвок",
    "q.l13#13.o3" to "Болеют только нетренированные",
    "q.l13#13.e" to "Исследования показывают, что пожилые треккеры на средней высоте (в среднем 65 лет) болеют с той же частотой, что и молодые. Риск определяют скорость подъёма, высота ночёвок и индивидуальная физиология — списывать всё на возраст или форму опасно.",
    "q.l14#0.p" to "Какие признаки должны включить тревогу по HACE?",
    "q.l14#0.o0" to "Неустойчивая походка (не может идти по прямой) и изменённое сознание",
    "q.l14#0.o1" to "Слабая головная боль",
    "q.l14#0.o2" to "Слегка ухудшившийся аппетит",
    "q.l14#0.o3" to "Лёгкая ломота в ногах",
    "q.l14#0.e" to "Атаксия и изменённое сознание — ключевые маркеры HACE: отёк мозга уже влияет на движение и мышление. При таких признаках нужно немедленно спускаться и обращаться за медицинской помощью — больше никакого «понаблюдаем».",
    "q.l14#1.p" to "Какой самый характерный ранний признак HAPE?",
    "q.l14#1.o0" to "Одышка в покое с резким падением работоспособности",
    "q.l14#1.o1" to "Слегка заложенный нос",
    "q.l14#1.o2" to "Лёгкое онемение пальцев",
    "q.l14#1.o3" to "Жажда",
    "q.l14#1.e" to "Для HAPE характерно, что человек задыхается даже в покое. В отличие от простой усталости это не проходит с отдыхом, а продолжает усиливаться и может дойти до пенистой мокроты и синюшности — сигнал немедленно спускаться.",
    "q.l14#2.p" to "Каково основное лечение HACE и HAPE?",
    "q.l14#2.o0" to "Принять обезболивающее и продолжать подъём",
    "q.l14#2.o1" to "Немедленно спуститься на меньшую высоту, с кислородом и другими поддерживающими мерами",
    "q.l14#2.o2" to "Отдыхать на месте два дня",
    "q.l14#2.o3" to "Пить больше воды и больше спать",
    "q.l14#2.e" to "Спуск — единственная мера, которая надёжно обращает болезнь, потому что убирает причину — гипоксию. Кислород, гипербарическая камера и лекарства — вспомогательные средства, выигрывающие время, когда спуск нельзя начать сразу.",
    "q.l14#3.p" to "По клиническим источникам, какова обычная схема дексаметазона для лечения HACE?",
    "q.l14#3.o0" to "8–10 мг вначале, затем 4 мг каждые 6 часов",
    "q.l14#3.o1" to "2 мг один раз в день",
    "q.l14#3.o2" to "10 мг каждые 2 часа",
    "q.l14#3.o3" to "Только если пациент без сознания",
    "q.l14#3.e" to "Это лечебная доза, и давать её нужно под медицинским контролем. Препарат выигрывает время для спуска, но никогда его не заменяет. Спуск остаётся основным лечением и для HACE, и для HAPE.",
    "q.l14#4.p" to "Как часто HAPE и HACE встречаются вместе?",
    "q.l14#4.o0" to "Почти никогда",
    "q.l14#4.o1" to "Около 13–20 % случаев HAPE сопровождаются HACE",
    "q.l14#4.o2" to "В 100 % случаев",
    "q.l14#4.o3" to "Только у детей",
    "q.l14#4.e" to "Цифра показывает, что две критические формы высотной болезни часто идут вместе. Поэтому при признаках отёка лёгких проверяйте ещё и сознание с походкой, готовьтесь к худшему и спускайтесь немедленно.",
    "q.l14#5.p" to "Если участник больше не может идти, что в приоритете?",
    "q.l14#5.o0" to "Уговорить его идти дальше",
    "q.l14#5.o1" to "Организовать переноску, дать кислород, рассмотреть гипербарическую камеру и спускаться как можно быстрее",
    "q.l14#5.o2" to "Отдыхать на месте и ждать восстановления",
    "q.l14#5.o3" to "Сначала вернуться в лагерь за снаряжением",
    "q.l14#5.e" to "Потеря способности идти означает критическое состояние. Тогда спуск зависит от того, понесут ли пациента товарищи, или от внешнего спасения, — значит, настоящая стратегия безопасности в том, чтобы вообще никого не довести до этого, и в этом ценность раннего распознавания AMS.",
    "q.l14#6.p" to "Что делает портативная гипербарическая камера (например, мешок Гамова)?",
    "q.l14#6.o0" to "Полностью излечивает высотную болезнь",
    "q.l14#6.o1" to "Имитирует меньшую высоту, чтобы стабилизировать пациента, когда немедленный спуск невозможен",
    "q.l14#6.o2" to "Заменяет спуск",
    "q.l14#6.o3" to "В основном даёт тепло",
    "q.l14#6.e" to "Гипербарическая камера выигрывает время; это не конечная точка лечения. Она сдерживает болезнь в плохую погоду, при ожидании вертолёта или когда спуск нельзя начать сразу, — но в итоге спуск всё равно необходим.",
    "q.l14#7.p" to "Каково правильное отношение к лекарствам от высотной болезни?",
    "q.l14#7.o0" to "Если симптомы ослабли, продолжать подъём",
    "q.l14#7.o1" to "Это вспомогательное средство, выигрывающее время, применяется по назначению врача и никогда не заменяет спуск",
    "q.l14#7.o2" to "Их можно свободно раздавать товарищам",
    "q.l14#7.o3" to "Чем раньше, тем лучше, медицинская оценка не нужна",
    "q.l14#7.e" to "У этих препаратов есть конкретные показания, противопоказания и побочные эффекты, а подъём под их прикрытием скрывает признаки ухудшения. Стандарт — применение после врачебной оценки, при этом спуск остаётся основным лечением.",
    "q.l14#8.p" to "Какая доза дексаметазона обычна при высотном отёке головного мозга?",
    "q.l14#8.o0" to "20 мг каждые 12 часов",
    "q.l14#8.o1" to "4 мг каждые 6 часов",
    "q.l14#8.o2" to "8 мг один раз в день",
    "q.l14#8.o3" to "10 мг каждые 2 часа",
    "q.l14#8.e" to "Руководство приводит 4 мг каждые 6 часов. Препарат снижает внутричерепное давление и уменьшает отёк мозга, обычно с заметным улучшением в течение шести часов, — но он лишь выигрывает время для спуска и никогда его не заменяет.",
    "q.l14#9.p" to "Лечит ли дексаметазон высотный отёк лёгких?",
    "q.l14#9.o0" to "Да, это препарат первого выбора",
    "q.l14#9.o1" to "Нет, на отёк лёгких он не действует",
    "q.l14#9.o2" to "Да, но дозу нужно удвоить",
    "q.l14#9.o3" to "Действует только у детей",
    "q.l14#9.e" to "Это легко спутать: дексаметазон нацелен на отёк мозга и неэффективен при отёке лёгких, а нифедипин нацелен на отёк лёгких и слабо влияет на отёк мозга. Двум критическим состояниям нужны разные препараты — не тот препарат означает отсутствие лечения.",
    "q.l14#10.p" to "При высотном отёке лёгких какова рекомендуемая схема нифедипина и его важный побочный эффект?",
    "q.l14#10.o0" to "20–30 мг пролонгированного действия каждые 12 часов; давление может резко упасть, поэтому быстрый подъём с места может вызвать обморок",
    "q.l14#10.o1" to "4 мг каждые 6 часов; вызывает сонливость",
    "q.l14#10.o2" to "125 мг один раз в день; повышает давление",
    "q.l14#10.o3" to "Только внутривенно; побочных эффектов нет",
    "q.l14#10.e" to "Нифедипин снимает гипоксическую вазоконстрикцию лёгких и применяется для профилактики и лечения отёка лёгких. Побочный эффект очень практичен: давление может быстро упасть, поэтому при вставании из положения сидя или лёжа возможен обморок — особенно опасно на крутом склоне или при ночном подъёме.",
    "q.l14#11.p" to "Как давать дексаметазон пациенту с высотной болезнью, которого постоянно рвёт?",
    "q.l14#11.o0" to "Внутрь, в повышенной дозе",
    "q.l14#11.o1" to "Только инъекционно",
    "q.l14#11.o2" to "Под язык",
    "q.l14#11.o3" to "Давать нельзя, нужно просто ждать",
    "q.l14#11.e" to "Постоянная рвота означает, что таблетки не всасываются и могут быть просто выведены обратно. В руководстве прямо сказано, что нужна инъекция, — напоминание о том, что путь введения стоит продумать заранее в любом плане действий при высотной ЧС.",
    "q.l15#0.p" to "Выше 3 000 м на сколько должна расти высота ночёвки за день?",
    "q.l15#0.o0" to "Не более чем на 500 м",
    "q.l15#0.o1" to "Не более чем на 1 500 м",
    "q.l15#0.o2" to "Как можно быстрее",
    "q.l15#0.o3" to "Ограничений нет",
    "q.l15#0.e" to "Держать суточный прирост высоты ночёвки в пределах 500 м, с днём отдыха примерно каждые 1 000 м, — базовый совет, повторяющийся в международных рекомендациях. Он даёт телу время на компенсацию. (Источники называют значения от 300 до 700 м; в этом курсе используется один из распространённых вариантов.)",
    "q.l15#1.p" to "Что означает «высоко подняться, низко спать»?",
    "q.l15#1.o0" to "Днём подниматься выше, а на ночь возвращаться ниже",
    "q.l15#1.o1" to "Днём отдыхать, ночью идти",
    "q.l15#1.o2" to "Всё время оставаться на одной высоте",
    "q.l15#1.o3" to "Спать только в самой высокой точке",
    "q.l15#1.e" to "Дневное пребывание на высоте стимулирует образование красных клеток крови и дыхательную адаптацию, а возвращение ниже на ночь облегчает симптомы и сохраняет качество сна. Сочетание того и другого — самый эффективный способ акклиматизации.",
    "q.l15#2.p" to "Что из этого увеличивает нагрузку на акклиматизацию?",
    "q.l15#2.o0" to "Достаточное питьё",
    "q.l15#2.o1" to "Алкоголь или седативные препараты",
    "q.l15#2.o2" to "Питание с преобладанием углеводов",
    "q.l15#2.o3" to "Достаточный сон",
    "q.l15#2.e" to "Алкоголь и седативные подавляют дыхательный драйв и усиливают ночное периодическое дыхание и гипоксию, резко повышая риск болезни. На высоте качество дыхания во сне само по себе часть акклиматизации.",
    "q.l15#3.p" to "В чём смысл контроля сатурации пульсоксиметром?",
    "q.l15#3.o0" to "Он полностью заменяет оценку симптомов",
    "q.l15#3.o1" to "Он даёт объективный ориентир, особенно для людей с историей высотной болезни",
    "q.l15#3.o2" to "Только чтобы вести записи",
    "q.l15#3.o3" to "Практической ценности нет",
    "q.l15#3.e" to "Сатурация — полезный ориентир, но индивидуальный разброс велик, и она не может быть единственной основой решений. Симптомы и функциональное состояние — может ли человек идти по прямой, работает ли он — остаются главным критерием.",
    "q.l15#4.p" to "Для людей с высоким риском HAPE какие профилактические препараты может рассмотреть врач?",
    "q.l15#4.o0" to "Нифедипин или силденафил (ингибитор ФДЭ)",
    "q.l15#4.o1" to "Антибиотики широкого спектра",
    "q.l15#4.o2" to "Обычные обезболивающие",
    "q.l15#4.o3" to "Витаминные добавки",
    "q.l15#4.e" to "Оба класса снижают давление в лёгочной артерии и применяются для профилактики HAPE у людей высокого риска после врачебной оценки. Они действуют в другой точке, чем ацетазоламид, и не могут его заменить.",
    "q.l15#5.p" to "Почему слишком быстрый подъём — один из сильнейших факторов риска высотной болезни?",
    "q.l15#5.o0" to "Потому что это утомительно",
    "q.l15#5.o1" to "Потому что организм не успевает развить дыхательную адаптацию и увеличить число красных клеток",
    "q.l15#5.o2" to "Потому что несёшь больше веса",
    "q.l15#5.o3" to "Потому что погода в горах быстро меняется",
    "q.l15#5.e" to "Акклиматизация — накопление ряда физиологических компенсаций, и на неё нужны дни. Когда подъём опережает компенсацию, разрыв проявляется симптомами — отсюда и берутся все рекомендации по темпу набора высоты.",
    "q.l15#6.p" to "Что даёт акклиматизации достаточное питьё?",
    "q.l15#6.o0" to "Только утоляет жажду",
    "q.l15#6.o1" to "Поддерживает кровообращение и обмен веществ; обезвоживание заметно усиливает симптомы",
    "q.l15#6.o2" to "Предотвращает отёк лёгких",
    "q.l15#6.o3" to "Заменяет профилактические лекарства",
    "q.l15#6.e" to "Сухой воздух и учащённое дыхание на высоте существенно увеличивают потери жидкости, а обезвоживание сгущает кровь, усиливая ощущение гипоксии и головную боль. При этом избегайте перепоя: цель — ровное, достаточное питьё.",
    "q.l15#7.p" to "Почему на высоте нужно избегать перегрузки?",
    "q.l15#7.o0" to "Потому что быстро устаёшь",
    "q.l15#7.o1" to "Перегрузка может спровоцировать HAPE, особенно до акклиматизации",
    "q.l15#7.o2" to "Потому что она вызывает обезвоживание",
    "q.l15#7.o3" to "Потому что она замедляет группу",
    "q.l15#7.e" to "Тяжёлая нагрузка поднимает давление в лёгочной артерии и служит явным триггером HAPE у ещё не акклиматизированных людей. Контроль темпа — не только про экономию сил: он снижает риск болезни.",
    "q.l15#8.p" to "Когда начинать и когда прекращать приём ацетазоламида?",
    "q.l15#8.o0" to "Начать по прибытии на высоту и прекратить, когда акклиматизировался",
    "q.l15#8.o1" to "Начать примерно за день до подъёма и прекратить примерно через два дня после",
    "q.l15#8.o2" to "Принимать непрерывно всю поездку",
    "q.l15#8.o3" to "Только после появления симптомов",
    "q.l15#8.e" to "Начать за день до подъёма значит, что препарат уже работает, пока вы набираете высоту; прекращать примерно через два дня после подъёма — потому что организм уже начал акклиматизироваться сам. Ацетазоламид ускоряет акклиматизацию, но не заменяет её.",
    "q.l15#9.p" to "Отмена ацетазоламида вызывает отскок симптомов?",
    "q.l15#9.o0" to "Да, дозу нужно снижать постепенно",
    "q.l15#9.o1" to "Нет, акклиматизация просто возвращается к обычному темпу",
    "q.l15#9.o2" to "Да, симптомы возвращаются вдвое сильнее",
    "q.l15#9.o3" to "Зависит от высоты",
    "q.l15#9.e" to "В руководстве прямо сказано, что отмена не даёт отскока — темп акклиматизации просто возвращается к нормальному. Это важно: значит, препарат ничего не подавляет, а лишь на время ускоряет процесс.",
    "q.l15#10.p" to "Как применяют аспирин для облегчения высотной головной боли?",
    "q.l15#10.o0" to "500 мг однократно, после начала головной боли",
    "q.l15#10.o1" to "Начать за день до подъёма, по 320 мг три раза в день до завершения акклиматизации",
    "q.l15#10.o2" to "100 мг один раз в день",
    "q.l15#10.o3" to "Только перед сном",
    "q.l15#10.e" to "Это профилактическое применение, а не «выпью, когда заболит»: начать заранее, принимать регулярно и продолжать, пока процесс акклиматизации не завершится. Учтите, что аспирин несёт риск желудочно-кишечных осложнений и кровотечений — это врачебное решение, нужна оценка врача.",
    "q.l15#11.p" to "Как правильно относиться к экстракту гинкго для профилактики высотной болезни?",
    "q.l15#11.o0" to "Он работает лучше ацетазоламида и может его заменить",
    "q.l15#11.o1" to "У него есть некоторый профилактический эффект, но контролируемые исследования показывают, что он гораздо слабее ацетазоламида",
    "q.l15#11.o2" to "Он полностью неэффективен",
    "q.l15#11.o3" to "Он действует только на отёк мозга",
    "q.l15#11.e" to "Руководство осторожно: в части исследований есть облегчение симптомов, но дозы и условия слишком различаются, чтобы говорить о надёжной дозе, а прямые сравнения показывают, что он значительно слабее ацетазоламида. Учтите также взаимодействие с антикоагулянтами.",
    "q.l16#0.p" to "Что означает, когда дрожь прекратилась?",
    "q.l16#0.o0" to "Организм адаптировался к холоду",
    "q.l16#0.o1" to "Переохлаждение усиливается — тревожный признак",
    "q.l16#0.o2" to "Можно продолжать движение",
    "q.l16#0.o3" to "Нужно немедленно выпить воды",
    "q.l16#0.e" to "Дрожь — последнее средство организма производить тепло. Когда она прекращается, теплопродукция исчерпана и температура ядра падает быстрее — ключевая граница между лёгким и средним или тяжёлым переохлаждением и причина действовать немедленно.",
    "q.l16#1.p" to "Каков правильный способ согревания при отморожении в полевых условиях?",
    "q.l16#1.o0" to "Растирать участок снегом",
    "q.l16#1.o1" to "Погрузить в воду 37–40 °C примерно на 30 минут, пока кожа не покраснеет и не размягчится",
    "q.l16#1.o2" to "Согреть у костра",
    "q.l16#1.o3" to "Приложить грелку напрямую",
    "q.l16#1.e" to "В отмороженных тканях есть кристаллы льда, и растирание вызывает вторичное повреждение клеток; сильный жар обжигает кожу, потерявшую чувствительность. Быстрое согревание в тёплой воде — единственный стандартный метод; здоровая рука или подмышка могут быть экстренной мерой.",
    "q.l16#2.p" to "Когда нельзя согревать отморожение в поле?",
    "q.l16#2.o0" to "Всегда согревать любое отморожение",
    "q.l16#2.o1" to "Когда есть риск повторного замерзания: цикл замерзание–оттаивание–замерзание даёт худшее повреждение",
    "q.l16#2.o2" to "Никогда не согревать днём",
    "q.l16#2.o3" to "Согревать только лёгкое отморожение",
    "q.l16#2.e" to "Цикл согревание–повторное замерзание разрушает гораздо больше тканей, чем пребывание в замёрзшем состоянии. Поэтому, если вероятно дальнейшее воздействие холода и тепло нельзя гарантировать, защитите участок, избегайте трения и спуститесь туда, где возможно устойчивое тепло, прежде чем согревать.",
    "q.l16#3.p" to "Почему при среднем и более тяжёлом переохлаждении нельзя интенсивно двигать конечностями?",
    "q.l16#3.o0" to "Потому что это тратит энергию",
    "q.l16#3.o1" to "Потому что охлаждённая сердечная мышца легко впадает в аритмию",
    "q.l16#3.o2" to "Потому что пациент становится раздражительным",
    "q.l16#3.o3" to "Потому что это усиливает отморожение",
    "q.l16#3.e" to "Это самый контринтуитивный момент в помощи при переохлаждении: заставлять пациента идти часто смертельно. В охлаждённом сердце миокард очень возбудим, и резкое движение конечностей или грубое обращение могут сразу вызвать фибрилляцию желудочков.",
    "q.l16#4.p" to "Какая температура воды правильна для согревания отморожения?",
    "q.l16#4.o0" to "0–5 °C",
    "q.l16#4.o1" to "20–25 °C",
    "q.l16#4.o2" to "37–40 °C",
    "q.l16#4.o3" to "Выше 60 °C",
    "q.l16#4.e" to "Слишком холодная вода — согревание не удаётся; слишком горячая — обжигает кожу без чувствительности. 37–40 °C быстро расплавляет кристаллы льда, не вызывая термического повреждения. Согревание очень болезненно и требует обезболивания.",
    "q.l16#5.p" to "Почему при переохлаждении сначала согревают туловище, а потом конечности?",
    "q.l16#5.o0" to "Потому что конечности не важны",
    "q.l16#5.o1" to "Согревание конечностей возвращает холодную кровь с периферии в ядро и ещё сильнее снижает температуру ядра",
    "q.l16#5.o2" to "Потому что туловище удобнее обрабатывать",
    "q.l16#5.o3" to "Потому что конечности могут быть уже отморожены",
    "q.l16#5.e" to "Это один из ключевых принципов помощи при переохлаждении. Начиная с конечностей, вы гоните холодную кровь с периферии обратно в ядро, что может ещё сильнее снизить температуру ядра и спровоцировать аритмию, — сначала ядро, потом конечности.",
    "q.l16#6.p" to "Как вести лёгкое переохлаждение в поле?",
    "q.l16#6.o0" to "Немедленно отправить в больницу",
    "q.l16#6.o1" to "Укрыть от ветра и холода, сменить мокрую одежду, дать тепло и продолжать следить за ухудшением",
    "q.l16#6.o2" to "Заставлять ходить, чтобы согреться",
    "q.l16#6.o3" to "Растирать тело снегом для стимуляции кровообращения",
    "q.l16#6.e" to "Человек с лёгким переохлаждением ещё может вырабатывать тепло, поэтому приоритет — остановить дальнейшую теплопотерю и дать энергию. Но продолжайте наблюдать: прекращение дрожи обычно признак перехода к среднему переохлаждению, а не улучшения.",
    "q.l16#7.p" to "Можно ли прикладывать грелку напрямую к отмороженным тканям?",
    "q.l16#7.o0" to "Да, чем быстрее согревание, тем лучше",
    "q.l16#7.o1" to "Нет — кожа без чувствительности легко обжигается; используйте только воду 37–40 °C",
    "q.l16#7.o2" to "Да, если завернуть в полотенце",
    "q.l16#7.o3" to "Да, если температура не слишком высокая",
    "q.l16#7.e" to "Отмороженная кожа потеряла и болевую, и температурную чувствительность, поэтому не может сигнализировать, что слишком горячо. Прямой источник тепла легко добавляет ожог и может уничтожить ткани, которые иначе восстановились бы.",
    "q.l16#8.p" to "[Множественный выбор] Что из этого неверно при первой помощи при переохлаждении?",
    "q.l16#8.o0" to "Дать пациенту алкоголь, чтобы согреть",
    "q.l16#8.o1" to "Заставлять сильно переохлаждённого пациента идти, чтобы согреться",
    "q.l16#8.o2" to "Энергично растирать отмороженные конечности",
    "q.l16#8.o3" to "Согревать конечности раньше туловища",
    "q.l16#8.o4" to "Укрыть пациента от ветра и сменить мокрую одежду",
    "q.l16#8.e" to "Первые четыре неверны, каждое по своей причине: алкоголь расширяет периферические сосуды и ускоряет теплопотерю; ходьба может вызвать аритмию при тяжёлом переохлаждении; растирание даёт вторичное повреждение отмороженных тканей; согревание конечностей гонит холодную кровь в ядро и ещё сильнее снижает температуру ядра.",
    "q.l16#9.p" to "Каков основной порядок приоритетов в помощи при переохлаждении?",
    "q.l16#9.o0" to "Сначала согреть конечности, потом туловище",
    "q.l16#9.o1" to "Сначала согреть ядро — туловище, избегая грубого обращения и интенсивных движений конечностями",
    "q.l16#9.o2" to "Сначала дать пациенту горячей воды",
    "q.l16#9.o3" to "Сначала снять всю одежду",
    "q.l16#9.e" to "Сначала ядро — первый принцип: когда туловище согрето, сердце и мозг снова работают, и кровь можно безопасно отдавать конечностям. Обратный порядок напрямую снижает температуру ядра.",
    "q.l16#10.p" to "Каков правильный уход после согревания отморожения?",
    "q.l16#10.o0" to "Проколоть пузыри, чтобы снять давление",
    "q.l16#10.o1" to "Не прокалывать пузыри; наложить свободную стерильную повязку и избегать нагрузки",
    "q.l16#10.o2" to "Энергично массировать для улучшения кровообращения",
    "q.l16#10.o3" to "Сразу приложить участок к источнику тепла",
    "q.l16#10.e" to "Согретые ткани крайне хрупки: пузыри — естественная повязка, а прокол открывает путь инфекции; массаж даёт механическое повреждение; тепло обжигает кожу без чувствительности. Защитите участок, держите его сухим, избегайте нагрузки и доберитесь до медицинской помощи.",
    "q.l16#11.p" to "Какие отдалённые последствия может оставить отморожение?",
    "q.l16#11.o0" to "Обычно полное выздоровление без последствий",
    "q.l16#11.o1" to "Холодовая чувствительность, нарушения чувствительности и патологическое потоотделение, возможно на месяцы и дольше",
    "q.l16#11.o2" to "Только косметические эффекты",
    "q.l16#11.o3" to "Только потеря спортивной формы",
    "q.l16#11.e" to "Отморожение повреждает глубокие ткани и нервные окончания, поэтому даже когда кожа выглядит восстановившейся, холодовая чувствительность, онемение, покалывание и нарушение потоотделения могут сохраняться долго. Именно поэтому профилактика отморожения важнее его лечения.",
    "q.l17#0.p" to "Как правильно наносить удар ледовым инструментом?",
    "q.l17#0.o0" to "Бить изо всех сил от плеча",
    "q.l17#0.o1" to "Бить от кисти, чтобы клюв входил в лёд вертикально",
    "q.l17#0.o2" to "Стучать по поверхности теслом",
    "q.l17#0.o3" to "Подрезать лёд горизонтально",
    "q.l17#0.e" to "Удар от кисти загоняет клюв вертикально и быстро: он легче входит и тратит меньше сил. Бить всей рукой обычно означает, что клюв входит под углом и разбивает поверхность в крошащуюся корку, которая не держит.",
    "q.l17#1.p" to "Что в ледолазании означает три точки опоры?",
    "q.l17#1.o0" to "Две руки и одна нога (или две ноги и одна рука) держат три устойчивые точки, пока четвёртая двигается",
    "q.l17#1.o1" to "Трое лезут вместе",
    "q.l17#1.o2" to "Три узла делят нагрузку",
    "q.l17#1.o3" to "На развеске должно быть три точки крепления",
    "q.l17#1.e" to "Три точки опоры — правило движения, общее для льда и скал: всегда держите три надёжные точки и двигайте только одну. Так, если одна откажет, опора остаётся.",
    "q.l17#2.p" to "Что характерно для WI4?",
    "q.l17#2.o0" to "Лёд малого угла, по которому можно идти пешком",
    "q.l17#2.o1" to "Почти вертикально с короткими вертикальными участками, а страховка может быть плохой",
    "q.l17#2.o2" to "Сплошные карнизы",
    "q.l17#2.o3" to "Достаточно одной треккинговой палки",
    "q.l17#2.e" to "WI4 означает, что рельеф близок к вертикали с короткими вертикальными участками, а места под ледобур могут быть ненадёжными. Это требует лучшей техники и оценки. WI1–WI2 — учебный рельеф.",
    "q.l17#3.p" to "Почему в ледолазании нужно экономить удары?",
    "q.l17#3.o0" to "Чтобы сэкономить силы",
    "q.l17#3.o1" to "Разбитый лёд превращается в крошащуюся корку, которая не держит",
    "q.l17#3.o2" to "Потому что инструмент изнашивается",
    "q.l17#3.o3" to "Потому что это мешает партнёрам",
    "q.l17#3.e" to "Каждый промах оставляет кратер. Многократные удары разрушают несущий лёд на целом участке и заставляют вас висеть на руках — замкнутый круг.",
    "q.l17#4.p" to "Почему ледолазание опаснее спортивного лазания?",
    "q.l17#4.o0" to "Потому что холоднее",
    "q.l17#4.o1" to "Ледобуры могут вырваться под нагрузкой, а лёд меняется день ото дня",
    "q.l17#4.o2" to "Потому что там нет страховки",
    "q.l17#4.o3" to "Потому что нельзя использовать верёвку",
    "q.l17#4.e" to "Хорошо поставленная закладка или крюк в скале остаются надёжными; ледобур зависит от самого льда, а лёд тает, становится хрупким и в нём появляются пустоты — точка, которая держала вчера, сегодня может не значить ничего.",
    "q.l17#5.p" to "Почему сначала нужно поставить ноги, а потом бить инструментом?",
    "q.l17#5.o0" to "Потому что руки устают быстрее ног",
    "q.l17#5.o1" to "Ноги несут вес и дают отдых, а руки только помогают",
    "q.l17#5.o2" to "Потому что ледовые инструменты дорогие",
    "q.l17#5.o3" to "Потому что так выглядит профессиональнее",
    "q.l17#5.e" to "Сила рук на льду иссякает очень быстро; ноги способны нести вес часами. Удар до того, как ноги встали, сжигает руки раньше времени и на самом деле повышает шанс сорваться.",
    "q.l17#6.p" to "При каких условиях лёд обычно становится плохим?",
    "q.l17#6.o0" to "После холодной ночи",
    "q.l17#6.o1" to "После сильного солнца или повышения температуры, когда лёд размягчается и становится сотовым",
    "q.l17#6.o2" to "Сразу после свежего снега",
    "q.l17#6.o3" to "Когда усиливается ветер",
    "q.l17#6.e" to "Лёд — функция температуры. Твёрдый утренний лёд принимает точные постановки; дневная каша кажется удобной, но ледобуры из неё вырываются легче. Оценивать лёд значит учитывать время дня, экспозицию, температуру и историю солнца.",
    "q.l17#7.p" to "Перед постановкой ледобура что нужно проверить?",
    "q.l17#7.o0" to "Заметного ли цвета ледобур",
    "q.l17#7.o1" to "Плотный ли лёд в этом месте, нет ли пустот и сотовости",
    "q.l17#7.o2" to "Хорошо ли он получится на фото",
    "q.l17#7.o3" to "Как далеко он над землёй",
    "q.l17#7.e" to "Прочность ледобура даёт лёд, а не техника. Ледобур в пустоте или в сотовом льду едва ли удержит падение — это самое принципиальное отличие ледовой страховки от скальной.",
    "q.l17#8.p" to "На ледовом участке у вас забиваются предплечья. Что делать?",
    "q.l17#8.o0" to "Лезть быстрее, чтобы пройти участок",
    "q.l17#8.o1" to "Как можно скорее выйти на полку, перенести вес на ноги и встряхнуть руки",
    "q.l17#8.o2" to "Схватиться крепче, чтобы держаться устойчиво",
    "q.l17#8.o3" to "Немедленно отступить",
    "q.l17#8.e" to "«Забитость» — это ишемия предплечья; если продолжать, хватка пропадает совсем. Правильная реакция — перенести вес на ноги, пока вы ещё контролируете ситуацию, и дать крови вернуться; именно это на практике и означает «не давайте ногам лениться».",
    "q.l17#9.p" to "[Сопоставление] Соотнесите каждую категорию водно-ледового WI с её типичным характером.",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.r0" to "Непрерывный лёд около 60° с возможными наплывами; хорошая страховка",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.r1" to "Непрерывные 60–75°; страховка обычно хорошая, но нагрузки высокие",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.r2" to "Почти вертикально с короткими вертикальными участками; страховка может быть плохой",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r3" to "Непрерывно вертикально; страховка плохая, очень тяжело",
    "q.l17#9.e" to "Категория WI складывается из трёх переменных: угол, качество страховки и физическая цена. Чем выше категория, тем меньше возможностей отступить или провести самоспасение, — поэтому категория лишь ориентир, а исход решают сегодняшний лёд и состояние группы.",
    "q.l17#10.p" to "[Множественный выбор] Что из снаряжения должно быть на обвязке под рукой при ледолазании?",
    "q.l17#10.o0" to "Несколько ледобуров",
    "q.l17#10.o1" to "Карабины и оттяжки",
    "q.l17#10.o2" to "Шнур для прусика",
    "q.l17#10.o3" to "Спусковое устройство",
    "q.l17#10.o4" to "Запасной спальный мешок",
    "q.l17#10.e" to "Ледолазание означает, что страховку строишь по ходу движения, поэтому всё, что зарыто в рюкзаке, можно считать отсутствующим. Список спасательного набора в руководстве — ледобуры, карабины, стропы, блок, прусики, жумар — следует той же логике: всё нужное остаётся под рукой.",
    "q.l17#11.p" to "Почему ледобур может вырваться?",
    "q.l17#11.o0" to "Потому что он слишком короткий",
    "q.l17#11.o1" to "Потому что в самом льду могут быть пустоты, сотовость или таяние, и он не держит",
    "q.l17#11.o2" to "Потому что на него навешано слишком много",
    "q.l17#11.o3" to "Потому что он затуплен",
    "q.l17#11.e" to "Прочность даёт лёд, а не постановка. Ледобур в пустоте или сотовом льду едва ли выдержит падение — в этом суть отличия от скальной страховки и причина проверять лёд перед постановкой.",
    "q.l17#12.p" to "Почему категория льда — только ориентир?",
    "q.l17#12.o0" to "Потому что категории произвольны",
    "q.l17#12.o1" to "Потому что лёд меняется каждый день: солнце, температура и сезон заметно меняют один и тот же маршрут",
    "q.l17#12.o2" to "Потому что в разных странах категории разные",
    "q.l17#12.o3" to "Потому что категории описывают только длину",
    "q.l17#12.e" to "Лёд — функция температуры: твёрдый утренний лёд требует точных постановок, а мягкий дневной кажется простым, но ледобуры из него вырываются легче. Один и тот же маршрут может отличаться больше чем на категорию, — поэтому то, что перед вами, всегда важнее цифры в путеводителе.",
    "q.l17#13.p" to "[Порядок] Расставьте ритм трёх точек опоры в ледолазании по порядку.",
    "q.l17#13.o0" to "Прочитать лёд и выбрать, куда пойдут инструмент и ноги",
    "q.l17#13.o1" to "Вбить передние зубья и поставить обе ноги",
    "q.l17#13.o2" to "С устойчивыми ногами нанести удар инструментом и убедиться, что он держит",
    "q.l17#13.o3" to "Когда три точки устойчивы, переместить четвёртую",
    "q.l17#13.e" to "Этот порядок объясняет, почему «не давайте ногам лениться» — главная дисциплина ледолазания: ноги несут вес часами, руки только помогают. Удар до постановки ног истощает руки раньше времени — на крутом льду это смертельно.",
    "q.l18#0.p" to "На каких углах склона лавины концентрируются чаще всего?",
    "q.l18#0.o0" to "10°–25°",
    "q.l18#0.o1" to "34°–45°",
    "q.l18#0.o2" to "55°–70°",
    "q.l18#0.o3" to "Вертикальный лёд",
    "q.l18#0.e" to "Статистика показывает, что подавляющее большинство лавин сходит между 34° и 45° (96 % — в пределах 30–50°). Это как раз достаточно круто, чтобы скользить, и достаточно полого, чтобы держать снег, — окно опасности и тот угол, который альпинистские маршруты пересекают чаще всего.",
    "q.l18#1.p" to "Почему большинство происшествий происходит на 3-м уровне опасности, «значительном»?",
    "q.l18#1.o0" to "Потому что снежный покров наиболее неустойчив",
    "q.l18#1.o1" to "Потому что условия кажутся приемлемыми и их легче всего недооценить",
    "q.l18#1.o2" to "Потому что все остаются дома",
    "q.l18#1.o3" to "Потому что прогноз неточен",
    "q.l18#1.e" to "Парадокс третьего уровня в том, что лавины действительно возможны, а рельеф выглядит «нормально», поэтому на лавинный рельеф выходит много людей. На уровнях 4 и 5 почти все держатся в стороне, и доля происшествий падает. Самое опасное состояние — никогда не крайнее, а среднее, которое недооценивают.",
    "q.l18#2.p" to "Что такое лавинный набор из трёх предметов?",
    "q.l18#2.o0" to "Бипер, щуп и лопата",
    "q.l18#2.o1" to "Каска, верёвка и обвязка",
    "q.l18#2.o2" to "Ледоруб, кошки и ледобуры",
    "q.l18#2.o3" to "Палатка, спальник и коврик",
    "q.l18#2.e" to "Бипер находит, щуп уточняет точку, лопата копает. Нужны все три, и все три надо отрабатывать, чтобы уложить спасение в золотые десять с небольшим минут.",
    "q.l18#3.p" to "Почему склоны, которые не кажутся крутыми, часто самые опасные?",
    "q.l18#3.o0" to "Потому что снега там больше",
    "q.l18#3.o1" to "Потому что 34–45° — зона концентрации лавин, а люди систематически недооценивают угол",
    "q.l18#3.o2" to "Потому что по ним быстрее двигаются",
    "q.l18#3.o3" to "Потому что солнце сильнее",
    "q.l18#3.e" to "Ниже примерно 30° слишком полого для пластовых лавин; выше примерно 50° снег не накапливается. Окно опасности попадает ровно в диапазон, который кажется проходимым, — именно поэтому его и недооценивают.",
    "q.l18#4.p" to "Как правильно пересекать лавинный рельеф?",
    "q.l18#4.o0" to "Проходить всей группой быстро вместе",
    "q.l18#4.o1" to "Расходиться, пересекать по одному, ставить наблюдателя и планировать путь отхода",
    "q.l18#4.o2" to "Идти по самой короткой линии по дну долины",
    "q.l18#4.o3" to "Держаться там, где снег глубже",
    "q.l18#4.e" to "По одному ограничивает риск одним человеком, а наблюдатель может сразу найти и организовать спасение. Пересечение всей группой означает, что один триггер засыпает всю команду — худший возможный исход.",
    "q.l18#5.p" to "Вы слышите «вумпф», снежный покров проседает. Что это значит?",
    "q.l18#5.o0" to "Вы просто провалились в яму",
    "q.l18#5.o1" to "Есть легко срабатывающий слабый слой, и снежный покров неустойчив",
    "q.l18#5.o2" to "Снег глубокий, идти хорошо",
    "q.l18#5.o3" to "Снежный покров стабилизировался",
    "q.l18#5.e" to "«Вумпф» — звук проседания снежного покрова при разрушении слабого слоя. Это очень прямой сигнал нестабильности: продолжать выход на такой склон значит использовать себя как испытание — сойдёт ли он пластом.",
    "q.l18#6.p" to "Почему пластовые лавины смертельнее лавин из рыхлого снега?",
    "q.l18#6.o0" to "Потому что они холоднее",
    "q.l18#6.o1" to "Пласт сходит сразу целиком и засыпает вас, почти не оставляя шанса на самоспасение",
    "q.l18#6.o2" to "Потому что они громче",
    "q.l18#6.o3" to "Потому что случаются чаще",
    "q.l18#6.e" to "Пласт разрывается по всему склону сразу, и вы теряете опору, ещё находясь на стене. После засыпания вес снега и его быстрое схватывание делают самоспасение почти невозможным — поэтому спасение товарищами должно начинаться немедленно.",
    "q.l18#7.p" to "Как нужно носить и использовать бипер?",
    "q.l18#7.o0" to "Где угодно в рюкзаке",
    "q.l18#7.o1" to "Проверять друг у друга режим передачи перед выходом и регулярно отрабатывать поиск",
    "q.l18#7.o2" to "Носит только руководитель группы",
    "q.l18#7.o3" to "Выключать, чтобы сэкономить батарею",
    "q.l18#7.e" to "Бипер в рюкзаке почти бесполезен: под снегом руки могут вообще не двигаться, поэтому его носят на теле, обычно на груди. Алгоритм поиска тоже нужно отрабатывать, иначе вы никого не найдёте в золотые десять минут.",
    "q.l18#8.p" to "Перед выходом на лавинный рельеф что важнее всего подготовить?",
    "q.l18#8.o0" to "Достаточно иметь всё снаряжение",
    "q.l18#8.o1" to "Прочитать лавинный прогноз на день и постоянно уточнять маршрут и план по наблюдениям на месте",
    "q.l18#8.o2" to "Полностью доверять личному опыту",
    "q.l18#8.o3" to "Идти по чужому следу",
    "q.l18#8.e" to "Прогноз даёт региональную оценку, наблюдения на месте — данные по конкретному склону; нужно и то и другое. Идти по старому следу особенно опасно: ему может быть несколько часов, и снежный покров уже изменился.",
    "q.l18#9.p" to "По статистике, какая причина даёт больше всего смертей в альпинизме?",
    "q.l18#9.o0" to "Сначала лавины, потом падения",
    "q.l18#9.o1" to "Сначала падения, потом лавины",
    "q.l18#9.o2" to "Сначала болезни, потом камнепад",
    "q.l18#9.o3" to "Сначала переохлаждение, потом лавины",
    "q.l18#9.e" to "В руководстве сказано прямо: падения на первом месте, лавины на втором. Порядок важен: лавин боятся больше всего, но убивает чаще обычное скольжение. Ранжируйте риски по данным, а не по впечатлению.",
    "q.l18#10.p" to "После засыпания сколько примерно длится золотое окно спасения?",
    "q.l18#10.o0" to "Около десяти-пятнадцати минут",
    "q.l18#10.o1" to "Два часа",
    "q.l18#10.o2" to "Шесть часов",
    "q.l18#10.o3" to "24 часа",
    "q.l18#10.e" to "Десять-пятнадцать минут — время, которое означает, что спасать должны ваши партнёры, потому что организованное спасение придёт слишком поздно. Поэтому набор носят на себе и отрабатывают, а не просто кладут в рюкзак.",
    "q.l18#11.p" to "[Множественный выбор] Какие признаки на месте стоит учитывать при оценке лавинного риска?",
    "q.l18#11.o0" to "«Вумпф» при проседании снежного покрова",
    "q.l18#11.o1" to "Свежие трещины на склоне",
    "q.l18#11.o2" to "Недавний свежий снег или явный ветровой перенос",
    "q.l18#11.o3" to "Слышное оседание и проваливание под ногами на подъёме",
    "q.l18#11.o4" to "Перистые облака и отличная видимость",
    "q.l18#11.e" to "Это прямые доказательства того, что устойчивость падает прямо сейчас. Их ценность в непосредственности: прогноз даёт региональную картину, а эти признаки описывают склон под вашими ногами в этот момент. Нужно и то и другое.",
    "q.l18#12.p" to "На изображении три участка одной горы. Нажмите на участок с наибольшим лавинным риском.",
    "q.l18#12.e" to "Лавины концентрируются между 34° и 45°. Пологий склон слева (около 16°) слишком плоский для пластовых лавин; крутой справа (около 60°) слишком крут, чтобы снег накопил толстый пласт. Только средний склон около 40° попадает в окно, где снег и накапливается, и может сойти, — и именно этот угол маршруты пересекают чаще всего, поэтому его так легко недооценить.",
    "q.l19#0.p" to "Зачем устанавливать время поворота?",
    "q.l19#0.o0" to "Чтобы в этот час безусловно повернуть назад и не стать заложником цели",
    "q.l19#0.o1" to "Чтобы рассчитать свою скорость подъёма",
    "q.l19#0.o2" to "Чтобы решить, сколько еды брать",
    "q.l19#0.o3" to "Это формальность",
    "q.l19#0.e" to "Время поворота выводит решение из эмоций момента: правило, принятое на трезвую голову, подменяет собой рассудительность, когда вы устали и не хотите поворачивать. Это самое действенное средство против «вершинной лихорадки».",
    "q.l19#1.p" to "Что обычно вызывает «вершинную лихорадку»?",
    "q.l19#1.o0" to "Очень хорошая погода",
    "q.l19#1.o1" to "Уже вложенные усилия плюс давление группы, искажающие оценку",
    "q.l19#1.o2" to "Недостаточное снаряжение",
    "q.l19#1.o3" to "Слишком малая высота",
    "q.l19#1.e" to "Потраченные время, деньги и силы мешают признать, что пора остановиться; молчание или взаимное подбадривание в группе ещё сильнее подавляют сомнения. Понимание механизма — условие того, чтобы заранее задать объективные правила.",
    "q.l19#2.p" to "Когда группа должна договориться о решении отступать?",
    "q.l19#2.o0" to "До выхода, согласовав объективные триггеры и того, кто решает",
    "q.l19#2.o1" to "На вершине",
    "q.l19#2.o2" to "Когда появилась опасность — по ситуации",
    "q.l19#2.o3" to "На месте, сильнейшим участником",
    "q.l19#2.e" to "Обсуждать отступление уставшим, в гипоксии и на эмоциях почти всегда означает склониться к продолжению. Договоритесь об объективных триггерах заранее — время, изменение погоды, состояние группы — и назовите, за кем последнее слово.",
    "q.l19#3.p" to "Почему так много происшествий происходит на спуске?",
    "q.l19#3.o0" to "Потому что спускаться по рельефу сложнее",
    "q.l19#3.o1" to "Потому что после достижения цели внимание падает, а тело уже на пределе",
    "q.l19#3.o2" to "Потому что на спуске погода всегда хуже",
    "q.l19#3.o3" to "Потому что отказывает снаряжение",
    "q.l19#3.e" to "«Вершина — только половина пути» на деле означает, что риск похода высвобождается на спуске. Связку, страховку и темп на спуске нельзя ослаблять только потому, что вы сходили на вершину.",
    "q.l19#4.p" to "В чём ценность заранее согласованного решения об отступлении?",
    "q.l19#4.o0" to "Это экономит время",
    "q.l19#4.o1" to "Оно выводит решение из усталости и эмоций и позволяет сработать вашей оценке, сделанной до выхода",
    "q.l19#4.o2" to "Это даёт руководителю больше власти",
    "q.l19#4.o3" to "Это помогает избежать споров",
    "q.l19#4.e" to "Решать в гипоксии, усталости и нежелании возвращаться почти всегда означает склониться к продолжению. Заранее согласованные объективные триггеры и права на решение — это когда спокойная версия вас решает за измученную.",
    "q.l19#5.p" to "Почему план отступления должен быть вписан в план восхождения?",
    "q.l19#5.o0" to "Чтобы план выглядел полным",
    "q.l19#5.o1" to "Отступление требует снаряжения, маршрута и запаса времени; решения по ситуации не оставляют времени подготовиться",
    "q.l19#5.o2" to "Чтобы пройти проверку",
    "q.l19#5.o3" to "Потому что этого требуют правила",
    "q.l19#5.e" to "Отступление — настоящая техническая операция: может понадобиться станция, спуск по верёвке и движение в темноте. Если в плане на это не заложены время и снаряжение, отступление превращается в рискованную импровизацию.",
    "q.l19#6.p" to "Когда участники расходятся во мнениях о маршруте или погоде, как поступить?",
    "q.l19#6.o0" to "Голосование большинства",
    "q.l19#6.o1" to "Принять самую консервативную точку зрения, пока новые данные не убедят всех",
    "q.l19#6.o2" to "Пусть решает самый сильный",
    "q.l19#6.o3" to "Проголосовать и закрыть тему",
    "q.l19#6.e" to "В ситуациях высокого риска вес должна иметь самая консервативная точка зрения. Голосование большинства подавляет обоснованное беспокойство меньшинства, — а самая частая фраза в разборах аварий: «кто-то чувствовал неладное, но никто не сказал».",
    "q.l19#7.p" to "Какой взгляд на «с гидом ты в безопасности» верен?",
    "q.l19#7.o0" to "Гид делает тебя абсолютно безопасным",
    "q.l19#7.o1" to "Гид снижает риск, но не может убрать объективные опасности; участники всё равно должны оценивать",
    "q.l19#7.o2" to "Гиды только показывают дорогу, безопасность — твоё дело",
    "q.l19#7.o3" to "Участникам не нужно ничего оценивать",
    "q.l19#7.e" to "Ценность гида — опыт и качество решений, но лавины, камнепад и погода не исчезают оттого, что кто-то ведёт. Участники, которые понимают риск, замечают признаки опасности и говорят о них, сами становятся частью запаса безопасности группы.",
    "q.l19#8.p" to "Что такое «расползание цели» в альпинизме?",
    "q.l19#8.o0" to "Снижение категории сложности маршрута",
    "q.l19#8.o1" to "Постепенное ослабление установленных вами стандартов безопасности ради вершины",
    "q.l19#8.o2" to "Смена целевой вершины в середине похода",
    "q.l19#8.o3" to "Сокращение группы",
    "q.l19#8.e" to "«Расползание цели» — классический признак вершинной лихорадки: время поворота всё сдвигается, приемлемое погодное окно всё расширяется, симптомы всё терпятся. Единственная защита — заранее оцифровать стандарты, чтобы их ослабление было явным и требовало объяснения партнёрам.",
    "q.l19#9.p" to "[Множественный выбор] Что должен содержать полный план восхождения?",
    "q.l19#9.o0" to "Маршрут и график, включая время поворота",
    "q.l19#9.o1" to "План отступления и запасные маршруты",
    "q.l19#9.o2" to "Оценку состояния группы и распределение ролей",
    "q.l19#9.o3" to "Способ связи, контактное лицо и порядок действий в ЧС",
    "q.l19#9.o4" to "План работы с медиа и публичности",
    "q.l19#9.e" to "Первые четыре обязательны. Чаще всего пропускают второй и четвёртый — потому что при хорошем развитии событий они не нужны. Но план ценен именно тогда, когда всё идёт плохо, а тогда писать его уже некогда.",
    "q.l19#10.p" to "Зачем закладывать в план резервные дни?",
    "q.l19#10.o0" to "Чтобы поглотить задержки: более позднее погодное окно или недомогание участника",
    "q.l19#10.o1" to "Чтобы больше отдыхать",
    "q.l19#10.o2" to "Чтобы сэкономить деньги",
    "q.l19#10.o3" to "Чтобы график выглядел комфортным",
    "q.l19#10.e" to "Высотные поездки почти всегда сдвигаются: погода не хочет сотрудничать, кому-то нужен лишний день акклиматизации, подход медленнее ожидаемого. Без запаса любая задержка заставляет сокращать акклиматизацию или удлинять дневные переходы — и то и другое резко повышает риск.",
    "q.l19#11.p" to "[Порядок] Расставьте шаги составления плана восхождения в разумном порядке.",
    "q.l19#11.o0" to "Зафиксировать цель и маршрут; собрать информацию и историю погоды",
    "q.l19#11.o1" to "Оценить возможности группы и время; спланировать ритм акклиматизации",
    "q.l19#11.o2" to "Задать время поворота и измеримые триггеры отступления",
    "q.l19#11.o3" to "Описать план отступления и порядок действий в ЧС, проинформировать контактное лицо",
    "q.l19#11.e" to "Порядок такой: задать цель, проверить возможности, провести красную линию, затем обеспечить выход. Многие делают наоборот — цель сначала, выход в конце, — поэтому выход оказывается в самом низу списка и никогда не прорабатывается как следует.",
    "q.l19#12.p" to "Почему время спуска так часто недооценивают?",
    "q.l19#12.o0" to "Потому что вниз быстрее",
    "q.l19#12.o1" to "Потому что вы измотаны, поверхность может быть хуже, да ещё нужно страховать и снимать снаряжение",
    "q.l19#12.o2" to "Потому что карты неточны",
    "q.l19#12.o3" to "Потому что гиды торопят",
    "q.l19#12.e" to "Подъём мог занять шесть часов, а спуск часто занимает больше: меньше сил, более мягкий или обледенелый снег, хуже видимость и, возможно, спуски по верёвке и сбор снаряжения. Оценивать спуск по времени подъёма — одна из самых частых ошибок планирования.",
    "q.l19#13.p" to "Зачем прописывать в плане связь и контактные договорённости?",
    "q.l19#13.o0" to "Для отчётности",
    "q.l19#13.o1" to "Потому что если вы пропадёте, тем, кто дома, нужно знать, где искать и когда начинать",
    "q.l19#13.o2" to "Чтобы отчитаться перед компанией",
    "q.l19#13.o3" to "Чтобы выполнить требования разрешений",
    "q.l19#13.e" to "Самое трудное в поисково-спасательных работах — не знать, где человек. Маршрут, график, запасные варианты и время контрольных связей — это то, что сжимает поиск с дней до часов, и такую информацию можно передать только до выхода.",
    "q.l19#14.p" to "Как размер группы влияет на план?",
    "q.l19#14.o0" to "Размер не влияет на планирование",
    "q.l19#14.o1" to "Больше людей — медленнее движение, тяжелее логистика и труднее синхронизировать акклиматизацию",
    "q.l19#14.o2" to "Больше людей — безопаснее, поэтому ничего менять не нужно",
    "q.l19#14.o3" to "Больше людей — быстрее",
    "q.l19#14.e" to "Большая группа делит людские ресурсы и снаряжение, но платит скоростью и гибкостью: у каждого свой ритм, и группа идёт со скоростью самого медленного. Размер группы — часть расчёта времени, а не тема для жалоб после.",
    "q.l19#15.p" to "Заполните: в высотных планах обычно закладывают около ( ) % резервных дней.",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20–30",
    "q.l19#15.a5" to "двадцать–тридцать",
    "q.l19#15.e" to "Обычная рекомендация — запас 20–30 %. Поездку на десять дней, например, стоит планировать на двенадцать-тринадцать с учётом продуктов, разрешений и выезда: выглядит избыточно осторожно, пока не сравнишь с тем, как часто задержки действительно случаются.",
    "q.l20#0.p" to "Каков первый принцип спасения?",
    "q.l20#0.o0" to "Как можно быстрее переместить пострадавшего",
    "q.l20#0.o1" to "Обезопасить место, чтобы не создать второго пострадавшего",
    "q.l20#0.o2" to "Сначала сфотографировать место",
    "q.l20#0.o3" to "Сначала дать пострадавшему воды",
    "q.l20#0.e" to "Среди камнепада, лавин, трещин или крутого рельефа спешка к пострадавшему часто превращает спасателя во второго пострадавшего и вдвое уменьшает помощь. Оценка обстановки — первый шаг, который нельзя пропустить.",
    "q.l20#1.p" to "С чего начинается правильная последовательность действий в ЧС?",
    "q.l20#1.o0" to "Сначала обезопасить место, затем оценить травмы",
    "q.l20#1.o1" to "Сначала переместить пострадавшего в безопасное место",
    "q.l20#1.o2" to "Поискать еду и воду",
    "q.l20#1.o3" to "Построить верёвочную систему",
    "q.l20#1.e" to "Стандартная последовательность: безопасность, оценка, вызов помощи, помощь, транспортировка. Пропустить оценку безопасности и броситься сразу к пострадавшему — самая частая ошибка при спасении.",
    "q.l20#2.p" to "Почему на высоте профилактика важнее спасения?",
    "q.l20#2.o0" to "Потому что спасение дорого",
    "q.l20#2.o1" to "Потому что спасение ограничено погодой, кислородом и людьми и часто не успевает",
    "q.l20#2.o2" to "Потому что спасатели не хотят",
    "q.l20#2.o3" to "Потому что нет сигнала связи",
    "q.l20#2.e" to "Высота ухудшает обе стороны: вертолёты ограничены турбулентностью и высотой, наземным группам нужны часы, а пострадавший в гипоксии и холоде угасает быстрее. Этот разрыв во времени — единственный спасательный ресурс, который у вас действительно есть.",
    "q.l20#3.p" to "Почему горное спасение часто занимает часы или дни?",
    "q.l20#3.o0" to "Потому что группы не хотят идти",
    "q.l20#3.o1" to "Жёсткие ограничения по погоде, кислороду, связи и людям; вертолёты ограничены турбулентностью и высотой",
    "q.l20#3.o2" to "Потому что расстояния слишком велики",
    "q.l20#3.o3" to "Потому что это слишком дорого",
    "q.l20#3.e" to "На высоте вертолёт страдает от нехватки подъёмной силы и турбулентности, а наземной группе нужны часы, чтобы до вас дойти. Этот разрыв означает одно: наверху вы сами себе первая спасательная команда.",
    "q.l20#4.p" to "В чём смысл оставленного маршрута и контактного лица?",
    "q.l20#4.o0" to "Формальность",
    "q.l20#4.o1" to "Если вы пропадёте, спасатели будут знать, где искать, и поиск резко сократится",
    "q.l20#4.o2" to "Чтобы легче было оформить расходы",
    "q.l20#4.o3" to "Чтобы соблюсти правила",
    "q.l20#4.e" to "Самое трудное в поисково-спасательных работах — не знать, где человек. Маршрут, график, запасные варианты и договорённости о связи — это то, что сжимает поиск с дней до часов.",
    "q.l20#5.p" to "При оценке пострадавшего что лечат в первую очередь?",
    "q.l20#5.o0" to "Шинирование переломов",
    "q.l20#5.o1" to "Угрожающие жизни проблемы, например дыхательные пути и дыхание",
    "q.l20#5.o2" to "Подробную запись травм",
    "q.l20#5.o3" to "Промывание видимых ран",
    "q.l20#5.e" to "Оценка идёт по принципу «сначала угрожающее жизни»: дыхательные пути, дыхание и кровообращение прежде переломов и ран, не являющихся непосредственно смертельными. Ошибётесь в порядке — всё остальное будет значить гораздо меньше.",
    "q.l20#6.p" to "Почему на высоте утепление — критическая часть первой помощи?",
    "q.l20#6.o0" to "Потому что так пострадавшему комфортнее",
    "q.l20#6.o1" to "Потому что обездвиженный пострадавший быстро теряет тепло, и это ухудшает травму",
    "q.l20#6.o2" to "Потому что этого требуют правила",
    "q.l20#6.o3" to "Чтобы легче было нести",
    "q.l20#6.e" to "В холоде и гипоксии пострадавший, который не может двигаться, быстро теряет теплопродукцию. Переохлаждение углубляет шок и маскирует симптомы, поэтому изоляция от земли, защита от ветра и смена мокрой одежды так же важны, как остановка кровотечения.",
    "q.l20#7.p" to "Каким должен быть план действий группы при отказе связи?",
    "q.l20#7.o0" to "Ждать на месте, пока связь не восстановится",
    "q.l20#7.o1" to "Заранее договориться о месте встречи, сроке «нет связи» и дальнейших действиях",
    "q.l20#7.o2" to "Сразу разделиться и искать",
    "q.l20#7.o3" to "Всем сразу спускаться",
    "q.l20#7.e" to "Потеря связи в горах — норма, а не исключение. Заранее договориться, что делать, если к определённому времени вы не вышли на связь, — это предотвращает панику на месте и говорит контактному лицу, когда поднимать тревогу.",
    "q.l20#8.p" to "Каково правильное отношение к обучению первой помощи и спасению?",
    "q.l20#8.o0" to "Достаточно посмотреть урок и запомнить шаги",
    "q.l20#8.o1" to "Нужно регулярно отрабатывать руками; одно чтение не переносится в реальную ситуацию",
    "q.l20#8.o2" to "Это нужно только руководителю",
    "q.l20#8.o3" to "Это только для профессиональных спасателей",
    "q.l20#8.e" to "Первая помощь и спасение — навыки с жёсткой процедурой, и под давлением вы откатываетесь к тому уровню, на котором реально тренировались. Чтение строит каркас; только повторная отработка сохраняет правильные действия, когда страшно.",
    "q.l20#9.p" to "[Порядок] Расставьте стандартную последовательность оценки и помощи пострадавшему.",
    "q.l20#9.o0" to "Обезопасить место, чтобы не создать второго пострадавшего",
    "q.l20#9.o1" to "Оценить сознание, дыхательные пути, дыхание и кровообращение",
    "q.l20#9.o2" to "Устранить непосредственные угрозы жизни: кровотечение, утепление, шинирование",
    "q.l20#9.o3" to "Вызвать помощь и организовать транспортировку либо ждать профессионального спасения",
    "q.l20#9.e" to "Чаще всего пропускают первый и четвёртый шаги — под стрессом люди бегут прямо к пострадавшему. Но небезопасное место превращает спасателя во второго пострадавшего и вдвое уменьшает силы, а без вызова помощи нет резерва для всего последующего.",
    "q.l20#10.p" to "[Множественный выбор] Какую ключевую информацию должен содержать вызов помощи?",
    "q.l20#10.o0" to "Точное место (координаты или заметный ориентир)",
    "q.l20#10.o1" to "Число пострадавших, сознание и характер дыхания",
    "q.l20#10.o2" to "Рельеф и погода на месте",
    "q.l20#10.o3" to "Доступный способ связи и время контрольных выходов на связь",
    "q.l20#10.o4" to "Альпинистское резюме пострадавшего",
    "q.l20#10.e" to "Эти четыре определяют, что именно пошлют, сколько и каким путём. Неточное место теряет часы, неизвестные травмы означают не то снаряжение, а неизвестная погода может подвергнуть риску и спасателей. Вызов помощи — навык общения, который стоит отрабатывать.",
    "q.l20#11.p" to "Почему вертолётное спасение на высоте часто невозможно?",
    "q.l20#11.o0" to "Потому что это слишком дорого",
    "q.l20#11.o1" to "Потому что разреженный воздух снижает подъёмную силу и полезную нагрузку, турбулентность сильна, а погодные окна коротки",
    "q.l20#11.o2" to "Потому что пилоты отказываются туда лететь",
    "q.l20#11.o3" to "Потому что на высоте нет воздушных трасс",
    "q.l20#11.e" to "Подъёмная сила вертолёта берётся из воздуха, а наверху воздух разрежен — это напрямую ограничивает, сколько он может поднять и на какой высоте работать. Добавьте турбулентный горный воздух и быстро меняющуюся погоду, и лётное окно может составлять всего десятки минут. Поэтому спасение не может быть вашим планом.",
    "q.l20#12.p" to "[Сопоставление] Соотнесите каждую меру первой помощи с ситуацией, когда она применяется.",
    "q.l20#12.l0" to "Утепление",
    "q.l20#12.r0" to "Приоритет для любого пострадавшего на высоте, чтобы переохлаждение не углубило шок",
    "q.l20#12.l1" to "Остановка кровотечения",
    "q.l20#12.r1" to "Первая реакция на открытую рану или кровотечение из конечности",
    "q.l20#12.l2" to "Шинирование",
    "q.l20#12.r2" to "Подозрение на перелом или травму сустава, чтобы не повредить при перемещении",
    "q.l20#12.l3" to "Кислород",
    "q.l20#12.r3" to "Затруднённое дыхание, явно низкая сатурация или подозрение на отёк лёгких",
    "q.l20#12.e" to "Все четыре — базовые действия на высоте, а не специальные процедуры. Общее у них то, что сложное снаряжение не нужно, а правильный порядок нужен: утепление, например, в общей первой помощи часто идёт поздно, а наверху оно приоритет.",
    "q.l20#13.p" to "Зачем оценивать риск самого спасения?",
    "q.l20#13.o0" to "Потому что спасать утомительно",
    "q.l20#13.o1" to "Потому что спасение может подвергнуть опасности больше людей и снизить общие шансы на выживание",
    "q.l20#13.o2" to "Потому что этого требует страховка",
    "q.l20#13.o3" to "Потому что этого требуют правила",
    "q.l20#13.e" to "Решения о спасении — это распределение ресурсов: если, добираясь до пострадавшего, вы травмируете двух спасателей, было «один пострадавший и два спасателя», станет «три пострадавших и никто». Это не холодность, а арифметика, максимизирующая общее выживание.",
    "q.l20#14.p" to "Когда нужно прекратить самоспасение и ждать профессиональной помощи?",
    "q.l20#14.o0" to "Самоспасаться, пока есть силы",
    "q.l20#14.o1" to "Когда самоспасение грозит новыми травмами или условия превышают возможности группы",
    "q.l20#14.o2" to "Только когда полностью выдохлись",
    "q.l20#14.o3" to "Никогда не прекращать самоспасение",
    "q.l20#14.e" to "Самоспасение — про выигрыш времени, а не про риск. Когда продолжение может тяжелее травмировать пострадавшего или спасателей, либо когда буря делает движение опаснее, чем ожидание, лучше удержать ситуацию и ждать резерва.",
    "q.l20#15.p" to "Заполните: в оценке SAMPLE буква E означает ( ).",
    "q.l20#15.a0" to "событие",
    "q.l20#15.a1" to "Событие",
    "q.l20#15.a2" to "то, что случилось",
    "q.l20#15.a3" to "происшествие",
    "q.l20#15.e" to "E означает Event — что произошло. Этот пункт часто недооценивают: механизм (как произошло падение, был ли удар головой, сколько длилось засыпание) прямо указывает на вероятные травмы и служит ключевой подсказкой при оценке.",
    "q.l21#0.p" to "В трёхслойной системе какова основная задача базового слоя?",
    "q.l21#0.o0" to "Защищать от ветра и снега",
    "q.l21#0.o1" to "Отводить пот от кожи и сохранять сухость",
    "q.l21#0.o2" to "Давать основное тепло",
    "q.l21#0.o3" to "Хранить запасные вещи",
    "q.l21#0.e" to "Главная функция базового слоя — влагоотведение. Он лежит на коже, и если остаётся влажным, то сколько бы слоёв вы ни надели сверху, тепло продолжает уходить, — поэтому базовый слой и называют второй кожей.",
    "q.l21#1.p" to "Почему в мокрых условиях флис надёжнее пуха?",
    "q.l21#1.o0" to "Потому что флис толще",
    "q.l21#1.o1" to "Потому что полиэфирное волокно само по себе гидрофобно и греет даже мокрым",
    "q.l21#1.o2" to "Потому что флис дешевле",
    "q.l21#1.o3" to "Потому что пух нельзя носить в качестве внутреннего слоя",
    "q.l21#1.e" to "Флис сделан из пластикового (полиэфирного) волокна, которое почти не впитывает влагу, поэтому во влажном состоянии он всё ещё удерживает слой воздуха и греет. Пух слёживается и теряет объём, намокнув, — поэтому его нужно держать строго сухим.",
    "q.l21#2.p" to "Какое пуховое наполнение рекомендуется для пуховика для экстремального высотного холода?",
    "q.l21#2.o0" to "Ниже 500",
    "q.l21#2.o1" to "Около 600",
    "q.l21#2.o2" to "800 fill power и выше",
    "q.l21#2.o3" to "Наполнение не имеет значения",
    "q.l21#2.e" to "Чем выше fill power, тем больше воздуха удерживает тот же вес пуха и тем эффективнее утепление. 800 и выше — обычная рекомендация для высотных поездок, вместе с капюшоном и без синтетического наполнителя.",
    "q.l21#3.p" to "Какова основная функция мембранной куртки (хардшелл)?",
    "q.l21#3.o0" to "Давать основное тепло",
    "q.l21#3.o1" to "Не пропускать воду и ветер, дышать, с капюшоном, который надевается поверх каски",
    "q.l21#3.o2" to "Отводить пот",
    "q.l21#3.o3" to "Добавлять вес для тренировочного эффекта",
    "q.l21#3.e" to "Мембрана не пропускает ветер, дождь и снег, выпуская влагу, которую вырабатываете вы. При плохой паропроницаемости водяной пар конденсируется на внутренних слоях — вы создаёте себе влажную среду своими руками.",
    "q.l21#4.p" to "Какая перчатка в системе специально предназначена для работы с сенсорными экранами?",
    "q.l21#4.o0" to "Тонкие флисовые перчатки",
    "q.l21#4.o1" to "Ветрозащитная и износостойкая перчатка с хорошей чувствительностью сенсора",
    "q.l21#4.o2" to "Толстые утеплённые перчатки гида",
    "q.l21#4.o3" to "Вершинные рукавицы",
    "q.l21#4.e" to "Работа с телефоном, GPS или камерой на высоте требует перчатки, которая одновременно защищает от ветра и работает с сенсором. Снимать перчатки, чтобы что-то нажать, — один из самых частых триггеров отморожения; лучше носить лишнюю пару именно для этого.",
    "q.l21#5.p" to "Какое утверждение о химических грелках для рук и ног верно?",
    "q.l21#5.o0" to "Их можно клеить куда угодно снаружи носка",
    "q.l21#5.o1" to "Использовать только в закрытом пространстве — в перчатках или внутри ботинка; на открытом воздухе они разогреваются примерно до 74 °C",
    "q.l21#5.o2" to "Чем ближе к коже, тем лучше",
    "q.l21#5.o3" to "Их можно клеить снаружи шапки",
    "q.l21#5.e" to "Грелки рассчитаны на ограниченный приток воздуха, который регулирует температуру. На вентилируемом воздухе они реагируют бурно и могут нагреться примерно до 74 °C — достаточно для ожога. Поэтому их место в закрытом пространстве — перчатки, внутренность ботинка — и никогда прямо на коже или на открытой поверхности.",
    "q.l21#6.p" to "Почему рекомендуются утеплённые куртки с капюшоном и пуховики с капюшоном?",
    "q.l21#6.o0" to "Потому что они лучше выглядят",
    "q.l21#6.o1" to "Потому что они универсальнее и заметно сокращают теплопотери через голову",
    "q.l21#6.o2" to "Потому что их легче упаковать",
    "q.l21#6.o3" to "Потому что версии с капюшоном легче",
    "q.l21#6.e" to "Голова — крупный источник теплопотерь, а капюшон — самое лёгкое утепление прямо на ядре. Куртку с капюшоном можно надеть мгновенно в лагере, на привале или при резком падении температуры; без капюшона приходится нести отдельную шапку, а это лишние хлопоты и лишний вес.",
    "q.l21#7.p" to "[Множественный выбор] Какие правила обращения с пуховиком и его хранения верны?",
    "q.l21#7.o0" to "Держать строго сухим: намокнув, он быстро теряет тепло",
    "q.l21#7.o1" to "Хранить сухим",
    "q.l21#7.o2" to "В экстремальный холод выбирать вариант с капюшоном и без синтетического наполнителя",
    "q.l21#7.o3" to "Чем выше fill power, тем теплее при том же весе",
    "q.l21#7.o4" to "Хранить долго в компрессионном мешке для экономии места",
    "q.l21#7.e" to "Пух греет за счёт удержания воздуха и слёживается, намокнув. Поэтому в мокрых условиях как рабочий средний слой предпочитают флис (гидрофобный полиэстер), а пух оставляют основным утеплением для сухой среды.",
    "q.l21#8.p" to "Какая характеристика разумна для высотного солнцезащитного средства?",
    "q.l21#8.o0" to "SPF 15, достаточно обычного крема",
    "q.l21#8.o1" to "Высокое содержание оксида цинка, уровень SPF 50",
    "q.l21#8.o2" to "Ниже SPF 30 — лучше дышит",
    "q.l21#8.o3" to "Любое средство с защитой, независимо от цифры",
    "q.l21#8.e" to "На высоте УФ интенсивен, а отражение от снега добавляет вторую дозу, поэтому обычный крем быстро перестаёт быть достаточным. Высокое содержание оксида цинка и SPF 50 — обычная рекомендация, и наносить заново нужно по расписанию: пот, вытирание и трение снижают защиту.",
    "q.l21#9.p" to "Что важно при выборе бальзама для губ для улицы?",
    "q.l21#9.o0" to "Чем дешевле, тем лучше",
    "q.l21#9.o1" to "Много цинка, умеренная стойкость к поту, SPF 30–50",
    "q.l21#9.o2" to "Достаточно увлажнения",
    "q.l21#9.o3" to "С ментолом ощущается прохладнее",
    "q.l21#9.e" to "Кожа губ тонкая и почти не имеет меланиновой защиты, поэтому на высоте легко сгорает и трескается. Цинк даёт физическую защиту, а стойкость к поту помогает бальзаму держаться при потоотделении, еде и питье, — самый мелкий предмет снаряжения, который чаще всего забывают и который сильнее всего влияет на ощущение похода.",
    "q.l22#0.p" to "Какой самый базовый предмет снаряжения для построения системы спасения из трещины?",
    "q.l22#0.o0" to "Петли прусика (вспомогательный шнур)",
    "q.l22#0.o1" to "Бинокль",
    "q.l22#0.o2" to "Запасной спальный мешок",
    "q.l22#0.o3" to "Треккинговые палки",
    "q.l22#0.e" to "Петли прусика служат для вязки схватывающих узлов и являются основой системы вытаскивания 3:1. Без них у вас остаётся только вытягивание 1:1 голыми руками, — а один человек почти никогда не вытащит партнёра из трещины одной силой.",
    "q.l22#1.p" to "В высокогорных районах какой способ вызова помощи обычно самый надёжный?",
    "q.l22#1.o0" to "Сигнал мобильного телефона",
    "q.l22#1.o1" to "Спутниковый телефон или GPS-трекер",
    "q.l22#1.o2" to "Крик",
    "q.l22#1.o3" to "Дымный костёр",
    "q.l22#1.e" to "В большинстве горных районов нет мобильного покрытия. Спутниковый телефон позволяет звонить и писать напрямую, а GPS-трекер даёт внешнему миру следить за вашим положением, — и то и другое нужно решить до выезда, а не в горах.",
    "q.l22#2.p" to "Какая яркость рекомендуется для запасного налобного фонаря?",
    "q.l22#2.o0" to "Ниже 100 люмен",
    "q.l22#2.o1" to "200 люмен достаточно",
    "q.l22#2.o2" to "400 люмен и выше",
    "q.l22#2.o3" to "Яркость не имеет значения",
    "q.l22#2.e" to "Налобный фонарь нужен для движения по лагерю ночью и для выходов до рассвета (штурм вершины обычно начинается в ранние часы). На ветру, в снегу, в тумане и когда нужно разглядеть маршрут адекватная яркость прямо влияет на качество ваших решений. Влагозащищённые модели в плохих условиях заметно лучше.",
    "q.l22#3.p" to "Каково ключевое требование при выборе альпинистской обвязки?",
    "q.l22#3.o0" to "Как можно легче, независимо от размера",
    "q.l22#3.o1" to "Достаточно большой по поясу и ногам, чтобы надеваться поверх верхней одежды",
    "q.l22#3.o2" to "Обязательно несколько петель для снаряжения",
    "q.l22#3.o3" to "Заметный цвет",
    "q.l22#3.e" to "На высоте вы обычно в объёмной одежде, и обвязка должна правильно сидеть поверх неё. Обвязка, растянутая до последнего предела только чтобы застегнуться поверх толстых слоёв, — частая и опасная ошибка.",
    "q.l22#4.p" to "Как штормовое предупреждение в часах-высотомере определяет непогоду?",
    "q.l22#4.o0" to "По спутниковым снимкам облачности",
    "q.l22#4.o1" to "По быстрому падению барометрического давления за короткий период",
    "q.l22#4.o2" to "По измерению скорости ветра",
    "q.l22#4.o3" to "По резкому падению температуры",
    "q.l22#4.e" to "Быстрое падение давления — предвестник ухудшения погоды. Часы-высотомер предупреждают, непрерывно отслеживая изменение давления, и на высоте это очень практично: то, как сдвигается погодное окно, часто и есть решающая переменная похода.",
    "q.l22#5.p" to "[Сопоставление] Соотнесите форму карабина с наиболее подходящим применением.",
    "q.l22#5.l0" to "HMS грушевидный",
    "q.l22#5.r0" to "Широкое раскрытие; держит итальянский узел для спуска, самый универсальный",
    "q.l22#5.l1" to "D-образный",
    "q.l22#5.r1" to "Часто в паре с блоком в спасательных системах",
    "q.l22#5.l2" to "X-образный",
    "q.l22#5.r2" to "Симметричный, простая муфта, легко встёгивать",
    "q.l22#5.l3" to "B-образный",
    "q.l22#5.r3" to "Базовый карабин для любых временных соединений",
    "q.l22#5.e" to "У каждой формы своя сильная сторона: HMS раскрывается достаточно широко для узла и спуска, D прочен и хорошо работает с блоком, X симметричен и удобен в обращении, B — универсальная база. Выбор карабина — не про то, какой «прочнее», а про то, соответствует ли механизм задаче.",
    "q.l22#6.p" to "При использовании жумара от чего руководство специально предостерегает?",
    "q.l22#6.o0" to "От использования в мокрых условиях",
    "q.l22#6.o1" to "От подведения жумара слишком близко к закреплённому концу (узлу)",
    "q.l22#6.o2" to "От работы одной рукой",
    "q.l22#6.o3" to "От использования на снегу",
    "q.l22#6.e" to "Если подвести жумар вплотную к узлу или закреплённой точке, он не может двигаться дальше, но и снять его быстро трудно, — вы застреваете: ни вверх, ни освободиться. Такая заклинившая ситуация очень опасна, когда нужно быстро перестроиться, поэтому решайте её, пока есть запас.",
    "q.l22#7.p" to "Какое утверждение о выборе перил и движения в связке верно?",
    "q.l22#7.o0" to "Перила всегда безопаснее связки",
    "q.l22#7.o1" to "Большие группы чаще используют перила; малым группам или на технических вершинах эффективнее идти в связке",
    "q.l22#7.o2" to "Связка подходит только для снежных склонов",
    "q.l22#7.o3" to "Перила только для спуска",
    "q.l22#7.e" to "Перила повышают общую безопасность, но требуют больше людей и снаряжения и дольше навешиваются. Небольшой слаженной группе или технической вершине часто лучше подходит движение в связке. Это классический случай «нет единственно верного ответа, есть соответствие задаче».",
    "q.l22#8.p" to "[Множественный выбор] Что из этого — устройства связи и навигации для больших высот?",
    "q.l22#8.o0" to "Спутниковый телефон",
    "q.l22#8.o1" to "Рация",
    "q.l22#8.o2" to "GPS-трекер",
    "q.l22#8.o3" to "Часы-высотомер с барометром",
    "q.l22#8.o4" to "Бинокль",
    "q.l22#8.e" to "Все четыре делают разное: спутниковый телефон — вызвать помощь наружу, рация — координация внутри группы, GPS-трекер — чтобы внешний мир знал, где вы, часы-высотомер — давление и тенденции высоты. Риски на высоте — это как раз невозможность позвать помощь и незнание, где вы; эти устройства бьют прямо в обе.",
    "q.l22#9.p" to "Почему каска должна допускать крепление налобного фонаря?",
    "q.l22#9.o0" to "Для визуального единообразия",
    "q.l22#9.o1" to "Потому что штурм вершины обычно начинается до рассвета, и фонарь должен держаться на голове устойчиво",
    "q.l22#9.o2" to "Чтобы уменьшить вес фонаря",
    "q.l22#9.o3" to "Чтобы повысить прочность каски",
    "q.l22#9.e" to "День вершины обычно начинается в ранние часы, и налобный фонарь — единственный источник света; при надетой каске его нужно крепить на каску, чтобы луч держался ровно. Фонарь, который болтается или слетает на ходу, лишает вас возможности видеть точки опоры — на техническом рельефе это реальный риск.",
    "q.m01#0.p" to "Насколько примерно падает температура воздуха на каждые 1 000 м подъёма?",
    "q.m01#0.o0" to "Около 1,5 °C",
    "q.m01#0.o1" to "Около 3 °C",
    "q.m01#0.o2" to "Около 6,5 °C",
    "q.m01#0.o3" to "Около 10 °C",
    "q.m01#0.e" to "Температура падает примерно на 6,5 °C на 1 000 м — это вертикальный градиент. Он объясняет высоту снеговой линии и почему вершина 5 000 м остаётся под снегом даже летом.",
    "q.m01#1.p" to "В чём основная причина гипоксии на высоте?",
    "q.m01#1.o0" to "Доля кислорода в воздухе ниже",
    "q.m01#1.o1" to "Давление воздуха падает, поэтому парциальное давление кислорода в каждом вдохе снижается",
    "q.m01#1.o2" to "Ультрафиолет разлагает кислород",
    "q.m01#1.o3" to "Воздух разрежается, и кислород замещается другими газами",
    "q.m01#1.e" to "Это очень распространённое заблуждение. Кислород на высоте по-прежнему около 21 % — доля не меняется. Меняется давление: при низком давлении в том же объёме меньше молекул кислорода, поэтому парциальное давление падает и организм получает меньше кислорода.",
    "q.m01#2.p" to "[Множественный выбор] Что типично для высокогорной среды?",
    "q.m01#2.o0" to "Низкое давление и низкое парциальное давление кислорода",
    "q.m01#2.o1" to "Низкая температура с большим суточным перепадом",
    "q.m01#2.o2" to "Заметно более сильное ультрафиолетовое излучение",
    "q.m01#2.o3" to "Чрезвычайно сухой воздух",
    "q.m01#2.o4" to "Значительно меньшая доля кислорода в воздухе",
    "q.m01#2.e" to "Первые четыре верны, и они усиливают друг друга: холод плюс гипоксия — организм плохо и греется, и получает кислород; сухость плюс сильный УФ быстрее повреждают дыхательные пути, кожу и глаза. Снаряжение и график должны закрывать все четыре сразу.",
    "q.m01#3.p" to "Давление на уровне моря около 1 013 гПа. Каково давление на 5 000 м?",
    "q.m01#3.o0" to "Около 900 гПа",
    "q.m01#3.o1" to "Около 700 гПа",
    "q.m01#3.o2" to "Около 540 гПа",
    "q.m01#3.o3" to "Около 300 гПа",
    "q.m01#3.e" to "На 5 000 м давление примерно вдвое ниже, чем на уровне моря. Поэтому в каждом вдохе примерно вдвое меньше молекул кислорода, — организм компенсирует это учащением дыхания и пульса, и это физическая причина того, что наверху вы задыхаетесь и идёте медленнее.",
    "q.m01#4.p" to "Заполните: температура падает примерно на ( ) °C на каждые 1 000 м подъёма.",
    "q.m01#4.a0" to "6,5",
    "q.m01#4.a1" to "шесть целых пять десятых",
    "q.m01#4.e" to "6,5 °C на 1 000 м. Эта цифра действительно полезна при планировании: переход от базового лагеря 3 000 м к 5 000 м означает примерно на 13 °C холоднее, и это напрямую определяет, насколько толстыми нужны пуховик и спальник.",
    "q.m01#5.p" to "[Порядок] Расставьте причинно-следственную цепочку высотной гипоксии по порядку.",
    "q.m01#5.o0" to "Давление воздуха падает, снижая парциальное давление вдыхаемого кислорода",
    "q.m01#5.o1" to "Сатурация артериальной крови падает",
    "q.m01#5.o2" to "Организм компенсирует учащением дыхания и пульса",
    "q.m01#5.o3" to "Длительная гипоксия может привести к высотной болезни",
    "q.m01#5.e" to "Эта цепочка — каркас высотной медицины: среда, физиология, компенсация, декомпенсация. Как только вы её видите, AMS, HACE и HAPE перестают быть отдельными фактами и становятся разными стадиями одной цепи.",
    "q.m01#6.p" to "Каково отражение свежего снега?",
    "q.m01#6.o0" to "Около 20 %",
    "q.m01#6.o1" to "Около 40 %",
    "q.m01#6.o2" to "Около 60 %",
    "q.m01#6.o3" to "Около 80–90 %",
    "q.m01#6.e" to "Свежий снег отражает примерно 80–90 % солнечной радиации. Поэтому УФ-нагрузка на снежном поле почти удваивается: прямо сверху плюс отражение от поверхности. Именно поэтому снежная слепота и сильные солнечные ожоги так часты в горах.",
    "q.m01#7.p" to "Почему защита от солнца на высоте обязательна, а не по желанию?",
    "q.m01#7.o0" to "Потому что там солнце ближе к земле",
    "q.m01#7.o1" to "Потому что УФ растёт с высотой, а снег отражает его вам в лицо",
    "q.m01#7.o2" to "Потому что озоновый слой тоньше и видимый свет сильнее",
    "q.m01#7.o3" to "Потому что холод ослабляет сопротивляемость кожи",
    "q.m01#7.e" to "Интенсивность УФ растёт примерно на 10–12 % на каждые 1 000 м, а снег добавляет ещё 80–90 % отражения. Вместе доза намного превышает низкогорную точку на той же широте. Крем, бальзам для губ и очки UV400 — это снаряжение, а не дополнение.",
    "q.m01#8.p" to "У сухого воздуха на высоте есть одно легко упускаемое следствие. Какое?",
    "q.m01#8.o0" to "Кожа становится лучше",
    "q.m01#8.o1" to "Незаметная потеря воды при дыхании и потоотделении, усиливающая обезвоживание и высотные симптомы",
    "q.m01#8.o2" to "Аппетит становится больше",
    "q.m01#8.o3" to "Сон становится глубже",
    "q.m01#8.e" to "Сухой воздух и учащённое дыхание непрерывно вытягивают влагу из дыхательных путей, а жажды вы часто совсем не чувствуете. Обезвоживание сгущает кровь и усиливает ощущение гипоксии и головную боль, — поэтому регулярное питьё часть акклиматизации, а не запоздалая мысль.",
    "q.m01#9.p" to "[Множественный выбор] Какие из этих травм вызваны непосредственно высокогорной средой?",
    "q.m01#9.o0" to "Солнечный ожог",
    "q.m01#9.o1" to "Снежная слепота",
    "q.m01#9.o2" to "Обезвоживание",
    "q.m01#9.o3" to "Трещины на губах",
    "q.m01#9.o4" to "Растяжение голеностопа",
    "q.m01#9.e" to "Первые четыре — травмы среды, и у них общая черта: их почти полностью можно предотвратить. В отличие от лавин они не трудно предсказуемы — они зависят только от снаряжения и привычек, поэтому их появление в группе обычно означает ошибку в подготовке.",
    "q.m01#10.p" to "Какое утверждение о составе воздуха на высоте верно?",
    "q.m01#10.o0" to "Доля кислорода падает с высотой",
    "q.m01#10.o1" to "Доля остаётся примерно той же; низкое давление снижает парциальное давление",
    "q.m01#10.o2" to "Доля азота растёт с высотой",
    "q.m01#10.o3" to "Кислород вытесняется другими газами на высоте",
    "q.m01#10.e" to "В тропосфере состав практически постоянен (около 21 % кислорода, 78 % азота). С высотой меняется давление — сколько молекул в том же глотке воздуха. Разберитесь с этим различием, и многие вопросы о снаряжении и физиологии станут простыми.",
    "q.m01#11.p" to "Почему вершины 5 000 м остаются под снегом летом?",
    "q.m01#11.o0" to "Потому что высокие места дальше от солнца",
    "q.m01#11.o1" to "Потому что воздух на высоте намного холоднее, чем на низменности на той же широте, и осадки выпадают снегом",
    "q.m01#11.o2" to "Потому что сильный ветер на вершине не даёт снегу таять",
    "q.m01#11.o3" to "Потому что слежавшийся снег превращается в лёд и больше не тает",
    "q.m01#11.e" to "Правило 6,5 °C на 1 000 м удерживает летние температуры на 5 000 м ниже нуля. Это же объясняет, почему одна и та же гора сложнее в один сезон, чем в другой: снеговая линия смещается, а вместе с ней и маршрут.",
    "q.m01#12.p" to "От базового лагеря 3 000 м до лагеря 5 000 м, по среднему градиенту, насколько примерно холоднее?",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13 °C. Арифметика: набор 2 000 м при 6,5 °C на 1 000 м даёт 2 × 6,5 = 13 °C. Эта оценка очень практична до поездки — она определяет, насколько толстыми должны быть утепление и спальник.",
    "q.m02#0.p" to "Какая физическая форма важнее всего для высотного альпинизма?",
    "q.m02#0.o0" to "Взрывная сила и короткие спринты",
    "q.m02#0.o1" to "Аэробная выносливость, держащаяся часами",
    "q.m02#0.o2" to "Максимальная сила хвата",
    "q.m02#0.o3" to "Гибкость",
    "q.m02#0.e" to "Высотный альпинизм — долгая работа низкой интенсивности: шесть-десять часов в день, не круто, но без передышки. Гипоксия резко ограничивает анаэробные возможности, поэтому несут вас аэробная база и умение держать ровный темп.",
    "q.m02#1.p" to "Как организовать тренировки перед выездом?",
    "q.m02#1.o0" to "Впихнуть большой блок за неделю до выезда",
    "q.m02#1.o1" to "Сделать разгрузку в последние две-три недели и уехать отдохнувшим",
    "q.m02#1.o2" to "Тренироваться на максимуме до последнего дня",
    "q.m02#1.o3" to "Не тренироваться вовсе, положиться на акклиматизацию на месте",
    "q.m02#1.e" to "Прирост формы происходит во время восстановления. Приехать уставшим — подорвать и работоспособность, и акклиматизацию, а сама акклиматизация стоит энергии. Разгрузка и есть то, что превращает тренировки в форму.",
    "q.m02#2.p" to "На чём должен основываться рацион на высоте?",
    "q.m02#2.o0" to "На жирной пище",
    "q.m02#2.o1" to "На углеводах",
    "q.m02#2.o2" to "На белковой пище",
    "q.m02#2.o3" to "Только на жидкости",
    "q.m02#2.e" to "Углеводы метаболизируются эффективнее и требуют меньше кислорода в условиях гипоксии, и организм наверху инстинктивно предпочитает их. Это идёт против интуиции, что высота требует калорийного жира, — ограничение здесь в кислородной эффективности.",
    "q.m02#3.p" to "Какой практичный показатель достаточного питья?",
    "q.m02#3.o0" to "Насколько вы чувствуете жажду",
    "q.m02#3.o1" to "Моча остаётся светлой",
    "q.m02#3.o2" to "Выпивать фиксированный 1 литр в день",
    "q.m02#3.o3" to "Изменение массы тела",
    "q.m02#3.e" to "Жажда на высоте ненадёжна: и холод, и гипоксия её притупляют. Цвет и запах мочи — более прямой ежедневный индикатор: светлая значит примерно достаточно, тёмная и резкая — пейте больше.",
    "q.m02#4.p" to "Почему на высоте избегают алкоголя?",
    "q.m02#4.o0" to "Потому что от него набирают вес",
    "q.m02#4.o1" to "Потому что он подавляет дыхательный драйв и усиливает ночную гипоксию",
    "q.m02#4.o2" to "Потому что он ускоряет УФ-повреждение",
    "q.m02#4.o3" to "Потому что там нет холодильника",
    "q.m02#4.e" to "И алкоголь, и седативные подавляют дыхательный центр. Ночи на высоте и так склонны к периодическому дыханию, а добавление угнетения дыхания заметно снижает сатурацию — один из ключевых механизмов, из-за которых высотная болезнь усиливается за ночь.",
    "q.m02#5.p" to "[Множественный выбор] Какие способы получать энергию в движении на высоте верны?",
    "q.m02#5.o0" to "Понемногу и часто, до того как сильно проголодались",
    "q.m02#5.o1" to "Предпочитать легко усваиваемую еду с умеренным содержанием воды",
    "q.m02#5.o2" to "Основывать рацион на углеводах",
    "q.m02#5.o3" to "Съедать один большой приём, чтобы сократить число перекусов",
    "q.m02#5.e" to "Понемногу и часто облегчает пищеварение и держит сахар ровным. Большой приём в гипоксии обычно даёт вздутие и тошноту, — а поскольку потеря аппетита сама по себе частый симптом, заставлять себя съесть много — путь назад.",
    "q.m02#6.p" to "На высоте аппетит падает. Как правильно поступить?",
    "q.m02#6.o0" to "Перестать есть и ждать голода",
    "q.m02#6.o1" to "Есть осознанно, выбирая углеводную и легко усваиваемую еду",
    "q.m02#6.o2" to "Пить много кофе вместо еды",
    "q.m02#6.o3" to "Принимать только электролиты",
    "q.m02#6.e" to "Потеря аппетита — часть высотной болезни, а недоедание ослабляет акклиматизацию: замкнутый круг. Ешьте осознанно, понемногу и часто: дело не в том, чувствуете ли вы голод, а в необходимости.",
    "q.m02#7.p" to "Какое утверждение о форме и высоте верно?",
    "q.m02#7.o0" to "Если ты в форме, высотная болезнь тебе не грозит",
    "q.m02#7.o1" to "Форма улучшает работоспособность, но не заменяет акклиматизацию",
    "q.m02#7.o2" to "Нетренированным не стоит ехать на высоту",
    "q.m02#7.o3" to "Чем лучше форма, тем меньше нужна акклиматизация",
    "q.m02#7.e" to "Форма и акклиматизация — две разные линии. Тренированный человек на той же высоте может чувствовать себя комфортнее, но физиологии всё равно нужны дни, — и логика «я в форме, значит не заболею» стоит за многими авариями.",
    "q.m02#8.p" to "[Порядок] Расставьте разумную последовательность подготовки к восхождению по времени.",
    "q.m02#8.o0" to "Базовая физическая подготовка (за два-три месяца)",
    "q.m02#8.o1" to "Разгрузка и защита восстановления (за две-три недели)",
    "q.m02#8.o2" to "Проверка снаряжения, графика и страховки (за неделю)",
    "q.m02#8.o3" to "Акклиматизация по плану (во время поездки)",
    "q.m02#8.e" to "Порядок и есть метод: тренироваться заранее, оставить место для восстановления, подготовиться в деталях, акклиматизироваться медленно. Чаще всего ломаются два последних шага: многие тщательно проверяют снаряжение, а потом в горах гонятся за графиком и сокращают акклиматизацию.",
    "q.m02#9.p" to "Какие проблемы может вызвать избыточное питьё (большой объём за короткое время) на высоте?",
    "q.m02#9.o0" to "Никаких",
    "q.m02#9.o1" to "Разбавляет электролиты крови, в тяжёлых случаях вызывает гипонатриемию",
    "q.m02#9.o2" to "Эффективно предотвращает отёк лёгких",
    "q.m02#9.o3" to "Может заменить еду",
    "q.m02#9.e" to "«Пить достаточно» не значит «пить отчаянно». Большой объём за короткое время без электролитов может разбавить натрий крови и вызвать головную боль, тошноту и изменение сознания — симптомы, очень похожие на высотную болезнь и легко прочитываемые неверно. Ответ — ровное, достаточное питьё.",
    "q.m03#0.p" to "В чём суть принципа минимального воздействия?",
    "q.m03#0.o0" to "Брать более лёгкое снаряжение, чтобы меньше нагружать себя",
    "q.m03#0.o1" to "Минимизировать воздействие человеческой деятельности на горную среду",
    "q.m03#0.o2" to "Снижать сложность восхождения ради безопасности",
    "q.m03#0.o3" to "Сокращать число людей в группе",
    "q.m03#0.e" to "Принцип минимального воздействия — экологическая этика, принятая в горном туризме. Речь не о том, насколько легко вы идёте, а о том, насколько гора меняется от вашего присутствия: мусор, вытаптывание, костры и беспокойство животных — всё считается.",
    "q.m03#1.p" to "Уходя из лагеря, как правильно поступать с мусором?",
    "q.m03#1.o0" to "Пищевые отходы можно закопать на месте",
    "q.m03#1.o1" to "Вынести всё, включая туалетную бумагу и гигиенические средства",
    "q.m03#1.o2" to "Забрать только пластик",
    "q.m03#1.o3" to "Сжечь в яме",
    "q.m03#1.e" to "В руководстве сказано прямо: упаковать всё, что вы произвели, и вынести; проверить лагерь и место деятельности и вынести гигиенические средства, включая туалетную бумагу. Закапывание и сжигание оставляют следы, а в холодных высокогорных условиях отходы разлагаются крайне медленно.",
    "q.m03#2.p" to "Какой принцип определяет выбор места для туалета в природе?",
    "q.m03#2.o0" to "Чем скрытнее, тем лучше — приватность прежде всего",
    "q.m03#2.o1" to "Подальше от источников воды, лагерей и троп",
    "q.m03#2.o2" to "Где снег ровнее",
    "q.m03#2.o3" to "Рядом с ручьём, чтобы смывало",
    "q.m03#2.e" to "Цель — не загрязнять воду и не заставить следующую группу на это наткнуться. На практике это значит определённое расстояние от воды и троп, неглубокая ямка и вынос использованной бумаги, а выше снеговой линии — вынести всё, потому что разложение почти не идёт.",
    "q.m03#3.p" to "Зачем герметично упаковывать еду и мусор?",
    "q.m03#3.o0" to "Чтобы не отсырело",
    "q.m03#3.o1" to "Чтобы животные не разоряли запасы и не привыкали к этому",
    "q.m03#3.o2" to "Чтобы сэкономить место в рюкзаке",
    "q.m03#3.o3" to "Чтобы легче было взвесить",
    "q.m03#3.e" to "Животных, которые роются в еде, обычно приучают к этому сами группы: как только они связывают лагерь с едой, риск на этом маршруте растёт навсегда. Герметичность защищает вашу еду, животных и всех, кто придёт после вас.",
    "q.m03#4.p" to "Что в основном означает чувствительный период для дикой природы?",
    "q.m03#4.o0" to "Дневные часы кормления",
    "q.m03#4.o1" to "Сезоны спаривания и выкармливания потомства",
    "q.m03#4.o2" to "Сезон миграции",
    "q.m03#4.o3" to "Зимний покой",
    "q.m03#4.e" to "Животные особенно чувствительны к беспокойству во время спаривания и выращивания молодняка, а мать, защищающая детёныша, может быть агрессивной. Поэтому помимо избегания их участков, избегайте постоянного времени и места водопоя: это защищает и их, и вас.",
    "q.m03#5.p" to "Почему нужно идти по существующим тропам?",
    "q.m03#5.o0" to "Потому что этого требуют правила",
    "q.m03#5.o1" to "Потому что вытаптывание создаёт новые устойчивые тропы и запускает эрозию",
    "q.m03#5.o2" to "Потому что по тропам легче идти",
    "q.m03#5.o3" to "Потому что гиды их размечают",
    "q.m03#5.e" to "Высокогорная растительность растёт крайне медленно; один след ботинка может сохраняться годами. Параллельные «срезки» прорезают растительность и концентрируют сток воды, постепенно прорезая промоины, — так маршрут и начинает деградировать.",
    "q.m03#6.p" to "[Множественный выбор] Что из этого обязательно выносить из гор?",
    "q.m03#6.o0" to "Упаковка от еды",
    "q.m03#6.o1" to "Фруктовые очистки и остатки еды",
    "q.m03#6.o2" to "Использованная туалетная бумага",
    "q.m03#6.o3" to "Окурки",
    "q.m03#6.o4" to "Скотч и шнур можно сжечь на месте",
    "q.m03#6.e" to "Первые четыре уходят с вами. Самое частое заблуждение — очистки и остатки: они выглядят биоразлагаемыми, но в холодных сухих высокогорных условиях разлагаются очень медленно и привлекают животных, меняя их поведение.",
    "q.m03#7.p" to "Как правильно относиться к сбору природных объектов (камней, растений, окаменелостей) на память?",
    "q.m03#7.o0" to "Мелкие предметы брать можно",
    "q.m03#7.o1" to "Не брать ничего природного — вместо этого фотографировать",
    "q.m03#7.o2" to "Можно, если не вредишь окружающей среде",
    "q.m03#7.o3" to "Сбор образцов помогает науке",
    "q.m03#7.e" to "«Берите только фотографии, оставляйте только следы» — классическая формулировка. Природные объекты часть местной экологии и ландшафта, а когда каждая группа берёт понемногу, суммарный эффект значителен.",
    "q.m03#8.p" to "Как альпинизм в основном влияет на горную среду?",
    "q.m03#8.o0" to "Только через мусор",
    "q.m03#8.o1" to "Повреждение растительности, сокращение ареалов животных, мусор и культурное влияние приезжих на местные сообщества",
    "q.m03#8.o2" to "В основном шумом",
    "q.m03#8.o3" to "Влияние ничтожно",
    "q.m03#8.e" to "В руководстве воздействие делится на экологическое и социальное: повреждение растительности, вытеснение животных и мусор с одной стороны, культурное давление на местный уклад с другой. Понимание этого и есть причина, по которой этикет входит в альпинистское обучение.",
    "q.m03#9.p" to "[Порядок] Расставьте порядок действий при уходе из лагеря по принципу минимального воздействия.",
    "q.m03#9.o0" to "Собрать личное и групповое снаряжение",
    "q.m03#9.o1" to "Разобрать и упаковать весь мусор",
    "q.m03#9.o2" to "Разобраться с человеческими отходами (закопать или вынести)",
    "q.m03#9.o3" to "Обойти лагерь и место деятельности и убедиться, что ничего не осталось",
    "q.m03#9.e" to "Последний шаг — обход — пропускают чаще всего, и он самый важный: люди инстинктивно забирают «свои вещи», и именно так остаются колышки, концы верёвок и оброненные обёртки. Оглянуться почти ничего не стоит.",
    "q.m04#0.p" to "Какой признак изменения погоды самый надёжный?",
    "q.m04#0.o0" to "Солнечно ли сейчас",
    "q.m04#0.o1" to "Тенденции давления, облачности и ветра",
    "q.m04#0.o2" to "Прогноз, сделанный до выезда",
    "q.m04#0.o3" to "Самочувствие партнёров",
    "q.m04#0.e" to "Настоящее — это снимок, тенденция — направление. Давление устойчиво падает, облака густеют и опускаются, ветер усиливается: когда все три совпадают, погода меняется. В этом и практическая ценность барометра — в часах или отдельного.",
    "q.m04#1.p" to "Что типично для кучево-дождевого облака и что это означает?",
    "q.m04#1.o0" to "Тонкое и ровное — устойчивая погода",
    "q.m04#1.o1" to "Вертикальное развитие с наковальней — грозы и сильные осадки",
    "q.m04#1.o2" to "Растекается слоями — только морось",
    "q.m04#1.o3" to "Перистые нити — хорошая погода",
    "q.m04#1.e" to "Вертикальный рост говорит о сильной конвекции, а наковальня — что облако достигло зрелости. Встретить такое на высоте значит, что возможны молния, град и сильные осадки, — немедленно уходите с открытых гребней и высоких мест.",
    "q.m04#2.p" to "Какие масштабы карт обычно используются в альпинизме?",
    "q.m04#2.o0" to "1:1 000 и 1:5 000",
    "q.m04#2.o1" to "1:50 000 и 1:10 000",
    "q.m04#2.o2" to "1:250 000 и 1:500 000",
    "q.m04#2.o3" to "Любой масштаб подойдёт",
    "q.m04#2.e" to "1:50 000 и 1:10 000 — обычная пара: первый охватывает большую площадь и годится для планирования, второй несёт детали и подходит для технического рельефа. 1:200 000 используют иногда, 1:10 000 — реже: лист покрывает так мало, что вы быстро с него уходите.",
    "q.m04#3.p" to "Что означают близко расположенные горизонтали на топографической карте?",
    "q.m04#3.o0" to "Пологий склон",
    "q.m04#3.o1" to "Крутой склон",
    "q.m04#3.o2" to "Долину",
    "q.m04#3.o3" to "Ледник",
    "q.m04#3.e" to "Чем ближе горизонтали, тем больше высоты набирается на том же горизонтальном расстоянии, иными словами — тем круче. Это полезный навык чтения при планировании: крутые участки, полки и возможные места под палатку можно отметить ещё до выхода.",
    "q.m04#4.p" to "Что означает замкнутая горизонталь на топографической карте?",
    "q.m04#4.o0" to "Озеро",
    "q.m04#4.o1" to "Отдельную вершину",
    "q.m04#4.o2" to "Ледник",
    "q.m04#4.o3" to "Скалу",
    "q.m04#4.e" to "Замкнутая горизонталь означает, что массив падает во все стороны — это и есть определение отдельной вершины. Несколько концентрических замкнутых колец означают, что гора поднимается ступенями, а внутреннее кольцо обозначает привершинную зону.",
    "q.m04#5.p" to "[Множественный выбор] На что обращать внимание при работе с компасом?",
    "q.m04#5.o0" to "Держать его как можно ровнее",
    "q.m04#5.o1" to "Держаться подальше от магнитных предметов",
    "q.m04#5.o2" to "Не путать южный конец стрелки с севером",
    "q.m04#5.o3" to "Учитывать местное магнитное склонение",
    "q.m04#5.o4" to "Держать его рядом с металлическими пряжками рюкзака, чтобы не качался",
    "q.m04#5.e" to "Все четыре пункта прямо перечислены в руководстве. Одна только ошибка с южным концом даёт ошибку направления на 180°, — в сложном рельефе это может увести вас в противоположную сторону незаметно для себя.",
    "q.m04#6.p" to "Что такое магнитное склонение?",
    "q.m04#6.o0" to "Производственная погрешность компаса",
    "q.m04#6.o1" to "Расхождение между магнитным и истинным севером, которое нужно учитывать",
    "q.m04#6.o2" to "Изменение угла из-за высоты",
    "q.m04#6.o3" to "Искажение из-за картографической проекции",
    "q.m04#6.e" to "Стрелка показывает на магнитный север, а карты привязаны к истинному, и они расходятся. Склонение зависит от региона, поэтому его нужно учитывать при совместной работе с картой и компасом, — иначе весь маршрут смещается.",
    "q.m04#7.p" to "Что представляют собой ровные квадратные линии сетки на топографической карте?",
    "q.m04#7.o0" to "Линии широты и долготы",
    "q.m04#7.o1" to "Сетку UTM (Universal Transverse Mercator)",
    "q.m04#7.o2" to "Горизонтали",
    "q.m04#7.o3" to "Административные границы",
    "q.m04#7.e" to "Это не широта и долгота, а UTM. Это важно, потому что Земля — эллипсоид: ячейки широты-долготы на разных широтах не равны по размеру, а квадраты UTM равны, — поэтому измерять расстояния и координаты по ним просто.",
    "q.m04#8.p" to "Почему нельзя полагаться только на GPS?",
    "q.m04#8.o0" to "Потому что GPS недостаточно точен",
    "q.m04#8.o1" to "Потому что устройство может разрядиться, намокнуть, сломаться или потерять сигнал",
    "q.m04#8.o2" to "Потому что GPS работает только в городах",
    "q.m04#8.o3" to "Потому что для GPS нужна подписка",
    "q.m04#8.e" to "GPS — отличное подспорье, но предполагает работающее устройство. На высотном холоде батареи садятся быстро, а вода и падения — обычное дело. Карта и компас не требуют питания, поэтому они и остаются обязательными в альпинистском обучении.",
    "q.m04#9.p" to "Когда видимость пропадает (туман, «молочное небо»), что делать в первую очередь?",
    "q.m04#9.o0" to "Ускориться и пройти это место",
    "q.m04#9.o1" to "Немедленно определить своё положение и направление движения, при необходимости ждать на месте",
    "q.m04#9.o2" to "Идти прямо по первоначальному плану",
    "q.m04#9.o3" to "Разделиться и искать маршрут",
    "q.m04#9.e" to "Опасность «молочного неба» в потере всех визуальных ориентиров, и люди инстинктивно идут не туда. Зафиксируйте положение, запишите направление и при необходимости подождите — это гораздо безопаснее, чем идти дальше, а разделяться — худший из вариантов.",
    "q.m05#0.p" to "В чём основное различие между треккинговой и технической вершиной?",
    "q.m05#0.o0" to "В высоте",
    "q.m05#0.o1" to "В том, нужны ли техническое снаряжение и технические приёмы",
    "q.m05#0.o2" to "В том, в какой стране она находится",
    "q.m05#0.o3" to "В том, нужно ли разрешение",
    "q.m05#0.e" to "Разделяет их техническая сложность, а не высота. Килиманджаро на 5 895 м не требует технического снаряжения, а Хаба на 5 396 м выше снеговой линии требует кошек и ледоруба. Высота — лишь одно измерение сложности.",
    "q.m05#1.p" to "Как называется высшая точка Килиманджаро?",
    "q.m05#1.o0" to "Пик Ухуру",
    "q.m05#1.o1" to "Кибо",
    "q.m05#1.o2" to "Мавензи",
    "q.m05#1.o3" to "Шира",
    "q.m05#1.e" to "Вершина — пик Ухуру, 5 895 м. Килиманджаро — потухший вулкан из трёх конусов: Кибо, Мавензи и Шира, и Ухуру — высшая точка Кибо.",
    "q.m05#2.p" to "Чем уникален Килиманджаро?",
    "q.m05#2.o0" to "Это наименее посещаемая вершина 5 000 м в мире",
    "q.m05#2.o1" to "Он стоит почти на экваторе, но несёт ледники, пересекая климатические зоны от тропического леса до высокогорной пустыни",
    "q.m05#2.o2" to "Требует сложного технического снаряжения",
    "q.m05#2.o3" to "На него можно подняться только один месяц в году",
    "q.m05#2.e" to "Экватор плюс ледники делают Килиманджаро вертикальным климатическим коридором: от тропического леса до льда за одну поездку. Отсюда и практическая проблема — большой перепад высот при быстром наборе, поэтому акклиматизация становится главной задачей.",
    "q.m05#3.p" to "К какой группе вершин относится Аотайна?",
    "q.m05#3.o0" to "Сигунян",
    "q.m05#3.o1" to "Снежные горы Саньао",
    "q.m05#3.o2" to "Гунга",
    "q.m05#3.o3" to "Мэйли",
    "q.m05#3.e" to "Группа Саньао в Хэйшуй (Сычуань) состоит из Аотайцзи (отца гор), Аотаймэй (матери) и Аотайны (сына). Аотайна — самая простая из трёх и часто выбирается первой снежной вершиной.",
    "q.m05#4.p" to "Какое описание высоты Аотайны точно?",
    "q.m05#4.o0" to "Все источники сходятся на 4 800 м",
    "q.m05#4.o1" to "Официальная высота 5 211 м, но измеренная около 4 800 м — источники расходятся",
    "q.m05#4.o2" to "Официально 4 800 м, измерено 5 211 м",
    "q.m05#4.o3" to "Высоту никогда не оспаривали",
    "q.m05#4.e" to "Такие расхождения в данных о вершинах обычны: официальные цифры, измерения и разные методики съёмки расходятся. Практический вывод — указывать источник, когда приводите данные о вершине, а не считать одно число абсолютной истиной.",
    "q.m05#5.p" to "Каковы высоты Дафэн и Эрфэн в Сигуняне?",
    "q.m05#5.o0" to "5 025 м и 5 276 м",
    "q.m05#5.o1" to "5 276 м и 5 025 м",
    "q.m05#5.o2" to "5 025 м и 5 355 м",
    "q.m05#5.o3" to "4 850 м и 5 276 м",
    "q.m05#5.e" to "Дафэн — 5 025 м, Эрфэн — 5 276 м. Их часто берут парой как ступени входа: сначала Дафэн для высотного опыта, затем Эрфэн, последний участок которого требует простой технической поддержки, — естественный шаг к техническому альпинизму.",
    "q.m05#6.p" to "[Множественный выбор] При выборе первой снежной вершины какие факторы стоит сравнить в первую очередь?",
    "q.m05#6.o0" to "Насколько освоен маршрут и какова доля успешных восхождений",
    "q.m05#6.o1" to "Надёжны ли гиды и спасательная поддержка",
    "q.m05#6.o2" to "Разумно ли выстроен набор высоты",
    "q.m05#6.o3" to "Ваша текущая форма и сколько времени вы можете выделить",
    "q.m05#6.o4" to "Насколько вершина популярна в соцсетях",
    "q.m05#6.e" to "Первые четыре вместе отвечают на вопрос «подходит ли мне эта гора сейчас». Смотреть только на цифру высоты обманчиво: вершина 5 000 м с разумным темпом и хорошей поддержкой может быть безопаснее вершины 5 500 м, требующей три спешных дня.",
    "q.m05#7.p" to "Что чаще всего становится причиной неудачи на вводной вершине?",
    "q.m05#7.o0" to "Техническая сложность",
    "q.m05#7.o1" to "Высотная болезнь и погода, а не техническая сложность",
    "q.m05#7.o2" to "Недостаточное снаряжение",
    "q.m05#7.o3" to "Слишком маленькая группа",
    "q.m05#7.e" to "Это самый недооценённый момент: на вводных вершинах неудача почти всегда «не хватило сил» или «погода не подождала», а не «не прошли ключ». Поэтому настоящая домашняя работа на этом уровне — акклиматизация, темп и форма, а не технические приёмы.",
    "q.m05#8.p" to "Почему доля успешных восхождений — полезная цифра при выборе вершины?",
    "q.m05#8.o0" to "Потому что она отражает красоту вершины",
    "q.m05#8.o1" to "Потому что она объединяет сложность маршрута, темп и реальный уровень поддержки",
    "q.m05#8.o2" to "Потому что она определяет стоимость",
    "q.m05#8.o3" to "Потому что она не связана с безопасностью",
    "q.m05#8.e" to "Доля успеха — произведение многого: насколько сложен маршрут, разумен ли набор высоты, насколько широки погодные окна, надёжна ли логистика. Она говорит о том, с чем вы реально столкнётесь, больше, чем одна высота.",
    "q.m05#9.p" to "Каково правильное отношение к вводной снежной вершине?",
    "q.m05#9.o0" to "Вводная значит без риска",
    "q.m05#9.o1" to "Вводная значит только меньшую техническую сложность; риски высоты и погоды остаются реальными",
    "q.m05#9.o2" to "Вводным вершинам не нужен гид",
    "q.m05#9.o3" to "Вводные вершины не требуют физической подготовки",
    "q.m05#9.e" to "«Вводная» описывает технический порог, а не общий риск. Высота сама по себе, резкая погода и истощение могут убить на любой высоте. Отношение «вводная — значит легко» и есть начало плохой подготовки.",
    "q.m06#0.p" to "Какие три базовые системы технического альпинизма?",
    "q.m06#0.o0" to "Снаряжение, форма, погода",
    "q.m06#0.o1" to "Задержание, страховка, движение",
    "q.m06#0.o2" to "Подъём, спуск, отдых",
    "q.m06#0.o3" to "Кошки, ледоруб, верёвка",
    "q.m06#0.e" to "Задержание отвечает на вопрос «что делать, потеряв опору», страховка — «кто поймает, если я сорвусь», движение — «как пройти опасный участок». Вместе они замыкают контур: уберите любую — и технический альпинизм не работает.",
    "q.m06#1.p" to "В чём главный смысл обучения техническому альпинизму?",
    "q.m06#1.o0" to "Лазить более сложные маршруты",
    "q.m06#1.o1" to "Превратить неконтролируемое скольжение в управляемый риск",
    "q.m06#1.o2" to "Получить сертификат",
    "q.m06#1.o3" to "Двигаться быстрее",
    "q.m06#1.e" to "Техника не делает гору ниже, она меняет то, что происходит после ошибки. С задержанием срыв уже не необратимая катастрофа; со страховкой одна ошибка не означает автоматически падение. В этом и реальная ценность.",
    "q.m06#2.p" to "Как лучше всего освоить технический приём?",
    "q.m06#2.o0" to "Многократно смотреть обучающие видео",
    "q.m06#2.o1" to "Повторять на защищённом рельефе, пока движение не станет рефлексом",
    "q.m06#2.o2" to "Прочитать руководство и запомнить пункты",
    "q.m06#2.o3" to "Выучить сразу на реальном крутом склоне",
    "q.m06#2.e" to "Технические действия приходится выполнять под давлением, а давление откатывает вас к тому уровню, на котором вы реально тренировались. Пологий склон, мягкий снег, чистый выкат и инструктор на страховке — когда есть все четыре, навык действительно осваивается.",
    "q.m06#3.p" to "Почему самоудержание нельзя выучить по видео?",
    "q.m06#3.o0" to "Потому что качество видео плохое",
    "q.m06#3.o1" to "Потому что это рефлекс, который строится только повторной практикой на рельефе",
    "q.m06#3.o2" to "Потому что показанная техника неверна",
    "q.m06#3.o3" to "Потому что самоудержание вообще простое",
    "q.m06#3.e" to "После срыва у вас одна-две секунды и нет времени думать. Мышечная память покупается повторами, — поэтому любой нормальный курс настаивает: отрабатывайте, пока не сможете делать это не задумываясь.",
    "q.m06#4.p" to "Какие три стартовых предмета технического снаряжения?",
    "q.m06#4.o0" to "Каска, перчатки, очки",
    "q.m06#4.o1" to "Кошки под ваши ботинки, ледоруб и обвязка",
    "q.m06#4.o2" to "Палатка, спальник, коврик",
    "q.m06#4.o3" to "GPS, рация, налобный фонарь",
    "q.m06#4.e" to "Кошки дают сцепление, ледоруб — задержание и опору, обвязка связывает вас со страховочной системой. Общее у них то, что безопасность они создают только подобранными и работающими как система с партнёром, — ни один предмет сам по себе никого не защищает.",
    "q.m06#5.p" to "Когда технические навыки освоены, какая способность становится важнейшей?",
    "q.m06#5.o0" to "Скорость лазания",
    "q.m06#5.o1" to "Умение понять, когда техническое снаряжение вообще не нужно",
    "q.m06#5.o2" to "Обслуживание снаряжения",
    "q.m06#5.o3" to "Дальнейший рост формы",
    "q.m06#5.e" to "Это самый контринтуитивный момент в техническом альпинизме: навык открывает вход в более сложный рельеф, а настоящие эксперты используют его, чтобы получить право туда не идти. Оценка всегда важнее исполнения.",
    "q.m06#6.p" to "[Множественный выбор] Что из этого относится к техническому альпинизму?",
    "q.m06#6.o0" to "Движение по ледовому склону с задержанием",
    "q.m06#6.o1" to "Переход ледника в связке",
    "q.m06#6.o2" to "Построение станции",
    "q.m06#6.o3" to "Спуск по верёвке",
    "q.m06#6.o4" to "Поход по обустроенной тропе",
    "q.m06#6.e" to "Первые четыре технические: каждое требует снаряжения, систем и специальной подготовки. Просто идти по снегу или по обустроенной тропе — нет; различие в том, нужны ли эти системы.",
    "q.m06#7.p" to "Почему техника никогда не заменяет оценку?",
    "q.m06#7.o0" to "Потому что технику нельзя натренировать",
    "q.m06#7.o1" to "Потому что плохая оценка заводит в рельеф, куда вы вообще не должны были входить, и там техника уже не спасёт",
    "q.m06#7.o2" to "Потому что оценке легче научиться",
    "q.m06#7.o3" to "Потому что техника применима только на скалах",
    "q.m06#7.e" to "Техника — то, что вы применяете, когда уже в опасности; оценка решает, войдёте ли вы в опасность вообще. В разборах аварий редко пишут «движение было неверным» — гораздо чаще «им не следовало там быть».",
    "q.m06#8.p" to "[Порядок] Расставьте последовательность обучения техническому альпинизму.",
    "q.m06#8.o0" to "Разобраться в снаряжении: как работают кошки, ледоруб и обвязка",
    "q.m06#8.o1" to "Многократно отработать базовые действия на безопасном рельефе (например, самоудержание)",
    "q.m06#8.o2" to "Освоить верёвочные системы: узлы, связка, станции",
    "q.m06#8.o3" to "Применить всё на реальных, но контролируемых маршрутах",
    "q.m06#8.e" to "Логика такая: сначала защитить себя, затем связаться с другими, затем выйти на реальный рельеф. Пропущенный шаг оставляет пробел в подготовке: например, выйти в связке на ледник с неотработанным задержанием — умножить риск на всю группу.",
    "q.m06#9.p" to "Что сделал этот раздел?",
    "q.m06#9.o0" to "Завершил всю высотную подготовку",
    "q.m06#9.o1" to "Заложил основу по среде, науке и снаряжению — можно начинать технические приёмы",
    "q.m06#9.o2" to "Завершил подготовку к 8 000 м",
    "q.m06#9.o3" to "Даёт сертификат спасателя",
    "q.m06#9.e" to "Вводный раздел о 5 000 м закладывает базу: наука о среде, снаряжение, одежда, форма, практика минимального воздействия, погода и навигация и, наконец, технический альпинизм. Следующий раздел начинается уже с кошек, ледоруба, задержания и работы с верёвкой.",
    "q.m07#0.p" to "В чём основная идея построения станции?",
    "q.m07#0.o0" to "Использовать как можно меньше снаряжения",
    "q.m07#0.o1" to "Отказ одной точки страховки не должен разрушать систему",
    "q.m07#0.o2" to "Строить станцию как можно выше",
    "q.m07#0.o3" to "Использовать только естественные точки",
    "q.m07#0.e" to "Скальные и снежные точки никогда не бывают абсолютно надёжными, поэтому систему строят с допуском на ошибку, а не на абсолютную прочность. Всё остальное — резервирование, выравнивание, отсутствие удлинения — просто развёрнутая формулировка этой идеи.",
    "q.m07#1.p" to "При двух точках страховки под углом 90° какую примерно долю нагрузки несёт каждая?",
    "q.m07#1.o0" to "Около 50 %",
    "q.m07#1.o1" to "Около 58 %",
    "q.m07#1.o2" to "Около 71 %",
    "q.m07#1.o3" to "Около 100 %",
    "q.m07#1.e" to "Это ключевые цифры из таблицы руководства: при 0° каждая точка несёт около 50 %, при 60° — около 58 %, при 90° — около 71 %. Чем шире угол, тем большую силу от одного и того же человека чувствует каждая точка, — и это напрямую определяет выбор и расположение точек.",
    "q.m07#2.p" to "С точки зрения нагрузки как обращаться с углом между точками страховки?",
    "q.m07#2.o0" to "Делать его как можно меньше, чтобы направления нагрузки почти совпадали",
    "q.m07#2.o1" to "Делать его как можно больше, чтобы распределить нагрузку в разные стороны",
    "q.m07#2.o2" to "Он обязательно должен быть 90°",
    "q.m07#2.o3" to "Угол не влияет на нагрузку",
    "q.m07#2.e" to "Чем меньше угол, тем ближе распределение к 50/50; расширьте — и нагрузка на каждую точку растёт. Частое правило «держать угол стропы в пределах 60°» прямо следует из этих цифр.",
    "q.m07#3.p" to "[Множественный выбор] Какие измерения учитывать при оценке станции?",
    "q.m07#3.o0" to "Прочность: каждая точка достаточно надёжна",
    "q.m07#3.o1" to "Резервирование: несколько независимых точек",
    "q.m07#3.o2" to "Выравнивание: нагрузка распределена разумно",
    "q.m07#3.o3" to "Отсутствие удлинения: отказ не создаёт удлинения с рывком",
    "q.m07#3.o4" to "Симметрия: аккуратная, визуально уравновешенная схема",
    "q.m07#3.e" to "Эти четыре — базовый каркас. Чаще всего упускают отсутствие удлинения: оставьте слабину между точками, и отказ даст рывок на остальные. Рывковые нагрузки гораздо больше статических, и многие этого не учитывают.",
    "q.m07#4.p" to "[Сопоставление] Соотнесите тип страховки со средой и способом.",
    "q.m07#4.l0" to "Естественные точки",
    "q.m07#4.r0" to "Скальные выступы, крупные деревья, большие блоки — убедиться, что они целы и устойчивы",
    "q.m07#4.l1" to "Снежная страховка",
    "q.m07#4.r1" to "Снежные анкеры, «мертвецы», Т-образные траншеи — надёжность сильно зависит от качества снега и закопки",
    "q.m07#4.l2" to "Ледовая страховка",
    "q.m07#4.r2" to "Ледобуры — убедиться, что лёд плотный, без пустот и сотовости",
    "q.m07#4.e" to "Три среды, три совершенно разных набора критериев. Одна из самых частых причин аварий — судить снег или лёд скальными инстинктами: «выглядит прочно» в снежном покрове почти ничего не значит.",
    "q.m07#5.p" to "Что из этого — ложное резервирование?",
    "q.m07#5.o0" to "Использование двух элементов разной прочности",
    "q.m07#5.o1" to "Две точки страховки, которые фактически зависят от одной трещины или одного блока",
    "q.m07#5.o2" to "Соединение точек стропами",
    "q.m07#5.o3" to "Установка трёх точек страховки",
    "q.m07#5.e" to "Резервирование требует независимого отказа. Если две точки делят одну трещину, раскрытие трещины выводит обе сразу: выглядит как две точки, работает как одна. Ложное резервирование встречается часто и убивает.",
    "q.m07#6.p" to "Зачем предварительно натягивать систему, чтобы не было удлинения?",
    "q.m07#6.o0" to "Для аккуратного вида",
    "q.m07#6.o1" to "Чтобы отказ не дал рывка на оставшиеся точки",
    "q.m07#6.o2" to "Чтобы сэкономить длину стропы",
    "q.m07#6.o3" to "Чтобы быстрее разбирать",
    "q.m07#6.e" to "Рывковая нагрузка гораздо больше статической: тот же человек, внезапно нагружающий точку, создаёт куда большую силу, чем когда висит спокойно. Станция со слабиной выглядит «гибче», но на деле превращает один отказ в рывок по всей системе.",
    "q.m07#7.p" to "[Порядок] Расставьте шаги построения станции в разумном порядке.",
    "q.m07#7.o0" to "Осмотреться и выбрать пригодные, взаимно независимые места под точки",
    "q.m07#7.o1" to "Установить каждую точку и убедиться, что она прочна сама по себе",
    "q.m07#7.o2" to "Соединить точки стропой или верёвкой, контролируя угол и предварительное натяжение",
    "q.m07#7.o3" to "Проверить всю систему на ложное резервирование и удлинение",
    "q.m07#7.e" to "Порядок такой: выбрать места, поставить отдельные точки, соединить систему, затем пересмотреть её. Проверка не формальность: при постройке вы сосредоточены на каждой постановке и легко упускаете общие связи, например две точки на одном элементе рельефа.",
    "q.m07#8.p" to "При использовании естественных точек что нужно проверить в первую очередь?",
    "q.m07#8.o0" to "Достаточно ли она велика",
    "q.m07#8.o1" to "Цела ли она — не подвижна, не выветрена, не отделена от основного массива",
    "q.m07#8.o2" to "Хорошо ли выглядит",
    "q.m07#8.o3" to "Легко ли обвязать",
    "q.m07#8.e" to "Опасность естественных точек обычно в том, что они выглядят большими, но уже подвижны. Важно, действительно ли они часть основного массива и нет ли трещин и признаков выветривания. Большое, толстое и очевидное не значит прочное.",
    "q.m07#9.p" to "Почему станцию нужно строить как можно быстрее, насколько это разумно?",
    "q.m07#9.o0" to "Чтобы сэкономить силы",
    "q.m07#9.o1" to "Потому что время на её постройку и есть время под риском",
    "q.m07#9.o2" to "Потому что партнёры будут торопить",
    "q.m07#9.o3" to "Потому что снаряжение теряется",
    "q.m07#9.e" to "Пока вы строите станцию, вы часто без страховки или со слабой страховкой, поэтому это время должно быть коротким. Именно поэтому в оценке есть не только прочность, резервирование и выравнивание, но и эффективность со своевременностью.",
    "q.m07#10.p" to "От чего в основном зависит надёжность снежной точки?",
    "q.m07#10.o0" to "От марки снаряжения",
    "q.m07#10.o1" to "От качества снега и качества закопки",
    "q.m07#10.o2" to "От высоты",
    "q.m07#10.o3" to "От цвета верёвки",
    "q.m07#10.e" to "Один и тот же снежный анкер держит совершенно разные нагрузки в глубоком снегу, в мокром снегу или на краю снежного моста. Снежная страховка требует оценки снежного покрова на месте, и это же делает её одним из самых требовательных навыков.",
    "q.m07#11.p" to "Если у станции только одна точка страховки, в чём главная проблема?",
    "q.m07#11.o0" to "Нагрузка слишком велика",
    "q.m07#11.o1" to "Запаса нет вообще: откажет эта точка — откажет система",
    "q.m07#11.o2" to "Неудобно работать",
    "q.m07#11.o3" to "Некрасиво выглядит",
    "q.m07#11.e" to "Станция на одной точке отдаёт вашу жизнь одному неопределённому фактору. Иногда это действительно единственный вариант — например, один хороший ледобур, — и тогда нужно сделать эту точку максимально хорошей и свести к минимуму время, которое система на ней висит.",
    "q.m08#0.p" to "Какова высота главной вершины Ганшики?",
    "q.m08#0.o0" to "5 005 м",
    "q.m08#0.o1" to "5 150 м",
    "q.m08#0.o2" to "5 254,5 м",
    "q.m08#0.o3" to "5 396 м",
    "q.m08#0.e" to "Главная вершина — 5 254,5 м. Обратите внимание на иерархию: третья вершина 5 005 м < плечевая 5 150 м < главная 5 254,5 м — три высоты, три уровня сложности, поэтому Ганшику часто используют как ступенчатую цель.",
    "q.m08#1.p" to "Какова высота и характер третьей вершины Ганшики?",
    "q.m08#1.o0" to "5 005 м, вводная техническая, около 95 % успешных восхождений у новичков",
    "q.m08#1.o1" to "5 254 м, высокая техническая сложность",
    "q.m08#1.o2" to "5 150 м, чистый треккинг",
    "q.m08#1.o3" to "5 396 м, ледниковый маршрут",
    "q.m08#1.e" to "Третья вершина — 5 005 м и вводная техническая. Успех около 95 % у новичков говорит, что маршрут посилен, а логистика отработана, — хорошо подходит, чтобы впервые надеть техническое снаряжение.",
    "q.m08#2.p" to "В чём географическое значение Ганшики?",
    "q.m08#2.o0" to "Высшая вершина хребта Куньлунь",
    "q.m08#2.o1" to "Высшая вершина восточной части хребта Цилянь",
    "q.m08#2.o2" to "Высшая вершина Тибетского плато",
    "q.m08#2.o3" to "Высшая вершина хребта Хэндуань",
    "q.m08#2.e" to "Ганшика — высшая вершина восточной части Цилянь, уезд Мэньюань, округ Хайбэй, Цинхай. Это также одна из высоких снежных вершин, ближайших к городу в Китае: доступность напрямую определяет, насколько вершина популярна как тренировочная цель.",
    "q.m08#3.p" to "Каковы подход и обычное время для третьей вершины Ганшики?",
    "q.m08#3.o0" to "Около 3 км / 2 часа",
    "q.m08#3.o1" to "Около 10 км / 6 часов",
    "q.m08#3.o2" to "Около 25 км / двое суток",
    "q.m08#3.o3" to "Около 1 км / 30 минут",
    "q.m08#3.e" to "Около 10 км и шесть часов. Такая нагрузка как раз подходит для первого технического восхождения: вы выигрываете не тем, что терпите долгую тропёжку, а тем, что сосредоточены на технике и оценке.",
    "q.m08#4.p" to "Какова высота Хабы?",
    "q.m08#4.o0" to "5 005 м",
    "q.m08#4.o1" to "5 254 м",
    "q.m08#4.o2" to "5 396 м",
    "q.m08#4.o3" to "5 642 м",
    "q.m08#4.e" to "Хаба — 5 396 м, Шангри-Ла, Юньнань. Её ценность в том, что выше снеговой линии есть настоящий лёд, требующий кошек и ледоруба, но без жёсткого давления акклиматизации, как на вершине 6 000 м.",
    "q.m08#5.p" to "Где Хаба требует технических навыков?",
    "q.m08#5.o0" to "Нужны навыки скалолазания",
    "q.m08#5.o1" to "Выше снеговой линии есть ледовый склон, требующий кошек и ледоруба",
    "q.m08#5.o2" to "Нужны навыки дайвинга",
    "q.m08#5.o3" to "Техническое снаряжение вообще не нужно",
    "q.m08#5.e" to "Ключевое слово Хабы — «лёд выше снеговой линии». Нужно уметь устойчиво двигаться по льду в кошках и использовать ледоруб для опоры и задержания, — именно это и разбирают предыдущие уроки этого раздела о 5 000 м.",
    "q.m08#6.p" to "Какова высота и статус Эльбруса?",
    "q.m08#6.o0" to "5 642 м, высшая вершина Европы",
    "q.m08#6.o1" to "5 895 м, высшая в Африке",
    "q.m08#6.o2" to "5 254 м, высшая в хребте Цилянь",
    "q.m08#6.o3" to "6 178 м, высокая вершина Куньлуня",
    "q.m08#6.e" to "Эльбрус — 5 642 м, высшая вершина Европы, в российском Кавказе. Его место в прогрессии необычно: высота класса 5 000 м, но требует движения по леднику и связки — классический мост от треккинговых вершин к техническим.",
    "q.m08#7.p" to "Каковы базовые требования для восхождения на Эльбрус?",
    "q.m08#7.o0" to "Только физическая форма",
    "q.m08#7.o1" to "Кошки и ледоруб; движение по леднику и связка — базовые требования",
    "q.m08#7.o2" to "Дополнительный кислород",
    "q.m08#7.o3" to "Навыки скалолазания",
    "q.m08#7.e" to "Маршрут Эльбруса пересекает ледники, поэтому связка, понимание трещин и работа в кошках — базовый минимум. Его часто сравнивают с Килиманджаро: обе 5 000 м класса, одна — чистый треккинг, другая требует настоящей технической работы.",
    "q.m08#8.p" to "[Множественный выбор] При переходе от треккинговых вершин к техническим какие способности стоит развивать сначала?",
    "q.m08#8.o0" to "Правильное использование технического снаряжения (кошки, ледоруб, обвязка)",
    "q.m08#8.o1" to "Базовые технические действия, например задержание падения",
    "q.m08#8.o2" to "Движение по леднику в связке и базовые страховочные системы",
    "q.m08#8.o3" to "Оценка того, когда не нужно продолжать",
    "q.m08#8.o4" to "Покупка более дорогого снаряжения",
    "q.m08#8.e" to "Первые три — способности, четвёртое — ограничение. Многие развивают только первые три и по мере роста навыка становятся увереннее, что повышает риск. Техническая подготовка и подготовка оценки должны идти вместе, поэтому в этом разделе уроки техники соседствуют с уроками вершин.",
    "q.m08#9.p" to "[Порядок] Расставьте эти цели по возрастанию сложности.",
    "q.m08#9.o0" to "Аотайна (треккинг, без технической сложности)",
    "q.m08#9.o1" to "Третья вершина Ганшики (вводная техническая)",
    "q.m08#9.o2" to "Хаба / Эльбрус (смешанные, кошки и связка)",
    "q.m08#9.o3" to "Юйчжу, южный склон (6 000 м, смешанный)",
    "q.m08#9.e" to "Смысл в том, чтобы добавлять по одной новой переменной: без техники, затем техническое снаряжение, затем применение на реальном льду, затем высота. Обычная ошибка — не пропуск шага, а одновременный максимум сложности и высоты: тогда не понять, к чему именно вы не готовы.",
    "q.m08#10.p" to "Почему переход от третьей вершины к главной разумен?",
    "q.m08#10.o0" to "Потому что третья вершина ближе к главной",
    "q.m08#10.o1" to "Потому что разные маршруты на одной горе отделяют техническую сложность от сложности среды",
    "q.m08#10.o2" to "Потому что главная вершина дешевле",
    "q.m08#10.o3" to "Потому что на третьей вершине легче заблудиться",
    "q.m08#10.e" to "Рост на одной и той же горе держит переменные среды — погоду, подъезд, логистику, гидов — примерно постоянными, и вы ясно чувствуете, откуда берётся дополнительная сложность. Меняя гору каждый раз, вы никогда не поймёте, что вас ограничило: техника или акклиматизация.",
    "q.m08#11.p" to "Каково правильное отношение к выбору цели в прогрессии 5 000 м?",
    "q.m08#11.o0" to "Выбрать самую высокую и пропустить ступени",
    "q.m08#11.o1" to "Добавлять по одной новой сложности и ставить в приоритет надёжную поддержку",
    "q.m08#11.o2" to "Выбрать самую дешёвую",
    "q.m08#11.o3" to "Смотреть только на долю успеха, а не на технические требования",
    "q.m08#11.e" to "Способности накапливаются, и каждый пропущенный шаг умножает риск. Надёжная поддержка — гиды, спасение, план отхода — общая база безопасности на любом вводном уровне: она не мешает вам ошибиться, но не даёт ошибке стать смертельной.",
    "q.m09#0.p" to "Каковы две базовые цели лекарств на высоте?",
    "q.m09#0.o0" to "Вылечить высотную болезнь и заменить спуск",
    "q.m09#0.o1" to "Ускорить акклиматизацию и выиграть время для спуска",
    "q.m09#0.o2" to "Улучшить форму и выносливость",
    "q.m09#0.o3" to "Защитить от простуды и улучшить сон",
    "q.m09#0.e" to "Держать эти две вещи врозь критически важно: ацетазоламид относится к первой (быстрее акклиматизироваться), дексаметазон и нифедипин ко второй (выиграть время). Принять препарат, выигрывающий время, за доказательство выздоровления — самое опасное заблуждение в высотной помощи.",
    "q.m09#1.p" to "Влияет ли дексаметазон на акклиматизацию?",
    "q.m09#1.o0" to "Да, ускоряет её",
    "q.m09#1.o1" to "Нет, на акклиматизацию он не влияет вовсе",
    "q.m09#1.o2" to "Да, замедляет её",
    "q.m09#1.o3" to "Только при длительном применении",
    "q.m09#1.e" to "В руководстве сказано прямо: дексаметазон снимает симптомы отёка мозга, на акклиматизацию не влияет и отёк лёгких не лечит. Он только выигрывает время, — и это время нужно потратить на спуск.",
    "q.m09#2.p" to "Какой побочный эффект нифедипина требует наибольшей осторожности?",
    "q.m09#2.o0" to "Сонливость",
    "q.m09#2.o1" to "Быстрое падение давления, из-за чего при резком вставании возможен обморок",
    "q.m09#2.o2" to "Шум в ушах",
    "q.m09#2.o3" to "Потеря аппетита",
    "q.m09#2.e" to "В реальных условиях это опасно: обморок от ортостатической гипотензии на крутом склоне или при выходе из палатки ночью может иметь более немедленные последствия, чем сама высотная болезнь. В руководстве также отмечено, что нифедипин может помогать треккерам, но не лучший выбор для альпинистов.",
    "q.m09#3.p" to "Каково правильное отношение к лекарствам от высотной болезни?",
    "q.m09#3.o0" to "Запомнить дозу и применять самому",
    "q.m09#3.o1" to "Это врачебное решение — оценивать с врачом и следовать его указаниям",
    "q.m09#3.o2" to "Члены группы могут свободно делиться",
    "q.m09#3.o3" to "Побочные эффекты не влияют на применение",
    "q.m09#3.e" to "У каждого препарата есть конкретные показания, противопоказания и побочные эффекты (нифедипин снижает давление, аспирин несёт риск кровотечений, дексаметазон — стероид). Это не «высотный здравый смысл», а медицинские вмешательства, — отсюда и постоянные напоминания о врачебной консультации.",
    "q.m09#4.p" to "Симптомы ослабли после дексаметазона. Что делать?",
    "q.m09#4.o0" to "Продолжать подъём по плану",
    "q.m09#4.o1" to "Всё равно не подниматься; спускаться как можно скорее",
    "q.m09#4.o2" to "Увеличить дозу и продолжать",
    "q.m09#4.o3" to "Немедленно прекратить препарат и наблюдать",
    "q.m09#4.e" to "Препарат снимает симптомы, но причина отёка мозга — гипоксия — остаётся. Вывод руководства однозначен: даже при облегчении симптомов не продолжать набор высоты. Спуск — единственное действие, убирающее причину.",
    "q.m09#5.p" to "Как применяют аспирин при высотной головной боли?",
    "q.m09#5.o0" to "Принимают, когда начинается боль",
    "q.m09#5.o1" to "Профилактически: начать заранее и принимать регулярно",
    "q.m09#5.o2" to "Только перед сном",
    "q.m09#5.o3" to "Только после спуска",
    "q.m09#5.e" to "В руководстве указано 320 мг три раза в день, начиная за день до подъёма, до завершения акклиматизации, — регулярная профилактическая схема, а не «выпью, когда заболит». Эти два подхода работают по совершенно разной логике.",
    "q.m09#6.p" to "В чём принципиальное различие между ацетазоламидом и дексаметазоном?",
    "q.m09#6.o0" to "Один дешёвый, другой дорогой",
    "q.m09#6.o1" to "Один ускоряет акклиматизацию, другой только снимает симптомы",
    "q.m09#6.o2" to "Один пероральный, другой инъекционный",
    "q.m09#6.o3" to "Они действуют одинаково",
    "q.m09#6.e" to "Это различие определяет всё дальнейшее: после ацетазоламида улучшение можно читать как то, что организм действительно акклиматизируется; после дексаметазона улучшение лишь маскировка, — и ответ на вопрос, можно ли продолжать подъём, в этих двух случаях противоположный.",
    "q.m09#7.p" to "[Множественный выбор] Какие утверждения о лекарствах на высоте верны?",
    "q.m09#7.o0" to "Лекарства не могут заменить спуск",
    "q.m09#7.o1" to "Доза и сроки требуют врачебного руководства",
    "q.m09#7.o2" to "Разные препараты нацелены на разные состояния, и их нельзя путать",
    "q.m09#7.o3" to "Когда лекарство маскирует симптомы, оценивать становится труднее",
    "q.m09#7.o4" to "Как только симптомы ослабли, можно безопасно продолжать подъём",
    "q.m09#7.e" to "Первые четыре ключевые. Чаще всего упускают, что маскировка затрудняет оценку: симптомы ушли, и вы теряете самый прямой индикатор, приходится опираться на более объективные признаки — походку, сознание, дыхание. Поэтому после препарата за этими тремя нужно следить ещё внимательнее.",
    "q.m09#8.p" to "Почему «без лекарств, немедленно вниз» часто самый надёжный выбор?",
    "q.m09#8.o0" to "Потому что лекарства не работают",
    "q.m09#8.o1" to "Потому что спуск убирает причину, а лекарства действуют лишь косвенно",
    "q.m09#8.o2" to "Потому что лекарства дорогие",
    "q.m09#8.o3" to "Потому что лекарства неудобно нести",
    "q.m09#8.e" to "Причина высотной болезни — гипоксия, а гипоксия напрямую от высоты. Спуск убирает причину; лекарства лишь меняют реакцию организма на неё. Когда условия позволяют, спуск — действие высшего приоритета.",
    "q.m09#9.p" to "[Порядок] У участника признаки тяжёлой высотной болезни. Каков правильный порядок действий?",
    "q.m09#9.o0" to "Немедленно прекратить подъём; оценить сознание, походку и дыхание",
    "q.m09#9.o1" to "Организовать спуск (не менее 1 000 м), при наличии — с кислородом",
    "q.m09#9.o2" to "Дать соответствующий препарат (например, дексаметазон) под медицинским контролем",
    "q.m09#9.o3" to "Если спуск невозможен, использовать гипербарическую камеру и вызвать спасение",
    "q.m09#9.e" to "Порядок и есть приоритет: оценить, спуститься, поддержать препаратом и только затем прибегать к мерам выигрывания времени. Самая частая ошибка на практике — обратный порядок: искать препарат и забывать, что спуск и есть основное лечение.",
    "q.m09#10.p" to "Почему заранее обсудить схему лекарств с врачом так важно для высотных поездок?",
    "q.m09#10.o0" to "Потому что на горе лекарства не купить",
    "q.m09#10.o1" to "Потому что профессионального совета там нет, а рвота может изменить путь введения",
    "q.m09#10.o2" to "Потому что лекарства истекают",
    "q.m09#10.o3" to "Потому что этого требуют гиды",
    "q.m09#10.e" to "На высоте нет ни врача, ни диагностики; хуже того, пациента может рвать, и он не сможет принять ничего внутрь. Схему — дозу, сроки, путь введения и противопоказания — нужно согласовать до выезда.",
    "q.m09#11.p" to "[Сопоставление] Соотнесите препарат с его основным действием.",
    "q.m09#11.l0" to "Ацетазоламид",
    "q.m09#11.r0" to "Ускоряет акклиматизацию; применяется профилактически",
    "q.m09#11.l1" to "Дексаметазон",
    "q.m09#11.r1" to "Снижает внутричерепное давление и уменьшает отёк мозга",
    "q.m09#11.l2" to "Нифедипин",
    "q.m09#11.r2" to "Снимает лёгочную вазоконстрикцию; применяется при отёке лёгких",
    "q.m09#11.e" to "Три карты, три задачи: ацетазоламид — за акклиматизацию, дексаметазон — за мозг, нифедипин — за лёгкие. Сначала определите, какая проблема у пациента, потом выбирайте карту, а не относитесь к любому препарату как к универсальной «таблетке от высоты».",
    "q.m10#0.p" to "Что такое погодное окно?",
    "q.m10#0.o0" to "День с наименьшей вероятностью осадков в прогнозе",
    "q.m10#0.o1" to "Период, в который вы можете безопасно выполнить задачу",
    "q.m10#0.o2" to "Часы с наибольшей продолжительностью светового дня",
    "q.m10#0.o3" to "Время с наименьшим ветром",
    "q.m10#0.e" to "Погодное окно — составное понятие: оно удовлетворяет и «погода позволяет», и «группа может». Поэтому при одинаковой погоде окно сильной и слабой группы совершенно разной ширины: окна относительны, а не абсолютны.",
    "q.m10#1.p" to "Почему прогноз горной погоды относительно неточен?",
    "q.m10#1.o0" to "Потому что метеостанций слишком мало",
    "q.m10#1.o1" to "Потому что сложный рельеф создаёт огромную локальную изменчивость: на разных высотах и экспозициях погода может быть совершенно разной",
    "q.m10#1.o2" to "Потому что прогнозисты небрежны",
    "q.m10#1.o3" to "Потому что на высоте нет данных",
    "q.m10#1.e" to "Орографический подъём, блокировка и обтекание гребней резко разделяют погоду на малых масштабах: в нескольких километрах может быть другой мир. Региональный прогноз — только фон; на месте вы решаете по наблюдениям.",
    "q.m10#2.p" to "Утолщение облачности и снижение нижней границы обычно означают что?",
    "q.m10#2.o0" to "Улучшение погоды",
    "q.m10#2.o1" to "Ухудшение погоды, видимость, вероятно, быстро упадёт",
    "q.m10#2.o2" to "Скоро прояснится",
    "q.m10#2.o3" to "Ничего особенного",
    "q.m10#2.e" to "Снижение нижней границы облаков означает рост влажности и падение уровня конденсации, — часто это предвестник фронта осадков. В горах это ещё и значит, что обзор вот-вот сократится, а это уже отдельный риск.",
    "q.m10#3.p" to "Почему тенденция давления важнее его значения?",
    "q.m10#3.o0" to "Потому что значение всегда неверно",
    "q.m10#3.o1" to "Потому что погоду определяет изменение давления, а базовые значения на разной высоте и так различаются",
    "q.m10#3.o2" to "Потому что тенденции легче запомнить",
    "q.m10#3.o3" to "Потому что значения слишком колеблются",
    "q.m10#3.e" to "Одно и то же показание давления значит совершенно разное на разных высотах и в разных местах, поэтому изолированное число не имеет системы отсчёта. А устойчивое падение везде означает одно: погода меняется.",
    "q.m10#4.p" to "В чём практическая ценность шкалы Бофорта?",
    "q.m10#4.o0" to "Она делает ветер более профессиональным на вид",
    "q.m10#4.o1" to "Она переводит скорость ветра в наблюдаемую, передаваемую шкалу для оценки подвижности и разговора друг с другом",
    "q.m10#4.o2" to "Она измеряет осадки",
    "q.m10#4.o3" to "Она оценивает температуру",
    "q.m10#4.e" to "Ветер — информация, которую нужно произнести: группе нужен общий язык для вопроса «можем ли мы идти дальше». Бофорт превращает абстрактную скорость в наблюдаемые признаки — листья, снежную пыль, как ощущается, — и оценка быстро распространяется по группе.",
    "q.m10#5.p" to "[Множественный выбор] Какие признаки на месте говорят об ухудшении погоды?",
    "q.m10#5.o0" to "Давление устойчиво падает",
    "q.m10#5.o1" to "Облачность быстро густеет, нижняя граница снижается",
    "q.m10#5.o2" to "Ветер заметно усиливается и часто меняет направление",
    "q.m10#5.o3" to "Вдали растёт кучево-дождевое облако",
    "q.m10#5.o4" to "Давление устойчиво растёт, ветер стихает",
    "q.m10#5.e" to "Первые четыре — основные сигналы ухудшения в руководстве. Все они описывают тенденцию, а не мгновение, — поэтому важны регулярные наблюдения по времени. Тенденция что-то значит только когда есть с чем сравнить.",
    "q.m10#6.p" to "Во время грозы какое поведение опаснее всего?",
    "q.m10#6.o0" to "Остановиться и спускаться",
    "q.m10#6.o1" to "Оставаться на гребне, вершине или открытой воде — везде, где вы открыты",
    "q.m10#6.o2" to "Убрать металлическое снаряжение",
    "q.m10#6.o3" to "Присесть низко и ждать",
    "q.m10#6.e" to "Худшее в грозу — быть самым высоким объектом вокруг. Гребни и вершины как раз самые открытые места, поэтому уходите оттуда, как только грозит молния. Металлическое снаряжение держите вместе и подальше от тела.",
    "q.m10#7.p" to "Почему штурм вершины обычно начинают до рассвета?",
    "q.m10#7.o0" to "Чтобы избежать толпы",
    "q.m10#7.o1" to "Потому что раннее утро обычно самая устойчивая часть дня, а днём конвекция усиливается и шансы падают",
    "q.m10#7.o2" to "Потому что в 3 часа ночи больше всего сил",
    "q.m10#7.o3" to "Потому что днём слишком жарко",
    "q.m10#7.e" to "Это следует из суточного цикла: дневной прогрев вызывает конвекцию, поэтому днём вероятность облаков и осадков растёт. Поставить самую тяжёлую и ответственную часть восхождения до рассвета значит купить более снисходительное окно.",
    "q.m10#8.p" to "Как время поворота связано с погодным окном?",
    "q.m10#8.o0" to "Они не связаны",
    "q.m10#8.o1" to "Время поворота должно выводиться из погодного окна; сужение окна сдвигает его раньше",
    "q.m10#8.o2" to "Время поворота всегда фиксировано",
    "q.m10#8.o3" to "В хорошую погоду время поворота не нужно",
    "q.m10#8.e" to "Время поворота — не фиксированное число, его считают от окна на этот день. Сколько до вершины, сколько на спуск, когда окно начинает закрываться, — обратный расчёт даёт последний момент, когда нужно повернуть.",
    "q.m10#9.p" to "[Порядок] Расставьте шаги обычной оценки погоды в разумном порядке.",
    "q.m10#9.o0" to "До выхода посмотреть региональный прогноз и тенденцию давления",
    "q.m10#9.o1" to "В движении регулярно наблюдать облачность, ветер и видимость",
    "q.m10#9.o2" to "Сравнить наблюдения на месте с прогнозом и оценить направление тенденции",
    "q.m10#9.o3" to "Скорректировать план или повернуть раньше в соответствии с этой тенденцией",
    "q.m10#9.e" to "Третий шаг — ключевой: многие останавливаются на втором, ощущая, что погода меняется, но не превращая это в решение. Наблюдение, которое никогда не становится действием, — не наблюдение.",
    "q.m10#10.p" to "Когда погодное окно сужается, от чего отказываться в первую очередь?",
    "q.m10#10.o0" to "От страховочного снаряжения",
    "q.m10#10.o1" to "От самой цели — вершины",
    "q.m10#10.o2" to "От части участников",
    "q.m10#10.o3" to "От средств связи",
    "q.m10#10.e" to "Это вопрос приоритета: когда окно не вмещает и вершину, и безопасный спуск, вы сохраняете спуск и отбрасываете вершину. Решите это до выхода, а не в горах.",
    "q.m10#11.p" to "Какой взгляд на «молочное небо» верен?",
    "q.m10#11.o0" to "Просто плохая видимость, опасности нет",
    "q.m10#11.o1" to "Вы теряете все визуальные ориентиры и инстинктивно идёте не туда — сначала зафиксируйте положение",
    "q.m10#11.o2" to "Оно приносит осадки",
    "q.m10#11.o3" to "Оно бывает только ночью",
    "q.m10#11.e" to "Опасность «молочного неба» не в том, что вы не видите, а в том, что вам кажется, будто видите. Без ориентиров чувство направления систематически уходит, поэтому первая задача — зафиксировать положение и записать направление, а не идти дальше.",
    "q.m11#0.p" to "Какова высота и расположение Юйчжу?",
    "q.m11#0.o0" to "6 178 м, Голмуд, Цинхай, восточный Куньлунь",
    "q.m11#0.o1" to "6 206 м, Дамсюн, Тибет, Ньэнчентанглха",
    "q.m11#0.o2" to "6 119 м, Кхумбу, Непал",
    "q.m11#0.o3" to "6 189 м, Кхумбу, Непал",
    "q.m11#0.e" to "Юйчжу — 6 178 м, восточная часть Куньлуня в округе Голмуд, Цинхай. Её южный склон относительно полог, а подъезд хорош, поэтому это первая вершина 6 000 м для многих.",
    "q.m11#1.p" to "Какова высота и хребет Цицзы?",
    "q.m11#1.o0" to "6 178 м, Куньлунь",
    "q.m11#1.o1" to "6 206 м, Ньэнчентанглха",
    "q.m11#1.o2" to "6 119 м, Гималаи",
    "q.m11#1.o3" to "6 189 м, Каракорум",
    "q.m11#1.e" to "Цицзы — 6 206 м, хребет Ньэнчентанглха, Дамсюн, Тибет. Её отличают стабильные снежные склоны и удобный подъезд: стабильные склоны означают, что риск лавин и трещин относительно управляем, поэтому она подходит для тренировочной прогрессии.",
    "q.m11#2.p" to "Какова высота и расположение Лобуче-Ист?",
    "q.m11#2.o0" to "6 119 м, Кхумбу, Непал",
    "q.m11#2.o1" to "6 189 м, Кхумбу, Непал",
    "q.m11#2.o2" to "6 206 м, Дамсюн, Тибет",
    "q.m11#2.o3" to "6 178 м, Голмуд, Цинхай",
    "q.m11#2.e" to "Лобуче-Ист — 6 119 м в районе Кхумбу, Непал, прямо у треккингового маршрута к Эвересту. Такое положение означает отработанную акклиматизацию и логистику, а более крутые снежные склоны делают её хорошей ступенью к большим высотам.",
    "q.m11#3.p" to "Какова самая характерная техническая особенность Айленд-Пик (Имджа-Цзе)?",
    "q.m11#3.o0" to "Техническое снаряжение вообще не нужно",
    "q.m11#3.o1" to "Движение в связке и прохождение трещин",
    "q.m11#3.o2" to "Нужен дополнительный кислород",
    "q.m11#3.o3" to "Нужны навыки скалолазания",
    "q.m11#3.e" to "Айленд-Пик, 6 189 м, — классическая техническая вершина 6 000 м: вы идёте в связке и работаете с трещинами. Поэтому её и используют как подготовку к 7 000 м: она применяет систему «ледник плюс связка» на практике.",
    "q.m11#4.p" to "По сравнению с 5 000 м какой риск на 6 000 м возрастает сильнее всего?",
    "q.m11#4.o0" to "Камнепад",
    "q.m11#4.o1" to "Давление акклиматизации и риск высотной болезни",
    "q.m11#4.o2" to "Насекомые",
    "q.m11#4.o3" to "Вес снаряжения",
    "q.m11#4.e" to "Выше 6 000 м частота и тяжесть высотной болезни заметно растут, — поэтому в этом разделе высотная болезнь стала основной главой. Технически шаг может быть плавным, но физиологический шаг реален.",
    "q.m11#5.p" to "[Множественный выбор] Что должно быть уже освоено до вершины 6 000 м?",
    "q.m11#5.o0" to "Базовое использование кошек и ледоруба",
    "q.m11#5.o1" to "Базовые узлы и движение в связке",
    "q.m11#5.o2" to "Распознавание высотной болезни и действия при ней",
    "q.m11#5.o3" to "Базовое понимание риска трещин",
    "q.m11#5.o4" to "Самостоятельное лидирование на льду WI5",
    "q.m11#5.e" to "Первые четыре соответствуют вводному и прогрессионному разделам о 5 000 м. Раздел о 6 000 м их не переучивает, а переносит в более жёсткую среду. Идти сразу на 6 000 м со слабой базой значит умножить риск.",
    "q.m11#6.p" to "Почему южный склон Юйчжу часто становится первой целью 6 000 м?",
    "q.m11#6.o0" to "Потому что это дешевле",
    "q.m11#6.o1" to "Потому что маршрут относительно полог, а подъезд и логистика отработаны, и можно сосредоточиться на акклиматизации",
    "q.m11#6.o2" to "Потому что там нет опасностей",
    "q.m11#6.o3" to "Потому что не нужен гид",
    "q.m11#6.e" to "Ценность первой цели — в добавлении только одной новой переменной. Южный склон держит техническую сложность в посильных пределах, чтобы вы сосредоточились на настоящей задаче — акклиматизации. Выберите технически требовательную вершину 6 000 м, и вы не поймёте, что пошло не так.",
    "q.m11#7.p" to "[Порядок] Расставьте цели по возрастанию высоты.",
    "q.m11#7.o0" to "Лобуче-Ист (6 119 м)",
    "q.m11#7.o1" to "Юйчжу (6 178 м)",
    "q.m11#7.o2" to "Айленд-Пик (6 189 м)",
    "q.m11#7.o3" to "Цицзы (6 206 м)",
    "q.m11#7.e" to "Разброс высот крошечный — от 6 119 до 6 206 м, меньше 90 м. Что и показывает суть: в полосе 6 000 м выбирать нужно по типу маршрута, поддержке и своим слабым местам, а не по цифре высоты.",
    "q.m11#8.p" to "Почему на 6 000 м нужно исходить из того, что трещины есть?",
    "q.m11#8.o0" to "Потому что трещины шумят",
    "q.m11#8.o1" to "Потому что снежные мосты могут быть полностью закрыты свежим снегом и выглядеть как обычная поверхность",
    "q.m11#8.o2" to "Потому что трещины появляются только ночью",
    "q.m11#8.o3" to "Потому что трещины легко распознать",
    "q.m11#8.e" to "Именно это и делает трещины такими смертельными: в отличие от камнепада они не дают явного предупреждения. Правильная установка на 6 000 м — «они везде», а риск управляют связкой и снаряжением, а не оценкой «выглядит безопасно».",
    "q.m11#9.p" to "При выборе вершины 6 000 м что важнее высоты?",
    "q.m11#9.o0" to "Насколько вершина известна",
    "q.m11#9.o1" to "Тип маршрута (треккинг / смешанный / технический), условия поддержки и темп набора",
    "q.m11#9.o2" to "Стоимость",
    "q.m11#9.o3" to "Популярность в соцсетях",
    "q.m11#9.e" to "Вершины схожей высоты могут сильно отличаться по техническим требованиям и давлению акклиматизации. Только сочетание типа маршрута, поддержки и темпа набора даёт ответ на вопрос «подходит ли мне эта гора сейчас».",
    "q.m11#10.p" to "Какой взгляд на технический порог 6 000 м верен?",
    "q.m11#10.o0" to "Он очень низкий, важна только форма",
    "q.m11#10.o1" to "Он невысок, но начинать с нуля нельзя, а навыки движения по леднику обязательны",
    "q.m11#10.o2" to "Нужен опыт скалолазания",
    "q.m11#10.o3" to "Нужно уметь пользоваться дополнительным кислородом",
    "q.m11#10.e" to "Типичный профиль 6 000 м: умеренная техническая сложность, но вы уже должны уметь идти в связке, оценивать риск трещин и самостоятельно двигаться по леднику. Здесь начинается «я могу защитить себя системой», а не «я смотрю, как это делают другие».",
    "q.m11#11.p" to "Почему лучший сезон вершины так важен для плана?",
    "q.m11#11.o0" to "Потому что разрешения вне сезона дешевле",
    "q.m11#11.o1" to "Потому что окно восходимости сильно зависит от сезонных погодных схем; в неправильный сезон окна может почти не быть",
    "q.m11#11.o2" to "Потому что сезон меняет цвет снега",
    "q.m11#11.o3" to "Потому что гиды работают только в высокий сезон",
    "q.m11#11.e" to "Причины различаются по вершинам: одни сезоны избегают муссонных осадков, другие — экстремального зимнего холода и ветра. Понимать, почему сезон работает, гораздо важнее, чем запоминать месяц, — тем более что изменение климата сдвигает эти схемы.",
    "q.m12#0.p" to "Почему система Z 3:1 (Z-drag) даёт тройное усилие?",
    "q.m12#0.o0" to "Потому что использует более толстую верёвку",
    "q.m12#0.o1" to "Потому что сочетание прусика и блока утраивает длину вашего вытягивания",
    "q.m12#0.o2" to "Потому что помогает гравитация",
    "q.m12#0.o3" to "Потому что блоки сами экономят силы",
    "q.m12#0.e" to "Выигрыш в силе — это по сути обмен расстояния на силу: вы вытягиваете три метра верёвки, а груз поднимается на один. Плата — скорость, и при спасении из трещины эта плата полностью приемлема.",
    "q.m12#1.p" to "Какова главная задача блока в спасательной системе?",
    "q.m12#1.o0" to "Давать дополнительную прочность",
    "q.m12#1.o1" to "Снижать потери на трении верёвки и повышать эффективность системы",
    "q.m12#1.o2" to "Закреплять верёвку",
    "q.m12#1.o3" to "Защищать верёвку от износа",
    "q.m12#1.e" to "Трение — скрытый враг выигрыша в силе: каждый перегиб отнимает часть силы. Блок превращает трение скольжения в трение качения, и теоретические 3:1 становятся ближе к реальным 3:1.",
    "q.m12#2.p" to "Можно ли построить спасательную систему без блоков?",
    "q.m12#2.o0" to "Совсем нет",
    "q.m12#2.o1" to "Да, на карабинах, но трение заметно растёт, а эффективность падает",
    "q.m12#2.o2" to "Да, одной верёвкой, с той же эффективностью",
    "q.m12#2.o3" to "Нет, нужно ждать снаряжение",
    "q.m12#2.e" to "Карабины могут заменить блоки, поэтому многие группы считают запасные муфтованные карабины обязательными. Разница в том, что фактический выигрыш оказывается заметно ниже теоретического, — и, зная это, вы подготовитесь морально и физически, когда развеска неполная.",
    "q.m12#3.p" to "[Множественный выбор] Что руководство указывает как стандартный спасательный набор связки?",
    "q.m12#3.o0" to "2–3 снежных анкера или ледобура",
    "q.m12#3.o1" to "2–5 карабинов и 2–5 строп",
    "q.m12#3.o2" to "1 страховочный блок",
    "q.m12#3.o3" to "2–3 прусика и 1 жумар",
    "q.m12#3.o4" to "1 портативная горелка с газом",
    "q.m12#3.e" to "Ключевая строка в этом списке: каждый участник связки должен нести достаточный спасательный набор, то есть это личное снаряжение, а не групповое. Когда кто-то падает, доступно только то, что на вашей обвязке.",
    "q.m12#4.p" to "Как тормозит жумар?",
    "q.m12#4.o0" to "Пружиной, прижимающей верёвку",
    "q.m12#4.o1" to "Обратным трением между стальными зубьями и верёвкой",
    "q.m12#4.o2" to "Магнитным притяжением",
    "q.m12#4.o3" to "Собственным весом верёвки",
    "q.m12#4.e" to "Понимать механизм важно на практике: стальные зубья впиваются в волокна, поэтому чрезмерное усилие повреждает верёвку и может перерезать волокна в нагруженной точке. Поэтому в руководстве подчёркнуто: где возможно, используйте его с поддерживающим торможением.",
    "q.m12#5.p" to "Что будет, если рвануть жумар слишком сильно?",
    "q.m12#5.o0" to "Ничего",
    "q.m12#5.o1" to "Стальные зубья повреждают верёвку",
    "q.m12#5.o2" to "Жумар заклинит",
    "q.m12#5.o3" to "Жумар слетит",
    "q.m12#5.e" to "Зубья тормозят обратным трением, поэтому сильное усилие оставляет следы на оплётке и в сумме может создать точку разрушения. Вы увидите немало людей, которые привычно рвут жумар, — меняя привычку на риск.",
    "q.m12#6.p" to "[Порядок] Расставьте шаги построения системы Z 3:1 в разумном порядке.",
    "q.m12#6.o0" to "Убедиться, что станция надёжна, и перенести на неё вес упавшего",
    "q.m12#6.o1" to "Поставить основной прусик на нагруженную верёвку и добавить дублирующий",
    "q.m12#6.o2" to "Подключить блок или карабин к прусику, образуя путь Z",
    "q.m12#6.o3" to "Проверить всю систему, затем вытаскивать, подтягивая после каждого рывка",
    "q.m12#6.e" to "Первый шаг — основа: без переноса веса руки заняты удержанием. А последний — подтягивать после каждого рывка — легко пропустить, и тогда люди тянут очень долго, а потом съезжают назад.",
    "q.m12#7.p" to "[Сопоставление] Соотнесите предмет спасения с его ролью в системе.",
    "q.m12#7.l0" to "Прусик",
    "q.m12#7.r0" to "Односторонний захват: система может двигаться вперёд и не идёт назад",
    "q.m12#7.l1" to "Блок",
    "q.m12#7.r1" to "Снижает потери на трении и повышает эффективность",
    "q.m12#7.l2" to "Страховочный блок",
    "q.m12#7.r2" to "Фиксируется в одном направлении; служит для контроля выдачи и подтягивания",
    "q.m12#7.l3" to "Жумар",
    "q.m12#7.r3" to "Двигается по верёвке; полезен и для фиксации системы",
    "q.m12#7.e" to "Четыре разные задачи: прусик даёт односторонность, блок снимает трение, спусковое даёт контроль, жумар — подвижность. Уберите любое — и система станет либо неэффективной, либо неуправляемой.",
    "q.m12#8.p" to "Зачем рядом с основным прусиком ставят дублирующий?",
    "q.m12#8.o0" to "Для вида",
    "q.m12#8.o1" to "Потому что прусик может подвести из-за обледенения, грязи или несовпадения диаметров, а отказ мгновенно отнимает выигрыш",
    "q.m12#8.o2" to "Потому что этого требуют правила",
    "q.m12#8.o3" to "Чтобы верёвка не крутилась",
    "q.m12#8.e" to "Прусик работает за счёт трения, а трение зависит от многого. Если основной проскользнёт, упавший снова полетит без предупреждения, — задача дублирующего поймать это мгновение.",
    "q.m12#9.p" to "Как выбирать между системой 2:1 и 3:1?",
    "q.m12#9.o0" to "2:1 всегда лучше",
    "q.m12#9.o1" to "По людям, длине верёвки и рельефу: больший выигрыш требует больше верёвки и работает медленнее",
    "q.m12#9.o2" to "3:1 всегда лучше",
    "q.m12#9.o3" to "Они одинаковы",
    "q.m12#9.e" to "Выигрыш в силе не безусловное благо: 3:1 требует больше верёвки, а при спасении из трещины верёвка часто ограничена. Реальный выбор — система, которую вы можете собрать из имеющейся верёвки и людей, а не теоретически оптимальная.",
    "q.m12#10.p" to "Почему система выигрыша в силе никогда не заменяет оценку?",
    "q.m12#10.o0" to "Потому что системы ломаются",
    "q.m12#10.o1" to "Потому что система только умножает силу; она не решает, вытаскивать ли и в какую сторону",
    "q.m12#10.o2" to "Потому что системы тяжёлые",
    "q.m12#10.o3" to "Потому что нужно много людей",
    "q.m12#10.e" to "Трудная часть спасения — никогда не физика, а оценка: в какую сторону, через какой край и выживет ли пострадавший. Система — инструмент, направление дают люди. Ошибётесь с направлением — и большая сила сделает хуже.",
    "q.m12#11.p" to "Что из этого не приводит к отказу прусика?",
    "q.m12#11.o0" to "Несовпадение диаметров верёвки",
    "q.m12#11.o1" to "Лёд или грязь",
    "q.m12#11.o2" to "Слишком мало витков",
    "q.m12#11.o3" to "Более светлый цвет основной верёвки",
    "q.m12#11.e" to "Диаметр, чистота и число витков напрямую влияют на трение; цвет к механике отношения не имеет. Это также показывает, что надёжность прусика нельзя оценить на глаз, — только проверив сочетание заранее и испытав на месте.",
    "q.m12#12.p" to "Почему часто используют страховочный блок, а не обычный?",
    "q.m12#12.o0" to "Потому что он легче",
    "q.m12#12.o1" to "Потому что он фиксируется в одном направлении, и вы контролируете выдачу без обратного хода системы",
    "q.m12#12.o2" to "Потому что он дешевле",
    "q.m12#12.o3" to "Потому что его цвет заметнее",
    "q.m12#12.e" to "При спасении часто приходится одновременно тянуть и подстраивать, а обычный блок свободно идёт в обе стороны: отпустил — потерял результат. Односторонний фиксирующий элемент делает удержание позиции свойством системы. Наглядный пример того, как выбор снаряжения влияет на безопасность работы.",
    "q.m12#13.p" to "Заполните: выигрыш в силе системы Z составляет ( ):1.",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "три",
    "q.m12#13.e" to "3:1. Практическая ценность этой цифры — оценка нагрузки: взрослый со снаряжением может весить 80–100 кг, поэтому при 3:1 тянуть всё равно нужно с силой около 30 кг, — гораздо тяжелее, чем звучит, и поэтому при спасении нужны несколько человек.",
    "q.m12#14.p" to "[Множественный выбор] Что должна включать проверка после сборки?",
    "q.m12#14.o0" to "Витки прусика и направление нагрузки верны",
    "q.m12#14.o1" to "Блоки и карабины замуфтованы",
    "q.m12#14.o2" to "Точки крепления на правильной части обвязки",
    "q.m12#14.o3" to "Дублирование на месте, а верёвка не зажата",
    "q.m12#14.o4" to "Верёвка и одежда партнёров одного цвета",
    "q.m12#14.e" to "Четыре проверки соответствуют четырём классическим ошибкам: перевёрнутый прусик, открытая муфта, встёгнуто не в ту петлю, нет дублирования. Отказы спасательных систем редко бывают от нехватки знаний — это пропущенный шаг в темноте и под стрессом. Пользуйтесь чек-листом, а не памятью.",
    "q.m12#15.p" to "Почему спасательную систему нужно отрабатывать до выезда?",
    "q.m12#15.o0" to "Чтобы сдать зачёт",
    "q.m12#15.o1" to "Потому что реальное спасение происходит на высоте, в холоде и темноте, и выполняется на инстинкте",
    "q.m12#15.o2" to "Чтобы освоиться со снаряжением",
    "q.m12#15.o3" to "Потому что правила задают часы отработки",
    "q.m12#15.e" to "Условия реального спасения почти всегда худшие из возможных: ветер, мёрзнущие руки, плохой свет, партнёру становится хуже. В таких условиях выполняются только те действия, которые вы повторяли много раз, — учиться на месте не вариант.",
    "q.m13#0.p" to "Почему самообеспечение на 7 000 м — жёсткое требование?",
    "q.m13#0.o0" to "Потому что товарищи не хотят вас спасать",
    "q.m13#0.o1" to "Потому что в высокогорных условиях партнёры могут не успеть до вас добраться; вы должны уметь справиться со своей ситуацией сами",
    "q.m13#0.o2" to "Потому что спасательного снаряжения недостаточно",
    "q.m13#0.o3" to "Потому что этого требуют правила",
    "q.m13#0.e" to "Чем выше, тем дороже и медленнее спасение. Партнёр может сам бороться с высотной болезнью, а погода может запрещать любое движение. Полностью передать себя внешнему спасению значит принять предпосылку, которую никто не может гарантировать.",
    "q.m13#1.p" to "В чём основной принцип подъёма на прусиках?",
    "q.m13#1.o0" to "Подтягиваться силой рук",
    "q.m13#1.o1" to "Чередовать два прусика: один держит вес, пока другой скользит вверх по верёвке",
    "q.m13#1.o2" to "Подниматься одним жумаром",
    "q.m13#1.o3" to "Зажимать верёвку между ног",
    "q.m13#1.e" to "Один прусик только держит позицию — он не двигается, поэтому нужны два по очереди: пока нижний держит вес, верхний скользит вверх, и наоборот. Это чередование нужно отработать в безопасных условиях: именно оно решит в момент, когда вам это нужнее всего, подниметесь ли вы вообще.",
    "q.m13#2.p" to "Почему при подъёме на прусиках хотя бы один прусик должен всегда быть нагружен?",
    "q.m13#2.o0" to "Чтобы сэкономить силы",
    "q.m13#2.o1" to "Потому что если отпустить оба сразу, вы съедете вниз к началу или сорвётесь",
    "q.m13#2.o2" to "Чтобы верёвка не путалась",
    "q.m13#2.o3" to "Чтобы подниматься быстрее",
    "q.m13#2.e" to "Это правило трёх точек, применённое к верёвке: всегда оставляйте одну надёжную опору. В трещине одна ошибка не только отнимает силы, но и позволяет верёвке ещё сильнее перепилить снежный край, повышая сложность всего спасения.",
    "q.m13#3.p" to "[Порядок] Расставьте четыре шага спасения в связке по порядку.",
    "q.m13#3.o0" to "Сразу занять задержание и стабилизироваться",
    "q.m13#3.o1" to "Построить независимую станцию",
    "q.m13#3.o2" to "Перенести нагрузку на станцию",
    "q.m13#3.o3" to "Вытаскивать системой 3:1",
    "q.m13#3.e" to "Эти четыре шага вы прошли в разделе о 6 000 м; здесь важно выполнить их под давлением. Наибольший разрыв между тренировкой и реальностью: в реальности первые три шага нужно уложить в десятки секунд, а на тренировке вы, возможно, тратили пять минут.",
    "q.m13#4.p" to "На каком расстоянии друг от друга должны держаться участники, попав в грозу?",
    "q.m13#4.o0" to "Сбившись в кучу",
    "q.m13#4.o1" to "Около 50 м",
    "q.m13#4.o2" to "Около 500 м",
    "q.m13#4.o3" to "Без ограничений",
    "q.m13#4.e" to "В руководстве предлагается примерно 50 м: смысл в том, чтобы один удар не поранил сразу нескольких и кто-то остался способен оказать первую помощь. За цифрой простая мысль: никогда не ставить всё на одно место.",
    "q.m13#5.p" to "Какой единственный действенный способ снизить опасность во время грозы?",
    "q.m13#5.o0" to "Выбросить металлическое снаряжение, например ледорубы",
    "q.m13#5.o1" to "Как можно быстрее уйти с высоких точек и открытого рельефа, держась как можно ниже",
    "q.m13#5.o2" to "Присесть и обхватить колени",
    "q.m13#5.o3" to "Расстегнуть все молнии",
    "q.m13#5.e" to "В руководстве прямо отвергается несколько распространённых практик: нет данных, что небольшие металлические предметы вроде ледорубов или палаточных дуг притягивают молнию, поэтому не тратьте время на их выбрасывание. Работает изменение положения — с самого высокого объекта вокруг на незаметный участок рельефа.",
    "q.m13#6.p" to "Если вы слышите гром, молния не дальше примерно:",
    "q.m13#6.o0" to "3 км",
    "q.m13#6.o1" to "10–16 км",
    "q.m13#6.o2" to "30 км",
    "q.m13#6.o3" to "50 км",
    "q.m13#6.e" to "Услышать гром значит, что молния в пределах 10–16 км, то есть уже в зоне, где нужно реагировать. Увидеть молнию значит, что расстояние не больше примерно 24 км, — две цифры, два уровня реакции.",
    "q.m13#7.p" to "Как оценить расстояние до молнии по задержке между вспышкой и громом?",
    "q.m13#7.o0" to "Секунды × 0,34 = расстояние в км",
    "q.m13#7.o1" to "Секунды ÷ 0,34 = расстояние в км",
    "q.m13#7.o2" to "Секунды × 3,4 = расстояние в км",
    "q.m13#7.o3" to "Оценить невозможно",
    "q.m13#7.e" to "Звук идёт в воздухе со скоростью около 0,34 км в секунду, поэтому каждая секунда после вспышки — примерно 0,34 км. Практическая ценность: без всякого снаряжения вы можете понять, приближается гроза или уходит.",
    "q.m13#8.p" to "Притягивают ли небольшие металлические предметы (ледоруб, дуги палатки) молнию?",
    "q.m13#8.o0" to "Да — выбрасывать немедленно",
    "q.m13#8.o1" to "Данных об этом нет, поэтому не тратьте время на выбрасывание",
    "q.m13#8.o2" to "Да, но только на высоте",
    "q.m13#8.o3" to "Только когда мокрые",
    "q.m13#8.e" to "Это классический высотный миф. В руководстве сказано прямо: подтверждений нет, поэтому не тратьте драгоценное время на избавление от снаряжения. Нужно как можно быстрее уйти с открытой позиции, — это и есть решающая переменная.",
    "q.m13#9.p" to "Где лучше всего укрыться во время грозы?",
    "q.m13#9.o0" to "На вершине",
    "q.m13#9.o1" to "В середине лесного массива, подальше от вершины и гребня, — но никогда не прислоняясь к дереву",
    "q.m13#9.o2" to "Посреди травянистого склона",
    "q.m13#9.o3" to "В палатке",
    "q.m13#9.e" to "Середина леса работает потому, что вокруг есть объекты выше вас, но вы не прижимаетесь к проводнику. Обратный пример — лагерь на открытом гребне: в руководстве это названо крайне глупым, потому что вы сознательно обосновались в самой высокой точке вокруг.",
    "q.m13#10.p" to "Почему нельзя ставить лагерь на гребне, когда растут кучевые облака?",
    "q.m13#10.o0" to "Потому что сильный ветер",
    "q.m13#10.o1" to "Потому что кучевые, вырастающие в кучево-дождевые, означают молнию, а гребень — самое открытое место",
    "q.m13#10.o2" to "Потому что плохая видимость",
    "q.m13#10.o3" to "Потому что неровная земля",
    "q.m13#10.e" to "Переход от кучевых к кучево-дождевым часто занимает всего час-два. Лагерь на гребне ставит вас в самое начало пути грозы, — со всем снаряжением и палатками, в состоянии, когда быстрая эвакуация почти невозможна.",
    "q.m13#11.p" to "Человека только что ударила молния. Что в первую очередь?",
    "q.m13#11.o0" to "Сначала проверить внешние повреждения",
    "q.m13#11.o1" to "Немедленно проверить дыхание и пульс, при необходимости начать СЛР и как можно скорее вызвать медицинскую помощь",
    "q.m13#11.o2" to "Сначала переодеть в сухое",
    "q.m13#11.o3" to "Сначала переместить на нижний участок",
    "q.m13#11.e" to "Удар может вызвать остановку сердца и внутренние повреждения, не оставив видимых следов. Поэтому проверка дыхания и пульса идёт прежде всего, — и даже человек в сознании должен быть эвакуирован: влияние тока на сердце может проявиться позже.",
    "q.m13#12.p" to "[Множественный выбор] Что обычно включает способность к самообеспечению?",
    "q.m13#12.o0" to "Подъём на прусиках",
    "q.m13#12.o1" to "Самоудержание и самозащита",
    "q.m13#12.o2" to "Построение станции без помощи партнёра",
    "q.m13#12.o3" to "Оценка, когда ждать на месте, а когда выбираться самому",
    "q.m13#12.o4" to "Соло-лазание без страховки",
    "q.m13#12.e" to "Первые три — навыки, четвёртое — оценка. Особое внимание к «когда ждать на месте, а когда выбираться самому»: не каждая ситуация требует самоспасения, — при травме или ухудшении погоды остаться и ждать помощи может быть безопаснее, чем опрометчиво двигаться.",
    "q.m13#13.p" to "Почему «дождусь, что меня спасёт партнёр» не может быть основной стратегией безопасности?",
    "q.m13#13.o0" to "Потому что партнёры могут не захотеть",
    "q.m13#13.o1" to "Потому что партнёр сам может быть в опасности, травмирован или не иметь возможности двигаться",
    "q.m13#13.o2" to "Потому что спасательного снаряжения мало",
    "q.m13#13.o3" to "Потому что правила не позволяют",
    "q.m13#13.e" to "Смысл связки — взаимная защита, но нельзя исходить из того, что у партнёра есть запас возможностей. На высоте один участник, решающий проблемы двоих, часто выходит за пределы возможного, — поэтому самообеспечение обязательно, а спасение партнёром — бонус.",
    "q.m14#0.p" to "На какой вопрос на самом деле отвечает оценка опасности?",
    "q.m14#0.o0" to "Есть ли опасность?",
    "q.m14#0.o1" to "Приемлем ли этот риск и на каком основании?",
    "q.m14#0.o2" to "Насколько велика опасность?",
    "q.m14#0.o3" to "Испугаются ли партнёры?",
    "q.m14#0.e" to "«Есть ли опасность?» почти всегда «да»: без риска не бывает горной деятельности. Настоящий вопрос — стоит ли этот риск выигрыша и на чём мы это основываем. Именно поэтому оценка должна быть произносимой и открытой для обсуждения.",
    "q.m14#1.p" to "Что такое «цепочка происшествия»?",
    "q.m14#1.o0" to "Число пострадавших в одном происшествии",
    "q.m14#1.o1" to "Процесс, в котором несколько мелких ошибок последовательно складываются, пока не случится авария",
    "q.m14#1.o2" to "Хронология спасения",
    "q.m14#1.o3" to "Цепочка отказов снаряжения",
    "q.m14#1.e" to "Самое ценное в этом понятии то, что оно превращает аварию из невезения в процесс, на который можно повлиять. Сделайте другой выбор на любом звене, и результат изменится.",
    "q.m14#2.p" to "Каков самый действенный способ разорвать цепочку происшествия?",
    "q.m14#2.o0" to "Сделать более консервативный выбор на любом звене",
    "q.m14#2.o1" to "Сосредоточиться только на последнем звене",
    "q.m14#2.o2" to "Взять больше снаряжения",
    "q.m14#2.o3" to "Повысить форму группы",
    "q.m14#2.e" to "Подходит любое звено: выйти раньше, вовремя повернуть, не экономить на страховке ради времени. Поэтому запас и превосходит исправление: запас действует рано в цепочке, а исправление обычно происходит на последнем звене.",
    "q.m14#3.p" to "[Множественный выбор] Что из этого — распространённые искажения решений?",
    "q.m14#3.o0" to "Уже вложенные усилия",
    "q.m14#3.o1" to "Давление группы",
    "q.m14#3.o2" to "Фиксация на цели",
    "q.m14#3.o3" to "Нормализация риска",
    "q.m14#3.o4" to "Вера в марки снаряжения",
    "q.m14#3.e" to "Четыре работают в сочетании: мы уже много вложили (вложенные усилия), все остальные идут вверх (давление группы), мы почти дошли (фиксация на цели), и в прошлый раз всё прошло хорошо (нормализация риска). Когда все четыре появляются сразу, оценка почти неизбежно склоняется к риску.",
    "q.m14#4.p" to "Как вложенные усилия влияют на решения в альпинизме?",
    "q.m14#4.o0" to "Делают людей осторожнее",
    "q.m14#4.o1" to "Раз уже вложено столько времени и денег, трудно признать, что пора остановиться",
    "q.m14#4.o2" to "Повышают форму",
    "q.m14#4.o3" to "Никак не влияют",
    "q.m14#4.e" to "Суть вложенных усилий в том, что их нельзя вернуть, но психологически они становятся поводом вкладывать дальше. В горах вместе с фиксацией на цели они превращают разумное отступление в «сдаться», а сдаваться люди внутренне сопротивляются.",
    "q.m14#5.p" to "Что такое «нормализация риска»?",
    "q.m14#5.o0" to "Держать опасность в приемлемых пределах",
    "q.m14#5.o1" to "После нескольких благополучных прохождений данного условия бессознательно переклассифицировать его как «безопасное»",
    "q.m14#5.o2" to "Изучать методы оценки риска",
    "q.m14#5.o3" to "Использовать стандартизированную шкалу риска",
    "q.m14#5.e" to "Нормализация риска происходит медленно, поэтому сам человек её почти не замечает. Один и тот же альпинист может быть крайне осторожен в первый раз на крутом склоне и уже не использовать связку на десятый, — склон не изменился, изменилась оценка.",
    "q.m14#6.p" to "Почему правило большинства проблематично в среде высокого риска?",
    "q.m14#6.o0" to "Потому что это неэффективно",
    "q.m14#6.o1" to "Потому что правило большинства позволяет подавить обоснованное беспокойство меньшинства",
    "q.m14#6.o2" to "Потому что голосование не всегда честно",
    "q.m14#6.o3" to "Потому что группы разного размера",
    "q.m14#6.e" to "Сигналы опасности часто замечают лишь один-два человека — кто-то увидел трещину в снежном слое, — и это информация у меньшинства, но смертельная, если верна. Решать её судьбу голосованием значит систематически игнорировать маловероятные сигналы с тяжёлыми последствиями.",
    "q.m14#7.p" to "Почему «побеждает самое консервативное мнение»?",
    "q.m14#7.o0" to "Потому что консервативные люди опытнее",
    "q.m14#7.o1" to "Потому что в условиях неопределённости цена ошибки в консервативную сторону гораздо ниже, чем в рискованную",
    "q.m14#7.o2" to "Потому что этого требуют правила",
    "q.m14#7.o3" to "Чтобы всем было приятно",
    "q.m14#7.e" to "Это классический случай асимметричной цены: консерватизм может означать потерянную поездку, риск — смерть. Когда цены асимметричны, решение должно склоняться в сторону контролируемой цены, — и этот наклон нужно согласовать до выхода, иначе на месте его очень трудно выполнить.",
    "q.m14#8.p" to "[Сопоставление] Соотнесите искажение решения с его типичным проявлением.",
    "q.m14#8.l0" to "Уже вложенные усилия",
    "q.m14#8.r0" to "Мы зашли так далеко — поворачивать сейчас значит потерять всё",
    "q.m14#8.l1" to "Давление группы",
    "q.m14#8.r1" to "Все хотят идти дальше, мне неудобно говорить, что пора заканчивать",
    "q.m14#8.l2" to "Фиксация на цели",
    "q.m14#8.r2" to "Остался последний участок",
    "q.m14#8.l3" to "Нормализация риска",
    "q.m14#8.r3" to "В прошлый раз всё прошло нормально",
    "q.m14#8.e" to "Интересно, что эти четыре фразы постоянно встречаются в разборах аварий, — и говорят их часто опытные альпинисты. В этом и суть: это не проблемы новичков, а проблемы устройства человеческого мышления.",
    "q.m14#9.p" to "Почему «опытнее» не значит «точнее оценивает»?",
    "q.m14#9.o0" to "Потому что опыт замедляет",
    "q.m14#9.o1" to "Потому что опыт постепенно повышает терпимость к риску",
    "q.m14#9.o2" to "Потому что опыт не важен",
    "q.m14#9.o3" to "Потому что ветераны упрямее",
    "q.m14#9.e" to "Опыт приносит привычность, а привычность притупляет настороженность. Поэтому опытным группам нужны внешние ограничения больше, а не меньше: фиксированное время поворота, оцифрованные погодные пороги, — правила против уже притупившейся интуиции.",
    "q.m14#10.p" to "[Порядок] Каков разумный порядок принятия решения об отступлении?",
    "q.m14#10.o0" to "Проверить объективные сигналы, согласованные до выхода (время, погода, состояние группы)",
    "q.m14#10.o1" to "Убедиться, сработал ли какой-либо из них в фактических условиях",
    "q.m14#10.o2" to "Заранее назначенный решающий объявляет отступление",
    "q.m14#10.o3" to "Выполнить отступление и сообщить тем, кто ждёт дома",
    "q.m14#10.e" to "Ценность процесса в том, что сначала проверяется стандарт, а потом ситуация, — не наоборот. Поменяйте порядок, и стандарт будет понемногу размываться настроением на месте, пока не превратится в «давайте ещё чуть-чуть посмотрим».",
    "q.m14#11.p" to "Почему заранее назначают, у кого есть право объявить отступление?",
    "q.m14#11.o0" to "Чтобы легче было найти виноватого",
    "q.m14#11.o1" to "Потому что человеку очень трудно по своей инициативе идти против настроения группы",
    "q.m14#11.o2" to "Чтобы усилить власть руководителя",
    "q.m14#11.o3" to "Чтобы задокументировать процесс",
    "q.m14#11.e" to "Отступление означает отказ от ожиданий всей группы, и начать это внутри групповой атмосферы очень трудно. Сделайте «объявить отступление» обязанностью, выданной заранее, а не актом личной храбрости, — только тогда это действительно происходит.",
    "q.m14#12.p" to "Когда стоит рассмотреть завершение поездки?",
    "q.m14#12.o0" to "Никогда, пока вершина ещё возможна",
    "q.m14#12.o1" to "Когда сработал любой заранее согласованный объективный сигнал",
    "q.m14#12.o2" to "Только когда участник травмирован",
    "q.m14#12.o3" to "Когда решит самый слабый",
    "q.m14#12.e" to "Сигнал значит стоп: в этом весь смысл оцифрованных критериев. Это превращает решение из «стоит ли» в «сработало ли». Первое требует спора и убеждения, второе — только проверки фактов, поэтому его действительно можно выполнить на месте.",
    "q.m14#13.p" to "Что лучше всего противодействует фиксации на цели?",
    "q.m14#13.o0" to "Личная сила воли",
    "q.m14#13.o1" to "Оцифровать критерии до выхода, чтобы «их ослабление» стало явным действием, которое нужно объяснить партнёрам",
    "q.m14#13.o2" to "Не ставить цели вообще",
    "q.m14#13.o3" to "Взять больше снаряжения",
    "q.m14#13.e" to "Психологическое искажение нельзя обойти напоминанием себе не поддаваться. Работающий метод — сделать «в срок повернуть» поведением по умолчанию, чтобы тот, кто хочет продолжать, должен был активно приводить доводы: бремя доказывания перевёрнуто одним движением.",
    "q.m14#14.p" to "Почему «никто не возразил» не равно «все согласны»?",
    "q.m14#14.o0" to "Потому что они могли не слышать",
    "q.m14#14.o1" to "Потому что молчание может означать лишь нежелание портить атмосферу, а настоящие сомнения остались невысказанными",
    "q.m14#14.o2" to "Потому что кто-то спал",
    "q.m14#14.o3" to "Потому что возражения проигнорировали",
    "q.m14#14.e" to "Поэтому хорошие группы намеренно создают разногласие: руководитель прямо спрашивает «кто считает, что нам не стоит продолжать» или обходит всех и просит высказать позицию. Молчание в горах не означает согласия, оно означает лишь, что ничего не сказали.",
    "q.m14#15.p" to "Заполните: при решении в условиях неопределённости первым принимают самое ( ) мнение.",
    "q.m14#15.a0" to "консервативное",
    "q.m14#15.e" to "«Сначала консервативное» — правило, которое можно выполнять прямо на месте: не нужно судить, чей довод сильнее, только какой вариант консервативнее. Плата — возможно, потерянная поездка, и эта плата оправдана.",
    "q.m14#16.p" to "Ситуация: на 7 000 м в день вершины погода ухудшается",
    "q.m14#16.c" to "День вершины на 7 000 м, вы вышли в 3 утра. В 8 утра вы в точке примерно в двух часах от вершины. Ветер заметно усилился, с запада идёт облачность, температура падает. Один участник начал постоянно кашлять и заметно сбавил темп.",
    "q.m14#16.e" to "Суть этой ситуации не в каком-то одном ответе, а в последовательности: проверить факты, выявить сигналы опасности, противостоять психологическому давлению, затем правильно выполнить отступление. Два шага чаще всего ломаются: первый (пропускают) и третий (захватывают эмоции).",
    "q.m14#16.s0.p" to "Шаг 1: какое решение нужно принять прямо сейчас?",
    "q.m14#16.s0.o0" to "Уточнить состояние группы и тенденцию погоды и сверить их с сигналами поворота, согласованными до выхода",
    "q.m14#16.s0.o1" to "Ускориться и выйти на вершину до ухудшения погоды",
    "q.m14#16.s0.o2" to "Ждать на месте улучшения погоды",
    "q.m14#16.s0.o3" to "Отправить медленного участника вниз одного",
    "q.m14#16.s0.e" to "Любое решение должно начинаться с проверки фактов: как группа, улучшается погода или ухудшается, сработал ли заранее заданный сигнал. Пропустите это — и решение примет эмоция.",
    "q.m14#16.s1.p" to "Шаг 2: у участника постоянный кашель. Какая реакция разумнее?",
    "q.m14#16.s1.o0" to "Просто холодный воздух раздражает дыхательные пути — идём дальше",
    "q.m14#16.s1.o1" to "На высоте это требует высокой настороженности по отёку лёгких: прекратить подъём и как можно скорее спускаться",
    "q.m14#16.s1.o2" to "Дать лекарство от кашля и продолжать",
    "q.m14#16.s1.o3" to "Дать отдохнуть 10 минут и продолжить",
    "q.m14#16.s1.e" to "На 7 000 м постоянный кашель в покое или при лёгкой нагрузке — сигнал, требующий высокой настороженности. На этой высоте цена «понаблюдать ещё немного» может намного превысить цену немедленного спуска.",
    "q.m14#16.s2.p" to "Шаг 3: вы в двух часах от вершины и решаете повернуть. Каково наибольшее психологическое сопротивление?",
    "q.m14#16.s2.o0" to "Недостаточная форма",
    "q.m14#16.s2.o1" to "Уже вложенные усилия и фиксация на цели — «мы так далеко зашли»",
    "q.m14#16.s2.o2" to "Проблемы со снаряжением",
    "q.m14#16.s2.o3" to "Незнакомый маршрут",
    "q.m14#16.s2.e" to "Именно поэтому существует время поворота: оно переносит решение в момент, когда вы ещё разумны. Когда появляется «ещё чуть-чуть», нужна не свежая оценка, а сверка с правилом, согласованным заранее.",
    "q.m14#16.s3.p" to "Шаг 4: как организовать группу на спуске?",
    "q.m14#16.s3.o0" to "Самые сильные уходят вперёд готовить лагерь",
    "q.m14#16.s3.o1" to "Идти группой, пусть самый сильный ведёт и задаёт темп, и сообщить домой о состоянии группы",
    "q.m14#16.s3.o2" to "Разделиться, чтобы спускаться быстрее",
    "q.m14#16.s3.o3" to "Пусть самый слабый идёт медленно один",
    "q.m14#16.s3.e" to "На высоте разошедшаяся группа теряет взаимное прикрытие, — а спуск как раз фаза с наибольшим числом происшествий. Движение единой группой, контроль темпа и информирование внешнего мира: все три обязательны.",
    "q.m15#0.p" to "В чём главная ценность умения читать облака?",
    "q.m15#0.o0" to "Это делает альпинизм более профессиональным на вид",
    "q.m15#0.o1" to "Это даёт вам запас времени перед изменением погоды",
    "q.m15#0.o2" to "Это заменяет прогноз погоды",
    "q.m15#0.o3" to "Это позволяет измерить высоту",
    "q.m15#0.e" to "Прогноз может сказать за сутки, но горная погода меняется быстро на малых масштабах. Облака — это прогноз прямо над головой: запас времени может быть всего час-два, и именно этот час-два и есть окно, в котором вы решаете, поворачивать ли.",
    "q.m15#1.p" to "О чём говорит вертикальное развитие кучевых облаков?",
    "q.m15#1.o0" to "Об устойчивой погоде",
    "q.m15#1.o1" to "О сильной конвекции и возможном развитии в кучево-дождевое",
    "q.m15#1.o2" to "О скором похолодании",
    "q.m15#1.o3" to "Об ослаблении приземного ветра",
    "q.m15#1.e" to "Само кучевое облако не опасно, но это растущий сигнал. Ключ не в том, чтобы отметить «это кучевое», а в том, чтобы следить, как оно растёт, поднимается башней и темнеет, — этот процесс и есть накопление энергии атмосферой.",
    "q.m15#2.p" to "Что означает наковальня на кучево-дождевом облаке?",
    "q.m15#2.o0" to "Оно ещё формируется",
    "q.m15#2.o1" to "Оно достигло зрелости: возможны молния, град и сильные осадки",
    "q.m15#2.o2" to "Оно скоро рассеется",
    "q.m15#2.o3" to "Это значит только сильный ветер на высоте",
    "q.m15#2.e" to "Наковальня — вершина облака, срезанная высотным ветром: значит, восходящий поток дошёл до тропопаузы и подниматься дальше не может. Это признак грозы в зрелой стадии. Когда вы видите наковальню, времени на реакцию уже мало.",
    "q.m15#3.p" to "В какое время суток чаще всего образуются кучевые облака?",
    "q.m15#3.o0" to "Ранним утром",
    "q.m15#3.o1" to "В середине утра",
    "q.m15#3.o2" to "Днём",
    "q.m15#3.o3" to "Поздней ночью",
    "q.m15#3.e" to "Причина — солнечный прогрев: земля нагревается за день и создаёт восходящие потоки и конвекцию. Это физический механизм за правилом «выходить рано, спускаться вовремя», а не просто народная мудрость.",
    "q.m15#4.p" to "О чём обычно говорят чечевицеобразные (грибовидные или дисковые) облака?",
    "q.m15#4.o0" to "О спокойной погоде",
    "q.m15#4.o1" to "О сильном ветре",
    "q.m15#4.o2" to "О скором дожде",
    "q.m15#4.o3" to "О повышении температуры",
    "q.m15#4.e" to "Чечевицеобразные — стоячие волновые облака, которые образуются, когда воздух перетекает через гребень: само их существование показывает высокую скорость ветра на высоте. В горах это значит, что на открытых гребнях возможны очень сильные порывы, а порывы — прямая причина потери равновесия.",
    "q.m15#5.p" to "Заметное увеличение перистых облаков обычно означает:",
    "q.m15#5.o0" to "Приближается погодная система",
    "q.m15#5.o1" to "Холодный период заканчивается",
    "q.m15#5.o2" to "Ветер скоро стихнет",
    "q.m15#5.o3" to "УФ ослабнет",
    "q.m15#5.e" to "Перистые облака часто передний край погодной системы: когда они появляются, погода ещё не изменилась, но изменение уже в пути. Это ценный запас времени, особенно для графика, из которого нужно выйти раньше.",
    "q.m15#6.p" to "Снижение слоистых облаков с явным падением нижней границы — каков самый прямой эффект?",
    "q.m15#6.o0" to "Температура растёт",
    "q.m15#6.o1" to "Видимость быстро ухудшается, оценивать рельеф становится трудно",
    "q.m15#6.o2" to "Ветер ослабевает",
    "q.m15#6.o3" to "Осадки прекращаются",
    "q.m15#6.e" to "Снижающиеся слоистые облака несут не дождь, а потерю видимости, — а потеря видимости сама по себе риск: вы можете уже сбиться с маршрута, приближаться к карнизу или пропустить поворот на отступление.",
    "q.m15#7.p" to "[Множественный выбор] Какие изменения облачности говорят об ухудшении погоды?",
    "q.m15#7.o0" to "Облачность быстро растёт, слой утолщается",
    "q.m15#7.o1" to "Нижняя граница продолжает снижаться",
    "q.m15#7.o2" to "Облака темнеют, появляется явное вертикальное развитие",
    "q.m15#7.o3" to "Появляется наковальня",
    "q.m15#7.o4" to "Облачность начинает уменьшаться, небо проясняется",
    "q.m15#7.e" to "Эти четыре — стадии одного процесса: растёт покров, снижается граница, тело темнеет и поднимается башней, появляется наковальня. Распознавая их по порядку, вы превращаете «погода испортилась» из одного мгновения в процесс, о котором предупреждают заранее.",
    "q.m15#8.p" to "Почему в горах облака развиваются бурнее, чем на равнине?",
    "q.m15#8.o0" to "Потому что там выше и холоднее",
    "q.m15#8.o1" to "Потому что рельеф заставляет воздух подниматься, усиливая конвекцию",
    "q.m15#8.o2" to "Потому что УФ сильнее",
    "q.m15#8.o3" to "Потому что воздух разрежен",
    "q.m15#8.e" to "Ветер, ударяя в гору, вынужден подниматься, будто его толкают вверх по пандусу: подъём вызывает охлаждение и конденсацию напрямую, поэтому облака образуются быстрее и локальнее, чем над равниной. Поэтому горная погода может полностью измениться за очень короткое время.",
    "q.m15#9.p" to "Как отличить развивающееся облако от рассеивающегося?",
    "q.m15#9.o0" to "По цвету",
    "q.m15#9.o1" to "Постоянно наблюдая, растут и отвердевают ли его объём, высота и очертания краёв",
    "q.m15#9.o2" to "По температуре",
    "q.m15#9.o3" to "По глубине снега",
    "q.m15#9.e" to "Ключ — непрерывное наблюдение: один взгляд даёт состояние, два — тенденцию. Развивающееся облако растёт в объёме, верх поднимается, края заостряются; рассеивающееся делает наоборот. Поэтому взгляд вверх через равные промежутки почти ничего не стоит, а даёт много.",
    "q.m15#10.p" to "[Сопоставление] Соотнесите тип облаков с их погодным значением.",
    "q.m15#10.l0" to "Кучево-дождевое (с наковальней)",
    "q.m15#10.r0" to "Гроза, град и сильные осадки",
    "q.m15#10.l1" to "Чечевицеобразное облако",
    "q.m15#10.r1" to "Сильный ветер на высоте, сильные порывы на гребнях",
    "q.m15#10.l2" to "Перистые облака",
    "q.m15#10.r2" to "Приближается погодная система",
    "q.m15#10.l3" to "Низкие слоистые",
    "q.m15#10.r3" to "Видимость падает, оценивать рельеф трудно",
    "q.m15#10.e" to "Эти четыре покрывают четыре вида погодной информации, которые чаще всего встречаются в горах. Одна оговорка: чтение облаков требует тренировки на картинках, а в приложении пока только текстовые вопросы, — распознавание облаков по изображениям добавим, когда будет готов канал изображений.",
    "q.m15#11.p" to "Почему чтение облаков нужно сочетать с тенденцией давления?",
    "q.m15#11.o0" to "Для полноты данных",
    "q.m15#11.o1" to "Потому что облака показывают текущее состояние, а тенденция давления — направление изменения",
    "q.m15#11.o2" to "Потому что барометр точнее",
    "q.m15#11.o3" to "Чтобы рассчитать высоту",
    "q.m15#11.e" to "Это разные измерения: облака говорят, что есть сейчас, давление — куда всё идёт. По одним облакам легко прочитать «ухудшается» как «просто пока пасмурно», — добавьте тенденцию, и картина полная.",
    "q.m15#12.p" to "Что в основном вызывает «молочное небо»?",
    "q.m15#12.o0" to "Чрезмерный снегопад",
    "q.m15#12.o1" to "Облака, туман и снежная поверхность близки по цвету, и граница между землёй и небом исчезает",
    "q.m15#12.o2" to "Крайне низкая температура",
    "q.m15#12.o3" to "Чрезмерный УФ",
    "q.m15#12.e" to "«Молочное небо» — это не сильный снег, а отсутствие контраста. Когда снег и облака близки по яркости, горизонт исчезает, и восприятие расстояния и уклона полностью отказывает, — поэтому это гораздо опаснее обычного снегопада.",
    "q.m15#13.p" to "Почему прогноз вида «местами кратковременные дожди» в горах малополезен?",
    "q.m15#13.o0" to "Потому что прогнозы неточны",
    "q.m15#13.o1" to "Потому что масштаб изменчивости погоды в горах намного меньше сетки прогноза, и на месте условия могут быть совершенно другими",
    "q.m15#13.o2" to "Потому что альпинисты не читают прогнозы",
    "q.m15#13.o3" to "Потому что осадки не важны",
    "q.m15#13.e" to "Ячейка прогноза может быть десятки километров, а две стороны одного гребня могут иметь совершенно разную погоду. Прогноз даёт фоновый риск; решение, можно ли двигаться сегодня, принимается на месте. Одно не заменяет другое.",
    "q.m15#14.p" to "В прогнозе «солнечно», но вы видите быстро растущие вертикально кучевые. Чему верить?",
    "q.m15#14.o0" to "Прогнозу — продолжаем по плану",
    "q.m15#14.o1" to "Своему наблюдению — решаем исходя из возможного ухудшения",
    "q.m15#14.o2" to "Усреднить оба",
    "q.m15#14.o3" to "Наблюдать ещё час",
    "q.m15#14.e" to "Прогноз груб и по времени, и по масштабу, а наблюдение — здесь и сейчас. Когда они расходятся, побеждает свидетельство на месте, — это и есть основная установка всей системы оценки погоды: прогноз задаёт фон, земля задаёт действие.",
    "q.m15#15.p" to "Заполните: после вспышки молнии каждая отсчитанная секунда соответствует примерно ( ) километра.",
    "q.m15#15.a0" to "0,34",
    "q.m15#15.a1" to ",34",
    "q.m15#15.a2" to "ноль целых тридцать четыре сотых",
    "q.m15#15.e" to "0,34 км в секунду — скорость звука в воздухе. Это преобразование превращает счёт секунд в рабочий инструмент: без всякого снаряжения вы понимаете, приближается гроза или уходит.",
    "q.m15#16.p" to "[Множественный выбор] В каких ситуациях стоит серьёзно рассмотреть немедленный спуск?",
    "q.m15#16.o0" to "Кучевые развились в кучево-дождевое с наковальней",
    "q.m15#16.o1" to "Снежный покров просел со звуком «вумпф»",
    "q.m15#16.o2" to "Видимость быстро падает, и вы больше не можете зафиксировать положение",
    "q.m15#16.o3" to "У участника прогрессивно ухудшаются высотные симптомы",
    "q.m15#16.o4" to "Участник говорит, что немного устал и хочет отдохнуть десять минут",
    "q.m15#16.e" to "Эти четыре идут из четырёх измерений — погоды, снежного покрова, навигации и физиологии, — и общее у них то, что все они прогрессируют, а значит цена сейчас гораздо ниже цены через десять минут. Чем раньше вы решите спускаться, тем дешевле.",
    "q.m15#17.p" to "Нажмите на кривую графика, которая обозначает уровень замерзания.",
    "q.m15#17.c" to "На этом прогнозе погода на разных высотах одной горы показана строками друг под другом. Фиолетовая кривая в легенде отмечает уровень замерзания — высоту линии дождь/снег.",
    "q.m15#17.e" to "Кривая уровня замерзания — одна из самых полезных данных в этом прогнозе: она отмечает высоту, на которой осадки переходят из дождя в снег. Растущая кривая значит, что приходит более тёплый и влажный воздух и осадки сменятся с снега на дождь; падающая — что установился холодный воздух и выше станет снежно. Для понимания, встретите ли вы снег на своей высоте, это полезнее чтения цифр температуры.",
    "q.m15#18.p" to "Это прогноз для той же горы, где сезон закончился раньше времени. Каков суммарный снегопад в сантиметрах за три периода пятницы 25-го (утро / день / ночь)? Введите сумму.",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 см. Почти 2,8 м снега за один день значит, что маршрут полностью засыпан, лавинная опасность резко растёт, а лагерям грозит разрушение. При таком масштабе вопрос уже не в том, можно ли выйти на вершину, а в том, можно ли безопасно эвакуироваться, — типичный способ, которым циклон завершает сезон.",
    "q.m15#19.p" to "Ситуация: читаем высотный прогноз погоды",
    "q.m15#19.c" to "Гид кладёт перед вами два прогноза для Манаслу — один из обычного окна восхождений, другой из записей сезона, который закончился раньше времени. Понимать их важнее, чем запоминать любую цифру.",
    "q.m15#19.e" to "Оценка погоды в итоге упирается не в «какая погода будет завтра», а в «можем ли мы двигаться в это окно». Один и тот же интерфейс, один говорит «продолжайте», другой «стоп», — разница не в чтении графика, а в понимании, при каких условиях нужно остановиться.",
    "q.m15#19.s0.p" to "Шаг 1: в прогнозе обычного окна что означают розовые блоки в строке высоты вершины (8 163 м)?",
    "q.m15#19.s0.o0" to "Ожидаемый снегопад за этот период",
    "q.m15#19.s0.o1" to "Дождь за этот период",
    "q.m15#19.s0.o2" to "Ощущаемая температура за этот период",
    "q.m15#19.s0.o3" to "Скорость ветра за этот период",
    "q.m15#19.s0.e" to "Розовый — снег, синий — дождь: прогноз отмечает тип осадков отдельно на каждой высоте именно потому, что его главный вопрос — будет ли на вашей высоте снег или дождь. В верхней строке блоки мелкие и редкие, значит на вершине бывает редкий слабый снег, без большого масштаба.",
    "q.m15#19.s1.p" to "Шаг 2: по сравнению с прогнозом конца сезона каково самое заметное изменение?",
    "q.m15#19.s1.o0" to "Только падает температура",
    "q.m15#19.s1.o1" to "Снегопад и скорость ветра резко растут, а осадки покрывают все высотные полосы",
    "q.m15#19.s1.o2" to "Дождь заменяет снег",
    "q.m15#19.s1.o3" to "Уровень замерзания сильно поднимается",
    "q.m15#19.s1.e" to "Снегопад идёт от разрозненных 1–4 см до 280 см за день, ветер — от 25–30 км/ч до 55–60 км/ч, а полоса осадков проходит через все высоты от 8 163 м до 1 500 м. Все три сразу — признак погодной системы, проходящей прямо над вами.",
    "q.m15#19.s2.p" to "Шаг 3: если бы ваша группа оказалась внутри такого прогнозного окна, каково правильное решение?",
    "q.m15#19.s2.o0" to "Ускорить штурм, пока погода совсем не испортилась",
    "q.m15#19.s2.o1" to "Немедленно прекратить попытку вершины, спускаться по плану и готовиться к эвакуации",
    "q.m15#19.s2.o2" to "Ждать на высотном лагере улучшения погоды",
    "q.m15#19.s2.o3" to "Разделиться на две группы: одна идёт на вершину, другая остаётся",
    "q.m15#19.s2.e" to "Когда прогноз показывает проходящую систему, а не короткое колебание, «подождать, пока пройдёт» обычно означает ещё несколько дней на высоте, чего не выдержат ни запасы, ни палатки. Поэтому столько сезонов заканчиваются не «мы дошли», а «нам пришлось выбираться», — и информация для такого решения как раз и есть на этих двух графиках.",
    "q.m15#20.p" to "Ситуация: читаем почасовой прогноз",
    "q.m15#20.c" to "Это почасовой прогноз на один день для Гунги (7 556 м). Плотность информации здесь намного выше, чем в обзоре на 16 дней, но и ошибиться строкой легче, — ключ в том, чтобы понимать, что именно говорит каждая строка.",
    "q.m15#20.e" to "Почасовой прогноз отвечает на то, на что не отвечает обзор: какой конкретно период рабочий. Уровень замерзания задаёт тип осадков, ощущаемая температура — выдержит ли человек, скорость ветра и солнце — насколько широко окно. Только вместе они дают решение, которое можно выполнить.",
    "q.m15#20.s0.p" to "Шаг 1: в строке Freeze уровень замерзания между 4 895 и 5 304 м, а вершина Гунги — 7 556 м. Что означает это сочетание?",
    "q.m15#20.s0.o0" to "Все осадки на горе выпадают снегом",
    "q.m15#20.s0.o1" to "На вершине будет дождь",
    "q.m15#20.s0.o2" to "Снег будет и ниже уровня замерзания",
    "q.m15#20.s0.o3" to "По этому нельзя судить о типе осадков",
    "q.m15#20.s0.e" to "Уровень замерзания — линия дождь/снег. Он устойчиво держится на 4 900–5 300 м, а все маршруты лежат выше. Иными словами, весь маршрут выше уровня замерзания, поэтому любые осадки приходят снегом. Одна цифра отвечает на вопрос «в каком виде я встречу осадки», — поэтому уровень замерзания полезнее значения температуры.",
    "q.m15#20.s1.p" to "Шаг 2: в строке Feels °C показано −18…−21, а Max / Min °C всего −10…−11. Чем в основном объясняется разрыв?",
    "q.m15#20.s1.o0" to "Ошибкой прогноза",
    "q.m15#20.s1.o1" to "Ветро-холодовым индексом: чем сильнее ветер, тем ниже ощущаемая температура",
    "q.m15#20.s1.o2" to "Разницей температур из-за высоты",
    "q.m15#20.s1.o3" to "Влиянием изменения влажности",
    "q.m15#20.s1.e" to "Скорость ветра в тот же период 20–30 км/ч. Ветер по открытой коже ускоряет теплопотери, поэтому ощущаемая температура почти на 10 °C ниже измеренной. На высоте возможность находиться снаружи определяет ощущаемая температура, а не температура воздуха. Те же −10 °C с ветром и без — совершенно разные вещи.",
    "q.m15#20.s2.p" to "Шаг 3: по этому прогнозу (ветер 20–30 км/ч, редкий снегопад 2/1/1 см, ощущаемая около −20 °C, светлое время 6:56–19:15) какова ваша оценка окна?",
    "q.m15#20.s2.o0" to "Условия суровые — отменить любое движение",
    "q.m15#20.s2.o1" to "Это относительно рабочее окно; главная сложность — холод и ветер, а не осадки",
    "q.m15#20.s2.o2" to "Слишком много осадков — есть лавинный риск",
    "q.m15#20.s2.o3" to "Данных недостаточно",
    "q.m15#20.s2.e" to "Ветер 20–30 км/ч ещё в рабочем диапазоне, а снегопад всего несколько сантиметров. Реальное давление создаёт ощущаемая температура около −20 °C, поэтому остерегаться нужно отморожения и переохлаждения. Логика такого окна: осадки и ветер приемлемы, проблема в температуре и длительности. Значит, сокращайте время под риском, усильте утепление конечностей и сдвиньте время поворота раньше.",
    "q.m15#21.p" to "В том же прогнозе для Гунги измеренная температура воздуха около −11 °C, а ощущаемый минимум −21 °C. Какова разница в градусах Цельсия?",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10 °C: −11 − (−21) = 10. Этот разрыв сам по себе информация для решения: одевайтесь по ощущаемой температуре, а не по температуре воздуха. Это же объясняет, как люди получают отморожения при −10 °C: они оделись по цифре на графике.",
    "q.m15#22.p" to "На этом прогнозе скорость ветра показана зелёными кружками. Что это, скорее всего, означает?",
    "q.m15#22.o0" to "Скорость ветра в этот период в пределах, подходящих для восхождения",
    "q.m15#22.o1" to "Скорость ветра в этот период достигла опасного уровня",
    "q.m15#22.o2" to "В этот период есть дождь",
    "q.m15#22.o3" to "Данные о ветре за этот период отсутствуют",
    "q.m15#22.e" to "Профессиональные горные погодные сервисы обычно кодируют скорость ветра цветом по её влиянию на движение. 20–30 км/ч зелёным значит попадание в полосу «двигаться можно»; выше цвет сдвигается к жёлтому или красному.\nНо цвет — это подсказка поставщика, а не ваш критерий. Разные маршруты и разные группы терпят один и тот же ветер по-разному. Читать число важнее, чем читать цвет.",
    "q.m15#23.p" to "Этот профессиональный интерфейс показывает температуру для 8000 / 6000 / 4000 / 2000 м четырьмя параллельными строками. В чём главная ценность такой подачи?",
    "q.m15#23.o0" to "Можно читать прогноз прямо для своей высоты, не экстраполируя с низкогорных данных",
    "q.m15#23.o1" to "Страница выглядит насыщеннее",
    "q.m15#23.o2" to "Показывает, что четыре строки не связаны",
    "q.m15#23.o3" to "Только чтобы легче было печатать на бумаге",
    "q.m15#23.e" to "Обычный прогноз даёт данные для одной точки, обычно ближайшего города или аэропорта. Вам приходится экстраполировать вверх по горе через градиент, — шаг, в котором легко ошибиться и который выбрасывает детали рельефа.\nПрофессиональный горный сервис делает наоборот: сначала нарезает гору по высотам, затем прогнозирует каждый срез. Вам остаётся найти строку для высоты, на которой вы будете завтра, и прочитать её. Это и простой тест на адекватность погодного сервиса: нарезает ли он гору по высоте.",
    "q.m15#24.p" to "В таблице строка «Cloud base (m)» в большинстве периодов содержит прочерк (—). Как это правильно читать?",
    "q.m15#24.o0" to "Нижняя граница облаков в этот период равна нулю, то есть облако на земле",
    "q.m15#24.o1" to "Для этого периода данных о нижней границе нет; нельзя читать это как «граница = 0»",
    "q.m15#24.o2" to "Это значит, что в этот период облаков нет вовсе",
    "q.m15#24.o3" to "Это значит, что нижняя граница выше вершины",
    "q.m15#24.e" to "В погодной таблице «пусто» и «ноль» — совершенно разные вещи. Пусто значит, что по этому пункту за период данных нет: он может быть не покрыт, либо осмысленную оценку дать нельзя. Это не значит, что значение равно нулю.\nСчитать пустое за ноль приводит к выводам вроде «облако на земле, ужасная видимость», не имеющим отношения к фактам. В любой погодной таблице сначала разделяйте эти две вещи. Это самая лёгкая ошибка при чтении прогноза и реже всего о ней говорят.",
    "q.m15#25.p" to "В строке ветра этого интерфейса числа идут со значками стрелок. Что, скорее всего, показывают стрелки?",
    "q.m15#25.o0" to "Тенденцию скорости ветра",
    "q.m15#25.o1" to "Направление ветра",
    "q.m15#25.o2" to "Вероятность осадков",
    "q.m15#25.o3" to "Рост или падение температуры",
    "q.m15#25.e" to "На высоте скорость и направление нужно читать вместе. Те же 30 км/ч ощущаются совершенно по-разному с наветренной и подветренной стороны и по-разному влияют на снежный покров: ветер переносит снег на подветренные склоны и сбивает его в пласты. Это одна из важнейших данных при оценке лавинной опасности.\nЧитать только число и не читать направление значит выбросить половину информации. Профессиональные интерфейсы ставят стрелку рядом с числом именно потому, что их нельзя читать врозь.",
    "q.m15#26.p" to "На этом 16-дневном графике красные маркеры (Snow) группируются около полосы 6 000 м, а синие (Rain) появляются ниже 5 000 м. О чём это говорит?",
    "q.m15#26.o0" to "Линия дождь/снег примерно между 5 500 и 6 000 м",
    "q.m15#26.o1" to "На горе выпадает только снег, дождя не бывает",
    "q.m15#26.o2" to "Дождь идёт до самой вершины",
    "q.m15#26.o3" to "По этому графику судить нельзя",
    "q.m15#26.e" to "Этот график не говорит, что и где выпадает в конкретный час; он отвечает прямо, в какую высотную полосу попадают осадки. Для альпиниста это как раз то, что нужно.\nКрасное в полосе 6 000 м и синее только ниже 5 000 м ставит линию дождь/снег примерно между 5 500 и 6 000 м. Вместе с фиолетовой кривой уровня замерзания в легенде (падает примерно с 6 000 до 4 800 м) видно и то, что линия будет опускаться дальше по прогнозу: полосы, где сейчас дождь, постепенно перейдут на снег.\nОдно и то же количество осадков действует на поход совершенно по-разному в зависимости от того, выпадает оно дождём или снегом.",
    "q.m15#27.p" to "В почасовом прогнозе на том же графике в 17:00 появляется значок молнии. Что этот сигнал означает на высоте?",
    "q.m15#27.o0" to "Это просто значок, особых мер не нужно",
    "q.m15#27.o1" to "Риск грозы: планируйте движение на утро, а днём уходите с гребней и открытого рельефа",
    "q.m15#27.o2" to "Идёт сильный дождь — достаточно взять дождевик",
    "q.m15#27.o3" to "Скорость ветра вырастет до опасного уровня",
    "q.m15#27.e" to "Дневные грозы на высоте обычны и действительно опасны. Подъём рельефом заставляет кучевые облака быстро расти во второй половине дня. Поэтому «выходить рано» не только про твёрдый снег, но и про то, чтобы уйти с открытого рельефа до образования гроз.\nГлавное в грозу: держаться подальше от вершин, гребней, одиночных деревьев и воды; не ложиться плашмя на землю; расходиться примерно на 50 м, чтобы один удар не поранил нескольких. Расстояние до молнии в километрах оценивают как секунды между вспышкой и громом × 0,34.",
    "q.m15#28.p" to "Что правильнее в вопросе, есть ли на источнике данных рельефа отметка вершины?",
    "q.m15#28.o0" to "Отметка всегда означает большую точность; доверять только картам с отметкой",
    "q.m15#28.o1" to "Отметки удобны для быстрого позиционирования и объяснений, но точная оценка рельефа всё равно требует горизонталей",
    "q.m15#28.o2" to "Карта без отметок бесполезна",
    "q.m15#28.o3" to "Отметки только мешают читать; игнорируйте их",
    "q.m15#28.e" to "На этой карте Google для Музтаг-Аты вершина отмечена прямо красной булавкой. Это очень полезно для ориентирования и общения: вы сразу знаете, где цель, и можете точно сказать партнёру, какую точку имеете в виду.\nНо отметка не отвечает, насколько крут этот склон и где можно поставить лагерь. Точная оценка рельефа по-прежнему зависит от горизонталей, и отметка в ней не участвует.\nПрактический подход: отметкой быстро находите место, затем по горизонталям высокого разрешения (например, версия SRTM) читаете крутизну и детали рельефа. Каждое делает своё дело.",
    "q.m16#0.p" to "Какие три масштаба должна сочетать продвинутая оценка лавинной опасности?",
    "q.m16#0.o0" to "Температура, скорость ветра, осадки",
    "q.m16#0.o1" to "Региональный прогноз, рельеф, снежный покров",
    "q.m16#0.o2" to "Высота, крутизна склона, солнце",
    "q.m16#0.o3" to "Размер группы, снаряжение, время",
    "q.m16#0.e" to "Эти три отвечают на три разных вопроса: прогноз говорит, насколько рискован день в целом, рельеф — может ли этот склон держать снег и сойти, снежный покров — устойчив ли он прямо сейчас. Имея только прогноз, вы судите о склоне под ногами по региональному среднему.",
    "q.m16#1.p" to "На каком уровне лавинной опасности происходит большинство происшествий?",
    "q.m16#1.o0" to "1 (низкий)",
    "q.m16#1.o1" to "3 (значительный)",
    "q.m16#1.o2" to "5 (чрезвычайный)",
    "q.m16#1.o3" to "Разницы нет",
    "q.m16#1.e" to "На 5-м уровне люди держатся в стороне, поэтому происшествий на деле меньше; на 3-м рельеф «выглядит проходимым», и на лавинный рельеф выходит много людей. Самое опасное состояние — никогда не крайнее, а среднее, которое недооценивают.",
    "q.m16#2.p" to "В каком диапазоне склонов происходит большинство лавин?",
    "q.m16#2.o0" to "10°–25°",
    "q.m16#2.o1" to "34°–45°",
    "q.m16#2.o2" to "55°–70°",
    "q.m16#2.o3" to "Закономерности нет",
    "q.m16#2.e" to "Около 96 % лавин сходит между 30° и 50°, основная часть концентрируется между 34° и 45°. Это как раз тот диапазон, который маршруты проходят чаще всего: достаточно круто, чтобы скользить, достаточно полого, чтобы держать снег.",
    "q.m16#3.p" to "[Множественный выбор] Какие правила верны при пересечении лавинного рельефа?",
    "q.m16#3.o0" to "Держать интервал и пересекать по одному",
    "q.m16#3.o1" to "Поставить наблюдателя в безопасном месте",
    "q.m16#3.o2" to "Заранее спланировать путь отхода",
    "q.m16#3.o3" to "Провести всю группу быстро вместе, чтобы сократить время под риском",
    "q.m16#3.e" to "Первые два ограничивают риск одним человеком; третье гарантирует выход, если что-то случится. «Все сразу» делает наоборот: превращает риск возможного засыпания одного в возможное засыпание всей группы, поэтому это худший вариант.",
    "q.m16#4.p" to "Где должен стоять наблюдатель?",
    "q.m16#4.o0" to "На пересекаемом склоне",
    "q.m16#4.o1" to "Там, откуда он хорошо видит идущего и сам в безопасности",
    "q.m16#4.o2" to "На самом верху склона",
    "q.m16#4.o3" to "На дне долины",
    "q.m16#4.e" to "У наблюдателя две задачи: держать человека в поле зрения (чтобы знать, где он засыпан) и действовать сразу, если что-то случится. Стоя на склоне или на дне долины, он становится вторым пострадавшим, — собственная безопасность наблюдателя есть условие выполнения его работы.",
    "q.m16#5.p" to "Зачем копать снежную яму?",
    "q.m16#5.o0" to "Чтобы отдохнуть",
    "q.m16#5.o1" to "Чтобы увидеть строение слоёв, положение слабого слоя и различия твёрдости",
    "q.m16#5.o2" to "Чтобы измерить температуру",
    "q.m16#5.o3" to "Чтобы сделать фотографии",
    "q.m16#5.e" to "Лавине нужен слабый слой и пласт над ним, и эта структура становится видимой только когда её вскрыть. Яма превращает невидимую внутреннюю структуру в видимое свидетельство, — ключевой шаг от предположения о риске к его наблюдению.",
    "q.m16#6.p" to "Почему «идти по следам впереди идущих» опасно?",
    "q.m16#6.o0" to "Потому что следы неясные",
    "q.m16#6.o1" to "Потому что следам может быть несколько часов, а снежный покров давно изменился",
    "q.m16#6.o2" to "Потому что можно выбрать неверный маршрут",
    "q.m16#6.o3" to "Потому что следы мешают идти",
    "q.m16#6.e" to "Состояние снежного покрова постоянно меняется с температурой, ветром и снегопадом, — нескольких часов достаточно, чтобы перейти от «едва устойчиво» к «готово сойти». Следы доказывают только, что кто-то прошёл тогда; они ничего не говорят о том, безопасно ли сейчас.",
    "q.m16#7.p" to "Как ветровой перенос влияет на лавинную опасность?",
    "q.m16#7.o0" to "Ветер разравнивает снег и снижает риск",
    "q.m16#7.o1" to "Ветер переносит снег на подветренные склоны, создавая дополнительные пласты и слабые слои, что резко повышает риск",
    "q.m16#7.o2" to "Ветер не связан с лавинами",
    "q.m16#7.o3" to "Ветер влияет только на видимость",
    "q.m16#7.e" to "Ветер — самый недооценённый создатель лавин: за короткое время он может перенести много снега на подветренные склоны, создав толстые пласты и слабые слои внутри них. Поэтому даже без снегопада после сильного ветра может появиться новая лавинная опасность.",
    "q.m16#8.p" to "В чём главная опасность карниза?",
    "q.m16#8.o0" to "Он мешает обзору",
    "q.m16#8.o1" to "Он может обрушиться сам в любой момент, а его обрушение может вызвать лавину на склоне ниже",
    "q.m16#8.o2" to "Его цвет отличается от снежной поверхности",
    "q.m16#8.o3" to "Он перекрывает маршрут",
    "q.m16#8.e" to "Карниз опасен дважды: встаньте на него — можете уйти вниз вместе с ним; пройдите под ним — он может обрушиться на вас вместе с большой массой снега. Обычный подход — обходить со стороны, противоположной краю карниза, и никогда не отдыхать на нём.",
    "q.m16#9.p" to "[Порядок] Какова полная процедура пересечения лавинного рельефа?",
    "q.m16#9.o0" to "До выхода проверить лавинный прогноз на день и отметить склоны, которых нужно избегать",
    "q.m16#9.o1" to "На подходе наблюдать сигналы на месте (трещины, звуки проседания, ветровые поверхности)",
    "q.m16#9.o2" to "Назначить наблюдателя, порядок пересечения и путь отхода",
    "q.m16#9.o3" to "Пересекать по одному, держа интервал, и собраться в безопасной точке",
    "q.m16#9.e" to "Первые три шага происходят до входа, — именно там и живёт вся работа по лавинной безопасности. Как только вы ступили на склон, выбора почти не остаётся, а большинство происшествий восходит к пропуску первых двух шагов.",
    "q.m16#10.p" to "Почему спасение из лавины должны немедленно проводить партнёры?",
    "q.m16#10.o0" to "Потому что профессиональное спасение дорого",
    "q.m16#10.o1" to "Потому что окно выживания засыпанного — около пятнадцати минут",
    "q.m16#10.o2" to "Потому что профессиональные команды не поднимутся",
    "q.m16#10.o3" to "Потому что партнёры лучше знают рельеф",
    "q.m16#10.e" to "Пятнадцать минут окна выживания означают, что спасти вас могут только те, кто рядом. Поэтому лавинный набор нужно носить с собой и отрабатывать, — носить снаряжение, которым не умеешь пользоваться, то же самое, что не носить его.",
    "q.m16#11.p" to "[Сопоставление] Соотнесите уровень лавинной опасности с его значением.",
    "q.m16#11.l0" to "Уровень 1",
    "q.m16#11.r0" to "Низкий: и естественное, и человеческое срабатывание маловероятно",
    "q.m16#11.l1" to "Уровень 3",
    "q.m16#11.r1" to "Значительный: человеческое срабатывание возможно и легче всего недооценивается",
    "q.m16#11.l2" to "Уровень 4",
    "q.m16#11.r2" to "Большой: естественное срабатывание вероятно; избегайте лавинного рельефа",
    "q.m16#11.l3" to "Уровень 5",
    "q.m16#11.r3" to "Чрезвычайный: широкомасштабные естественные лавины очень вероятны",
    "q.m16#11.e" to "За каждой цифрой стоит сочетание вероятности срабатывания и масштаба последствий. Классическая ошибка новичка — считать 3-й уровень «нормальным», хотя именно на нём концентрируются происшествия.",
    "q.m16#12.p" to "Каковы функция и ограничения лавинного рюкзака (эйрбэга)?",
    "q.m16#12.o0" to "Он полностью предотвращает засыпание; ограничений нет",
    "q.m16#12.o1" to "Он повышает шанс остаться ближе к поверхности, но не заменяет бипер, щуп и лопату и не защищает от травм",
    "q.m16#12.o2" to "Он только для горнолыжных курортов",
    "q.m16#12.o3" to "Он сам вызывает помощь",
    "q.m16#12.e" to "Принцип — больший объём, больше шансов остаться у поверхности: он повышает шансы выжить, но не гарантирует их. И значительная доля смертей в лавинах связана с травмами, а не с асфиксией, поэтому эйрбэг никогда не может быть единственной опорой.",
    "q.m16#13.p" to "Почему склоны, которые «не выглядят такими крутыми», часто самые опасные?",
    "q.m16#13.o0" to "Потому что там глубже снег",
    "q.m16#13.o1" to "Потому что 34°–45° — зона концентрации лавин, а человеческий глаз недооценивает крутизну",
    "q.m16#13.o2" to "Потому что там мало кто ходит",
    "q.m16#13.o3" to "Потому что угол быстро меняется",
    "q.m16#13.e" to "Без ориентира люди оценивают крутизну с большой ошибкой, часто читая 35° как 25°. А 30°–35° — как раз полоса, которая «выглядит проходимой, но может сойти». Уклономер и карта с горизонталями и есть лекарство от этого искажения.",
    "q.m16#14.p" to "[Множественный выбор] Что группа должна сделать до входа на лавинный рельеф?",
    "q.m16#14.o0" to "Убедиться, что все умеют пользоваться бипером, щупом и лопатой",
    "q.m16#14.o1" to "Согласовать порядок пересечения и наблюдателя",
    "q.m16#14.o2" to "Согласовать место встречи и путь отхода",
    "q.m16#14.o3" to "Проверить, что биперы передают",
    "q.m16#14.o4" to "Многократно сильно потоптаться, чтобы проверить устойчивость снега",
    "q.m16#14.e" to "Все четыре — последние проверки перед входом, и все занимают минуты. Они важны потому, что на склоне единственным оставшимся вариантом будет надежда, что не сойдёт.",
    "q.m16#15.p" to "Снежный покров просел со звуком «вумпф». Какова правильная реакция?",
    "q.m16#15.o0" to "Идти дальше — снег просто оседает",
    "q.m16#15.o1" to "Немедленно остановиться и переоценить: слабый слой начал разрушаться",
    "q.m16#15.o2" to "Пройти быстрее",
    "q.m16#15.o3" to "Отдохнуть на месте десять минут",
    "q.m16#15.e" to "«Вумпф» — прямое доказательство того, что слабый слой разрушается: очень лёгкая нагрузка только что вызвала локальный срыв. Продолжать значит фактически проверять, не хватит ли ещё немного, чтобы всё сошло.",
    "q.m16#16.p" to "Заполните: около 96 % лавин сходит на склонах 30°–50°, основная часть концентрируется между 34° и ( )°.",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "сорока пятью",
    "q.m16#16.e" to "34°–45°. Этот диапазон стоит запомнить: это одновременно и лавинный очаг, и градиент, который маршруты проходят чаще всего, — именно пересечение этих двух фактов делает лавины одним из главных объективных рисков в альпинизме.",
    "q.m16#17.p" to "Ситуация: пересекаем участок лавинного рельефа",
    "q.m16#17.c" to "Маршрут должен пересечь снежный склон около 35°, длиной примерно 200 м. Лавинный прогноз на сегодня — «значительный» (3-й уровень), недавно выпало 30 см снега, ветер северо-западный, склон обращён на юго-восток.",
    "q.m16#17.e" to "Эта ситуация проверяет весь лавинный алгоритм: прочитать рельеф и снежный покров, выполнить подготовку до входа, затем использовать порядок движения для контроля последствий. Ни один шаг не труден; трудно выполнить все перед склоном, который выглядит проходимым.",
    "q.m16#17.s0.p" to "Шаг 1: что на этом склоне требует наибольшей осторожности?",
    "q.m16#17.s0.o0" to "Камнепад",
    "q.m16#17.s0.o1" to "Ветровые пласты и сама крутизна склона",
    "q.m16#17.s0.o2" to "Высокая температура",
    "q.m16#17.s0.o3" to "Растительность на земле",
    "q.m16#17.s0.e" to "35° попадает прямо в очаг 34°–45°; северо-западный ветер переносит снег на подветренный склон (здесь юго-восточная сторона), создавая дополнительный пласт. Два фактора складываются в классическое «выглядит проходимым, но может сойти».",
    "q.m16#17.s1.p" to "Шаг 2: подходя к склону, что делать в первую очередь?",
    "q.m16#17.s1.o0" to "Сразу начать пересечение",
    "q.m16#17.s1.o1" to "Сначала наблюдать сигналы на месте, затем зафиксировать наблюдателя, порядок пересечения и путь отхода",
    "q.m16#17.s1.o2" to "Сильно потоптаться на склоне для проверки",
    "q.m16#17.s1.o3" to "Быстро провести всю группу",
    "q.m16#17.s1.e" to "Вся подготовка относится к периоду до входа. Топтание не проверяет устойчивость, — оно может напрямую спровоцировать снежный покров, уже близкий к критической точке.",
    "q.m16#17.s2.p" to "Шаг 3: как расположить группу при пересечении?",
    "q.m16#17.s2.o0" to "По одному, остальные ждут в безопасной точке",
    "q.m16#17.s2.o1" to "Все вместе, взявшись за руки",
    "q.m16#17.s2.o2" to "По двое в ряд, чтобы следить друг за другом",
    "q.m16#17.s2.o3" to "Гуськом, плотно друг к другу",
    "q.m16#17.s2.e" to "По одному ограничивает риск одним человеком и позволяет наблюдателю сосредоточиться на одном. Подвергать опасности всю группу сразу значит увеличить последствие с возможного засыпания одного до возможного засыпания всех.",
    "q.m16#18.p" to "Нажмите на примерный район вершины Манаслу на карте.",
    "q.m16#18.c" to "Это карта горизонталей Манаслу, построенная по данным высот NASA SRTM с шагом 50 м; подписи дают высоту каждой горизонтали.",
    "q.m16#18.e" to "Вершину на карте горизонталей не спутать: замкнутые горизонтали стягиваются кольцо за кольцом, а подписи идут вверх (7600 → 7750 → 7900 → 7950 …). Найдите точку, охваченную кольцами небольших замкнутых кривых, — это и есть высшая точка.\nНаоборот, там где горизонтали расходятся веером и подписи падают, — склон идёт вниз; это, кстати, подсказывает, с какой стороны идёт маршрут.",
    "q.m16#19.p" to "На той же карте горизонтали на северо-восток — восток очень плотные. О чём это говорит?",
    "q.m16#19.o0" to "Эта сторона очень крутая, там очаг схода сераков и камнепада",
    "q.m16#19.o1" to "Эта сторона пологая и подходит для лагеря",
    "q.m16#19.o2" to "Эта сторона ниже и потому менее рискованна",
    "q.m16#19.o3" to "Плотные горизонтали означают, что рельеф там плоский",
    "q.m16#19.e" to "Чем плотнее горизонтали, тем больше перепад высоты на том же горизонтальном расстоянии, то есть круче склон. На этой карте северо-восточная сторона падает с 7 950 до 5 750 м, десятки горизонталей сжаты в короткое расстояние: классическая крутая стена.\nПри планировании маршрута этот навык чтения прямо влияет на две вещи: проходите ли вы через зоны схода сераков и камнепада, и есть ли пригодный рельеф для отступления, если что-то пойдёт не так. Более пологие, редко изрезанные горизонталями участки — там, где лагерь вероятнее.",
    "q.m16#20.p" to "Ситуация: сравниваем два источника данных о рельефе",
    "q.m16#20.c" to "Гид даёт вам две карты рельефа одной горы: одну из Google Maps, другую построенную по данным высот NASA SRTM. Ни одна не ошибочна, но их возможности ответить на ваши вопросы не равны.",
    "q.m16#20.e" to "Главное различие наборов данных о рельефе не в точности, а в шаге горизонталей, потому что шаг задаёт, насколько мелкое изменение склона вы можете увидеть. Интуиция имеет ценность, — она быстро строит общее впечатление, — но решение, крут ли конкретный участок и проходим ли он, всё равно возвращается к плотности горизонталей, которую можно измерить и сравнить.",
    "q.m16#20.s0.p" to "Шаг 1: на этой карте Google подписи горизонталей 6200, 6400, 6600, 6800… Каков шаг горизонталей?",
    "q.m16#20.s0.o0" to "50 м",
    "q.m16#20.s0.o1" to "100 м",
    "q.m16#20.s0.o2" to "200 м",
    "q.m16#20.s0.o3" to "500 м",
    "q.m16#20.s0.e" to "Соседние подписи различаются на 200 м, значит эта система горизонталей поднимается на 200 м между линиями. Шаг 200 м годится для общей формы, но детали рельефа между линиями — скажем, 40-метровая скальная ступень — просто исчезают с карты.",
    "q.m16#20.s1.p" to "Шаг 2: на карте SRTM шаг 50 м. В чём её самое существенное преимущество по сравнению с Google-картой с шагом 200 м?",
    "q.m16#20.s1.o0" to "Она красивее",
    "q.m16#20.s1.o1" to "На том же расстоянии линии плотнее, и изменение крутизны разрешается в четыре раза мельче",
    "q.m16#20.s1.o2" to "Цвета ярче",
    "q.m16#20.s1.o3" to "Подписи крупнее",
    "q.m16#20.s1.e" to "Чем меньше шаг, тем больше деталей рельефа вы различаете. Оценка проходимости склона опирается именно на плотность горизонталей: при шаге 200 м 150-метровая крутая ступень сглаживается в пологий склон, а при 50 м она нарисована как есть.\nПоэтому оценка рельефа на технических маршрутах опирается на источники высокого разрешения вроде SRTM.",
    "q.m16#20.s2.p" to "Шаг 3: у версии Google выражены свет и тень, она выглядит объёмной. Как относиться к этой отмывке при оценке крутизны?",
    "q.m16#20.s2.o0" to "Чем темнее тень, тем круче склон, — используйте это напрямую как доказательство",
    "q.m16#20.s2.o1" to "Отмывка отражает только освещение и экспозицию; её нельзя напрямую использовать как меру крутизны",
    "q.m16#20.s2.o2" to "Отмывка отмечает участки снежного покрова",
    "q.m16#20.s2.o3" to "Отмывка отмечает рельеф выше 7 000 м",
    "q.m16#20.s2.e" to "Отмывка рельефа имитирует, как склон освещён солнцем с заданного направления. Тёмное значит, что склон обращён от света, а не что он крутой. Пологий северный склон может быть темнее крутого южного.\nИспользовать отмывку как замену крутизны — распространённое и действительно опасное заблуждение. Отмывка хороша для общего впечатления; чтобы измерить крутизну, читайте плотность горизонталей и желательно сверяйтесь с данными высокого разрешения с подписями высот.",
    "q.m16#21.p" to "Как правильно понимать утверждение «Google Maps интуитивен, но неточен, SRTM точен, но не интуитивен»?",
    "q.m16#21.o0" to "SRTM точнее, поэтому Google Maps бесполезна",
    "q.m16#21.o1" to "Их нужно использовать вместе: общее впечатление строить по интуитивной карте, а измеримые суждения делать по горизонталям высокого разрешения",
    "q.m16#21.o2" to "Google Maps интуитивнее, поэтому при оценке склонов доверять сначала ей",
    "q.m16#21.o3" to "Они различаются только цветом, информация одна и та же",
    "q.m16#21.e" to "Два источника решают разные задачи. Отмывка и подписи Google быстро строят пространственное чувство: где гора, какая у неё примерная форма, куда идёт маршрут. Горизонтали SRTM с шагом 50 м поддерживают измеримые суждения: сколько градусов у этого склона, есть ли где поставить лагерь.\nОтсеивать по интуитивной карте, подтверждать по высокоразрешающей — это и есть практическое разделение. Использовать только одну значит либо медленно, либо неверно.",
    "q.m16#22.p" to "Нажмите на примерный район вершины Эвереста на карте.",
    "q.m16#22.c" to "Это карта горизонталей района Эверест — Лхоцзе по SRTM; на одном листе видны две вершины 8 000 м.",
    "q.m16#22.e" to "Чтобы найти вершину, ищите высшую подписанную замкнутую горизонталь. Здесь подписи рядом поднимаются до 8600 и 8700 м, а кольца стягиваются внутрь; внутреннее и есть вершина (8 848 м).\nВажно разделять высокое и крутое: привершинный рельеф часто не самая крутая часть горы, — круче всего там, где горизонтали плотнее. Это различие важно для риска на маршруте: выход наверх проверяет акклиматизацию и форму, а технический риск сосредоточен на нескольких склонах по пути вверх и вниз.",
    "q.m16#23.p" to "Между плотными замкнутыми горизонталями Эвереста и Лхоцзе на той же карте есть зона, где горизонтали заметно расходятся, а рельеф слегка проседает. Что это по рельефу?",
    "q.m16#23.o0" to "Исток ледника",
    "q.m16#23.o1" to "Седловина между двумя вершинами",
    "q.m16#23.o2" to "Высшая точка гребня",
    "q.m16#23.o3" to "Крутой обрыв",
    "q.m16#23.e" to "Между двумя плотными замкнутыми вершинами, где горизонтали расходятся и рельеф проседает, находится седловина. Та, что между Эверестом и Лхоцзе, — Южное седло около 7 900 м, где стоит четвёртый лагерь маршрута с юга, — последняя остановка перед штурмом.\nРаспознавать седловины на карте горизонталей очень практично. Они обычно означают сильный ветер и открытость, но относительно пологий рельеф: хорошо для лагеря, плохо для долгого пребывания, поэтому привершинные лагеря обычно стоят на седловине и в ту же ночь снимаются.",
    "q.m16#24.p" to "Нажмите на примерный район вершины Музтаг-Аты на карте.",
    "q.m16#24.c" to "Это карта горизонталей Музтаг-Аты (7 509 м) по SRTM. Её верх — не острый пик, а широкий снежный купол.",
    "q.m16#24.e" to "Форма вершины Музтаг-Аты показательна: купол, широкий и пологий сверху, где высшая замкнутая горизонталь широко раскинута, а не стянута плотно, как на остром пике. Чтобы найти такую вершину, ищите самую высокую подпись высоты (здесь 7 500 м) и замкнутое кольцо, в котором она стоит.\nФорма прямо влияет на ощущение восхождения. Купол значит, что привершинный участок не крут, но занимает много времени; при малом перепаде и без явных ориентиров на снежном поле легко потерять чувство направления на спуске. Об этом риске часто говорят именно в связи с Музтаг-Атой.",
    "q.m17#0.p" to "В чём основная цель управления высотным лагерем?",
    "q.m17#0.o0" to "Сделать лагерь комфортным",
    "q.m17#0.o1" to "Поддерживать работоспособность при минимальных затратах",
    "q.m17#0.o2" to "Экономить топливо",
    "q.m17#0.o3" to "Получать хорошие фотографии",
    "q.m17#0.e" to "На высоте каждая единица энергии — ограниченный ресурс, и лагерь — единственное место, где она возвращается. Поэтому любое решение по лагерю должно отвечать на один вопрос: сделает ли это группу завтра сильнее?",
    "q.m17#1.p" to "О чём думать в первую очередь при выборе места под лагерь?",
    "q.m17#1.o0" to "О виде",
    "q.m17#1.o1" to "Об избегании лавинных путей, зон схода сераков, участков под карнизами и трещин",
    "q.m17#1.o2" to "О близости воды",
    "q.m17#1.o3" to "О близости к началу маршрута",
    "q.m17#1.e" to "Первое правило выбора места — не попадать под объективную опасность, потому что лагерь — это где вы остаётесь часами или сутки и почти не можете быстро двигаться. Вид и удобство вторичны.",
    "q.m17#2.p" to "Почему нельзя ставить лагерь под карнизом?",
    "q.m17#2.o0" to "Потому что земля неровная",
    "q.m17#2.o1" to "Потому что карниз может обломиться в любой момент и обрушить на лагерь массу снега и льда",
    "q.m17#2.o2" to "Потому что там ветрено",
    "q.m17#2.o3" to "Потому что не видно вида",
    "q.m17#2.e" to "Обрушение карниза не даёт предсказуемого предупреждения: он может сойти в дневном тепле или в самый холодный час перед рассветом. Поставить лагерь под ним значит принять постоянную угрозу, которую вы не можете ни отследить, ни отработать заранее.",
    "q.m17#3.p" to "[Множественный выбор] Каких участков должен избегать лагерь?",
    "q.m17#3.o0" to "Под лавинным путём",
    "q.m17#3.o1" to "Прямо под карнизом или над ним",
    "q.m17#3.o2" to "Очевидные поля трещин",
    "q.m17#3.o3" to "В пределах досягаемости схода сераков",
    "q.m17#3.o4" to "Открытая площадка с хорошей панорамой",
    "q.m17#3.e" to "Все четыре — случаи, когда объективная опасность приходит точно в лагерь. Общее у них то, что их трудно отследить, а последствие, если случится, группового масштаба, — поэтому стандарты выбора места для лагеря должны быть консервативнее, чем для маршрута.",
    "q.m17#4.p" to "Как распределять топливо и еду?",
    "q.m17#4.o0" to "Держать всё у одного человека",
    "q.m17#4.o1" to "Фасовать по дням, отложив аварийный запас",
    "q.m17#4.o2" to "Держать всё у входа в палатку",
    "q.m17#4.o3" to "Делить поровну по числу людей без запаса",
    "q.m17#4.e" to "Фасовка по дням делает расход отслеживаемым, а запас гарантирует, что энергии всегда хватит на безопасный спуск. В горах топливо — это не только готовка: это ещё и таяние снега на воду, сушка одежды и поддержание температуры тела.",
    "q.m17#5.p" to "Зачем держать аварийный запас?",
    "q.m17#5.o0" to "Потому что еда портится",
    "q.m17#5.o1" to "Чтобы гарантировать топливо и еду для безопасного спуска в любых обстоятельствах",
    "q.m17#5.o2" to "Потому что так требует магазин",
    "q.m17#5.o3" to "Чтобы легче было идти назад",
    "q.m17#5.e" to "Запас рассчитан на худший случай: погода испортилась, пришлось остаться лишний день, кто-то травмирован и нужен медленный спуск. Если все ресурсы расписаны под лучший график, любая задержка оставляет вас и без запасов, и без возможности двигаться.",
    "q.m17#6.p" to "Как обращаться с электроникой (телефон, камера, батареи налобного фонаря) на ночь?",
    "q.m17#6.o0" to "Оставлять снаружи палатки",
    "q.m17#6.o1" to "Держать у тела или в спальнике в тепле",
    "q.m17#6.o2" to "Держать во внешнем кармане рюкзака",
    "q.m17#6.o3" to "Ничего делать не нужно",
    "q.m17#6.e" to "Литиевые батареи на холоде сильно теряют ёмкость и могут просто отключиться. Держать их в тепле нужно не для сохранности устройства, а чтобы завтра включился налобный фонарь и заработал GPS. Это снаряжение безопасности, а не личные вещи.",
    "q.m17#7.p" to "Что делать с мокрой одеждой?",
    "q.m17#7.o0" to "Повесить снаружи, чтобы высохла на морозе",
    "q.m17#7.o1" to "Держать у тела или в спальнике, чтобы она сохла от тепла тела",
    "q.m17#7.o2" to "Свалить в угол палатки",
    "q.m17#7.o3" to "Запихнуть сразу в рюкзак",
    "q.m17#7.e" to "Ночные температуры на высоте крайне низкие, поэтому мокрая одежда снаружи замерзает насквозь. Сушка на теле неполная, но по крайней мере завтра она не будет ледяной, — классический пример отношения к теплу тела как к ресурсу.",
    "q.m17#8.p" to "Почему лагерь всегда должен быть в состоянии, из которого можно сразу собраться и уйти?",
    "q.m17#8.o0" to "Чтобы удобнее было выходить",
    "q.m17#8.o1" to "Потому что погода или состояние участника могут потребовать экстренной эвакуации в любой момент",
    "q.m17#8.o2" to "Чтобы сэкономить время на сборах",
    "q.m17#8.o3" to "Чтобы было аккуратно",
    "q.m17#8.e" to "Погодное окно в высотном лагере может закрыться внезапно, а у участника могут внезапно появиться высотные симптомы. В этот момент то, сколько времени нужно, чтобы начать движение, определяет, сколько риска вы несёте, — а снаряжение, разбросанное по всей палатке, может стоить лишних полчаса.",
    "q.m17#9.p" to "Что НЕ является основной причиной плохого сна на высоте?",
    "q.m17#9.o0" to "Периодическое дыхание с частыми короткими пробуждениями",
    "q.m17#9.o1" to "Гипоксия и учащённый пульс",
    "q.m17#9.o2" to "Холод и неудобство",
    "q.m17#9.o3" to "Слишком яркий цвет палатки",
    "q.m17#9.e" to "Первые три — реальные физиологические причины, и периодическое дыхание самая типичная: на высоте ночное дыхание непроизвольно становится прерывистым и снова и снова возвращает вас в поверхностный сон. Качество сна в свою очередь прямо влияет на акклиматизацию, — так что плохо спать не мелочь.",
    "q.m17#10.p" to "[Порядок] Каков разумный порядок постановки и снятия лагеря?",
    "q.m17#10.o0" to "До прихода осмотреть окрестности на лавинную угрозу, сход сераков и карнизы",
    "q.m17#10.o1" to "Зафиксировать место палатки, выровнять площадку и закрепить палатку",
    "q.m17#10.o2" to "Распределить запасы, натопить воды и спланировать завтрашний график и сон",
    "q.m17#10.o3" to "Перед выходом пересчитать снаряжение и мусор и восстановить площадку",
    "q.m17#10.e" to "Первый шаг пропускают чаще всего, — особенно когда устал и любая ровная площадка кажется местом под лагерь. Но поставив лагерь, перенести его крайне дорого, поэтому осмотр перед выбором места должен стать привычкой.",
    "q.m17#11.p" to "Почему лагерь — ещё и опорный пункт отступления?",
    "q.m17#11.o0" to "Потому что в лагере запасы",
    "q.m17#11.o1" to "Потому что отступление обычно означает вернуться сначала в лагерь, а затем решить, идти ли ниже или ждать погоды",
    "q.m17#11.o2" to "Потому что в лагере средства связи",
    "q.m17#11.o3" to "Потому что в лагере гид",
    "q.m17#11.e" to "Спускаться с высоты редко получается одним непрерывным ходом: вы возвращаетесь в ближайший лагерь, чтобы восстановиться, понаблюдать и решить. Значит, сам лагерь должен быть надёжной целью, — не местом, куда страшно возвращаться.",
    "q.m17#12.p" to "Почему палатка должна проветриваться?",
    "q.m17#12.o0" to "Чтобы не было жарко",
    "q.m17#12.o1" to "Чтобы не накапливался угарный газ и внутренний иней и не случилось удушья и отравления",
    "q.m17#12.o2" to "Чтобы удобнее было входить и выходить",
    "q.m17#12.o3" to "Чтобы уменьшить парусность",
    "q.m17#12.e" to "Готовка на горелке в закрытой палатке может быстро поднять уровень угарного газа, а такое отравление обычно случается во сне, и его симптомы — головная боль, усталость — почти невозможно отличить от высотной болезни. Всё это делает проветривание жёстким требованием.",
    "q.m17#13.p" to "Что опаснее всего при использовании горелки в палатке?",
    "q.m17#13.o0" to "Утечка топлива",
    "q.m17#13.o1" to "Отравление угарным газом",
    "q.m17#13.o2" to "Расплавить палатку",
    "q.m17#13.o3" to "Шум",
    "q.m17#13.e" to "Угарный газ бесцветен и без запаха, а его ранние симптомы — головная боль, сонливость — сильно пересекаются с высотной болезнью. Именно это и делает его опасным: люди засыпают, считая, что это просто AMS. Горелка всегда требует проветривания.",
    "q.m17#14.p" to "[Множественный выбор] За какими вопросами здоровья нужно активно следить в лагере?",
    "q.m17#14.o0" to "Пить достаточно воды (тая снег)",
    "q.m17#14.o1" to "Есть достаточно, даже без аппетита",
    "q.m17#14.o2" to "Держать одежду сухой",
    "q.m17#14.o3" to "Следить за состоянием и походкой друг друга",
    "q.m17#14.o4" to "Заменять еду кофе и энергетиками",
    "q.m17#14.e" to "Первые три — забота о себе, четвёртое — забота о группе, и часто она действеннее первых трёх: ранние признаки высотной болезни (неустойчивая походка, замедленные реакции) трудно заметить у себя, но партнёру они видны с первого взгляда.",
    "q.m17#15.p" to "Заполните: выше высотного лагеря топливо и еду обычно фасуют по ( ), откладывая аварийный запас.",
    "q.m17#15.a0" to "дням",
    "q.m17#15.a1" to "дню",
    "q.m17#15.a2" to "каждому дню",
    "q.m17#15.a3" to "суткам",
    "q.m17#15.e" to "Фасуют по дням. Так прогресс расхода виден с первого взгляда и вы замечаете «сколько дней осталось» в момент сдвига графика, — а не тогда, когда всё уже кончилось.",
    "q.m18#0.p" to "Какова высота Музтаг-Аты?",
    "q.m18#0.o0" to "6 812 м",
    "q.m18#0.o1" to "7 126 м",
    "q.m18#0.o2" to "7 134 м",
    "q.m18#0.o3" to "7 509 м",
    "q.m18#0.e" to "Музтаг-Ата — 7 509 м, уезд Акто, Синьцзян. Это первый выбор для китайской цели 7 000 м и высшая из четырёх гор этого урока.",
    "q.m18#1.p" to "Почему Музтаг-Ату называют «отцом ледяных гор»?",
    "q.m18#1.o0" to "Потому что это высшая вершина мира",
    "q.m18#1.o1" to "Потому что её ледники и объём снега огромны, и издалека она выглядит как обширный ледяной щит",
    "q.m18#1.o2" to "Потому что она первой из 7 000 м была покорена",
    "q.m18#1.o3" to "Потому что это священная гора в местных легендах",
    "q.m18#1.e" to "Название идёт от облика: верх покрыт огромным ледяным щитом, а снежные склоны очень широки, поэтому издалека она читается как белый массив. Этот образ объясняет и характер восхождения: длинные снежные склоны, умеренный угол, но много времени.",
    "q.m18#2.p" to "Каковы технические особенности восхождения на Музтаг-Ату?",
    "q.m18#2.o0" to "В основном вертикальные ледовые стены, крайне технично",
    "q.m18#2.o1" to "Бесконечные снежные склоны при умеренной технической сложности, но очень высокие требования к акклиматизации и форме",
    "q.m18#2.o2" to "Техническое снаряжение почти не нужно",
    "q.m18#2.o3" to "В основном скальный рельеф",
    "q.m18#2.e" to "Это классический профиль 7 000 м: сам маршрут может быть несложным, но долгие дни с переноской груза на высоте увеличивают любую мелкую проблему. Поэтому реальный фокус подготовки — акклиматизация и форма, а не высокая техника.",
    "q.m18#3.p" to "Какова фактическая высота Ама-Даблам?",
    "q.m18#3.o0" to "6 812 м",
    "q.m18#3.o1" to "7 126 м",
    "q.m18#3.o2" to "7 509 м",
    "q.m18#3.o3" to "8 027 м",
    "q.m18#3.e" to "Ама-Даблам — 6 812 м, район Кхумбу, Непал. По высоте это вершина 6 000 м, но она в разделе 7 000 м, потому что её техническая сложность сравнима с вершинами выше 7 000 м.",
    "q.m18#4.p" to "Почему Ама-Даблам с её 6 812 м отнесена к разделу 7 000 м?",
    "q.m18#4.o0" to "Потому что административно она классифицируется как вершина 7 000 м",
    "q.m18#4.o1" to "Потому что её крутой смешанный скально-снежный рельеф и сильная открытость ставят сложность на уровень вершин выше 7 000 м",
    "q.m18#4.o2" to "Потому что у неё очень низкая доля успеха",
    "q.m18#4.o3" to "Потому что она лежит в горном массиве 7 000 м",
    "q.m18#4.e" to "Это самый важный пункт урока: сложность горы — не её высота. Ама-Даблам классическое доказательство: ниже многих вершин 7 000 м, но её технический порог и психологическая нагрузка могут быть больше. Выбирать гору только по высоте опасно.",
    "q.m18#5.p" to "Какова высота и расположение пика Ленина?",
    "q.m18#5.o0" to "7 126 м, Непал",
    "q.m18#5.o1" to "7 134 м, Памир",
    "q.m18#5.o2" to "7 509 м, Синьцзян",
    "q.m18#5.o3" to "6 812 м, Кхумбу, Непал",
    "q.m18#5.e" to "Пик Ленина — 7 134 м на Памире. Он среди более мягких вариантов 7 000 м и поэтому часто используется как первая цель 7 000 м.",
    "q.m18#6.p" to "Какова высота Химлунг-Химала?",
    "q.m18#6.o0" to "7 126 м",
    "q.m18#6.o1" to "7 134 м",
    "q.m18#6.o2" to "7 509 м",
    "q.m18#6.o3" to "6 812 м",
    "q.m18#6.e" to "Химлунг-Химал — 7 126 м, Непал. Его маршрут сочетает снежные склоны и ледовые стены, что делает его популярным среди непальских вершин 7 000 м.",
    "q.m18#7.p" to "[Порядок] Расставьте эти горы по возрастанию высоты.",
    "q.m18#7.o0" to "Ама-Даблам (6 812 м)",
    "q.m18#7.o1" to "Химлунг-Химал (7 126 м)",
    "q.m18#7.o2" to "Пик Ленина (7 134 м)",
    "q.m18#7.o3" to "Музтаг-Ата (7 509 м)",
    "q.m18#7.e" to "Этот порядок вскрывает частую ошибку: по высоте Ама-Даблам идёт раньше Музтаг-Аты, но реальная техническая сложность может быть обратной. Снова: высота — лишь одна из многих переменных.",
    "q.m18#8.p" to "[Множественный выбор] Что в основном меняется на 7 000 м по сравнению с 6 000 м?",
    "q.m18#8.o0" to "Более длинная акклиматизация с большим числом выходов в высотные лагеря",
    "q.m18#8.o1" to "Более узкие погодные окна, поэтому выбор времени важнее",
    "q.m18#8.o2" to "Более тяжёлое отступление, из-за чего самообеспечение становится жёстким требованием",
    "q.m18#8.o3" to "В целом более техничный рельеф и больше открытости",
    "q.m18#8.o4" to "Дополнительный кислород становится штатным снаряжением",
    "q.m18#8.e" to "Эти четыре не складываются, а умножаются: плохая акклиматизация заставляет упустить окно, упущенное окно вынуждает отступать в худших условиях, а отступление усилено высотой и техничным рельефом. Поэтому 7 000 м и называют водоразделом.",
    "q.m18#9.p" to "Почему 7 000 м называют «водоразделом»?",
    "q.m18#9.o0" to "Потому что выше 7 000 м нужны ледорубы",
    "q.m18#9.o1" to "Потому что с этого уровня техника, оценка, форма и логистика действуют одновременно, и никакая отдельная сила не компенсирует остальные",
    "q.m18#9.o2" to "Потому что ледники видны только выше 7 000 м",
    "q.m18#9.o3" to "Потому что коммерческие группы работают только выше 7 000 м",
    "q.m18#9.e" to "Неудачи на 5 000 м обычно имеют одну причину (акклиматизация или форма), на 6 000 м причины начинают складываться, а на 7 000 м всё должно быть на месте. Поэтому в этом разделе техника, оценка, погода, самообеспечение и управление лагерем собраны вместе, — они всегда были одной системой.",
    "q.m18#10.p" to "Что важнее всего при выборе цели 7 000 м?",
    "q.m18#10.o0" to "Высота",
    "q.m18#10.o1" to "Хорошее общее соответствие типа маршрута, логистики, графика акклиматизации и вариантов отступления",
    "q.m18#10.o2" to "Стоимость",
    "q.m18#10.o3" to "Доля успешных восхождений",
    "q.m18#10.e" to "Ни одного пункта недостаточно: выше не значит сложнее, высокая доля успеха не значит безопаснее, дешевле не значит выгоднее. Настоящая оценка — выдержу ли я, сегодняшний, сочетание этих четырёх.",
    "q.m18#11.p" to "Почему на Музтаг-Ате сами «бесконечные снежные склоны» — риск?",
    "q.m18#11.o0" to "Потому что склоны слишком скользкие",
    "q.m18#11.o1" to "Потому что длительное пребывание на высоте постепенно съедает форму и оценку, а расстояние отступления велико",
    "q.m18#11.o2" to "Потому что на склонах часты лавины",
    "q.m18#11.o3" to "Потому что на снежных склонах нельзя идти в связке",
    "q.m18#11.e" to "«Не сложно, но очень долго» — классическая модель риска 7 000 м: нет ни одного ключевого участка, но вас истощают непрерывно. Долгое пребывание значит, что форма, внимание и качество решений медленно проседают, — и этот потерянный запас и есть ваш запас безопасности.",
    "q.m18#12.p" to "[Сопоставление] Соотнесите гору с её типичным характером.",
    "q.m18#12.l0" to "Музтаг-Ата",
    "q.m18#12.r0" to "Отец ледяных гор: бесконечные снежные склоны, проверка акклиматизации и формы",
    "q.m18#12.l1" to "Ама-Даблам",
    "q.m18#12.r1" to "Крутой смешанный скально-снежный рельеф, сильная открытость, испытание перед 8 000 м",
    "q.m18#12.l2" to "Пик Ленина",
    "q.m18#12.r2" to "Памир; сравнительно мягкий среди вершин 7 000 м",
    "q.m18#12.l3" to "Химлунг-Химал",
    "q.m18#12.r3" to "В Непале; сочетание снежных склонов и ледовых стен",
    "q.m18#12.e" to "Эти четыре профиля соответствуют четырём разным приоритетам подготовки: Музтаг-Ата — акклиматизация, Ама-Даблам — техника и психология, пик Ленина — ступень, Химлунг — всесторонняя проверка. Увидев их вместе, можно выбирать по своему слабому месту.",
    "q.m18#13.p" to "Если цель — вершина 8 000 м, как разумнее выбирать среди вариантов 7 000 м?",
    "q.m18#13.o0" to "Выбрать самую высокую",
    "q.m18#13.o1" to "Выбрать ту, что закрывает ваше слабое место (технику, акклиматизацию или открытость)",
    "q.m18#13.o2" to "Выбрать самую дешёвую",
    "q.m18#13.o3" to "Выбрать с самой высокой долей успеха",
    "q.m18#13.e" to "Относиться к 7 000 м как к тренировке слабых мест ценнее, чем как к повышению уровня. Слабы в технике — выбирайте Ама-Даблам; плохо акклиматизируетесь — Музтаг-Ату с её длинными склонами и отработанными выходами в высотные лагеря.",
    "q.m18#14.p" to "Как правильно смотреть на период подготовки к вершине 7 000 м?",
    "q.m18#14.o0" to "Примерно как к 6 000 м",
    "q.m18#14.o1" to "Заметно дольше: нужны достаточное число выходов в высотные лагеря и время на акклиматизацию",
    "q.m18#14.o2" to "Достаточно только физической подготовки",
    "q.m18#14.o3" to "Можно начинать сразу после предыдущего восхождения",
    "q.m18#14.e" to "Акклиматизация накопительна, и 7 000 м обычно требуют нескольких выходов в высотные лагеря. Плотный график без заложенного времени на акклиматизацию — прямая причина, по которой многие группы на 7 000 м не выходят на вершину или попадают в происшествия.",
    "q.m18#15.p" to "Почему в этом разделе «оценка опасности» стоит после уроков техники?",
    "q.m18#15.o0" to "Потому что оценка проще техники",
    "q.m18#15.o1" to "Потому что технические навыки дают уверенность входить в более сложный рельеф, и именно поэтому оценка нужнее, чтобы это сдерживать",
    "q.m18#15.o2" to "Из-за ограничений объёма программы",
    "q.m18#15.o3" to "Потому что техника не важна",
    "q.m18#15.e" to "Это реалистичный порядок: чем выше навык, тем сложнее маршруты, которые вы можете попробовать, поэтому потребность ограничивать себя на деле растёт. Ставить оценку после техники значит повторять этот порядок в реальности: сначала возможность, затем сдержанность.",
    "q.m19#0.p" to "«Зона смерти» обычно означает:",
    "q.m19#0.o0" to "Выше 7 000 м",
    "q.m19#0.o1" to "Выше 8 000 м",
    "q.m19#0.o2" to "Выше 5 500 м",
    "q.m19#0.o3" to "Выше 6 000 м",
    "q.m19#0.e" to "Выше 8 000 м называют зоной смерти по простой причине: парциальное давление кислорода настолько низкое, что никакая акклиматизация не позволяет телу долго сохранять равновесие. Это не риторика, а физиологический факт, — и самая принципиальная граница между 8 000 и 7 000 м.",
    "q.m19#1.p" to "На 8 000 м атмосферное давление составляет примерно какую долю от уровня моря?",
    "q.m19#1.o0" to "Одну вторую",
    "q.m19#1.o1" to "Две трети",
    "q.m19#1.o2" to "Одну треть",
    "q.m19#1.o3" to "Одну пятую",
    "q.m19#1.e" to "Около одной трети. Значит, каждый вдох доставляет лишь около тридцати процентов молекул кислорода, доступных на уровне моря, — а подъём требует в несколько раз больше кислорода, чем покой. Этот разрыв между потребностью и поставкой и есть источник всех рисков на 8 000 м.",
    "q.m19#2.p" to "Почему человек не может долго оставаться выше 8 000 м?",
    "q.m19#2.o0" to "Потому что там слишком холодно",
    "q.m19#2.o1" to "Потому что парциальное давление кислорода ниже порога, нужного для поддержания обмена, и тело постепенно разрушается",
    "q.m19#2.o2" to "Потому что не хватает еды",
    "q.m19#2.o3" to "Потому что ветер слишком сильный",
    "q.m19#2.e" to "Долгое пребывание значит расход больше восстановления: даже в покое тело теряет мышцы и вес, а когнитивные способности снижаются. Поэтому график на 8 000 м должен быть быстрым туда и быстрым обратно: варианта дождаться улучшения условий нет.",
    "q.m19#3.p" to "Какую способность гипоксия обычно поражает первой?",
    "q.m19#3.o0" to "Силу ног",
    "q.m19#3.o1" to "Оценку и мышление",
    "q.m19#3.o2" to "Зрение",
    "q.m19#3.o3" to "Слух",
    "q.m19#3.e" to "Это самый опасный механизм на 8 000 м: человек, у которого снизилась оценка, не может оценить, что его оценка снизилась. Наоборот, слабые ноги вы замечаете сразу, а мысль «я могу идти дальше» сама может быть продуктом гипоксии.",
    "q.m19#4.p" to "Почему снижение оценки особенно опасно на 8 000 м?",
    "q.m19#4.o0" to "Потому что можно заблудиться",
    "q.m19#4.o1" to "Потому что решать, продолжать или отступать, приходится уже нарушенной оценкой",
    "q.m19#4.o2" to "Потому что это влияет на партнёров",
    "q.m19#4.o3" to "Потому что это замедляет",
    "q.m19#4.e" to "Это рекурсивная ловушка: именно когда нужно критическое решение — продолжать или отступать — ваша способность решать наименее надёжна. «Дойдём чуть дальше и посмотрим» на 4 000 м может быть разумно; на 8 000 м это может быть уже ошибкой, вызванной гипоксией.",
    "q.m19#5.p" to "[Множественный выбор] Каковы типичные признаки когнитивного снижения от гипоксии?",
    "q.m19#5.o0" to "Замедленные реакции, невнятная речь",
    "q.m19#5.o1" to "Ошибки в счёте и оценке",
    "q.m19#5.o2" to "Оценка риска становится излишне оптимистичной",
    "q.m19#5.o3" to "Перепады настроения, раздражительность или апатия",
    "q.m19#5.o4" to "Снижение чувствительности к отморожению пальцев рук и ног",
    "q.m19#5.e" to "Все четыре типичны, и у них общая черта: сам человек их почти не замечает. Поэтому надёжный подход — вынести всё наружу: чек-листы вместо памяти, фиксированное время вместо «кажется, пора», и наблюдение партнёров друг за другом вместо самооценки.",
    "q.m19#6.p" to "Что действеннее всего противодействует снижению оценки?",
    "q.m19#6.o0" to "Держаться на силе воли",
    "q.m19#6.o1" to "Вынести решения в заранее написанные чек-листы и фиксированные правила (время, остаток кислорода, погодные пороги)",
    "q.m19#6.o2" to "Пить больше горячей воды",
    "q.m19#6.o3" to "Замедлиться",
    "q.m19#6.e" to "Сила воли — как раз то, что гипоксия разрушает первым. Надёжный метод — записать правила, пока вы ещё работаете: во сколько нужно повернуть, при каком остатке кислорода начинать спуск, — тогда остаётся только проверять факты, а не судить заново.",
    "q.m19#7.p" to "Почему график на 8 000 м делает акцент на «выходить рано, возвращаться рано»?",
    "q.m19#7.o0" to "Чтобы избежать толпы",
    "q.m19#7.o1" to "Потому что днём растёт вероятность ухудшения погоды, а холод и ветер быстро съедают энергию и кислород",
    "q.m19#7.o2" to "Потому что утром маршрут короче",
    "q.m19#7.o3" to "Из-за привычек гидов",
    "q.m19#7.e" to "На 8 000 м цена «поздно» увеличивается: тот же рельеф днём требует вдвое больше усилий, а с наступлением темноты падают и температура, и оценка. «Спускались слишком поздно» почти всегда общая отправная точка этой цепочки происшествия.",
    "q.m19#8.p" to "Почему на 8 000 м нужно «упрощать решения»?",
    "q.m19#8.o0" to "Чтобы сэкономить время",
    "q.m19#8.o1" to "Потому что когнитивные ресурсы ограничены, и их нужно беречь для решений, которые действительно важны",
    "q.m19#8.o2" to "Потому что на высоте не хочется думать",
    "q.m19#8.o3" to "Потому что партнёры решат за вас",
    "q.m19#8.e" to "На практике: фиксированные места и порядок снаряжения, процедуры, превращённые в чек-листы, график, заданный заранее. Сделать «что надеть сегодня, что делать первым» поведением по умолчанию, не требующим мысли, значит сохранить оценку для решений вроде «продолжать или отступать».",
    "q.m19#9.p" to "Почему даже опытным альпинистам на 8 000 м нужны чек-листы?",
    "q.m19#9.o0" to "Потому что память ненадёжна",
    "q.m19#9.o1" to "Потому что гипоксия прежде всего повреждает рабочую память, а чек-лист от памяти не зависит",
    "q.m19#9.o2" to "Потому что этого требуют правила",
    "q.m19#9.o3" to "Чтобы помочь новичкам учиться",
    "q.m19#9.e" to "Логика та же, что в авиации: в средах высокой нагрузки и тяжёлых последствий нельзя полагаться на «я вряд ли забуду». Чек-лист — не учебное пособие для новичков, а страховка от ошибок, которые делают и эксперты.",
    "q.m19#10.p" to "Что в основном вызывает постоянную потерю веса на высоте?",
    "q.m19#10.o0" to "Потому что еда невкусная",
    "q.m19#10.o1" to "Потому что в гипоксии тело постоянно разбирает собственные ткани, а сниженный аппетит означает недостаточное поступление",
    "q.m19#10.o2" to "Из-за объёма нагрузки",
    "q.m19#10.o3" to "Из-за недостатка воды",
    "q.m19#10.e" to "Два фактора действуют вместе: гипоксия переводит тело в состояние, где распад превышает синтез, а сама высотная болезнь подавляет аппетит. Поэтому способность есть на высоте — это навык, а не удовольствие.",
    "q.m19#11.p" to "Почему на 8 000 м плохой сон?",
    "q.m19#11.o0" to "Потому что палатка неудобная",
    "q.m19#11.o1" to "Потому что низкое содержание кислорода вызывает периодическое дыхание с повторяющимися паузами, которые выдёргивают вас из сна",
    "q.m19#11.o2" to "Потому что ветрено",
    "q.m19#11.o3" to "Потому что вы слишком много спали днём",
    "q.m19#11.e" to "Периодическое дыхание — классический высотный феномен сна: неустойчивый дыхательный драйв даёт повторяющиеся циклы «остановка — встряска». Качество сна потом прямо влияет на акклиматизацию и энергию следующего дня, — поэтому способность спать — ключевая компетенция в высотном лагере.",
    "q.m19#12.p" to "[Порядок] Расставьте эффекты гипоксии на функции организма в обычном порядке появления.",
    "q.m19#12.o0" to "Учащённое дыхание и пульс (компенсация)",
    "q.m19#12.o1" to "Падение выносливости при длительной нагрузке",
    "q.m19#12.o2" to "Снижение оценки и способности считать",
    "q.m19#12.o3" to "Изменённое сознание, атаксия",
    "q.m19#12.e" to "Первые два — тело пытается справиться; последние два — тело отказывает. Опасно третье: оно появляется до всякого явного изменения сознания, поэтому «выглядит нормально» не значит «соображает ясно».",
    "q.m19#13.p" to "Какой самый прямой и надёжный способ противодействовать гипоксии на 8 000 м?",
    "q.m19#13.o0" to "Больше есть",
    "q.m19#13.o1" to "Использовать дополнительный кислород",
    "q.m19#13.o2" to "Больше отдыхать",
    "q.m19#13.o3" to "Замедлиться",
    "q.m19#13.e" to "Остальные действуют через снижение расхода или ускорение акклиматизации, а дополнительный кислород напрямую повышает парциальное давление вдыхаемого кислорода, — он меняет корневую переменную. Поэтому на 8 000 м кислород — штатное снаряжение безопасности.",
    "q.m19#14.p" to "Как правильно понимать «предел акклиматизации»?",
    "q.m19#14.o0" to "Акклиматизация может продолжаться бесконечно",
    "q.m19#14.o1" to "У акклиматизации есть потолок: выше определённой высоты она уже не компенсирует полностью",
    "q.m19#14.o2" to "Акклиматизация занимает один день",
    "q.m19#14.o3" to "Акклиматизация не связана с высотой",
    "q.m19#14.e" to "Акклиматизация — процесс с пределом, а не кривая, которая бесконечно растёт. Это и есть принципиальная причина, по которой 8 000 м зависят от кислорода и стратегии «быстро туда, быстро обратно»: дело не в недостаточной подготовке, а в физиологическом отсутствии варианта «акклиматизироваться и остаться».",
    "q.m19#15.p" to "Почему корень происшествий на 8 000 м редко бывает одним событием?",
    "q.m19#15.o0" to "Из-за невезения",
    "q.m19#15.o1" to "Потому что гипоксия одновременно ослабляет оценку, энергию и координацию, и несколько звеньев становятся хрупкими сразу",
    "q.m19#15.o2" to "Потому что снаряжение недостаточно",
    "q.m19#15.o3" to "Потому что слишком много людей",
    "q.m19#15.e" to "На малой высоте ошибка обычно оставляет запас на восстановление; на 8 000 м оценка, энергия и моторика падают вместе, поэтому мелкие ошибки напрямую сцепляются в происшествие. Значит, стратегия безопасности на 8 000 м — больше слоёв защиты, а не просто быть внимательнее.",
    "q.m19#16.p" to "[Множественный выбор] Каковы основные причины смерти на 8 000 м?",
    "q.m19#16.o0" to "Лавина и сход сераков",
    "q.m19#16.o1" to "Падения",
    "q.m19#16.o2" to "Переохлаждение",
    "q.m19#16.o3" to "Высотная болезнь и её осложнения",
    "q.m19#16.o4" to "Травмы среды, например снежная слепота и солнечные ожоги",
    "q.m19#16.e" to "Все четыре часты, и они часто складываются: падение лишает возможности самоспасения, затем ожидание на холоде, затем переохлаждение, затем ухудшение высотной болезни. Поэтому подготовка к 8 000 м не может ограничиваться высотной болезнью, — в неё входят техника, оценка и системы.",
    "q.m19#17.p" to "Заполните: выше 8 000 м называют «зоной ( )».",
    "q.m19#17.a0" to "смерти",
    "q.m19#17.a1" to "мёртвой",
    "q.m19#17.e" to "Зона смерти. Практическая ценность термина — в жёстком ограничении, которое он передаёт: здесь нет варианта ждать или сбавить. Любой план, расчёт запасов и решение должны строиться вокруг того, чтобы пройти как можно быстрее.",
    "q.m19#18.p" to "На 8 000 м вы замечаете, что «очень хотите идти дальше на вершину». Что делать?",
    "q.m19#18.o0" to "Довериться инстинкту и лезть дальше",
    "q.m19#18.o1" to "Счесть это возможным признаком гипоксической недооценки риска и немедленно свериться с условиями поворота, заданными заранее",
    "q.m19#18.o2" to "Ускориться и выйти наверх",
    "q.m19#18.o3" to "Пусть решают партнёры",
    "q.m19#18.e" to "Это очень характерная ситуация: сильное желание продолжать на малой высоте может быть просто желанием, а на 8 000 м — сигналом нарушенной оценки. Единственный надёжный ориентир тогда не самочувствие, а объективные условия, записанные до выхода.",
    "q.m20#0.p" to "Какова основная роль дополнительного кислорода на 8 000 м?",
    "q.m20#0.o0" to "Заменяет физическую подготовку",
    "q.m20#0.o1" to "Повышает кислород в крови, снижает риск высотной болезни и улучшает подвижность и оценку",
    "q.m20#0.o2" to "Греет",
    "q.m20#0.o3" to "Уменьшает вес рюкзака",
    "q.m20#0.e" to "Пункт, который чаще всего упускают и который критичен для безопасности, — улучшение оценки: он напрямую противодействует самому опасному фактору на 8 000 м. Поэтому кислород на этой высоте и является штатным снаряжением безопасности, а не средством облегчить труд.",
    "q.m20#1.p" to "Из чего состоит система дополнительного кислорода?",
    "q.m20#1.o0" to "Баллон, редуктор, расходомер, маска или назальная канюля",
    "q.m20#1.o1" to "Баллон и рюкзак",
    "q.m20#1.o2" to "Маска и утепляющий слой",
    "q.m20#1.o3" to "Редуктор и каска",
    "q.m20#1.e" to "У каждой части своя задача: баллон хранит, редуктор сбрасывает высокое давление до безопасного диапазона, расходомер задаёт подачу, маска или канюля доставляет. Отказ где угодно означает, что вы вдыхаете меньше, чем думаете, — поэтому систему проверяют на каждом выходе.",
    "q.m20#2.p" to "Какая подача типична при восхождении?",
    "q.m20#2.o0" to "0,5–1 л/мин",
    "q.m20#2.o1" to "2–4 л/мин",
    "q.m20#2.o2" to "8–10 л/мин",
    "q.m20#2.o3" to "Выше 15 л/мин",
    "q.m20#2.e" to "2–4 л/мин — обычный диапазон при восхождении; точная цифра зависит от высоты, нагрузки и индивидуальной реакции. Большая подача комфортнее, но расходует быстрее, — компромисс, который напрямую определяет, как долго вы можете находиться на 8 000 м.",
    "q.m20#3.p" to "Почему в расчёте кислорода аварийный запас считают отдельно?",
    "q.m20#3.o0" to "Чтобы взять немного лишнего",
    "q.m20#3.o1" to "Потому что задержки, помощь партнёру или отказ системы могут потребовать дополнительный кислород",
    "q.m20#3.o2" to "Потому что баллоны текут",
    "q.m20#3.o3" to "Потому что этого требуют правила",
    "q.m20#3.e" to "Классическая ошибка в планировании кислорода — «ровно до вершины». Реальные графики почти всегда медленнее плана, у партнёров может закончиться газ или система может подтекать. Без запаса любое отклонение оставляет вас играть в рулетку на самой опасной высоте.",
    "q.m20#4.p" to "Что может произойти, когда кислород заканчивается?",
    "q.m20#4.o0" to "Ничего",
    "q.m20#4.o1" to "Состояние может быстро ухудшиться, потому что тело адаптировалось к более высокой концентрации вдыхаемого кислорода",
    "q.m20#4.o2" to "Высотная болезнь ударит мгновенно",
    "q.m20#4.o3" to "Система автоматически переключится на окружающий воздух",
    "q.m20#4.e" to "Резкий переход от обогащённого кислорода обратно к окружающему парциальному давлению на 8 000 м равносилен мгновенному набору куска высоты. Если вы далеко от лагеря и уже истощены, всё может быстро стать опасным, — поэтому запас кислорода нужно держать консервативным.",
    "q.m20#5.p" to "[Множественный выбор] Какая дисциплина применяется к кислородной системе?",
    "q.m20#5.o0" to "Проверять подачу и соединения на каждом выходе",
    "q.m20#5.o1" to "Использовать плановую подачу; не крутить её по желанию",
    "q.m20#5.o2" to "Записывать остаток и оценку времени, на которое его хватит",
    "q.m20#5.o3" to "Заранее договориться, при каком остатке нужно спускаться",
    "q.m20#5.o4" to "При недомогании выкручивать подачу на максимум",
    "q.m20#5.e" to "Четвёртое важнее всего: сделать «спускаться при таком остатке» числом, зафиксированным заранее, а не обсуждением на месте. К моменту, когда это понадобится, человек, которому нужно это правило, может уже потерять способность оценивать точно.",
    "q.m20#6.p" to "Почему использование кислорода — не «читерство»?",
    "q.m20#6.o0" to "Потому что правила разрешают",
    "q.m20#6.o1" to "Потому что выше 8 000 м тело выходит за физиологический диапазон, который может долго компенсировать, и кислород — стандартный ответ на этот факт",
    "q.m20#6.o2" to "Потому что все так делают",
    "q.m20#6.o3" to "Потому что это повышает долю успеха",
    "q.m20#6.e" to "Слово «читерство» предполагает допущение, что чуть больше усилий позволяет проскочить предел, — но предел на 8 000 м задан физикой и физиологией, а не правилом. Кислород несколько поднимает физиологический потолок; он не меняет того, что долго оставаться нельзя.",
    "q.m20#7.p" to "В чём главное различие маски и назальной канюли?",
    "q.m20#7.o0" to "Маска даёт более стабильную концентрацию, но в ней душнее и она ограничивает обзор в движении",
    "q.m20#7.o1" to "Канюля может дать более высокую концентрацию",
    "q.m20#7.o2" to "Они одинаковы",
    "q.m20#7.o3" to "Маска легче",
    "q.m20#7.e" to "Маска лучше прилегает и держит стабильную концентрацию, но добавляет сопротивление дыханию, легко запотевает и неудобна в движении; канюля удобна и не мешает обзору, но фактическая вдыхаемая концентрация сильно зависит от характера дыхания. Выбор зависит от рельефа, интенсивности и личной переносимости, — это не просто «что лучше».",
    "q.m20#8.p" to "Какой компромисс возникает при повышении или понижении подачи?",
    "q.m20#8.o0" to "Комфорт против времени работы",
    "q.m20#8.o1" to "Вес против цены",
    "q.m20#8.o2" to "Компромисса нет",
    "q.m20#8.o3" to "Высота против температуры",
    "q.m20#8.e" to "Большая подача означает более комфортное тело и лучше сохранённую оценку, но меньше времени до опустошения. Кислородный план фактически есть бюджет того, как долго вы можете оставаться на высоте, — и он напрямую задаёт окно дня вершины и время поворота.",
    "q.m20#9.p" to "Почему вес баллонов становится проблемой логистики?",
    "q.m20#9.o0" to "Потому что они громоздкие",
    "q.m20#9.o1" to "Потому что и баллон, и газ тяжёлые, а выше высотного лагеря всё приходится нести людям",
    "q.m20#9.o2" to "Потому что их нельзя сдать в багаж",
    "q.m20#9.o3" to "Потому что они легко ломаются",
    "q.m20#9.e" to "На высоте цена каждого килограмма умножается, а баллон тяжёл и несжимаем. Поэтому кислородный план нужно проектировать вместе с раскладкой лагерей и людьми, — это не отдельный вопрос снаряжения.",
    "q.m20#10.p" to "Почему кислород нужно заранее занести в высотный лагерь?",
    "q.m20#10.o0" to "Чтобы облегчить день вершины и гарантировать наличие кислорода",
    "q.m20#10.o1" to "Чтобы его не украли",
    "q.m20#10.o2" to "Потому что там холоднее",
    "q.m20#10.o3" to "Чтобы сэкономить деньги",
    "q.m20#10.e" to "День вершины — когда вы наиболее растянуты и наименее в форме; нести кислород вверх в этот день вы уже не можете. Поэтому его нужно заносить заранее, партия за партией, — а значит количество кислорода, люди и погодное окно связаны уже на этапе планирования.",
    "q.m20#11.p" to "Что делать, если кислородная система отказала по пути?",
    "q.m20#11.o0" to "Продолжать подъём и починить дома",
    "q.m20#11.o1" to "Немедленно оценить остаток кислорода и свою высоту, затем действовать по плану: спускаться или перейти на резервную систему",
    "q.m20#11.o2" to "Выкрутить подачу, чтобы попытаться исправить",
    "q.m20#11.o3" to "Разобрать и отремонтировать",
    "q.m20#11.e" to "Отказ кислорода значит, что вы внезапно работаете в условиях большей высоты без защиты. Разбираться с этим важнее всего остального: сначала решить, позволяет ли резерв продолжать, и если нет — спускаться. На 8 000 м идти вниз — осмысленный выбор, а не поражение.",
    "q.m20#12.p" to "[Порядок] Какова последовательность проверки кислородной системы в день вершины?",
    "q.m20#12.o0" to "Подтвердить давление в баллоне и оценку поддерживаемого времени",
    "q.m20#12.o1" to "Проверить редуктор, шланг и маску или канюлю на повреждения",
    "q.m20#12.o2" to "Открыть подачу и убедиться, что газ действительно идёт",
    "q.m20#12.o3" to "Записать остаток и сообщить партнёрам и тем, кто ждёт дома",
    "q.m20#12.e" to "Первые три — технические проверки, четвёртая — командное общение, и на высоте она особенно важна: если партнёры знают ваш запас кислорода, они могут заметить ваше ухудшение раньше вас.",
    "q.m20#13.p" to "Почему кислород не заменяет акклиматизацию?",
    "q.m20#13.o0" to "Потому что кислород слишком дорог",
    "q.m20#13.o1" to "Потому что акклиматизация — собственная физиологическая компенсация тела, а кислород лишь повышает вдыхаемую концентрацию",
    "q.m20#13.o2" to "Потому что кислород перестаёт действовать",
    "q.m20#13.o3" to "Потому что кислород помогает только от высотной болезни",
    "q.m20#13.e" to "Акклиматизация меняет то, как тело использует кислород; кислород меняет то, сколько его поступает. Первое из второго не получить. Поэтому спуск, постепенный набор и достаточное время на акклиматизацию остаются обязательными условиями на 8 000 м.",
    "q.m20#14.p" to "[Множественный выбор] Какие отказы кислородной системы часты?",
    "q.m20#14.o0" to "Обледенение или засорение в соединении",
    "q.m20#14.o1" to "Утечки шланга",
    "q.m20#14.o2" to "Неисправность редуктора с неточной подачей",
    "q.m20#14.o3" to "Трудно открыть вентиль баллона",
    "q.m20#14.o4" to "Баллон тяжелее ожидаемого",
    "q.m20#14.e" to "Все четыре связаны с холодом, обледенением и неудобством работы, и все случаются на высоте, в усталости, когда разбираться труднее всего. Поэтому одной резервной системы недостаточно, — нужен ещё план решений при отказе.",
    "q.m20#15.p" to "Почему кислородный план должен быть вписан в график?",
    "q.m20#15.o0" to "Для виду",
    "q.m20#15.o1" to "Потому что количество кислорода напрямую определяет возможное время поворота и максимальное время пребывания",
    "q.m20#15.o2" to "Чтобы записать расходы",
    "q.m20#15.o3" to "Чтобы проще было отчитаться",
    "q.m20#15.e" to "Кислород — это не «взять немного и всё», а оцифрованный бюджет: сколько баллонов, при какой подаче, на сколько часов. Эти числа в свою очередь задают время поворота, поэтому их надо планировать вместе с графиком, а не отдельным списком.",
    "q.m20#16.p" to "Заполните: типичная подача при восхождении — около 2–( ) л/мин.",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "четырём",
    "q.m20#16.e" to "2–4 л/мин. Диапазон есть баланс между поддержанием достаточного кислорода в крови и экономией газа. Управление кислородом в итоге — непрерывная задача распределения ресурса.",
    "q.m20#17.p" to "Что делать, если у партнёра заканчивается кислород?",
    "q.m20#17.o0" to "Продолжать к вершине; каждый сам за себя",
    "q.m20#17.o1" to "Немедленно сообщить информацию и остатки друг другу, затем по плану спускаться вместе или перераспределить кислород",
    "q.m20#17.o2" to "Пусть сам разбирается",
    "q.m20#17.o3" to "Отдать ему весь свой кислород",
    "q.m20#17.e" to "Нехватка — событие группового уровня, а не личного: оно влияет на скорость спуска и взаимное прикрытие. Худшие варианты — две крайности: идти дальше на вершину или полностью отдать свой запас. Разумный ответ — перераспределить ресурсы и поставить в приоритет вывод вниз всех.",
    "q.m20#18.p" to "Рабочий баллон содержит 1 200 литров. При подаче 3 л/мин на сколько примерно минут его хватит?",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "Около 400 минут (примерно 6,7 часа): 1200 ÷ 3 = 400. Такие расчёты прямо важны в день вершины: они определяют, как долго вы можете оставаться на 8 000 м, а значит, на какое время назначать поворот.",
    "q.m20#19.p" to "План на вершину: 5 часов вверх, 3 часа вниз, подача 2 л/мин плюс 60 минут аварийного запаса. Какой общий объём кислорода нужен, в литрах?",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 литров: (5 + 3) часа × 60 мин × 2 л/мин = 960 литров, плюс 60 × 2 = 120 литров запаса, итого 1080. Считать подъём, спуск и запас тремя отдельными частями — базовая дисциплина кислородного планирования; считать только «хватит ли дойти наверх» — самая частая ошибка.",
    "q.m21#0.p" to "Сколько в мире вершин выше 8 000 м?",
    "q.m21#0.o0" to "10",
    "q.m21#0.o1" to "12",
    "q.m21#0.o2" to "14",
    "q.m21#0.o3" to "18",
    "q.m21#0.e" to "Четырнадцать, все в пределах Гималаев и Каракорума. Это число и стало источником альпинистской цели «четырнадцать восьмитысячников».",
    "q.m21#1.p" to "В каких странах находятся четырнадцать восьмитысячников?",
    "q.m21#1.o0" to "Китай, Непал, Индия, Пакистан",
    "q.m21#1.o1" to "Китай, Непал, Бутан, Индия",
    "q.m21#1.o2" to "Непал, Пакистан, Афганистан, Таджикистан",
    "q.m21#1.o3" to "Китай, Индия, Пакистан, Мьянма",
    "q.m21#1.e" to "Четыре страны: Китай, Непал, Индия и Пакистан. Понимать это распределение важно: оно определяет разрешения, логистику, спасение и политический риск, и всё это часть планирования на 8 000 м.",
    "q.m21#2.p" to "Какова высота Эвереста?",
    "q.m21#2.o0" to "8 611 м",
    "q.m21#2.o1" to "8 848 м",
    "q.m21#2.o2" to "8 586 м",
    "q.m21#2.o3" to "8 516 м",
    "q.m21#2.e" to "8 848 м (совместная китайско-непальская съёмка 2020 года дала 8 848,86 м). Как высшая в мире, она имеет и самую развитую коммерческую инфраструктуру, — но зрелость означает зрелую логистику и маршруты, а не низкий риск: очередь, стоимость и сложность сохранения трезвой оценки тоже реальные опасности.",
    "q.m21#3.p" to "Каково место Аннапурны I в истории восьмитысячников?",
    "q.m21#3.o0" to "Покорена последней",
    "q.m21#3.o1" to "Первый восьмитысячник, на который поднялись",
    "q.m21#3.o2" to "Самая низкая смертность",
    "q.m21#3.o3" to "Самая простая для восхождения",
    "q.m21#3.e" to "Аннапурна I — 8 091 м, первое восхождение в 1950 году, первый восьмитысячник в истории человечества. Смертность на ней долго была одной из самых высоких. То, что её покорили первой, никак не связано с простотой.",
    "q.m21#4.p" to "Чем выделяется Шишапангма?",
    "q.m21#4.o0" to "Она в Непале",
    "q.m21#4.o1" to "Единственный восьмитысячник, целиком лежащий в Китае, и последний из четырнадцати по времени восхождения",
    "q.m21#4.o2" to "Она самая высокая",
    "q.m21#4.o3" to "Она самая простая",
    "q.m21#4.e" to "Шишапангма — 8 027 м в Тибете, единственный восьмитысячник, целиком находящийся в Китае; первое восхождение в 1964 году совершила китайская команда, и это последний из четырнадцати, на который поднялись.",
    "q.m21#5.p" to "Как связаны Лхоцзе и Эверест?",
    "q.m21#5.o0" to "Они далеко друг от друга",
    "q.m21#5.o1" to "Лхоцзе примыкает к Эвересту, и у них часто общий подход",
    "q.m21#5.o2" to "Лхоцзе выше Эвереста",
    "q.m21#5.o3" to "Они в разных хребтах",
    "q.m21#5.e" to "Лхоцзе — 8 516 м, прямо рядом с Эверестом, и с юга у них общая большая часть маршрута и лагерей. Поэтому их часто рассматривают в рамках одного плана по логистике и акклиматизации.",
    "q.m21#6.p" to "Как обычно оценивают Чо-Ойю?",
    "q.m21#6.o0" to "Самый техничный восьмитысячник",
    "q.m21#6.o1" to "Обычно считается одним из менее техничных восьмитысячников",
    "q.m21#6.o2" to "Восьмитысячник с самой высокой смертностью",
    "q.m21#6.o3" to "На неё не ходят коммерческие группы",
    "q.m21#6.e" to "Чо-Ойю — 8 188 м, и благодаря относительно пологому маршруту и зрелой логистике её часто относят к менее техничным восьмитысячникам. Но «относительно просто» всё равно означает дни в зоне смерти: масштаб недооценивать нельзя.",
    "q.m21#7.p" to "Чем известна Нанга-Парбат?",
    "q.m21#7.o0" to "Пологими маршрутами",
    "q.m21#7.o1" to "Огромным перепадом высоты и серьёзной лавинной опасностью",
    "q.m21#7.o2" to "Самые дешёвые разрешения",
    "q.m21#7.o3" to "Лучшая логистика",
    "q.m21#7.e" to "Нанга-Парбат — 8 126 м, известна как «Голая гора»: она поднимается на огромную высоту прямо из долины, с выраженной лавинной опасностью и камнепадом. Её историческая цена по числу жертв высока даже по меркам 8 000 м.",
    "q.m21#8.p" to "[Сопоставление] Соотнесите вершину с её высотой.",
    "q.m21#8.l0" to "Эверест",
    "q.m21#8.r0" to "8 848 м",
    "q.m21#8.l1" to "Канченджанга",
    "q.m21#8.r1" to "8 586 м",
    "q.m21#8.l2" to "Лхоцзе",
    "q.m21#8.r2" to "8 516 м",
    "q.m21#8.l3" to "Макалу",
    "q.m21#8.r3" to "8 485 м",
    "q.m21#8.e" to "Это первая, третья, четвёртая и пятая вершины мира. Не просто запоминайте числа — помните порядок и к какому хребту каждая относится. Числа можно посмотреть; общая картина должна быть в голове.",
    "q.m21#9.p" to "Почему «четырнадцать» стало признанной альпинистской целью?",
    "q.m21#9.o0" to "Потому что это круглая цифра",
    "q.m21#9.o1" to "Потому что они образуют законченную границу высотного альпинизма, а счёт в пределах одной жизни",
    "q.m21#9.o2" to "Потому что это продвигали коммерческие компании",
    "q.m21#9.o3" to "Потому что этого требует UIAA",
    "q.m21#9.e" to "Особенность четырнадцати в том, что у них есть объективная и однозначная граница (выше 8 000 м), конечный счёт и их можно перечислить поимённо. Это делает цель одновременно ясной и пожизненной, — поэтому она и стала эталоном.",
    "q.m21#10.p" to "[Множественный выбор] Что обычно требуется, чтобы взойти на восьмитысячник?",
    "q.m21#10.o0" to "Полный цикл акклиматизации с выходами в высотные лагеря",
    "q.m21#10.o1" to "Технические навыки и опыт движения по леднику",
    "q.m21#10.o2" to "Надёжная кислородная система и логистика",
    "q.m21#10.o3" to "Форма и оценка, проверенные на 7 000 м",
    "q.m21#10.o4" to "Профессиональная съёмочная группа",
    "q.m21#10.e" to "Четыре пункта соответствуют четырём измерениям: физиологическому (акклиматизация), техническому, логистическому и накопленному опыту. На 8 000 м они действуют одновременно, — отсутствие любого становится слабым звеном, а слабые звенья на высоте усиливаются быстро.",
    "q.m21#11.p" to "Дхаулагири, Манаслу и Аннапурна — в какой стране?",
    "q.m21#11.o0" to "Китай",
    "q.m21#11.o1" to "Непал",
    "q.m21#11.o2" to "Пакистан",
    "q.m21#11.o3" to "Индия",
    "q.m21#11.e" to "Все три в Непале. Непал владеет наибольшим числом восьмитысячников, поэтому его альпинистская индустрия так развита, — и поэтому же он постоянно испытывает давление по разрешениям, управлению и охране природы.",
    "q.m21#12.p" to "Почему «отработанные коммерческие маршруты» на восьмитысячниках всё равно опасны?",
    "q.m21#12.o0" to "Потому что они дорогие",
    "q.m21#12.o1" to "Потому что саму высоту изменить нельзя, а очередь, ожидание и трудное спасение создают новые риски",
    "q.m21#12.o2" to "Потому что гиды непрофессиональны",
    "q.m21#12.o3" to "Потому что снаряжение плохое",
    "q.m21#12.e" to "Коммерциализация решает логистику и знание маршрута, но не может понизить высоту. Наоборот, множество групп в одном окне создаёт очередь, — а ожидание на 8 000 м значит сжигание лишнего кислорода и тепла тела.",
    "q.m21#13.p" to "[Порядок] Расставьте вершины от высшей к низшей.",
    "q.m21#13.o0" to "Эверест (8 848)",
    "q.m21#13.o1" to "Канченджанга (8 586)",
    "q.m21#13.o2" to "Макалу (8 485)",
    "q.m21#13.o3" to "Аннапурна I (8 091)",
    "q.m21#13.e" to "За этим порядком стоит диапазон от первой вершины мира до десятой. Помнить порядок полезнее, чем точные цифры: обсуждая маршруты, логистику и сложность, вы обычно нуждаетесь в относительном положении.",
    "q.m21#14.p" to "Зачем изучать историю первых восхождений, знакомясь с восьмитысячниками?",
    "q.m21#14.o0" to "Для экзаменов",
    "q.m21#14.o1" to "Потому что первые восхождения обычно вскрывают главные трудности вершины и типы риска",
    "q.m21#14.o2" to "Чтобы запомнить имена",
    "q.m21#14.o3" to "Это не связано с альпинизмом",
    "q.m21#14.e" to "Неудачи и потери ранних команд указывают точно на главные трудности вершины — повторяющиеся лавинные участки, участки с сильным ветром, открытые отрезки маршрута. Читать историю первых восхождений как картотеку рисков гораздо полезнее, чем как рассказ.",
    "q.m21#15.p" to "[Множественный выбор] Что из этого — гималайские восьмитысячники?",
    "q.m21#15.o0" to "Эверест",
    "q.m21#15.o1" to "Аннапурна I",
    "q.m21#15.o2" to "Шишапангма",
    "q.m21#15.o3" to "К2",
    "q.m21#15.e" to "Первые три в Гималаях; К2 в Каракоруме. Эти хребты географически соседние, но геологически разные, и их сезоны и погодные схемы различаются, — поэтому четырнадцать часто обсуждают сгруппированными по хребтам.",
    "q.m21#16.p" to "Как титул «высшая вершина мира» влияет на стратегию?",
    "q.m21#16.o0" to "Никак",
    "q.m21#16.o1" to "Это наибольшее внимание медиа и коммерции, а значит наибольшая плотность групп и риск очереди",
    "q.m21#16.o2" to "Это значит самый простой маршрут",
    "q.m21#16.o3" to "Это значит самое простое спасение",
    "q.m21#16.e" to "Внимание приносит ресурсы и одновременно толпу. Когда множество групп сосредоточено в одном окне, ожидание, очередь и психологическое давление «не хочу уступать место в очереди» становятся дополнительными источниками риска, — стратегическая проблема, свойственная именно высшей вершине.",
    "q.m21#17.p" to "Заполните: в мире ( ) вершин выше 8 000 м.",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "четырнадцать",
    "q.m21#17.e" to "Четырнадцать. Немного, но это число задаёт всю границу высотного альпинизма, — поэтому «четырнадцать» до сих пор считают целью, достойной жизни.",
    "q.m22#0.p" to "Сколько восьмитысячников в Каракоруме?",
    "q.m22#0.o0" to "2",
    "q.m22#0.o1" to "4",
    "q.m22#0.o2" to "6",
    "q.m22#0.o3" to "10",
    "q.m22#0.e" to "Четыре: К2, Гашербрум I, Гашербрум II и Броуд-Пик. Их также называют K2, K4, K5 и K3, — буква K означает Каракорум.",
    "q.m22#1.p" to "Какова высота и репутация К2?",
    "q.m22#1.o0" to "8 611 м, вторая в мире, и среди самых техничных и смертоносных восьмитысячников",
    "q.m22#1.o1" to "8 848 м, высшая в мире",
    "q.m22#1.o2" to "8 586 м, третья в мире",
    "q.m22#1.o3" to "8 051 м, одна из простых",
    "q.m22#1.e" to "К2 — 8 611 м, вторая в мире. Её широко считают одной из самых тяжёлых и опасных вершин 8 000 м, поэтому и называют «горой альпинистов»: здесь техника и оценка весят гораздо больше, чем логистическая поддержка.",
    "q.m22#2.p" to "Почему у Каракорума и Гималаев часто разные сезоны восхождений?",
    "q.m22#2.o0" to "Из-за разных широт и долгот",
    "q.m22#2.o1" to "Потому что на них влияют разные климатические системы: на Каракорум сильнее влияет западный перенос",
    "q.m22#2.o2" to "Из-за разной высоты",
    "q.m22#2.o3" to "Из-за разных правил",
    "q.m22#2.e" to "Лучший сезон в Гималаях определяется в основном муссонным циклом, а на Каракорум сильнее влияют западный перенос и орографические осадки. Это решает, когда ехать, — а выберите неверный сезон, и даже лучшая группа не увидит окна на вершину.",
    "q.m22#3.p" to "Как ещё называют Броуд-Пик?",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "Броуд-Пик — это также K3, 8 051 м. Рельеф там относительно открытый, но снегопады обильны, а сильные ветры часты, — исторически на нём было немало происшествий после недооценки.",
    "q.m22#4.p" to "Как ещё называют Гашербрум I и II?",
    "q.m22#4.o0" to "K4 и K5",
    "q.m22#4.o1" to "K5 и K4",
    "q.m22#4.o2" to "K2 и K3",
    "q.m22#4.o3" to "K3 и K4",
    "q.m22#4.e" to "Гашербрум I — это K5 (8 080 м), а Гашербрум II — K4 (8 035 м): нумерация не следует порядку высот, что и путает. Запомните, что номера K не отсортированы по высоте, и не ошибётесь.",
    "q.m22#5.p" to "Все четырнадцать восьмитысячников находятся в каких двух хребтах?",
    "q.m22#5.o0" to "Гималаи и Тянь-Шань",
    "q.m22#5.o1" to "Гималаи и Каракорум",
    "q.m22#5.o2" to "Каракорум и Альпы",
    "q.m22#5.o3" to "Ньэнчентанглха и Гималаи",
    "q.m22#5.e" to "Все в Гималаях и Каракоруме, — географически соседних хребтах с разными климатическими системами. Что снова показывает: на 8 000 м сама география является ключевой информацией.",
    "q.m22#6.p" to "[Сопоставление] Соотнесите вершину с её высотой.",
    "q.m22#6.l0" to "К2",
    "q.m22#6.r0" to "8 611 м",
    "q.m22#6.l1" to "Нанга-Парбат",
    "q.m22#6.r1" to "8 126 м",
    "q.m22#6.l2" to "Гашербрум I",
    "q.m22#6.r2" to "8 080 м",
    "q.m22#6.l3" to "Шишапангма",
    "q.m22#6.r3" to "8 027 м",
    "q.m22#6.e" to "Это вторая, девятая, одиннадцатая и четырнадцатая вершины мира. Разброс широк, но статус внутри «выше 8 000 м» у них один, — в этом и особенность класса: ясная граница при огромной внутренней разнице.",
    "q.m22#7.p" to "Как правильно смотреть на связь рейтинга восьмитысячников и сложности?",
    "q.m22#7.o0" to "Выше всегда значит сложнее",
    "q.m22#7.o1" to "Сложность задают в основном технический рельеф, климат и логистика, и она не соответствует напрямую рейтингу высоты",
    "q.m22#7.o2" to "Ниже всегда значит проще",
    "q.m22#7.o3" to "Сложность вообще нельзя сравнить",
    "q.m22#7.e" to "Это главный вывод из панорамы четырнадцати: Чо-Ойю на 8 188 м считают относительно простой, а К2 на 8 611 м — среди самых тяжёлых: разница меньше 500 м, а реальный порог несопоставим.",
    "q.m22#8.p" to "[Множественный выбор] Что определяет реальную сложность восьмитысячника?",
    "q.m22#8.o0" to "Технический рельеф и открытость",
    "q.m22#8.o1" to "Климат и погодные окна",
    "q.m22#8.o2" to "Логистика и подход",
    "q.m22#8.o3" to "Возможность спасения",
    "q.m22#8.o4" to "Место вершины в рейтинге высоты",
    "q.m22#8.e" to "Все четыре важны. Особенно часто игнорируют возможность спасения: гора, где спасение почти невозможно, несёт совершенно другой уровень риска, даже если маршрут несложный, потому что при проблеме нет буфера.",
    "q.m22#9.p" to "[Порядок] Расставьте вершины от высшей к низшей.",
    "q.m22#9.o0" to "К2 (8 611)",
    "q.m22#9.o1" to "Нанга-Парбат (8 126)",
    "q.m22#9.o2" to "Гашербрум I (8 080)",
    "q.m22#9.o3" to "Шишапангма (8 027)",
    "q.m22#9.e" to "Этот порядок охватывает вторую половину четырнадцати. Вместе с порядком из прошлого урока у вас теперь полная последовательность высот, — а это основа для понимания, к какому уровню относится данная гора.",
    "q.m22#10.p" to "Почему «четырнадцать» — настолько требовательная цель?",
    "q.m22#10.o0" to "Потому что это крайне дорого",
    "q.m22#10.o1" to "Потому что нужно много лет поддерживать технику, форму, акклиматизацию и оценку, через логистические системы нескольких стран",
    "q.m22#10.o2" to "Потому что это занимает слишком много времени",
    "q.m22#10.o3" to "Потому что трудно получить разрешения",
    "q.m22#10.e" to "Четырнадцать часто занимают больше десяти лет, за которые тело стареет, а обстоятельства жизни меняются. Это проверка не только альпинистских способностей, но и постоянства долгосрочного поддержания формы и управления риском.",
    "q.m22#11.p" to "Почему успех на 8 000 м часто зависит от погодного окна, а не от техники?",
    "q.m22#11.o0" to "Потому что техника не важна",
    "q.m22#11.o1" to "Потому что даже при достаточной технике долгое ожидание на высоте съедает ваш запас безопасности",
    "q.m22#11.o2" to "Потому что технику можно выучить на горе",
    "q.m22#11.o3" to "Потому что гиды всё решают",
    "q.m22#11.e" to "Это реальность 8 000 м: техника — лишь входной билет, а окно решает, сможете ли вы пройти, пока у вас ещё есть ресурс. Поэтому в графиках на 8 000 м обычно закладывают щедрые резервные дни.",
    "q.m22#12.p" to "Если выбрать только один восьмитысячник как первый, какой подход разумнее?",
    "q.m22#12.o0" to "Сразу идти на К2 и закрыть тему",
    "q.m22#12.o1" to "Выбрать вершину с отработанным маршрутом, надёжной логистикой и возможным спасением и потратить «первый раз» на накопление опыта",
    "q.m22#12.o2" to "Просто выбрать самую низкую",
    "q.m22#12.o3" to "Выбрать любую, они все одинаковы",
    "q.m22#12.e" to "Ценность первого восьмитысячника — узнать своё реальное состояние в зоне смерти: как вы расходуете кислород, насколько падает оценка, каков ваш темп. Потратить это на более сложную гору значит проверять несколько неизвестных сразу.",
    "q.m22#13.p" to "[Множественный выбор] Что из этого — восьмитысячники Каракорума?",
    "q.m22#13.o0" to "К2",
    "q.m22#13.o1" to "Гашербрум I",
    "q.m22#13.o2" to "Гашербрум II",
    "q.m22#13.o3" to "Броуд-Пик",
    "q.m22#13.o4" to "Манаслу",
    "q.m22#13.e" to "Все четыре каракорумские, — фактически это все восьмитысячники этого хребта. Поэтому «каракорумская четвёрка» — устойчивое выражение, а вместе с гималайской десяткой получается ровно четырнадцать.",
    "q.m22#14.p" to "Какова самая практичная польза от изучения четырнадцати как целого?",
    "q.m22#14.o0" to "Уметь перечислить все высоты",
    "q.m22#14.o1" to "Понимать, почему сложность и высота — не одно и то же, и использовать это для оценки собственных целей",
    "q.m22#14.o2" to "Уметь быть гидом",
    "q.m22#14.o3" to "Уметь писать путеводители",
    "q.m22#14.e" to "Настоящая ценность — построить многомерный взгляд на сложность: техническое, климатическое, логистическое и спасательное измерения вместе определяют истинный порог горы. Та же схема применима при выборе среди вершин 5 000 и 6 000 м.",
    "q.m22#15.p" to "Почему подход к восьмитысячнику сам может быть фактором риска?",
    "q.m22#15.o0" to "Потому что он занимает много времени",
    "q.m22#15.o1" to "Потому что подход часто идёт по ледникам и лавинному рельефу, пока группа ещё не акклиматизирована",
    "q.m22#15.o2" to "Потому что пейзажи плохие",
    "q.m22#15.o3" to "Потому что нужны разрешения",
    "q.m22#15.e" to "Подход обычно приходится на фазу набора высоты, когда акклиматизация ещё слаба, а оценка наименее устойчива, и при этом нужно работать с трещинами и лавинным рельефом. Именно в этот дважды уязвимый период и происходит много происшествий.",
    "q.m22#16.p" to "Если вы составляете собственный список целей 8 000 м, что определить первым?",
    "q.m22#16.o0" to "Названия гор, которые хочется",
    "q.m22#16.o1" to "Свои слабые места (технику, акклиматизацию, оценку или опыт логистики), а затем подобрать вершины, которые их закрывают",
    "q.m22#16.o2" to "Бюджет",
    "q.m22#16.o3" to "Длину отпуска",
    "q.m22#16.e" to "Выбирать по слабым местам значит относиться к 8 000 м как к пути роста, а не как к набору достижений. Одна и та же гора значит разное для разных людей, в зависимости от того, какой из ваших пробелов она закрывает.",
    "q.m23#0.p" to "[Ситуация] Партнёр на 4 500 м с головной болью и тошнотой настаивает: «ещё один день акклиматизации, и я смогу идти наверх». С точки зрения науки о среде каково правильное суждение?",
    "q.m23#0.o0" to "Ещё один день точно поможет — поддержи его",
    "q.m23#0.o1" to "Симптомы означают, что компенсация недостаточна; не продолжать набор высоты, пока симптомы сохраняются",
    "q.m23#0.o2" to "Дать лекарство и продолжать подъём",
    "q.m23#0.o3" to "Достаточно спуститься на 100 м",
    "q.m23#0.e" to "Цепочка начинается с самой базовой причинности: низкое давление → низкое парциальное давление кислорода → телу нужно время. Симптомы — сигнал, что времени недостаточно, и ещё один день не гарантирует улучшения, — поэтому правильный шаг — прекратить подъём, а не ставить на завтра.",
    "q.m23#1.p" to "[Множественный выбор] Участник идёт на крутой снежный склон на 5 000 м. Что нужно подтвердить?",
    "q.m23#1.o0" to "Кошки строго подогнаны под ботинки",
    "q.m23#1.o1" to "Ледоруб под размер по росту",
    "q.m23#1.o2" to "Очки UV400 для ледника и солнцезащитный крем с высоким фактором",
    "q.m23#1.o3" to "Утепление и мембрана, соответствующие системе слоёв",
    "q.m23#1.o4" to "Камера и запасные батареи для фото на вершине",
    "q.m23#1.e" to "Четыре пункта соответствуют четырём типам риска: скольжение (кошки), задержание (ледоруб), УФ (очки и крем), переохлаждение (слои). Правильно проверять снаряжение, строя список от рисков, а не хватая предметы по привычке.",
    "q.m23#2.p" to "[Сопоставление] Соотнесите каждый слой системы одежды с его задачей.",
    "q.m23#2.l0" to "Базовый слой",
    "q.m23#2.r0" to "Отводит пот от кожи и сохраняет сухость",
    "q.m23#2.l1" to "Средний слой",
    "q.m23#2.r1" to "Удерживает слой воздуха для тепла (флис греет и влажным)",
    "q.m23#2.l2" to "Мембрана",
    "q.m23#2.r2" to "Не пропускает воду и ветер, дышит; защищает от непогоды",
    "q.m23#2.l3" to "Пуховый слой (в экстремальный холод)",
    "q.m23#2.r3" to "Самое эффективное тепло в сухой среде",
    "q.m23#2.e" to "Каждый слой делает одно дело. Увидев это разделение, вы поймёте, почему «больше слоёв — теплее» неверно: пропустите влагоотводящий слой, и вы несёте собственный влажный микроклимат, а недышащая мембрана запирает пар внутри.",
    "q.m23#3.p" to "[Ситуация] На подъёме по снежному склону идущий впереди выбивает неровные ступени. Каково наиболее вероятное последствие?",
    "q.m23#3.o0" to "Группа движется быстрее",
    "q.m23#3.o1" to "Идущие сзади вынуждены постоянно перебалансироваться, тратя больше сил и теряя устойчивость",
    "q.m23#3.o2" to "Склон обрушится",
    "q.m23#3.o3" to "Никакого эффекта",
    "q.m23#3.e" to "Ступени — фундамент группы. Неровные ступени заставляют всех постоянно искать опору, поверх и без того скудного на высоте запаса на баланс, — учебный пример того, как мелкие проблемы накапливаются в большой риск.",
    "q.m23#4.p" to "[Порядок] Расставьте последовательность самоудержания ледорубом по порядку.",
    "q.m23#4.o0" to "Взяться за ледоруб надёжно, проверив хват",
    "q.m23#4.o1" to "Перевернуться на живот лицом к снегу",
    "q.m23#4.o2" to "Вогнать клюв в снег, используя вес тела",
    "q.m23#4.o3" to "Поднять ноги, чтобы кошки не зацепились и не опрокинули вас",
    "q.m23#4.e" to "Эта последовательность — фундамент всей технической системы. Она должна выполняться не задумываясь: при реальном срыве у способности думать окно в одну-две секунды, и эти две секунды полностью заняты мышечной памятью.",
    "q.m23#5.p" to "[Ситуация] Альпинист срывается на крутом твёрдом снежном склоне, задержание не удалось. Какова наиболее вероятная причина при разборе?",
    "q.m23#5.o0" to "Ледоруб был слишком короткий",
    "q.m23#5.o1" to "Клюв не смог войти в твёрдый снег, — а крутой твёрдый склон следовало провесить перилами",
    "q.m23#5.o2" to "Ботинки были не те",
    "q.m23#5.o3" to "Они были без перчаток",
    "q.m23#5.e" to "Успешность задержания заметно падает на твёрдом снегу и льду; это предел самой техники. Поэтому настоящий вопрос обычно раньше: почему мы вообще были на крутом твёрдом склоне без страховочной системы?",
    "q.m23#6.p" to "[Множественный выбор] Какие риски легко упустить на спуске?",
    "q.m23#6.o0" to "Падение формы ослабляет контроль ног",
    "q.m23#6.o1" to "Внимание падает после достижения цели",
    "q.m23#6.o2" to "Снежная поверхность замерзает или размягчается, и условия отличаются от подъёма",
    "q.m23#6.o3" to "Свет уходит, снижая видимость и качество оценки",
    "q.m23#6.o4" to "Спусковые маршруты обычно короче подъёмных",
    "q.m23#6.e" to "Сложите эти четыре — и получите объяснение, почему так много происшествий случается на спуске. Спуск — не дорога домой после сделанной работы, а отрезок, требующий собственного плана и несущий сопоставимый риск.",
    "q.m23#7.p" to "[Ситуация] Клапан питьевой трубки быстро замерзает на холоде. Что делать?",
    "q.m23#7.o0" to "Перейти на широкогорлую термофлягу и после каждого глотка сдувать воду обратно или переворачивать флягу",
    "q.m23#7.o1" to "Продолжать пользоваться и ждать, пока оттает",
    "q.m23#7.o2" to "Нести гидратор снаружи рюкзака",
    "q.m23#7.o3" to "Перестать пить",
    "q.m23#7.e" to "Мелочь, но критичная: обезвоживание на высоте обычно происходит не от «не взял воды», а от «вода замёрзла, и я не смог её пить». Спроектировать незамерзающую систему питья и значит действительно быть готовым пить.",
    "q.m23#8.p" to "Заполните: температура падает примерно на ( ) °C на каждые 1 000 м подъёма.",
    "q.m23#8.a0" to "6,5",
    "q.m23#8.a1" to "шесть целых пять десятых",
    "q.m23#8.e" to "6,5 °C. Это число проходит через весь курс: оно объясняет снеговую линию, задаёт нужную толщину утепления и определяет, как меняются лавинные и ледовые условия. Понимать его значит уметь им рассуждать.",
    "q.m23#9.p" to "[Ситуация] На 5 000 м очки сильно запотевают, и вы больше не читаете рельеф. Каков главный риск?",
    "q.m23#9.o0" to "Это просто неудобно",
    "q.m23#9.o1" to "Вы теряете основу для оценки рельефа и можете выйти на крутой склон, карниз или поле трещин",
    "q.m23#9.o2" to "Вы получите снежную слепоту",
    "q.m23#9.o3" to "Партнёры будут ворчать",
    "q.m23#9.e" to "«Не вижу» на деле означает потерю свидетельств, по которым вы судите. На сложном снежном рельефе одна-две неверные точки опоры могут стоить очень дорого. Поэтому «вижу ли я ясно» нужно считать жёстким критерием надёжности снаряжения.",
    "q.m23#10.p" to "[Множественный выбор] У участника сильная потеря аппетита на высоте. Что делать?",
    "q.m23#10.o0" to "Есть активно, понемногу и часто, выбирая углеводную и легко усваиваемую еду",
    "q.m23#10.o1" to "Обеспечить ровное, достаточное питьё",
    "q.m23#10.o2" to "Считать потерю аппетита возможным сигналом акклиматизации и наблюдать",
    "q.m23#10.o3" to "Заменять еду большим количеством кофе и энергетиков",
    "q.m23#10.e" to "Первые три верны; четвёртое неверно очень характерным образом: кофеин даёт временное ощущение, но не заменяет энергию. На высоте недостаток энергии напрямую ослабляет акклиматизацию, создавая замкнутый круг.",
    "q.m23#11.p" to "[Ситуация] На снежном склоне на 5 000 м телефон прыгает с 40 % сразу к выключению. Каков наиболее разумный ответ?",
    "q.m23#11.o0" to "Согреть у тела и включить снова",
    "q.m23#11.o1" to "Включать его повторно снова и снова",
    "q.m23#11.o2" to "Отказаться от электроники",
    "q.m23#11.o3" to "Использовать остаток заряда, чтобы отправить сигнал бедствия",
    "q.m23#11.e" to "Это типичное поведение литиевой батареи на холоде: ёмкость обваливается, хотя заряд не исчез. Согревание у тела обычно возвращает питание. Урок: обращаться с электроникой как со снаряжением безопасности, которое может отказать без предупреждения.",
    "q.m23#12.p" to "[Порядок] Расставьте полную проверку снаряжения в разумном порядке.",
    "q.m23#12.o0" to "Построить список от рисков (что требует каждый рельеф, погода и высота)",
    "q.m23#12.o1" to "Проверить каждый предмет на комплектность и рабочее состояние",
    "q.m23#12.o2" to "Надеть и опробовать в работе критичные предметы (кошки, обвязка, каска, налобный фонарь)",
    "q.m23#12.o3" to "Записать и сообщить партнёрам состояние снаряжения и запасной план",
    "q.m23#12.e" to "Ключевой — третий шаг, опробование: комплектность не значит работоспособность. Не до конца застёгнутая скоба кошки или старая батарея в налобном фонаре проявятся только когда вы их наденете и включите.",
    "q.m23#13.p" to "[Ситуация] Группа решает спускаться из-за погоды, но один участник настаивает на продолжении: «мы так далеко зашли». Как поступить лучше?",
    "q.m23#13.o0" to "Уважать его выбор и отпустить одного",
    "q.m23#13.o1" to "Настоять, чтобы спускалась вся группа: одиночное движение на высоте недопустимо, а упрямство там само может быть гипоксией",
    "q.m23#13.o2" to "Проголосовать",
    "q.m23#13.o3" to "Пусть подождут час и потом решат",
    "q.m23#13.e" to "Две причины: одиночное движение на высоте крайне рискованно, а «мы так далеко зашли» — учебная формулировка вложенных усилий; на высоте эта эмоция и падающая оценка обычно сплетены, поэтому её нельзя считать надёжным вкладом в решение.",
    "q.m23#14.p" to "Верно ли, что более тренированные чаще болеют высотной болезнью?",
    "q.m23#14.o0" to "Чем лучше форма, тем ниже вероятность",
    "q.m23#14.o1" to "Высотная болезнь напрямую не связана с формой; она связана со скоростью подъёма, высотой ночёвок и индивидуальной реакцией",
    "q.m23#14.o2" to "Чем лучше форма, тем выше вероятность",
    "q.m23#14.o3" to "Болеют только нетренированные",
    "q.m23#14.e" to "Путать форму с акклиматизацией — самая частая ошибка новичка. На деле тренированные могут попадать в большую беду именно потому, что идут быстрее и забираются выше, — вполне реальная ловушка.",
    "q.m23#15.p" to "[Множественный выбор] Какие практики действительно снижают риск падения?",
    "q.m23#15.o0" to "Постоянно использовать ледоруб для самостраховки в движении",
    "q.m23#15.o1" to "Держать устойчивый, посильный темп без рывков",
    "q.m23#15.o2" to "Идти со скоростью самого медленного участника",
    "q.m23#15.o3" to "Вешать перила на твёрдых снежных и ледовых склонах",
    "q.m23#15.o4" to "На спуске меньше тормозить и двигаться быстрее",
    "q.m23#15.e" to "Четыре пункта соответствуют личной технике, контролю темпа, слаженности группы и системной страховке. Профилактика падений никогда не одно действие, а целый слой страховки на страховке.",
    "q.m23#16.p" to "[Ситуация] На отдыхе на снежном склоне участник оставляет ледоруб воткнутым в снег и отходит. Какой риск это создаёт?",
    "q.m23#16.o0" to "Ледоруб может потеряться",
    "q.m23#16.o1" to "При падении у него вообще не будет инструмента для задержания",
    "q.m23#16.o2" to "Кто-то может на него наступить",
    "q.m23#16.o3" to "Риска нет",
    "q.m23#16.e" to "Падения происходят крайне быстро, а ледоруб — единственное средство задержания. Оставить его в снегу значит временно отказаться от этой способности, — а на снежном склоне «временно» и есть самый опасный интервал.",
    "q.m23#17.p" to "Какую ключевую способность проверяет этот урок?",
    "q.m23#17.o0" to "Запоминание всех цифр",
    "q.m23#17.o1" to "Умение соединить знания о среде, снаряжении, одежде и движении, чтобы правильно оценить конкретную ситуацию",
    "q.m23#17.o2" to "Заучивание всей терминологии",
    "q.m23#17.o3" to "Хорошее знание марок снаряжения",
    "q.m23#17.e" to "Это логика построения всего курса: отдельные факты легко запомнить, но в горах вы сталкиваетесь с комбинированными задачами. Умение связать несколько знаний в конкретной ситуации и есть настоящее владение материалом.",
    "q.m24#0.p" to "[Ситуация] Партнёр провалился в трещину, и его вес держит только ваше тело. Что первым делом?",
    "q.m24#0.o0" to "Сразу начать вытаскивать",
    "q.m24#0.o1" to "Сначала построить станцию и перенести нагрузку, потом думать о вытаскивании",
    "q.m24#0.o2" to "Сначала вызвать помощь",
    "q.m24#0.o3" to "Сделать фотографию для отчёта",
    "q.m24#0.e" to "Пока вес на вас, у вас нет ресурса работать с системой. Значит: станция, затем перенос, затем вытаскивание, — порядок нельзя менять. Это самое практичное правило всей спасательной системы и шаг, который чаще всего пропускают под стрессом.",
    "q.m24#1.p" to "[Сопоставление] Соотнесите узел с его применением.",
    "q.m24#1.l0" to "Восьмёрка",
    "q.m24#1.r0" to "Соединение обвязки с точкой страховки",
    "q.m24#1.l1" to "Двойной рыбацкий узел",
    "q.m24#1.r1" to "Соединение двух верёвок или замыкание петли из шнура",
    "q.m24#1.l2" to "Прусик",
    "q.m24#1.r2" to "Схватывающий узел, держит в одном направлении",
    "q.m24#1.l3" to "Булинь",
    "q.m24#1.r3" to "Крепление к точке страховки; распространён на флоте",
    "q.m24#1.e" to "Эти четыре покрывают почти всё ледниковое передвижение и базовую страховку. Смысл проверки в том, что вязать их придётся в темноте и в перчатках.",
    "q.m24#2.p" to "[Ситуация] Угол стропы между двумя точками страховки близок к 100°. Что это значит?",
    "q.m24#2.o0" to "Нагрузка распределяется равномернее",
    "q.m24#2.o1" to "Нагрузка на каждую точку заметно растёт (чем шире угол, тем больше нагрузка на точку)",
    "q.m24#2.o2" to "Никакого эффекта",
    "q.m24#2.o3" to "Верёвка сама балансируется",
    "q.m24#2.e" to "Цифры наглядны: около 50 % на точку при 0°, около 58 % при 60°, около 71 % при 90°. При 100° каждая точка несёт много, — поэтому на практике угол держат в пределах 60°.",
    "q.m24#3.p" to "[Множественный выбор] Что должно быть у достаточной станции?",
    "q.m24#3.o0" to "Каждая отдельная точка прочна",
    "q.m24#3.o1" to "Независимый отказ точек (без ложного резервирования)",
    "q.m24#3.o2" to "Разумное распределение нагрузки, с предварительным натяжением",
    "q.m24#3.o3" to "Быстрая сборка, чтобы сократить время под риском",
    "q.m24#3.o4" to "Как можно меньше точек, чтобы сэкономить снаряжение",
    "q.m24#3.e" to "Первые три — требования безопасности, четвёртое — требование эффективности, а эффективность тоже безопасность, потому что сама сборка есть время под риском.",
    "q.m24#4.p" to "[Ситуация] Партнёр теряет устойчивость при ходьбе и становится спутанным. Что в приоритете?",
    "q.m24#4.o0" to "Дать кислород и наблюдать",
    "q.m24#4.o1" to "Немедленно спускаться и дать дексаметазон под медицинским контролем",
    "q.m24#4.o2" to "Продолжать подъём, чтобы быстрее дойти до лагеря",
    "q.m24#4.o3" to "Дать обезболивающее и отдохнуть",
    "q.m24#4.e" to "Атаксия и изменённое сознание — ключевые признаки HACE, неотложного состояния. Спуск — единственное надёжное лечение; дексаметазон лишь выигрывает время для спуска, — это не альтернативы.",
    "q.m24#5.p" to "[Множественный выбор] Какие утверждения о высотных лекарствах верны?",
    "q.m24#5.o0" to "Дексаметазон не влияет на акклиматизацию и не лечит отёк лёгких",
    "q.m24#5.o1" to "Ацетазоламид ускоряет акклиматизацию; начинать за день до подъёма и заканчивать примерно через два дня после",
    "q.m24#5.o2" to "Нифедипин может вызвать быстрое падение давления",
    "q.m24#5.o3" to "Лекарства не могут заменить спуск",
    "q.m24#5.o4" to "Ацетазоламид может заменить собственную акклиматизацию организма",
    "q.m24#5.e" to "Все четыре — ключевые пункты, и общий вывод у них один: лекарства не заменяют спуск, что бы ни было принято, основным лечением остаётся спуск. Препараты лишь создают для него условия.",
    "q.m24#6.p" to "[Ситуация] На холоде участник перестал дрожать и говорит невнятно. Чего делать НЕЛЬЗЯ?",
    "q.m24#6.o0" to "Сменить мокрую одежду и утеплить",
    "q.m24#6.o1" to "Заставить его ходить, чтобы согреться",
    "q.m24#6.o2" to "Сначала согревать туловище",
    "q.m24#6.o3" to "Избегать грубого обращения",
    "q.m24#6.e" to "«Перестал дрожать» означает среднее переохлаждение или тяжелее, а охлаждённое сердце очень склонно к аритмии. Заставлять пациента идти или грубо с ним обращаться может её спровоцировать напрямую, — самое контринтуитивное правило первой помощи при переохлаждении.",
    "q.m24#7.p" to "[Порядок] Расставьте четыре шага спасения в связке по порядку.",
    "q.m24#7.o0" to "Занять задержание и стабилизироваться",
    "q.m24#7.o1" to "Построить независимую станцию",
    "q.m24#7.o2" to "Перенести нагрузку на станцию",
    "q.m24#7.o3" to "Вытаскивать системой 3:1",
    "q.m24#7.e" to "Эти четыре нельзя переставлять. На экзамене вы, возможно, их перечислите; в реальности первые три нужно уложить в десятки секунд, — вот это и есть настоящий порог этого знания.",
    "q.m24#8.p" to "[Ситуация] В прогнозе «облачно», но вы видите быстро растущие вертикально кучевые. Что делать?",
    "q.m24#8.o0" to "Довериться прогнозу и идти по плану",
    "q.m24#8.o1" to "Решать исходя из возможного ухудшения и рассмотреть ранний спуск",
    "q.m24#8.o2" to "Подождать час и посмотреть снова",
    "q.m24#8.o3" to "Продолжать подъём, но быстрее",
    "q.m24#8.e" to "Прогноз даёт региональный фон; облако перед вами — свидетельство здесь и сейчас. Когда они расходятся, побеждает земля. Тем более что развитие кучевых на высоте часто измеряется минутами.",
    "q.m24#9.p" to "[Множественный выбор] Какие правила верны при пересечении лавинного рельефа?",
    "q.m24#9.o0" to "Пересекать по одному, держа интервал",
    "q.m24#9.o1" to "Поставить наблюдателя в безопасном месте",
    "q.m24#9.o2" to "Заранее спланировать путь отхода и место встречи",
    "q.m24#9.o3" to "Провести всю группу быстро вместе, чтобы сократить время под риском",
    "q.m24#9.e" to "Первые три ограничивают риск одним человеком; «все сразу» усиливает его до группового, — с возможного засыпания одного до возможного засыпания всех, поэтому это наименее приемлемый вариант.",
    "q.m24#10.p" to "[Ситуация] До вершины час, но время поворота уже прошло. Как правильно?",
    "q.m24#10.o0" to "Идти на вершину, ведь всего час",
    "q.m24#10.o1" to "Немедленно повернуть: смысл времени поворота именно в том, что оно работает в момент «ещё чуть-чуть»",
    "q.m24#10.o2" to "Продлить на полчаса",
    "q.m24#10.o3" to "Пусть идёт самый сильный",
    "q.m24#10.e" to "Этот вопрос проверяет, для чего вообще нужно время поворота. Если его соблюдают только когда легко, а на «ещё чуть-чуть» можно ослабить, значит его никогда не было, — и именно там и происходят аварии.",
    "q.m24#11.p" to "[Множественный выбор] Какие практики принятия решений в группе верны в среде высокого риска?",
    "q.m24#11.o0" to "Оцифровать сигналы отступления до выхода",
    "q.m24#11.o1" to "Побеждает самое консервативное мнение",
    "q.m24#11.o2" to "Намеренно приглашать возражения (например, обходить каждого)",
    "q.m24#11.o3" to "Решение большинством",
    "q.m24#11.e" to "Первые три вместе образуют механизм против коллективной ошибки; правило большинства делает наоборот, — оно подавляет обоснованное беспокойство меньшинства, а часто именно это меньшинство первым заметило сигнал опасности.",
    "q.m24#12.p" to "[Ситуация] Связи нет, а контрольный выход на связь с теми, кто дома, был час назад. Что делать?",
    "q.m24#12.o0" to "Продолжать по плану и ждать, пока вернётся сигнал",
    "q.m24#12.o1" to "Следовать плану на случай потери связи, согласованному до выхода (например, ждать в условленном месте)",
    "q.m24#12.o2" to "Разделиться и искать сигнал",
    "q.m24#12.o3" to "Всем немедленно спускаться",
    "q.m24#12.e" to "Потеря связи в горах — норма, а не происшествие, поэтому для неё нужен план до выхода. С планом потеря связи — известная ветка; без плана она превращается в неразбериху на месте.",
    "q.m24#13.p" to "[Порядок] Расставьте полную последовательность действий при тяжёлой травме.",
    "q.m24#13.o0" to "Обезопасить место и не допустить второго происшествия",
    "q.m24#13.o1" to "Оценить сознание, дыхание и кровообращение; устранить угрозы жизни",
    "q.m24#13.o2" to "Вызвать помощь и сообщить точное место и травмы",
    "q.m24#13.o3" to "Утеплить, иммобилизовать и наблюдать, ожидая эвакуации или профессионального спасения",
    "q.m24#13.e" to "Порядок воплощает принцип «сначала безопасность, затем помощь», при этом вызов идёт параллельно, а поддержание — после. Самая частая ошибка на практике — пропустить первый шаг и броситься прямо к пострадавшему: классический путь к появлению второго пострадавшего.",
    "q.m24#14.p" to "[Множественный выбор] Какие навыки технического альпинизма нужно отрабатывать на рельефе?",
    "q.m24#14.o0" to "Самоудержание ледорубом",
    "q.m24#14.o1" to "Прусик и системы связки",
    "q.m24#14.o2" to "Построение станций",
    "q.m24#14.o3" to "Последовательность спасения из трещины",
    "q.m24#14.o4" to "Запоминание названий и высот четырнадцати восьмитысячников",
    "q.m24#14.e" to "Ни один из четырёх нельзя освоить чтением. Общее у них: их выполняют под давлением, они почти не оставляют права на ошибку и зависят от мышечной памяти. Поэтому приложение снова и снова отмечает, что они требуют оценки инструктора.",
    "q.m24#15.p" to "[Ситуация] Вы прошли все теоретические проверки. Как теперь оценивать свои возможности?",
    "q.m24#15.o0" to "Теперь вы способны самостоятельно идти на 8 000 м",
    "q.m24#15.o1" to "У вас есть теоретическая база и рамка оценки, но каждый технический навык ещё требует оценки инструктора на рельефе",
    "q.m24#15.o2" to "Вы можете работать гидом",
    "q.m24#15.o3" to "Сданная теория значит, что способность есть",
    "q.m24#15.e" to "Это важнейшее утверждение всего курса: понимание теории не есть умение на рельефе. Приложение строит мыслительную рамку и рамку оценки; а спасает на ледовой стене то движение, которое вы повторили несколько сотен раз на безопасном рельефе.",
    "q.m24#16.p" to "После прохождения всего курса какой главный ресурс вы построили?",
    "q.m24#16.o0" to "Список снаряжения",
    "q.m24#16.o1" to "Мыслительную рамку: распознать риск, оценить риск, решить, — включая понимание, когда не нужно продолжать",
    "q.m24#16.o2" to "Альпинистский сертификат",
    "q.m24#16.o3" to "Набор фактов",
    "q.m24#16.e" to "От базовых 5 000 м до финальной проверки на 8 000 м курс повторяет одно: безопасность — продукт не техники, а оценки, и техника существует, чтобы дать оценке место.",
    "q.m24#17.p" to "Заполните: при решении в условиях неопределённости первым принимают самое ( ) мнение.",
    "q.m24#17.a0" to "консервативное",
    "q.m24#17.e" to "«Сначала консервативное» — завершающий принцип всего курса: достаточно простой, чтобы применять на месте, и достаточно сильный, чтобы противопоставить большинству когнитивных искажений. Гора всегда остаётся; вы — нет.",
    "q.m25#0.p" to "После подъёма вы чувствуете давление в голове и нехватку дыхания, а группа продолжает набор высоты по плану. Что делать?",
    "q.m25#0.o0" to "Терпеть — вы так далеко зашли",
    "q.m25#0.o1" to "Остановиться и честно сказать гиду или партнёрам, затем отдохнуть и понаблюдать",
    "q.m25#0.o2" to "Принять что-нибудь самому и держаться вместе с группой",
    "q.m25#0.o3" to "Ускориться: быстрее дойдёте до лагеря — быстрее пройдёт",
    "q.m25#0.e" to "На высоте есть две вещи, которых нельзя делать с сигналами тела: скрывать их и лечиться самому. Правильный первый шаг — честно сказать, как вы себя чувствуете, затем остановиться, отдохнуть и наблюдать.\nЭто не слабость: гид может судить, только когда знает, а вам нужен период наблюдения, чтобы понять, ослабевает или усиливается.",
    "q.m25#1.p" to "Почему фраза «мы так далеко зашли» опасна в высотной поездке?",
    "q.m25#1.o0" to "Потому что она тратит время",
    "q.m25#1.o1" to "Потому что она превращает уже вложенное время в повод продолжать рисковать",
    "q.m25#1.o2" to "Потому что она влияет на атмосферу в группе",
    "q.m25#1.o3" to "Потому что звучит непрофессионально",
    "q.m25#1.e" to "Это учебное мышление вложенных усилий: мы столько прошли, столько потратили, столько отпуска взяли, — значит не может быть зря.\nНо риск не падает от того, сколько вы вложили. Потраченное не вернуть, а цена продолжения может оказаться новыми невозвратными потерями.",
    "q.m25#2.p" to "Вы понимаете, что явно не держите темп группы и всё это время себя заставляли. Как лучше поступить?",
    "q.m25#2.o0" to "Стиснуть зубы и держаться, чтобы не подвести других",
    "q.m25#2.o1" to "Честно сказать и попросить группу идти со скоростью самого медленного",
    "q.m25#2.o2" to "Тихо замедлиться и делать вид, что всё в порядке",
    "q.m25#2.o3" to "Никому не говорить и спуститься одному",
    "q.m25#2.e" to "Форсировать темп на высоте — скрытый овердрафт: немедленная цена лишь усталость, но она накапливается в срыв на следующий день. А группа, идущая со скоростью самого быстрого, тянет всех на грань.\nПравильный шаг — задать темп по тому, что устойчиво выдерживает самый медленный, — это защищает и человека, и группу.",
    "q.m25#3.p" to "Партнёр говорит, что ему немного не по себе, но настаивает: «всё нормально, я могу идти». Что делать?",
    "q.m25#3.o0" to "Довериться его суждению и идти дальше",
    "q.m25#3.o1" to "Отнестись серьёзно и сказать гиду",
    "q.m25#3.o2" to "Не вмешиваться, пусть решает сам",
    "q.m25#3.o3" to "Не принимать всерьёз — многие так говорят",
    "q.m25#3.e" to "У недомогания на высоте жестокая особенность: оценка страдает первой, поэтому «я думаю, что всё нормально» там не считается.\nСообщить гиду о состоянии партнёра — ответственный поступок: если это действительно ничего, цена — одна лишняя проверка; если нет, вы можете оказаться единственным, кто заметил вовремя.",
    "q.m25#4.p" to "Перед выходом гид говорит, что завтрашний участок нужно проходить в связке. Кто-то считает: «такой пологий склон не требует верёвки». Как правильно понимать?",
    "q.m25#4.o0" to "Пологий склон действительно не требует верёвки",
    "q.m25#4.o1" to "Решение о связке принимает гид: у него информация о рельефе и снежном покрове",
    "q.m25#4.o2" to "Связка нужна в основном для аккуратного вида",
    "q.m25#4.o3" to "Решать должен самый сильный",
    "q.m25#4.e" to "Видеть «полого» издалека и стоять там, глядя на распределение трещин, снежных мостов и скрытых разрывов, — две разные вещи. У гида есть информация, которой нет у вас, — в этом и его ценность.\nВ технических решениях отдавать суждение тому, у кого больше информации, — базовое правило и эффективности, и безопасности.",
    "q.m25#5.p" to "Идя в середине группы, вы обнаруживаете, что вода закончилась, а до следующей точки пополнения два часа. Что делать?",
    "q.m25#5.o0" to "Молчать и никого не беспокоить",
    "q.m25#5.o1" to "Немедленно сказать руководителю и посмотреть, можно ли это урегулировать",
    "q.m25#5.o2" to "Попросить воды у ближайшего партнёра, но руководителю не говорить",
    "q.m25#5.o3" to "Меньше пить и идти дальше",
    "q.m25#5.e" to "Нехватка воды или еды — информация группового уровня, а не личная мелочь: она формирует суждение руководителя о темпе и пополнении.\nПопросить у партнёра втихую выглядит как «не поднимать шум», но обрывает информацию: руководитель по-прежнему считает, что группа в порядке, и может вести дальше по плану.",
    "q.m25#6.p" to "Что на высоте реально означает «медленно — значит быстро»?",
    "q.m25#6.o0" to "Медленная ходьба гарантирует вершину",
    "q.m25#6.o1" to "Устойчивый посильный темп экономит больше времени и безопаснее, чем повторяющиеся рывки",
    "q.m25#6.o2" to "Медленно — чтобы подстроиться под слабых",
    "q.m25#6.o3" to "На высоте скорость не имеет значения",
    "q.m25#6.e" to "На высоте поставка кислорода ограничена, а повторяющиеся взрывные усилия быстро накапливают лактат и ухудшают гипоксию.\nРовный темп на деле быстрее: он снимает необходимость частых остановок на восстановление и снижает шанс, что перерасход заставит повернуть. Фраза описывает энергетический обмен, а не утешение.",
    "q.m25#7.p" to "Вы доходите до лагеря на два часа позже плана, уже темно. Что делать?",
    "q.m25#7.o0" to "Идти ночью дальше до следующего лагеря",
    "q.m25#7.o1" to "Встать лагерем там, где вы есть, и сообщить домой своё положение",
    "q.m25#7.o2" to "Одному вернуться искать отставших",
    "q.m25#7.o3" to "Идти, пока не догоните группу впереди",
    "q.m25#7.e" to "Ночное движение на высоте сочетает худшие факторы: темноту, усталость, холод и невозможность читать рельеф. Встать лагерем на месте — разумный выбор.\nНо к этому нужно добавить одно: сообщить внешнему миру своё положение. Тогда, если понадобится спасение, хотя бы кто-то знает, где искать. Действовать в одиночку, наоборот, теряет для группы сразу двух человек.",
    "q.m25#8.p" to "По пути партнёру явно становится плохо, и он всё время замедляется. Группа разделилась во мнениях: ждать или отправить часть вперёд. Как разумнее?",
    "q.m25#8.o0" to "Вся группа идёт в прежнем темпе",
    "q.m25#8.o1" to "Никогда не разделяться; вся группа замедляется",
    "q.m25#8.o2" to "Выделить одного опытного сопровождать его, остальные идут дальше и держат связь",
    "q.m25#8.o3" to "Пусть идёт медленно один и встретимся в лагере",
    "q.m25#8.e" to "Разделение несёт свой риск на высоте, но при достаточном числе людей выделить самого опытного сопровождать медленного, а остальным идти дальше часто разумнее, чем и замедлять всех, и заставлять всех.\nТри вещи обязательны: кто-то остаётся с ним, связь поддерживается, а идущая вперёд группа знает ситуацию и ожидаемое время прихода. Остаться совсем одному — худший вариант.",
    "q.m25#9.p" to "Как правильно понимать место вершины во всей поездке?",
    "q.m25#9.o0" to "Вершина — это конец поездки",
    "q.m25#9.o1" to "Вершина — только половина поездки; риск концентрируется на спуске",
    "q.m25#9.o2" to "Важна только вершина",
    "q.m25#9.o3" to "Без вершины поездка провалена",
    "q.m25#9.e" to "Много происшествий случается на спуске, потому что после достижения цели внимание падает, а форма уже на пределе.\nСчитать вершину «половиной» значит заложить в план равные время, силы и страховку на спуск, — а не потратить всё на подъём.",
    "q.m25#10.p" to "Ситуация: первые 24 часа на высоте",
    "q.m25#10.c" to "Это ваша первая треккинговая вершина 5 000 м. После прихода в лагерь на 4 300 м за следующие 24 часа происходит несколько вещей.",
    "q.m25#10.e" to "Смысл этих четырёх шагов не в медицинских знаниях, а в двух привычках: говорить честно и переоценивать. В высотную опасность людей заталкивает не одно плохое решение, а цепочка мелких выборов — потерплю, не буду мешать, — которые складываются.",
    "q.m25#10.s0.p" to "Шаг 1: вечером у вас болит голова и пропадает аппетит. Партнёр говорит: «это нормально, поспи и пройдёт». Что делать?",
    "q.m25#10.s0.o0" to "Сделать как говорят и поспать",
    "q.m25#10.s0.o1" to "Честно сказать гиду, как вы себя чувствуете, затем по указаниям отдыхать, есть и пить понемногу и часто",
    "q.m25#10.s0.o2" to "Найти себе лекарство и никому не говорить",
    "q.m25#10.s0.o3" to "Выпить, чтобы лучше спалось",
    "q.m25#10.s0.e" to "Головная боль и потеря аппетита на высоте обычны, но обычное не значит то, что можно игнорировать. Честное сообщение плюс базовые меры — отдых, питьё, немного еды — стандартный ответ.\nКлючевое: гид должен узнать об изменении вашего состояния в тот момент, а не обнаружить его утром.",
    "q.m25#10.s1.p" to "Шаг 2: вы почти не спите всю ночь. Утром группа готовится идти дальше. Что выберете?",
    "q.m25#10.s1.o0" to "Ничего не говорить и просто идти следом",
    "q.m25#10.s1.o1" to "Сообщить, как прошла ночь, и дать гиду оценить, продолжать ли",
    "q.m25#10.s1.o2" to "Самому решить остаться, не сказав группе",
    "q.m25#10.s1.o3" to "Попросить всю группу остановиться и ждать вашего восстановления",
    "q.m25#10.s1.e" to "Плохой сон — одна из самых частых высотных жалоб; сам по себе он обычно не требует прекращать подъём, но он должен попасть в оценку, а не остаться молча.\nГид взвесит его вместе с головной болью, аппетитом и тем, как вы идёте. В этом и ценность его опыта.",
    "q.m25#10.s2.p" to "Шаг 3: группа идёт дальше, вам немного лучше, чем вчера, но вы идёте медленно. Какое настроение сейчас опаснее всего?",
    "q.m25#10.s2.o0" to "Беспокойство, что засмеют",
    "q.m25#10.s2.o1" to "Чувство «не может быть зря» — из-за него трудно остановиться, когда нужно",
    "q.m25#10.s2.o2" to "Желание фотографировать",
    "q.m25#10.s2.o3" to "Тревога о погоде",
    "q.m25#10.s2.e" to "Вложенные усилия ярче всего вспыхивают на второй день: вы промучились всю ночь, и сдаться теперь значит сделать эти мучения бессмысленными.\nТакая логика превращает уже уплаченную цену в повод продолжать, а не в сигнал переоценить.",
    "q.m25#10.s3.p" to "Шаг 4: в итоге вы не выходите на вершину — поворачиваете за час до неё. Как смотреть на эту поездку?",
    "q.m25#10.s3.o0" to "Провал; больше сюда не стоит",
    "q.m25#10.s3.o1" to "Полезный опыт акклиматизации; поворот был решением, а не провалом",
    "q.m25#10.s3.o2" to "Виноваты партнёры, они вас тормозили",
    "q.m25#10.s3.o3" to "В следующий раз выйти на вершину любой ценой",
    "q.m25#10.s3.e" to "Акклиматизация строится повторным пребыванием на высоте; первая поездка на 4 000–5 000 м никогда не должна была иметь вершину единственной целью.\nА способность повернуть, когда это правильно, в этом виде спорта ценнее всего. Она заведёт вас дальше, чем когда-либо случайная вершина.",
    "q.m25#11.p" to "Ситуация: давление группы",
    "q.m25#11.c" to "Четвёртый день поездки; погода начинает портиться, группа разделилась. Ваше собственное суждение несколько расходится с групповым.",
    "q.m25#11.e" to "Эта ситуация про то, чтобы озвучить сомнение. На практике это трудно, потому что цена выглядит социальной — испортить настроение, не вписаться, — а польза невидима: происшествие, которого не случилось. Запомните эти три пункта, и в следующий раз вы заговорите раньше.",
    "q.m25#11.s0.p" to "Шаг 1: одни говорят «пойдём, завтра погода может быть лучше», другие хотят спускаться. Вы склоняетесь к спуску, но не хотите быть тем, кто всё испортит. Что делать?",
    "q.m25#11.s0.o0" to "Промолчать и плыть по течению",
    "q.m25#11.s0.o1" to "Высказать своё суждение и доводы за ним",
    "q.m25#11.s0.o2" to "Пожаловаться втихую и на этом закончить",
    "q.m25#11.s0.o3" to "Сделать вид, что поддерживаете продолжение, оставив сомнения при себе",
    "q.m25#11.s0.e" to "Молчащее меньшинство — постоянный персонаж разборов аварий. Иметь сомнение и не озвучить его значит, что группа решает при неполной информации.\nЦена того, чтобы сказать, мала, возможно нулевая; цена молчания может быть очень велика.",
    "q.m25#11.s1.p" to "Шаг 2: после обсуждения группа решает продолжать, но вам всё равно неспокойно. Что дальше?",
    "q.m25#11.s1.o0" to "Подчиниться пассивно и делать минимум",
    "q.m25#11.s1.o1" to "Ясно обозначить своё сомнение и подтвердить условия поворота и план отступления группы",
    "q.m25#11.s1.o2" to "Немедленно спуститься одному",
    "q.m25#11.s1.o3" to "Больше ничего не говорить, но обидеться",
    "q.m25#11.s1.e" to "После принятого решения остаются три вещи: оставить ясную запись («я был против, потому что…»), убедиться, что условия отступления сформулированы однозначно, и проверить, что вы всё ещё хотите и можете это выполнять.\nСомнение — не пассивное подчинение: сказав своё, вы всё равно делаете свою часть как следует.",
    "q.m25#11.s2.p" to "Шаг 3: оказалось, ваше беспокойство было обоснованным, и группа спустилась раньше. В чём ценность этого опыта?",
    "q.m25#11.s2.o0" to "Доказывает, что вы лучше остальных",
    "q.m25#11.s2.o1" to "Подтверждает, что заранее озвученное сомнение действует и не портит отношения",
    "q.m25#11.s2.o2" to "Показывает, что в будущем надо действовать одному",
    "q.m25#11.s2.o3" to "Немного, раз вершины не было",
    "q.m25#11.s2.e" to "Многие, впервые озвучивая сомнение, боятся, что их сочтут чужими. В реальности хорошая группа после этого становится увереннее друг в друге, потому что доказано: кто-то готов сказать правду.\nДержитесь этого опыта; в следующий раз вы заговорите раньше.",
)
